WFAT is a rigorously derived tunnel ionization theory based on the expansion of the ionized wave function in parabolic channel basis in the asymptotic region. WFAT has been used in some works to help analyze experimental data \cite{wfat-application-laser-elstru-2015, wfat-application-atto-cm-2015, dissoc-tunnel-no-2019, wfat-application-hhs-2024}. In general, for OE-WFAT, the solution of \autoref{eq:schroedinger_eq} is expanded as follows \cite{wfat1_atom_ref-2013, ir_oewfat-2016},
\begin{gather}
    \psi(\mathbf r) = \eta^{-1/2} \sum_\nu F_\nu(\eta) \Phi_\nu(\xi, \varphi),
    \label{eq:wfn_expand}
\end{gather}
where 
\begin{gather}
    \Phi_\nu(\xi,\varphi) = \phi_\nu(\xi) \frac{e^{im\varphi}}{\sqrt{2\pi}},
\end{gather}
and $(\xi,\eta,\varphi)$ are coordinates in the parabolic coordinate system \cite{wfat_theory1-2011}. $\Phi_\nu(\xi,\varphi)$ are called parabolic channel functions and are characterized by the set of parabolic quantum numbers
\begin{gather}
    \nu \equiv (n_\xi,m), \hspace{3mm} n_\xi = 0,1,\ldots, \hspace{3mm} m = 0, \pm 1, \ldots.
\end{gather}
$\phi_\nu(\xi)$ is the solution of the following eigenproblem 
\begin{gather}
    \left(
    \odv*[fun]{\xi\odv*{}{\xi}}{\xi}
    - \frac{m^2}{4\xi}
    + Z
    + \frac{E\xi}{2}
    - \frac{F\xi^2}{4}
    - \beta_\nu
    \right)
    \phi_\nu(\xi)
    = 0,
    \label{eq:diff_eq_phi}
\end{gather}
where $Z$ is the total charge of the cation. By substituting Eq. \eqref{eq:wfn_expand} into Eq. \eqref{eq:schroedinger_eq} and using Eq. \eqref{eq:diff_eq_phi}, one may obtain the equation satisfied by $F_\nu(\eta)$. 

In the asymptotic region where $\eta \to \infty$ and also where the ionized electron propagates, $\psi(\mathbf{r})$ may be expressed as
\begin{gather}
    \psi(\mathbf r) \big|_{\eta \to \infty} = 
    \eta^{-1/2} 
    \sum_\nu f_\nu \, p_\nu(\eta) 
    \Phi_\nu(\xi, \varphi),
    \label{eq:wfn_expand_as}
\end{gather}
where $p_\nu(\eta) = f_\nu^{-1} F_\nu(\eta) \big|_{\eta \to \infty}$. The expression for $F_\nu(\eta) \big|_{\eta \to \infty}$, and hence $p_\nu(\eta)$, can be found in Refs. 
\cite{wfat_theory1-2011, wfat1_atom_ref-2013, oewfat1-h2_c-2015}.
\fgreen{The total ionization rate (or probability) $\Gamma$ is then calculated as the total flux of electrons leaving a surface of constant $\eta$ as $\eta$ approaches infinity \cite{wfat1_atom_ref-2013}. This results in the formula $\Gamma \approx \sum_\nu \Gamma_\nu$, where $\Gamma_\nu = |f_\nu|^2$.
}
% The ionization rate (or probability) into a particular parabolic channel characterized by $\nu$
% is then calculated as the probability of finding an electron in the asymptotic region in the parabolic channel/basis function $\eta^{-1/2} p_\nu(\eta) \, \Phi_\nu(\xi, \varphi)$, and is equal to $|f_\nu|^2$.
% \begin{align}
%     f_\nu(\eta) \big|_{\eta \to \infty} =
%     \frac{\sqrt{2} f_\nu}{(F\eta)^{1/4}}
%     \exp\left(
%     \frac{i\sqrt{F}\eta^{3/2}}{3}
%     + i\sqrt{\frac{\eta}{F}}E
%     \right).
%     \label{eq:f_asymptotic}
% \end{align}
% This probability, which is equal to , is taken as the ionization probability to the parabolic channel characterized by $\nu$.

In OE-WFAT(1), the partial ionization probability $\Gamma_\nu$ is expanded into powers of $F$ and then truncated up to the first power, which gives 
\begin{align}
    \Gamma_\nu \approx& \,\, \Gamma_\nu^{(1)}
    =
    W_\nu(F) e^{-2\varkappa \mu_z}
    \bigg(
    |g_\nu|^2
    \Big(
    1
    + A_\nu F \ln \frac{F}{4\varkappa^2}
    \nonumber \\
    & \,
    + \tilde B_\nu F 
    + 2F o_\nu
    \Big)
    + \, 2F \, \textrm{Re}\left[g_\nu^* h_\nu\right]
    \bigg),
    \label{eq:wfat1_rate}
\end{align}
where $\varkappa = \sqrt{2|E^{(0)}|}$, $E^{(0)}$ is the field-free orbital energy, $\mu_z$ is the $z$ component of the dipole vector in the LF, that is, 
\begin{equation}
    \mu_z \equiv [\boldsymbol\mu_\textrm{LF}]_3 = \left[\hat R^T (\beta,\gamma) \boldsymbol \mu_\textrm{MF} \right]_3,
    \label{eq:rotate_dipole}
\end{equation}
where  $\mu_\textrm{MF}$ is a 3-element vector whose element is equal to $- \big\langle \psi^{(0)} \big| x_s \big| \psi^{(0)} \big\rangle$ with $x_s$ being Cartesian coordinates in the MF. \pink{$W_\nu(F)$ is called field factor and is given by}
\begin{equation}
    W_\nu(F) = \frac{\varkappa}{2}     
    \left(\frac{4\varkappa^2}{F}\right)^{2Z/\varkappa-2n_\xi-|m|-1}
    \exp\left( -\frac{2\varkappa^3}{3F} \right)
    \label{eq:field_factor}
\end{equation}
The expressions for $A_\nu$, $\tilde B_\nu$, and $o_\nu$ can be found in Appendix \ref{app:define_quantities}.

%The field dependence of ionization rate in WFAT is exclusively contained within $W_\nu(F)$, while the remaining part of the right-hand side of \autoref{eq:wfat1_rate} encodes the orientation dependence. 
\pink{The ionization rate formula \autoref{eq:wfat1_rate} depends on the ionized orbital through the \textit{asymptotic coefficients}, $g_\nu$ and $h_\nu$.} \myorange{Their integral formulas in the MF are given by \cite{ir_oewfat-2016}}
\begin{gather}
    g_\nu = 
    \int d\mathbf r^3  \,
    \Omega_{\bar\nu}^{(0)}(\hat R^{-1} \mathbf r) \, V_c(\mathbf r) \, \psi^{(0)}(\mathbf r) ,
    \label{eq:define_gnu}
    %%%%
    \\
    %%%%
    h_\nu =
    \int d\mathbf r^3 
    \left( 
    \Omega_{\bar\nu}^{(0)}(\hat R^{-1} \mathbf r) \, \psi^{(1)}(\mathbf r) 
    +
    \Omega_{\bar\nu}^{(1)}(\hat R^{-1} \mathbf r) \, \psi^{(0)}(\mathbf r) 
    \right) \nonumber \\
    \times V_c(\mathbf r).
    \label{eq:define_hnu}
\end{gather}
\pink{Here, \wfnzero{\mathbf r} and \wfnone{\mathbf r} represent the field-free orbital and its first-order perturbation correction, respectively, so that the field-dressed orbital is approximated as $\psi(\mathbf r) \approx \wfnzero{\mathbf r} + F \wfnone{\mathbf r}$. The terms \omgzero{\nu}{\mathbf r} and \omgone{\nu}{\mathbf r} are the function that determines the final state of the ionized electron and its first-order perturbation correction, respectively. The potential term $V_c(\mathbf r) = V(\mathbf r) + Zr^{-1}$ appears as a result of the Lippmann-Schwinger integral reformulation of WFAT [20]. This potential term is absent in the TR formulation.}
Equations \eqref{eq:define_gnu}--\eqref{eq:define_hnu} constitute the most computationally expensive steps due to the required numerical integrations using \pink{spatial} grid points and the evaluation of two-electron potential terms inside $V(\mathbf r)$ at each of the grid points. \myorange{We note that $g_\nu$ and $h_\nu$ depend on the choice of origin through $V_c(\mathbf{ r)}$ and $\Omega_\nu^{(0,1)}(\mathbf{r})$. This origin dependence, however, is canceled by the origin dependence of $\exp(-2\varkappa\mu_z)$ when calculating $\Gamma_\nu$ (see \autoref{eq:wfat1_rate}).} 

The first-order correction (or distortion) of the field-free orbital may be expressed as
\begin{gather}
    \psi^{(1)} (\mathbf r) = \sum_{s=1}^3 \hat R_{s3} \, \psi_s^{(1)} (\mathbf r), 
    \label{eq:define_psi1}
\end{gather}
where 
\begin{gather}
    \psi_s^{(1)}(\mathbf r) 
    % \equiv \psi_{ns}^{(1)}(\mathbf r) 
    = \sum_{i; v_i \notin \mathcal D[n]} v_i(\mathbf r) \frac{\langle v_i |x_s| v_n \rangle}{\varepsilon_n - \varepsilon_i}.
    \label{eq:define_psi_s}
\end{gather}
$v_i$ and $\varepsilon_i$ are the eigenvectors and the corresponding eigenvalues of the unperturbed Hamiltonian, respectively. $n$ is the index of the unperturbed ionized wave function, i.e. $\psi^{(0)} \equiv v_n$ and $E^{(0)} \equiv \varepsilon_n$. $\mathcal D[n]$ is the degenerate subspace spanned by all unperturbed eigenstates with energy $\varepsilon_n$, which, for the case of non-degenerate state, consists of just $v_n$, and $x_s$ with $s=1,2,3$ are the three Cartesian coordinates in the MF. The addition of $F \psi^{(1)}(\mathbf{r})$ into $\psi^{(0)}(\mathbf{r})$ will distort the shape of the latter based on the field strength and its direction relative to the molecule, and will thus affect the orientation dependence of ionization rate. The effects of such a distortion to the orbital are one of the main subjects of the present work.

The functions \omgzero{\nu}{\mathbf{r}} and \omgone{\nu}{\mathbf{r}} are given by \cite{ir_oewfat-2016}
\begin{align}
    \Omega_\nu^{(0)}(\mathbf r) =
    &\,
    -\frac{2 \varkappa^{\beta_\nu^{(0)}/\varkappa-1}}{\sqrt{2\pi\eta}}
    \mathcal R_\nu^{(0)}(\eta) \phi_\nu^{(0)}(\xi) \, e^{im\varphi} ,
    \label{eq:Omega0_explicit}
    %%%%
    \\
    %%%%
    \Omega_\nu^{(1)}(\mathbf r) =
    &\,
    -\frac{2 \varkappa^{\beta_\nu^{(0)}/\varkappa-1}}{\sqrt{2\pi\eta}}
    e^{im\varphi}
    \nonumber
    \\
    &\,
    \times \left(
    \mathcal R_\nu^{(1)}(\eta) \phi_\nu^{(0)}(\xi) \,
    + \mathcal R_\nu^{(0)}(\eta)  
    \phi_\nu^{(1)}(\xi)
    \right) ,
    \label{eq:Omega1_explicit}
\end{align}
% In most cases, the contribution from $\nu = (0,0)$ channel dominates the ionization. The contributions from higher channels constitutes the parabolic channel effect, one of the main subjects of the present work.
where \betazero{\nu}, \retazero{\nu}{\eta}, \retaone{\nu}{\eta}, \phizero{\nu}{\xi}, and \phione{\nu}{\xi} can be found in Appendix \ref{app:define_quantities}. Rewriting \omgzero{\nu}{\mathbf{r}} and \omgone{\nu}{\mathbf{r}} as an expansion in terms of spherical harmonics constitutes the first step in deriving the partial-wave expansion method presented in \autoref{sec:derive_q}.



In Ref. \cite{ir_oewfat_grid-2018}, integrals of the form \autoref{eq:define_gnu} are computed by partitioning the integral into Becke cells \cite{becke_cell-1988}, a method which we shall also employ here. Each partition is an integral over the space defined by the cell centered around a nucleus. These individual partitioned integrals are then computed using a 3D quadrature before being summed over to yield the desired final integral. Using this integration method, one can of course directly compute the integrals in \autoref{eq:define_gnu} and \autoref{eq:define_hnu}.
%One way to compute the integrals in \autoref{eq:define_gnu} and \autoref{eq:define_hnu} is simply to numerically integrate these integrals, dubbed \textit{explicit method} hereafter. 
However, such a direct method, dubbed the \textit{explicit method} hereafter, has a severe drawback related to \myorange{a computationally expensive integral}---we will explain more about this in the following.
The orientation dependence in Eqs. \eqref{eq:define_gnu} and \eqref{eq:define_hnu} is encoded in the orientation between the $\Omega_\nu(\mathbf r)$'s and the wave functions as well as $V_c(\mathbf r)$: \myorange{the $\Omega_\nu(\mathbf r)$'s are bound to $z_\text{LF}$ (which is where the field points) whereas the wave functions and $V_c(\mathbf r)$ are bound to the MF. While Eqs. \eqref{eq:define_gnu} and \eqref{eq:define_hnu} have been written in the MF, one can also recast them into their LF form. However, since Becke cells are molecule-bound, the algorithm to calculate these integrals in the LF is essentially identical to that in the MF.}
% But the latter is expensive because in the LF, $V_c(\mathbf{r})$, which contains expensive two-electron integrals, needs to be reevaluated at each orientation angle. 
% \myorange{In contrast, in the MF, only the relatively inexpensive $\Omega_\nu^{(0)}(\mathbf r)$ needs to be rotated by applying $\hat R$ on it}.
% This means that for every orientation angle of interest one must recompute the whole integral, which can be expensive due to the two-electron integrals involved in the evaluation of $V_c(\mathbf r)$ at all Becke quadrature points. For \autoref{eq:define_gnu}, this can be mitigated by computing the integral in MF where the wave functions and $V_c(\mathbf r)$ are orientation-independent, therefore only the relatively cheap $\Omega_\nu^{(0)}(\mathbf r)$ needs to be \myorange{rotated by applying $\hat R$ on it}. 
Performing the integral of \autoref{eq:define_hnu} in the MF for a large number of orientations, however, can be very expensive
because: 
1) $\Omega_\nu^{(1)}(\mathbf r)$ must be recomputed whenever the orientation is changed, and
2) the computation of $\mathcal R_\nu^{(1)}(\eta)$ contained in $\Omega_\nu^{(1)}(\mathbf r)$ involves yet another integral that must be computed numerically (see Eq. \eqref{eq:define_r1_eta}).
% for all orientation angles can often be more expensive than the two-electron integrals. 
In  \autoref{sec:derive_q}, we shall derive a set of equations that allow for a highly efficient computation of \autoref{eq:define_hnu} in the MF for a large number of orientation angles, we will call this the \textit{partial wave method}.
%(for a reason that will be clear in \autoref{sec:derive_q}), is one of the main results of this paper. 
%This is the focus of \autoref{sec:derive_q}.

We end this section by noting that we have expressed some quantities such as $\psi^{(1)}(\mathbf{r})$ (Eq. \eqref{eq:define_psi1}), $\beta_\nu^{(1)}$ (Eq. \eqref{eq:define_beta1}), $o_\nu$ (Eq. \eqref{eq:define_onu}), and the expansion coefficients in Eq. \eqref{eq:phi1_expand} in the decomposed form of $\sum_i d_i f_i$ where $f_i$ is orientation-independent while $d_i$ depends on the orientation. This is done because to implement the efficient computation of OE-WFAT(1) ionization rates in \autoref{sec:derive_q}, 
%it is necessary to express computationally expensive quantities such that orientation-dependent and orientation-independent terms are explicitly separated. 
%This is so that 
we need to defer incorporating the orientation angle into the calculation until the last step (which is the computation of the ionization rate) when all computationally expensive, orientation-independent quantities have been calculated and stored in memory or on disk. Throughout this paper, a quantity is cast in the above decomposed form if it involves or is needed in expensive calculations (for example, see Appendix \ref{app:define_quantities}). 



\subsection{Orbital distortion and parabolic channel effects in tunnel ionization \label{sec:orb_distort_parabolic}}

Equation \eqref{eq:wfat1_rate} gives the OE-WFAT(1) rate formula for ionization to the parabolic channel $\nu$. We note that without the first-order correction, the OE-WFAT(0) partial rate reads \cite{wfat_theory1-2011, oewfat0-linearmol-2012, wfat-structurefactors-2013, wfat_partial_wave1-2017, ir_oewfat_grid-2018}
\begin{equation}
    \label{eq:wfat0_rate}
    \Gamma_\nu^{(0)} = W_\nu(F) \exp(-2 \varkappa \mu_z) |g_\nu|^2.
\end{equation}
Since the field and orientation dependences of $\Gamma_\nu^{(0)}$ are decoupled into 
$W_\nu(F)$ and $\exp(-2 \varkappa \mu_z) |g_\nu|^2$, respectively, in OE-WFAT(0), the angular shape of partial ionization rates \myorange{is independent of the field}. 
In the following, we present our study of the effects of the quantities that appear in going from $\Gamma_\nu^{(0)}$ (\autoref{eq:wfat0_rate}) to $\Gamma_\nu^{(1)}$ (\autoref{eq:wfat1_rate}) on the angular shape of ionization rate curves. This amounts to the first-order orbital distortion effect. These additional quantities depend on $\psi^{(1)}(\mathbf{r})$ and other quantities related to the first-order corrections in field \pink{strength. Consequently, they cause the field and orientation dependences of the ionization rates to become coupled, unlike in OE-WFAT(0) where these dependences are decoupled.}

The total ionization rate is obtained by summing over all parabolic channels, $\Gamma \approx \sum_\nu \Gamma_\nu$ \cite{wfat1_atom_ref-2013}. One then needs to apply the appropriate order of approximation to each parabolic channel based on the order of $F$ in $W_\nu(F)$. For the lowest three parabolic channels \pink{in first order}, this gives \cite{wfat1_atom_ref-2013}
\begin{equation}
    \Gamma \approx \Gamma_{00}^{(1)} + \Gamma_{0,+1}^{(0)} + \Gamma_{0,-1}^{(0)}.
    \label{eq:total_ion_rate}
\end{equation}
In many cases, $\Gamma_{00}$ \pink{(approximated as $\Gamma_{00}^{(1)}$ in \autoref{eq:total_ion_rate})} is the dominant contributor to the total rate. The dependence of $\Gamma_{00}$ on $(\beta,\gamma)$ resembles the shape of $\psi^{(0)}(\mathbf{r})$ at low field strengths. \pink{This term is therefore responsible for the mapping between} $\psi^{(0)}(\mathbf{r})$ and the orientation-dependent yield curve. The parabolic channel effect investigated in our work amounts to the contributions from $\Gamma_{0,\pm1}^{(0)}$. 

For the analyses of molecular ionization rates employed in this paper, we define the \textit{normalized rate} $\tilde \Gamma$ as $\tilde \Gamma = \Gamma / W_{00}$.



