\subsection{Partial-wave decomposition of OE-WFAT(1) \label{sec:derive_q}}

\myorange{In computing the MF integrals in Eqs. \eqref{eq:define_gnu}--\eqref{eq:define_hnu}, we need to apply $\hat R$ on \omgzero{\nu}{\mathbf{r}} and \omgone{\nu}{\mathbf{r}}. Therefore, we can expect to gain some computational efficiency if these functions are expanded in terms of the eigenfunctions of the generator of the rotation operator, namely, the spherical harmonics. This so-called partial-wave expansion method has been employed in Refs. \cite{wfat_partial_wave1-2017, ir_oewfat_grid-2018} to efficiently compute the integral in Eq. \eqref{eq:define_gnu}.}
% The integral in Eq. \eqref{eq:define_hnu} can be efficiently calculated by employing partial-wave expansion method, which has been applied in Ref. \cite{wfat_partial_wave1-2017, ir_oewfat_grid-2018} to efficiently compute the integral in Eq. \eqref{eq:define_gnu}. 
In this method, $\Omega_\nu^{(0)}(\mathbf r)$ is expressed as
% an infinite sum of spherical harmonics multiplied by some radial function,
\begin{gather}
    \label{eq:Omega0_expand}
    \Omega_\nu^{(0)}(\mathbf r) = 
    \sum_{l=|m|}^\infty 
    R_l^\nu(r) \,
    Y_{lm}(\theta,\varphi),
\end{gather}
where the radial function $R_l^\nu(r)$ is found to be
\begin{gather}
    R_l^\nu(r) =
    \omega_l^\nu
    (\varkappa r)^l
    e^{-\varkappa r}
    M(l+1-Z/\varkappa, 2l+2, 2\varkappa r), 
    \label{eq:define_rnu}
\end{gather}
with
\begin{align}
    \omega_l^\nu
    =& \,\,
    (-1)^{l+(|m|-m)/2+1} \,
    2^{l+3/2} \,
    % \varkappa^{Z/\varkappa - (|m|+1)/2 - n_\xi}   \nonumber \\
    \varkappa^{\betazero{\nu}/\varkappa}   \nonumber \\
    &\,\,
    \times
    \sqrt{(2l+1) (l+m)! (l-m)! (|m|+n_\xi)! n_\xi!}   \nonumber \\
    &\,\,
    \times
    \frac{l!}{(2l+1)!} 
    \sum_{k=0}^{\textrm{min}(n_\xi,l-|m|)}
    \frac
    {1}
    {k! (l-k)! (|m|+k)!}   \nonumber \\
    &\,\, 
    \times
    \frac{\Gamma(l+v-k)}{(l-|m|-k) !(n_\xi-k)!},
    \label{eq:define_omega_nu}
\end{align}
$\Gamma(z)$ is the gamma function, and $v = 1 + n_\xi - Z/\varkappa$.
\myorange{By applying $\hat R$ on \omgzero{\nu}{\mathbf{r}} in \autoref{eq:Omega0_expand} and using the result in \autoref{eq:define_gnu}, one obtains the partial-wave expansion of $g_\nu$,}
\begin{align}
    g_\nu(\beta,\gamma) = 
    & \,
    \sum_{l=|m|}^\infty \sum_{m'=-l}^l
    d_{mm'}^l(\beta) e^{-im'\gamma} I_{lm'}^\nu,
    \label{eq:gnu_partial_wave}
\end{align}
where $d_{mm'}^l(\beta)$ is the Wigner function \cite{varshalovich_angular_momentum-1988} and
\begin{gather}
    I_{lm'}^\nu =
    \int d\mathbf r^3 \,
    R_\nu^l(r) Y_{lm'}^*(\theta,\varphi) V_c(\mathbf r) \, \psi^{(0)}(\mathbf r).
    \label{eq:define-i}
\end{gather}
\myorange{In the partial-wave method, $g_\nu$ is calculated through \autoref{eq:gnu_partial_wave}, while in the explicit method, it is obtained from \autoref{eq:define_gnu}.}


To apply the partial-wave expansion for $h_\nu$ in \autoref{eq:define_hnu}, we need the partial-wave expansion for \omgzero{\nu}{\mathbf{r}}, given in Eqs. \eqref{eq:Omega0_expand}--\eqref{eq:define_omega_nu}, and \omgone{\nu}{\mathbf{r}},
%For the inclusion of the first order correction, we will also expand $\Omega_\nu^{(1)} (\mathbf r)$ in the same way as Eq. \eqref{eq:Omega0_expand}, 
\begin{gather}
    \label{eq:Omega1_expand}
    \Omega_\nu^{(1)}(\mathbf r) = 
    \sum_{l=|m|}^\infty 
    Q_l^\nu(r) \,
    Y_{lm}(\theta,\varphi).
\end{gather}
% which we have derived in the present work.
\pink{In \autoref{eq:Omega1_expand}, the objective is to determine $Q_l^\nu(r)$, which we derive in the present work. The partial-wave sum in \autoref{eq:Omega1_expand} must reproduce \omgone{\nu}{\mathbf{r}} given in \autoref{eq:Omega1_explicit}.}
% so that the sum in Eq. \eqref{eq:Omega1_expand} reproduces Eq. \eqref{eq:Omega1_explicit}. 
Appendix \ref{app:derive_q} describes the derivation to solve for $Q_l^\nu(r)$. Here, we will only invoke the final result, namely
\begin{gather}
    Q_l^\nu(r) = Q_1^{\nu l}(r) + \mu_z Q_2^{\nu l}(r),
    \label{eq:q_split}
\end{gather}
where    
\begin{align}    
    Q_1^{\nu l}(r) 
    =
    & \,
    d_1^{\nu l} g_l^\nu(r)
    + 
    \frac{2^{2l+2} \varkappa \, \Gamma(l+1-Z/\varkappa)}{(2l+1)!} 
    \int_0^r dr' r'^2   \nonumber
    \\
    & \, 
    \times 
    \left(
    k_{l|m|} r' R_{l-1}^\nu(r')
    +
    k_{l+1,|m|} r' R_{l+1}^\nu(r') 
    \right)
    \nonumber
    \\
    & \, 
    \times
    \left(
    g_l^\nu(r) h_l^\nu(r')
    -
    g_l^\nu(r') h_l^\nu(r)
    \right),
    \label{eq:define_q1}
    %%%%%%
    \\
    %%%%%%
    Q_2^{\nu l}(r) 
    =
    & \,
    d_2^{\nu l} g_l^\nu(r)
    + 
    \frac{2^{2l+2} \varkappa \, \Gamma(l+1-Z/\varkappa)}{(2l+1)!}
    \int_0^r dr' r'^2 \nonumber
    \\
    & \, 
    \times
    R_l^\nu(r')
    \left(
    g_l^\nu(r) h_l^\nu(r')
    -
    g_l^\nu(r') h_l^\nu(r)
    \right).
    \label{eq:define_q2}
\end{align}
Here, $k_{l|m|} = \sqrt{(l^2-m^2)(4l^2-1)^{-1}}$, $g_l^\nu(r)$ and $h_l^\nu(r)$ are defined in \autoref{eq:def_g} and \autoref{eq:def_h}, respectively, and 
\begin{widetext}
\begin{align}
    d_r^{\nu l}
    =
    & \,
    (-1)^{l+(m-|m|)/2+1} \,
    2^{l+3/2} \,
    \varkappa^{\beta_\nu^{(0)}/\varkappa}
    \sqrt{(2l+1) (l+m)! (l-m)} \frac{l!}{(2l+1)!} \nonumber
    \\
    & \,
    \times
    \left[
    \sum_{i=n_\xi-2; i \neq n_\xi}^{n_\xi+2} 
    \sqrt{(i+|m|)! \, i!} \, C_r^{im} \sum_{k=0}^{\textrm{min}(i,l-|m|)}
    \frac{\Gamma(l+v-k)}{k!(l-k)!(|m|+k)!(l-|m|-k)!(i-k)!}\, 
    + 
    \frac{\sqrt{(n_\xi+|m|)! n_\xi!}}{\varkappa^2 \Gamma(v+|m|)}
    \right. \nonumber
    \\
    & \,
    \left.
    \times
    \left\{
    \frac{(-1)^{|m|+1}}{\Gamma(v)}
    \left(
    e^1_r H_1^{\nu l}
    +
    e^2_r H_2^{\nu l}
    +
    e^3_r H_3^{\nu l}
