\section{Definitions of some quantities \label{app:define_quantities}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The improvement in OE-WFAT(1) from OE-WFAT(0) manifests in the appearance of first-order corrections to various quantities, some of them are $\psi^{(1)}(\mathbf{r})$, the static polarizability component $\alpha_{zz}$, \retaone{\nu}{\eta}, and \phione{\nu}{\xi}.
The zeroth- and first-order corrections to $\mathcal{R}_\nu(\eta)$ needed in \autoref{eq:Omega0_explicit} and \autoref{eq:Omega1_explicit} are given by \cite{ir_oewfat-2016}
\begin{align}
    \mathcal R_\nu^{(0)}(\eta) =
    &\,
    \frac{\Gamma(a)}{|m|!}
    (\varkappa \eta)^{b/2}
    e^{-\varkappa\eta/2}
    M(a,b,\varkappa\eta),
    \label{eq:define_r0_eta}
    %%%%
    \\
    %%%%
    \mathcal R_\nu^{(1)}(\eta) =
    &\,
    \frac{1}{\varkappa} \int_0^\eta d\eta'
    \left(
    \mathcal R_\nu^{(0)}(\eta') \mathcal O_\nu^{(0)}(\eta)
    - \mathcal R_\nu^{(0)}(\eta) \mathcal O_\nu^{(0)}(\eta')
    \right) \nonumber
    \\
    &\,
    \times
    \left(
    \frac{\beta_\nu^{(1)}}{\eta'}
    - \frac{\mu_z}{2}
    + \frac{\eta'}{4}
    \right)
    \mathcal R_\nu^{(0)}(\eta'),
    \label{eq:define_r1_eta}
\end{align}
where $a=(1+|m|)/2-\beta_\nu^{(0)}/\varkappa$, $b=1+|m|$, and $M(a,b,z)$ is the confluent hypergeometric function of the first kind \cite{math_handbook_abramowitz-1972}. 

The zeroth- and first-order corrections to the parabolic channel function $\phi_\nu(\xi)$ and its associated eigenvalue $\beta_\nu$ are given by \cite{wfat1_atom_ref-2013}
\begin{align}
    \phi_\nu^{(0)}(\xi) = 
    &\,
    \sqrt{\varkappa} \, (\varkappa \xi)^{|m|/2}
    e^{-\varkappa\xi/2}
    \sqrt{\frac{n_\xi!}{(n_\xi+|m|)!}}
    L_{n_\xi}^{(|m|)} (\varkappa\xi),
    %%%%
\end{align}
\begin{align}
    %%%%
    \phi_\nu^{(1)}(\xi) = 
    &\,
    \sum_{i=n_\xi-2, \, i \neq n_\xi}^{n_\xi+2}
    (C_1^{im} + \mu_z C_2^{im}) \phi_{im}^{(0)}(\xi),
    \label{eq:phi1_expand}
    %%%%
    \\
    %%%%
    \betazero{\nu} =
    &\,\,
    Z - \varkappa
    \left( n_\xi + \frac{|m|+1}{2} \right),
    %%%%
    \\
    %%%%
    \betaone{\nu} =
    &\,\,
    b_1^\nu + \mu_z b_2^\nu,
    \label{eq:define_beta1}
    %%%%
    \\
    %%%%
    b_1^\nu = 
    &\,
    -\frac{1}{4\varkappa^2}
    \left(
    6n_\xi(n_\xi+|m|+1) + m^2 + 3|m| + 2
    \right),
    \label{eq:define_b1}
    %%%%
    \\
    %%%%
    b_2^\nu = 
    &\,
    -\frac{1}{2\varkappa}
    (2n_\xi + |m| + 1).
    \label{eq:define_b2}
\end{align}
where $L_n^{(\alpha)}(x)$ are the generalized Laguerre polynomials \cite{math_handbook_abramowitz-1972}, and
\begin{subequations}
    \label{eq:phi1_expand_c}
    \begin{gather}
        C_r^{n_\xi-2,m} = \delta_{r1} c_{n_\xi-2} c_{n_\xi-1} / (8\varkappa^3),  
        %%%%
        \\
        %%%%
        % C_r^{n_\xi-1,m} = -c_{n_\xi-1} \left[ 1 + \delta_{r1}(2n_\xi+|m|) \right] / (2\varkappa^3),
