        %%%%
        % C_r^{n_\xi+1,m} = c_{n_\xi} \left[ 1 + \delta_{r1} (2n_\xi+|m|+2) \right] / (2\varkappa^3),
        C_r^{n_\xi+1,m} = c_{n_\xi} \left[ \delta_{r2}\varkappa + \delta_{r1} (2n_\xi+|m|+2) \right] / (2\varkappa^3),
        %%%%
        \\
        %%%%
        C_r^{n_\xi+2,m} = - \delta_{r1} c_{n_\xi} c_{n_\xi+1} / (8\varkappa^3),
        %%%%
        \\
        %%%%
        c_{n_\xi} = \sqrt{(n_\xi+1) (n_\xi+|m|+1)}.
