The static polarizability component $\alpha_{zz}$ is the component of the polarizability tensor in the direction of the field in the LF, so it is given by
\begin{gather}
    \alpha_{zz} \equiv [\boldsymbol\alpha_\textrm{LF}]_{33} = \left[ R^T (\beta,\gamma) \, \boldsymbol \alpha_\textrm{MF} \, R (\beta,\gamma) \right]_{33},
    \label{eq:rotate_polarizability}
\end{gather}
with the components of static polarizability tensor in the MF given by
% \begin{gather}
%     [\boldsymbol\mu_\textrm{MF}]_s = - \big\langle \psi^{(0)} \big| x_s \big| \psi^{(0)} \big\rangle ,
% \end{gather}
\begin{align}
    [\boldsymbol\alpha_\textrm{MF}]_{ss'} 
    =&\,\,
    -2 \, \big\langle \psi^{(0)} \big| x_s \big| \psi_{s'}^{(1)} \big\rangle 
    \nonumber \\
    =&\,\, 
    -2 \sum_{i; v_i \notin \mathcal D[n]} 
    \frac{\langle \psi^{(0)} |x_s| v_i \rangle \langle v_i |x_{s'}| \psi^{(0)} \rangle}{\varepsilon_n - \varepsilon_i},
    \label{eq:mf_polarizability}
\end{align}
where $s,s' = 1,2,3$. Note that $\boldsymbol\alpha_\textrm{MF}$ is a symmetric matrix.

The dependence of OE-WFAT(1) ionization rate on $\alpha_{zz}$ is encapsulated in $\tilde B_\nu$,
\begin{align}
    \tilde B_\nu = 
    &\,
    -\varkappa\alpha_{zz}
    - \frac{\mu_z^2}{\varkappa}
    + \frac{\mu_z}{\varkappa^2}
    + \frac{4\mu_z \beta_\nu^{(0)}}{\varkappa^3}
    - \frac{(9-6\gamma_m)\beta_\nu^{(0)}}{4\varkappa^4} \nonumber
    \\
    &\,
    -\frac{10+18\gamma_m+3\gamma_m^2}{24\varkappa^3}
    - \frac{(49+2\gamma_m)\beta_\nu^{(0)2}}{8\varkappa^5}
    + \frac{3\beta_\nu^{(0)3}}{2\varkappa^6} \nonumber
    \\
    &\,
    -\frac{\beta_\nu^{(0)4}}{8\varkappa^7},
    \label{eq:define_tbnu}
\end{align}
where $\gamma_m = (1-m^2)/4 - 2[\mathbf{d}_T^+]_z$. In our calculations, the origin is chosen so that $\mathbf{d}_T^+ = 0$, see Appendix \ref{app:origin}, therefore, we use $\gamma_m = (1-m^2)/4$.
While $A_\nu$ and $o_\nu$ do not depend on $\alpha_{zz}$, their orientation dependence only comes from $\mu_z$,
\begin{align}
    A_\nu = 
    &\,
    -\frac{2\beta_\nu^{(1)}}{\varkappa}
    - \frac{\gamma_m-2\mu_z \beta_\nu^{(0)}}{\varkappa^3}
    - \frac{3\beta_\nu^{(0)2}}{\varkappa^5},
    \label{eq:define_anu}
    %%%%
    \\
    %%%%
    o_\nu = &\, 
    o_1^\nu + \mu_z o_2^\nu,
    \label{eq:define_onu}
    %%%%
    \\
    %%%%
    o_1^\nu =
    &\, 
    \frac{1}{4\varkappa^3}
    \left(
    1 + \frac{\gamma_m^2}{2} - \gamma_m \left( \frac{4\beta_\nu^{(0)}}{\varkappa} - \frac{\beta_\nu^{(0)2}}{\varkappa^2} \right)
    + \frac{4\beta_\nu^{(0)}}{\varkappa} 
    \right. \nonumber
    \\
    &\,
    \left.
    + \, \frac{7\beta_\nu^{(0)2}}{2\varkappa^2}
    - \frac{4\beta_\nu^{(0)3}}{\varkappa^3}
    + \frac{\beta_\nu^{(0)4}}{2\varkappa^4}
    \right) \nonumber
    \\
    &\,
    + \frac{1}{\varkappa} \int_0^\infty d\eta
    \left(
    \left(
    \frac{b_1^\nu}{\eta} + \frac{\eta}{4}
    \right)
    \mathcal R_\nu^{(0)}(\eta) \mathcal O_\nu^{(0)}(\eta)
    - \frac{\eta}{4} \right. \nonumber
    \\
    &\,
    \left.
    - \, \frac{\beta_\nu^{(0)}}{2\varkappa^2}
    - \left(
    b_1^\nu + \frac{\gamma_m}{2\varkappa^2} + \frac{3\beta_\nu^{(0)2}}{2\varkappa^4}
    \right) \frac{1}{\eta+1}
    \right), 
    %%%%
    \\
    %%%%
    o_2^\nu =
    &\,
    -\frac{1}{2\varkappa^2}
    + \frac{1}{\varkappa}
    \int_0^\infty d\eta
    \left(
    \left(
    \frac{b_2^\nu}{\eta} - \frac{1}{2}
    \right)
    \mathcal R_\nu^{(0)}(\eta) \mathcal O_\nu^{(0)}(\eta) \right. \nonumber
    \\
    &\,
    \left.
    + \, \frac{1}{2}
    - \left(
    b_2^\nu - \frac{\beta_\nu^{(0)}}{\varkappa^2}
    \right)
    \frac{1}{\eta+1}
    \right),
\end{align}
where
\begin{gather}
    \mathcal O_\nu^{(0)}(\eta) =
    (\varkappa \eta)^{b/2}
    e^{-\varkappa\eta/2}
    U(a,b,\varkappa\eta),
    \label{eq:define_o0_eta}
\end{gather}
and $U(a,b,z)$ is the confluent hypergeometric function of the second kind \cite{math_handbook_abramowitz-1972}.






