\section{Derivation of $Q_l^\nu(r)$
\label{app:derive_q}}

In order to obtain the expression of $Q_l^\nu(r)$, we must first determine an equation of which $\Omega_\nu^{(1)}(\mathbf r)$ is a solution. It is straightforward to verify that $\Omega_\nu^{(1)}(\mathbf r)$ given in \autoref{eq:Omega1_explicit} satisfies the following differential equation,
\begin{gather}
    \left(
    \frac{\nabla^2}{2} + \frac{Z}{r} + E^{(0)}
    \right)
    \Omega_\nu^{(1)} (\mathbf r)
    = 
    \left( z + \mu_z \right) \Omega_\nu^{(0)} (\mathbf r).
    \label{eq:pde_def_Omega1}
\end{gather}
%\pink{Appendix \ref{app:proof_Omega1_solution} provides a formal way of deriving the solution of Eq. \eqref{eq:pde_def_Omega1}.} 
We can now insert the partial wave expansion form of $\Omega_\nu^{(1)}(\mathbf r)$ given in Eq. \eqref{eq:Omega1_expand} into Eq. \eqref{eq:pde_def_Omega1} and project the resulting equation onto a particular spherical harmonics. These give
\begin{gather}
    \left(
    \odv*[fun]{r^2 \odv{}{r}}{r} 
    -
    l(l+1)
    +
    2 Z r
    +
    2 E^{(0)} r^2
    \right)
    Q_l^\nu(r)
    = \nonumber 
    \\
    2 r^2
    \left(
    k_{l|m|} r R_{l-1}^\nu(r)
    +
    k_{l+1,|m|} r R_{l+1}^\nu(r)
    +
    \mu_z R_l^\nu(r)
    \right).
    \label{eq:ode_def_q}
\end{gather}
% where
% $
%     k_{l|m|} = \sqrt{
%     (l^2-m^2)(4l^2-1)^{-1}
%     }.
% $

The general solution of \autoref{eq:ode_def_q} may be written as
\begin{gather}
    Q_l^\nu(r) = 
    C_1 g_l^\nu(r) + C_2 h_l^\nu(r) + A_l^\nu(r),
    \label{eq:q_general_form}
\end{gather}
where $g_l^\nu(r)$ and $h_l^\nu(r)$ are the linearly independent solutions of a homogeneous differential equation obtained by setting the right-hand side of \autoref{eq:ode_def_q} to zero. We take the liberty of taking $h_l^\nu(r)$ as the solution that diverges at $r=0$, thus $g_l^\nu(0)$ is finite. These two functions are given by,
\begin{subequations}
    \begin{gather}
        g_l^\nu(r) = (\varkappa r)^l e^{-\varkappa r} M(l+1-Z/\varkappa, 2l+2, 2\varkappa r),
        \label{eq:def_g}
        %%%%
        \\
        %%%%
        h_l^\nu(r) = (\varkappa r)^l e^{-\varkappa r} U(l+1-Z/\varkappa, 2l+2, 2\varkappa r),
        \label{eq:def_h}
    \end{gather}
    \label{eq:def_gh}
\end{subequations}
With this convention, one may note that $g_l^\nu(r) \propto R_l^\nu(r)$.
Using the behavior of \retazero{\nu}{\eta} and \retaone{\nu}{\eta} near $\eta=0$, which may be found in Ref. \cite{ir_oewfat-2016}, we find the property $\omgone{\nu}{r=0,\theta,\varphi}=0$ (see \autoref{eq:Omega1_explicit}). This implies $Q_l^\nu(0)=0$, thus $C_2=0$.
%Since \pinkx{$Q_l^\nu(r)$ has to be finite at $r=0$}, we must have $C_2=0$.

To obtain $C_1$, we need the mathematical expression for $A_l^\nu(r)$, the particular solution of \autoref{eq:ode_def_q}. It can be shown that
\begin{align}
    A_l^\nu(r) =& 
    - \frac{1}{r^2 W(r)}
    \left[
    \int_0^r dr' \, h_l^\nu(r) g_l^\nu(r') Y(r') \,
    + \right. \nonumber \\
    &\left.
    \int_r^\infty dr' \, g_l^\nu(r) h_l^\nu(r') Y(r') 
    \right],
\end{align}
where $Y(r)$ is the right-hand side of \autoref{eq:ode_def_q} and $W(r)$ is the Wronskian of the homogeneous differential equation obtained by setting $Y(r)=0$ in \autoref{eq:ode_def_q}. By making use of the Wronskian of the defining differential equation for the Hypergeometric functions \cite{math_handbook_abramowitz-1972}, it can be shown that
\begin{gather}
    W(r) = -\frac{(2l+1)!}{\varkappa \, 2^{2l+1} \Gamma(l+1-Z/\varkappa) \, r^2}.
    \label{eq:wronskian}
\end{gather}
Therefore,
\begin{widetext}    
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% \layout
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{align}
    A_l^\nu(r) =
    \frac{\varkappa \, 2^{2l+1} \Gamma(l+1-Z/\varkappa)}{(2l+1)!}  
    \left[
    \int_0^r dr' \, h_l^\nu(r) g_l^\nu(r') Y(r') \,
    + 
    \int_r^\infty dr' \, g_l^\nu(r) h_l^\nu(r') Y(r') 
    \right].
    \label{eq:particular_solution}
\end{align}

Having obtained the expression for $A_l^\nu(r)$, we can now compute $C_1$ as
\begin{align}
