\begin{eqnarray}
& &\nabla^{(1)Ib}_\mu{\dot x}^{(1)bc,\mu} -\dot{x}^{(1)I,\mu}\nabla_\mu^{(1)Ic} \nonumber\\
&=& \frac{1}{2N}  {F}_{\mu \nu}^b \bar\partial^\nu_p
\left( \frac{\lambda s}{2|\bar p|^2}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta \mathscr{D}^{ bc}_\alpha\right)
- \frac{\lambda s}{2|\bar p|^2}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta \partial^x_\alpha
\left(\frac{1}{2N}  {F}_{\mu \nu}^c \bar\partial^\nu_p\right)\nonumber\\
&=& \frac{\lambda s}{4 N |\bar p|^2}  {F}_{\mu \nu}^b
\left(\bar\epsilon^{\mu\alpha\nu} +\frac{2\bar p^\nu}{|\bar p|^2}\bar \epsilon^{\mu\alpha\beta}\bar p_\beta \right)\mathscr{D}^{ bc}_\alpha
- \frac{\lambda s}{4N|\bar p|^2}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta
\left(\mathscr{D}_{\alpha}^{cb} {F}_{\mu \nu}^b \right)\bar\partial^\nu_p\nonumber\\
&=& \frac{\lambda s}{4 N |\bar p|^4}
\bar\epsilon^{\mu\nu\beta}\bar p_\beta {F}_{\mu \nu}^b \bar p^\alpha \mathscr{D}^{ bc}_\alpha
- \frac{\lambda s}{4N|\bar p|^2}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta
\left(\mathscr{D}_{\alpha}^{cb} {F}_{\mu \nu}^b \right)\bar\partial^\nu_p
\end{eqnarray}
\begin{eqnarray}
& &{\mathscr{D}}^{ca}_\mu \dot{x}^{(2)Ia,\mu}\nonumber\\
&=& - \frac{ \lambda s}{8N|\bar p|^3} \bar\epsilon^{\nu\alpha\beta}\bar p_\beta \hat{\bar p}^\mu
\left({\mathscr{D}}^{ca}_\mu{{ F}^{a}_{\alpha\nu}}\right)
+ \frac{s }{4N|\bar p|^3}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta \left( {\mathscr{D}}^{ca}_\mu {{ F}^{a}_{\alpha n}}\right)
\hspace{2cm} \nonumber\\
& & +  \bar\partial^\beta_p \left[\frac{\lambda  s }{4N|\bar p|^2}\bar\epsilon^{\mu\alpha\nu}\bar p_\nu
\left({\mathscr{D}}^{ca}_\mu { F}^{a}_{\alpha\beta} \right)\right]
