& & + \frac{\lambda  s }{2|\bar p|^2}\bar\epsilon^{\mu\alpha\beta}\bar p_\beta d^{cba}
\left(\mathscr{D}^{be}_\mu { F}^{e}_{\alpha\nu} \right) \bar\partial^\nu_p
-\frac{\lambda }{8|\bar p|}f^{cba}\dot{x}^{(0)\mu} \left({\mathscr{D}}^{be}_\mu  F_{n \nu}^e \right) \bar\partial^\nu_p
\end{eqnarray}
In deriving the above results, we used the following  identities
\begin{eqnarray}
f^{ade}f^{bce}+ f^{bde}f^{cae} + f^{cde}f^{abe} &=& 0,\\
f^{ade}d^{bce}+ f^{bde}d^{cae} + f^{cde}d^{abe} &=& 0.
\end{eqnarray}
Substituting all these results into the equations (\ref{cke-2-I-formal}) and (\ref{cke-2-a-formal}) results in the final results (\ref{cke-I-2-final}) and (\ref{cke-a-2-final}),
respectively.











