    \section{Non-Rectifiability and Repetitivity of the Delone Set}
    %\encodingdefinition*
    \realisable*
    \begin{proof} 
        This statement is attributed to Burago and Kleiner \cite[Lemma $2.1$]{burago1998separated}, with a complete proof contained inside the proof of Lemma~3.4 in \cite{dymond2023highly}, where the following more general statement is shown: If $X$ encodes $\rho$ which does not admit any bi-$\omega$ continuous solution $f\colon [0,1]^{d}\to \R^{d}$ of the equation $f\sharp \rho\leb=\leb|_{f([0,1]^{d})}$, then there is no homogeneous bi-$\omega$ bijection $X\to \Z^{d}$. The reader of the present paper does not need to know the meaning of the notions involving $\omega$, only that $\omega$ stands for a modulus of continuity and that when we take $\omega(t)=t$ the above statement becomes precisely the statement of the present lemma. Below we include a proof of Theorem~\ref{prop:non-rectifiable non-realisable} in succinct form, omitting one delicate part of the argument, for which we refer the reader to \cite[Proof of Lemma~3.4]{dymond2023highly}.

        For each $n \in \N$, since $X$ encodes $\rho$, define $r_n,$ $Q_n,$ $\varphi_n$ and $\mu_n$ congruous with Definition \ref{defn: X encoding rho}.
    Suppose that $X$ is rectifiable for a contradiction, that is, there exist $L\geq 1$ and an $L$-bi-Lipschitz bijection $f:X \rightarrow \Z^d.$ The proof will be structured as follows. We will show there exists a bi-Lipschitz mapping $g:[0,1]^d \to \R^d$ such that 
        $g \# (\rho \mathcal{L}) = \mathcal{L}|_{g([0,1]^d)}.$
    Then by Rademacher's theorem, $\text{Jac}(g)$ exists $a.e.$ on $[0,1]^d,$ and thus by changing variables, we must have that $\rho = \text{Jac}(g) \; a.e.,$ which is a contradiction to the non-realisability of $\rho.$  
    Define the sequence of mappings $g_n:\varphi_n^{-1}(X) \to  \frac{1}{r_n} \Z^d$ to be
    \begin{equation*}
        g_n(x) \coloneqq \frac{1}{r_n} f\circ \varphi_n(x).
    \end{equation*}
    Notice that each $g_n$ is $L$-bi-Lipschitz. Indeed, for $x,y \in \varphi_{n}^{-1}(X)$
    \begin{equation*}
        \begin{split}
            ||g_n(x)-g_n(y)||_2 = \frac{1}{r_n}||f \circ \varphi_n(x) - f \circ \varphi_n (y)||_2
             \leq \frac{L}{r_n}\text{Lip}(\varphi_n)||x-y||_2 = L||x-y||_2,
        \end{split}
    \end{equation*} with a similar calculation for $g^{-1}_n.$ By the Kirszbraun extension theorem \cite{kirszbraun1934zusammenziehende}, for each $n \in \N,$ $g_n|_{[0,1]^d}$ can be extended to an $L-$Lipschitz mapping $\overline{g_n}:[0,1]^d \to \R^d.$  By the Arzelà-Ascoli theorem, the sequence uniformly subconverges to an $L$-Lipschitz mapping $g:[0,1]^d \to \R^d$. Using that each $\overline{g_{n}}$ is actually $L$-bilipschitz on $\varphi_{n}^{-1}(X)$, a $\frac{\sqrt{d}}{r_{n}}$-net of $[0,1]^{d}$, it is straightforward to show that their uniform limit (along a subsequence) $g\colon [0,1]^{d}\to \R^{d}$ is $L$-bilipschitz. Relabel $\overline{g_n}$ as necessary to include only elements from a subsequence that uniformly converges to $g$. By the assumption that $X$ encodes $\rho$, we know that $\mu_n\rightharpoonup \rho\mathcal{L}$. Then by \cite[Lemma~5.6]{dymond2018mapping}, since $\overline{g_n}$ uniformly converges to $g,$ we get that ${\overline{g_n}} \# \mu_n \rightharpoonup g \# (\rho\mathcal{L})$. Separately, by the delicate argument of \cite[Proof of Lemma~3.4]{dymond2018mapping} read with $\omega(t)=t$, we have that ${\overline{g_n}} \# \mu_n \rightharpoonup \mathcal{L}|_{g([0,1]^d)}.$ Thus, by the uniqueness of weak limits, we get that $g\#(\rho\mathcal{L}) = \mathcal{L}|_{g([0,1]^d)}$. 
    \end{proof}
    The next proposition is an extension of~\cite[Lemma~5.5]{dymond2018mapping}. It provides conditions under which a sequence of measures $(\nu_n)_{n\in\N}$ converges weakly to a measure $\nu$.
 \begin{prop}[\cite{dymond2018mapping}, Lemma $5.5,$ extended] \label{5.5 extended} Let $\nu$ and $(\nu_n)_{n \in \N}$ be finite Borel measures on a compact metric space $\mathcal{K}$. Assume that for each $n \in\N$ there are finite collections $\mathcal{Q}_n\supseteq \widetilde{\mc{Q}_{n}}$ of Borel subsets of $\mathcal{K}$ satisfying 
    \begin{equation} \label{prop conditions}
        \begin{split}
        \sum_{Q \in \mathcal{Q}_n}\nu(Q) = \nu(\mathcal{K}),&\qquad \lim_{n \to \infty} \max\{\nu_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}),\nu(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n})\} = 0,\\
        \lim_{n \to \infty}\max_{Q \in \mathcal{Q}_n}\diam(Q) = 0& \qquad \emph{and} \qquad \max_{Q \in \widetilde{\mathcal{Q}_n}}|\nu_n(Q)-\nu(Q)| \in o\left(\frac{1}{|\mathcal{Q}_n|}\right).
        \end{split}
    \end{equation} Then $\nu_n \rightharpoonup \nu$.
    \end{prop}
    \begin{proof}
        Let $\zeta \in C(\mathcal{K};\R)$ and $\epsilon>0.$ For each $Q \in \widetilde{\mathcal{Q}_n},$ choose $z_Q \in Q$ arbitrarily. Since $\mathcal{K}$ is compact, $\zeta$ is uniformly continuous on $\mathcal{K}$, and so by the third condition of (\ref{prop conditions}) there exists $N_1 \in \N$ such that
        \begin{equation*}
            |\zeta(z_Q) - \zeta(x)| \leq \epsilon \qquad \text{for all $n \geq N_1,$ $Q \in \widetilde{\mathcal{Q}_n}$ and $x \in Q$}.
        \end{equation*}
        By the last condition of (\ref{prop conditions}), there exists $N_2 \in \N$ such that
        \begin{equation*}
            \sup_{Q \in \widetilde{\mathcal{Q}_n}}|\nu_n(Q)- \nu(Q)| \leq \frac{\epsilon}{|\mathcal{Q}_n|}\qquad \text{for all $n \geq N_2$}
        \end{equation*}
   and by the second condition of \eqref{prop conditions} there exists $N_3 \in \N$ satisfying 
   \begin{equation*}
    \max\{\nu_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}),\nu(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n})\} \leq \epsilon \qquad \text{for each $n\geq N_{3}$}.
   \end{equation*}
    Now choose $N \coloneqq \max\{N_1,N_2,N_3\}$ and let $n\geq N$. Then
    \begin{equation*}
        \begin{split}
            \int_Q \zeta \; d\nu_n &\leq \int_Q \zeta(z_Q)+\epsilon \; d\nu_n = (\zeta(z_Q)+\epsilon)\nu_n(Q) \leq (\zeta(z_Q)+\epsilon)\left(\nu(Q)+\frac{\epsilon}{|\mathcal{Q}_n|}\right)\\
            &\leq \int_Q (\zeta+2\epsilon) \; d\nu + (\zeta(z_Q)+\epsilon)\frac{\epsilon}{|\mathcal{Q}_n|} \leq \int_Q \zeta\; d\nu + 2\epsilon \nu(Q) + (\zeta(z_Q)+\epsilon)\frac{\epsilon}{|\mathcal{Q}_n|}.
        \end{split}
    \end{equation*}
    Symmetrically, the lower bound obtained is
    \begin{equation*}
        \int_Q \zeta\; d\nu_n \geq \int_Q \zeta\; d\nu - 2\epsilon \nu(Q) -(\zeta(z_Q)+\epsilon)\frac{\epsilon}{|\mathcal{Q}_n|}.
    \end{equation*}
   Summing up the above bound over all $Q \in \widetilde{\mathcal{Q}_n}$ and using the first condition of (\ref{prop conditions}) we get
    \begin{equation*}
        \bigg|\int_{\bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu_n - \int_{\bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu\bigg| \leq 2\epsilon \nu(\mathcal{K}) + \epsilon(||\zeta||_\infty + \epsilon).
    \end{equation*} 
    Moreover,
    \begin{equation*}
    \begin{split}
        \bigg|\int_{\mathcal{K}\setminus \bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu_n\bigg| \leq ||\zeta||_{\infty} \nu_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) \leq ||\zeta||_\infty\epsilon,
        \end{split}
    \end{equation*} 
    with the same bound obtained for $\bigg|\int_{\mathcal{K}\setminus \bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu\bigg|$. Therefore,
    \begin{equation*}
    \begin{split}
        \bigg|\int_\mathcal{K}\zeta \; d\nu_n - \int_\mathcal{K}\zeta \; d\nu\bigg| &\leq \bigg|\int_{\bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu_n - \int_{\bigcup \widetilde{\mathcal{Q}_n}}\zeta \; d\nu\bigg| + \bigg|\int_{\mathcal{K} \setminus {\bigcup \widetilde{\mathcal{Q}_n}}}\zeta \; d\nu_n\bigg| + \bigg|\int_{\mathcal{K} \setminus {\bigcup \widetilde{\mathcal{Q}_n}}}\zeta \; d\nu\bigg|\\
        &\leq 2\epsilon \nu(\mathcal{K}) + \epsilon(||\zeta||_\infty + \epsilon) + 2\epsilon||\zeta||_\infty\;\to 0 \; \text{as} \; \epsilon \to 0.
        \end{split}
    \end{equation*}  
    \end{proof}
    We are now ready to prove our first main result:
   \mainlemma* 
   \begin{proof} 
   Let $D \coloneqq 2^d$. For each $n \in \N,$ let $\epsilon_n \coloneqq \frac{1}{(1-\frac{1}{d}) \log \log(n+100)} \in (0,1).$ Introduce the sequences $(p_n)_{n \in \N}$ and $(c_n)_{n \in \N}$ so that $p_0 \coloneqq 0,$ $c_1 \coloneqq 3$ and for each $n \in \N$
   \begin{equation*}
       p_n = p_{n-1} +1+\bigg\lfloor\frac{1}{d}\log_2(Kn^{1+\epsilon_n}) \bigg\rfloor \qquad \text{and} \qquad c_n = \min\{3\lfloor n^{\frac{\epsilon_n}{Dd}}\rfloor,D(c_{n-1}-2)^{D+1}+2\},
   \end{equation*} where $K \coloneqq D3^{D+1}\sum_{n=1}^\infty{n^{-(1+\epsilon_n(1-\frac{1}{d}))}}.$ It can be verified that $K$ is well-defined using the Cauchy condensation test, and since the first term of the sum is $1,$ we see that $K \geq D3^{D+1} \geq 6^d.$
    Let $(\phi_j^{(n)})_{j \in [c_n],n \in \N}$ be the sequence of palettes from Theorem \ref{intermediate thm} associated with $(p_n)_{n \in \N}, (c_n)_{n \in \N}$ and $\rho$.
    Let $\Psi:\Z^d \to [2]$ be the function from the conclusion of Theorem \ref{main construction} associated with $(\phi_j^{(n)})_{j \in [c_n],n \in \N}$. 
     Let $T_1 \coloneqq \{\frac{1}{2}\}^d$ and $T_2 \coloneqq \set{\frac{1}{4},\frac{3}{4}}\times\set{\frac{1}{2}}^{d-1}.$ Finally, let $X \coloneqq \bigcup_{z\in\Z^{2}}z+T_{\Psi(z)}$.
The sequence of palettes, the function $\Psi$ and the set $X$ are well-defined since $(c_n)_{n \in \N}$ and $(p_n)_{n \in \N}$ satisfy the conditions (\ref{constraint cn pn}) and (\ref{cn tn pn}) respectively. Indeed, for each $n \in \N$, since $K \geq 6^d,$ we see that $p_n-p_{n-1} \geq 2.$ Next, we have for each $n \in \N$ that
\begin{equation*}
    2^{p_{n}-p_{n-1}-1} \geq 2^{\frac{1}{d}\log_2(Kn^{1+\epsilon_n})-1} = \frac{1}{2}K^{\frac{1}{d}}n^{\frac{1+\epsilon_n}{d}} \geq 3n^{\frac{\epsilon_n}{d}}\geq c_n^D,
\end{equation*} where the penultimate inequality holds since $K \geq 6^d.$ By definition, $c_n \leq D(c_{n-1}-2)^{D+1}+2.$ Finally,
\begin{equation*}
    \sum_{n=1}^\infty c_n^D2^{-d(p_{n}-p_{n-1}-1)} \leq \sum_{n=1}^\infty 3^Dn^{\frac{\epsilon_n}{d}}2^{-d(\frac{1}{d}\log_2(Kn^{1+\epsilon_n})-1)} =\frac{D3^D}{K}\sum_{n=1}^\infty n^{-1-\epsilon_n+\frac{\epsilon_n}{d}}=\frac{D3^D}{K}\sum_{n=1}^\infty \frac{1}{n^{1+\epsilon_n(1-\frac{1}{d})}}=\frac{1}{3}.
\end{equation*}Observe for each $n\in \N$ that $c_n\geq 3$. Indeed, $c_1 \coloneqq 3$, and assuming $c_{n-1}\geq 3$, we have that either $c_n = 3\lfloor n^\frac{\epsilon_n}{Dd}\rfloor \geq 3,$ or $c_n = D(c_{n-1}-2)^{D+1}+2,$ in which case we see
   \begin{equation*}
         \frac{D(c_{n-1}-2)^{D+1}}{c_{n-1}-2} = D(c_{n-1}-2)^D \geq {D} >1,
     \end{equation*} meaning $c_n > c_{n-1} \geq 3.$ As a corollary, noting that $n^{\epsilon_n} \to \infty$ as $n \to \infty,$ we have that $c_n$ is unbounded.
Now for each $n \in \N$, let $\varphi_n$ be an affine map taking $[0,1]^d$ to a $d-$dimensional cube of sidelength $2^{p_{n-1}}$ containing a cubic set $S_n \subset \Z^d$ of sidelength $2^{p_{n-1}}$ that satisfies for each $x \in S_n$
    \begin{equation*}
        \Psi(x) = \phi_{c_n}^{(n)}(x-\text{bp}(S_n)).
    \end{equation*} Note these affine maps exist by point (\ref{condition: every colour found somewhere}) of Theorem \ref{main construction}. Let $\mu_n$ be the measure defined on $[0,1]^d$ so that 
    for each $A \subseteq [0,1]^d$
    \begin{equation*}
        \mu_n(A) \coloneqq \frac{1}{2^{dp_{n-1}}}|\varphi_n(A) \cap X|.
    \end{equation*}
        Now we use Proposition \ref{5.5 extended} with $\mathcal{K} = [0,1]^d,$ $\nu_n = \mu_n,$ $\nu = \rho\mathcal{L}$, and $\mathcal{Q}_n =2^{-p_{n-1}}\mathcal{U}_n,$ where we recall from the statement of Theorem \ref{intermediate thm} that
        \begin{equation*}
            \mathcal{U}_n \coloneqq \bigg\{\prod_{i=1}^{d}[(m_{i}-1)2^{p_{n-2}},m_{i}2^{p_{n-2}}):(m_{1},\ldots,m_{d})\in [2^{p_{n-1}-p_{n-2}}]^d\bigg\},
        \end{equation*} and $\widetilde{\mathcal{U}_n} \subset \mathcal{U}_n$ with $|\widetilde{\mathcal{U}_n}| = 2^{d(p_{n-1}-p_{n-2})}-Dc_{n-1}^D.$ We set $\widetilde{\mathcal{Q}_n} = 2^{-p_{n-1}}\widetilde{\mathcal{U}_n} \subset \mathcal{Q}_n$. We must verify that the conditions of Proposition \ref{5.5 extended} hold.  For each $n \geq 2,$ since $c_{n-1}^D \leq 2^{p_{n-1}-p_{n-2}-1}$,
        \begin{equation*}
            \mathcal{L}(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n})  = \frac{Dc_{n-1}^D}{2^{d(p_{n-1}-p_{n-2})}} \leq \frac{D2^{p_{n-1}-p_{n-2}-1}}{2^{d(p_{n-1}-p_{n-2})}} = \frac{1}{2^{(d-1)(p_{n-1}-p_{n-2}-1)}} \to 0 \;
            \; \text{as} \;\; n \to \infty.
        \end{equation*}
     Since $\rho(x) \leq 2$ for all $x \in \mathcal{K}$, \begin{equation*}\nu(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) = \int_{\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}} \rho \; d\mathcal{L} \leq 2\mathcal{L}(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) \to 0 \qquad \text{as} \; n \to \infty.
    \end{equation*} Moreover, since $X$ contains at most two points in each unit volume cube in $\R^d$ with integer coordinates:
    \begin{equation*} \nu_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) = \frac{1}{2^{dp_{n-1}}}|\varphi_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) \cap X| \leq \frac{1}{2^{dp_{n-1}}}2\mathcal{L}(\varphi_n(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n})) = 2\mathcal{L}(\mathcal{K}\setminus\bigcup\widetilde{\mathcal{Q}_n}) \to 0 \qquad \text{as} \; n \to \infty.
    \end{equation*}The first two conditions of (\ref{prop conditions}) are clear. Thus, it suffices to show that
        \begin{equation*}
            \max_{Q \in \widetilde{\mathcal{Q}_n}}|\mu_n(Q) - \rho \mathcal{L}(Q)| \in o\left(\frac{1}{|\mathcal{Q}_n|}\right).
        \end{equation*}
       Note that $|\mathcal{Q}_n| = |\mathcal{U}_n| = 2^{d(p_{n-1}-p_{n-2})}.$ Using (\ref{rho bk}), for each $Q = 2^{-p_{n-1}}U\in \widetilde{\mathcal{Q}_n}$
        \begin{equation*}
            \begin{split}
                \mu_n(Q) &= \frac{1}{2^{dp_{n-1}}}|\varphi_n(Q) \cap X|= \frac{1}{2^{dp_{n-1}}}\sum_{x \in \varphi_n(Q) \cap \Z^d}\Psi(x)=\frac{1}{2^{dp_{n-1}}}\sum_{x \in \varphi_n(Q) \cap \Z^d}\phi_{c_n}^{(n)}(x-\text{bp}(S_n)) =\frac{1}{2^{dp_{n-1}}}\sum_{x \in U \cap \Z^d}\phi_{c_n}^{(n)}(x).
            \end{split}
        \end{equation*}
        Hence, from \eqref{rho bk}, we get
        \begin{equation*}
            \abs{\mu_{n}(Q)-\rho\leb(Q)}\leq \frac{1}{\br{c_{n-1}-2}2^{d(p_{n-1}-p_{n-2})}}=\frac{1}{(c_{n-1}-2)\abs{\mc{Q}_{n}}}.
        \end{equation*}
Therefore, $\mu_n \rightharpoonup \rho\mathcal{L},$ and so $X$ encodes $\rho.$

Let $\widetilde{R}(r)$ stand for the repetitivity function of $\Psi$ from Theorem~\ref{main construction}\eqref{eq: repetitivity function}. By Lemma~\ref{rep from mapping to net}, we have that $X$ is repetitive, with repetitivity function belonging to $O(\widetilde{R}(r))$. To complete the proof, we now show that $\widetilde{R}(r)\in \bigcap_{q>2/d}O(r(\frac{\log r}{\log \log r})^q)$. Fix $q>2/d$. Let $N\geq2$ be large enough so that $p_{N-2}>3$ and $\frac{2(1+\epsilon_{n-1})}{d}<q$ for all $n\geq N$. Now suppose $r>2^{p_{N-2}-1}$ and let $n\geq N$ be the unique integer satisfying $2^{p_{n-2}}<2r\leq 2^{p_{n-1}}$. Notice that 
    \begin{equation}\label{eqn: pnpn2}
        \begin{split}
        2^{p_n-p_{n-2}}= 2^{2+(p_{n}-p_{n-1}-1)+(p_{n-1}-p_{n-2}-1)} = 4\;2^{\frac{1}{d}(\log_2(Kn^{1+\epsilon_n})+\log_2(K(n-1)^{1+\epsilon_{n-1}}}))\\
        \leq 4K^\frac{2}{d}n^\frac{2(1+\epsilon_{n-1})}{d}\leq 4K^{\frac{2}{d}}n^{q}.
        \end{split}
    \end{equation}
   Since $\sum_{j=1}^{n-2} \log_2(j) \geq \int_1^{n-2}\log_2(x)\; dx$ and $\log_2(K) \geq \log_2(6^d) \geq \log_2(32) = 5$, we have
    \begin{equation*}
    \begin{split}
        p_{n-2}&= n-2+ \sum_{j=1}^{n-2}\lfloor\frac{1}{d}\log_2(Kj^{1+\epsilon_j})\rfloor \geq\frac{1}{d} \sum_{j=1}^{n-2}\log_2(Kj)\geq\frac{1}{d}\br{(\log_2K)(n-2)+\sum_{j=1}^{n-2}\log_2(j)}\\
        &\geq \frac{1}{d}\br{5(n-2) + \frac{(n-2)(\log(n-2)-1)+1}{\log 2}} \geq \frac{(n-2)(4+\log(n-2))+1}{d}\geq \frac{n\log_2 n +1}{d}.
        \end{split}
    \end{equation*}
    Therefore,
    \begin{equation*}
        n^n=2^{n \log_2 n} \leq 2^{dp_{n-2}-1}<2^{d-1}r^{d},
    \end{equation*}
    and so using that $\frac{\log x}{\log(x\log x)}\geq \frac{1}{2}$ for all $x>1$ and that the function $\frac{\log x}{\log\log x}$ is increasing on the interval $(e,\infty)$, we get
    \begin{equation}\label{eqn: pn n}
        \frac{1}{2}n \leq  \frac{\log n^n}{\log\log n^n} < \frac{\log(2^{d-1}r^{d})}{\log\log(2^{d-1}r^{d})}\leq \frac{2d\log r}{\log\log r}.
    \end{equation}
    Then by using (\ref{eqn: pnpn2}) and (\ref{eqn: pn n}),
    \begin{equation*}
            \frac{\widetilde{R}(r)}{2r} \leq \sqrt{d}\; 2^{p_{n}-p_{n-2}}\leq \sqrt{d}\; 4K^\frac{2}{d}(4d)^{q}\left(\frac{\log r}{\log \log r}\right)^{q}.
    \end{equation*}
    Hence, $\widetilde{R}(r)\in O\br{r\br{\frac{\log r}{\log\log r}}^{q}}$. 
    \end{proof} 
