(2)
& \symb{f}(\symb{cons}(x_2,\var{xs}_2), y_2) & \to & \symb{f}(\var{xs}_2, y_2 - \symb{1}) & \Constraint{\, x_2 \leq \symb{0} \land y_2 > \symb{0} \,}, \\
