%         and
%     \item for any constrained term $\CTerm{t'}{\psi'} \in P'$, there is no constrained term $\CTerm{u}{\varphi}$ in $P'\setminus\{\CTerm{t'}{\psi'}\}$ such that $\CTerm{t'}{\psi'} \doteq \CTerm{u}{\varphi}$.
% \end{itemize}
$\dot{P}$ denote a minimal set that contains exactly one representative for each equivalence class of constrained terms in $P$.
% Note that $\dot{P}$ is an optimized set of $P$ regarding $\doteq$.
In computing the union of sets of constrained terms, we use the equivalence $\doteq$.
To be more precise, we define the union of (constrained) term sets w.r.t.\ $\doteq$ as follows:
$P \dotcup Q := \dot{U}$, where $U = P \cup Q$.
The disjoint union $\uplus$ w.r.t.\ $\doteq$ is defined as follows:
Given sets $P,Q,U$ of constrained terms, 
$P \dotuplus Q = P \dotcup Q$ if and only if both of the following statements hold:
%\begin{itemize}
    % \item $P \dotcup Q = U$,
%    \item
(i)
for any constrained term $\CTerm{s}{\phi} \in P$, there exists no constrained term $\CTerm{t}{\psi}$ in $Q$ such that $\CTerm{s}{\phi} \doteq \CTerm{t}{\psi}$,
        and
%    \item
(ii)
for any constrained term $\CTerm{t}{\psi} \in Q$, there exists no constrained term $\CTerm{s}{\phi}$ in $P$ such that $\CTerm{s}{\phi} \doteq \CTerm{t}{\psi}$.
%\end{itemize}
We analogously define $\dotcup,\dotuplus$ for unconstrained terms.
% In the rest of the paper,
We abuse $\cup$ and $\uplus$ for $\dotcup$ and $\dotuplus$, respectively.
\end{convention}

\section{Complements of Constructor Terms and Substitutions}
\label{sec:construction-of-complements}

In this section, we define complements of constructor terms and constructor substitutions and then recall the operations in~\cite{LM86,LLT90,HA19pro} to compute finite complements of linear constructor terms and constructor substitutions.
% Together with correctness, we show some properties that are used to prove the correctness of the extension to constrained patterns of LCTRSs.
% As a leading example of this section, ignoring constraints and restricting constructors to $\cCzlist' = \{\symb{nil},\symb{cons},\symb{0},\symb{1}\}$, we use the patterns of the LCTRS $\cRflist$ in Example~\ref{ex:flist}, where $\Sigmaflist' = \{\symb{f}\}\cup\cCzlist'$.
% Correctness of the operations will be shown in Section~\ref{sec:correctness}.
In the rest of the paper, we consider a signature $\Sigma = \cD \uplus \cC$ 
% and its subsignature $\Sigma' \subseteq \Sigma$
without notice.
For examples in this section, we use a subsignature $\Sigmaflist' = \cDflist \cup \cCzlist'$ of $\Sigmaflist$, where $\cDflist=\{\symb{f}\}$ and $\cCzlist' = \{\symb{nil},\symb{cons},\symb{0},\symb{1}\}$.

We first define complements of $\cC$-terms, $\cC$-substitutions, and patterns.
\begin{definition}[complement]
% Let $\Sigma' \subseteq \Sigma = \cD \uplus \cC$. % and $t$ be a $\Sigma'$-term.
A set $P$ of $\cC$-terms is called a \emph{complement} of a $\cC$-term $u:\iota$ if
% $\{ t \in T(\cC) \mid t:\iota \} = \GInst[\cC]{u} \uplus \GInst[\cC]{P}$.
$\GInst[\cC]{P} = \{ t \in T(\cC) \mid t:\iota \} \setminus \GInst[\cC]{u}$.
A set $\Theta$ of $\cC$-substitutions is called a \emph{complement} of a $\cC$-substitution $\sigma$ w.r.t.\ a term $t \in T(\Sigma,\cV)$ if 
% $\GInst[\cC]{t} = \GInst[\cC]{t\sigma} \uplus \GInst[\cC]{\{ t\rho \mid \rho \in \Theta, \, t\sigma \ne t\rho \}}$.
$\GInst[\cC]{\{ t\rho \mid \rho \in \Theta, \, t\sigma \ne t\rho \}} = \GInst[\cC]{t} \setminus \GInst[\cC]{t\sigma}$.
% \begin{itemize}
%     \item $\Dom(\rho)=\Dom(\sigma)$ for any $\rho \in \Theta$, and 
%     \item $\GInst[\Sigma']{u} = \GInst[\Sigma']{u\sigma} \uplus \GInst[\Sigma']{\bigcup_{\rho \in \Theta} u\rho}$ for any term $u \in T(\Sigma,\Dom(\sigma))$.
% \end{itemize}
A set $P$ of patterns is called a \emph{complement} of a pattern $f(s_1,\ldots,s_n)$ if
% $\{ f(t_1,\ldots,t_n) \mid t_1,\ldots,t_n \in T(\cC) \} = \GInst[\cC]{f(s_1,\ldots,s_n)} \uplus \GInst[\cC]{P}$.
$\GInst[\cC]{P} = 
% \{ f(t_1,\ldots,t_n) \mid t_1,\ldots,t_n \in T(\cC) \}
\GInst[\cC]{f(x_1,\ldots,x_n)}
\setminus \GInst[\cC]{f(s_1,\ldots,s_n)}$,
where $x_1,\ldots,x_n$ are pairwise distinct variables.
% Note that any term $t \in P$ is rooted by $f$.
A set $P$ of patterns is called a \emph{complement} of a set $Q$ of patterns if 
% $\{ f(t_1,\ldots,t_n) \mid f \in \cD, \, t_1,\ldots,t_n \in T(\cC) \} = 
% \GInst[\cC]{Q} \uplus \GInst[\cC]{P}$.
$\GInst[\cC]{P} = 
% \{ f(t_1,\ldots,t_n) \mid f \in \cD, \, t_1,\ldots,t_n \in T(\cC) \}
\GInst[\cC]{\{ f(x_1,\ldots,x_n) \mid f \in \cD \}}
\setminus 
\GInst[\cC]{Q}$,
where $x_1,\ldots,x_n$ are pairwise distinct variables.
\end{definition}
Note that complements %of $\cC$-terms, $\cC$-substitutions, and patterns
are not unique in general.
Note also that complements of variables and the identity substitution are the empty set.
% This paper considers finite complements only.

