    where $c : \iota_1 \times \cdots \times \iota_n \to \iota \in \cC$,
    $x_1,\ldots,x_m$ are pairwise distinct variables, and $y_{i+1},\ldots,y_n$ are pairwise distinct fresh variables for any $i \in \{1,\ldots,n\}$.
%\end{itemize}
\end{definition}
