The construction below for $\cC$-substitutions is based on the construction $\Cocterm{\Cdot}$ for linear $\cC$-terms, and thus it works on \emph{linear} substitutions.
A substitution $\sigma$ is called \emph{linear w.r.t.\ $X \subseteq \cV$} ($X$-linear, for short) if 
$x\sigma$ is linear for any variable $x \in X$.
A $\cV$-linear substitution is simply called \emph{linear}.
\begin{definition}[{$\Cosubst[\cC]{\sigma}$} of linear $\cC$-substitution $\sigma$~\cite{HA19pro}]
\label{def:Cosubst}
    Let %$\Sigma' \subseteq \Sigma$, 
% $X \subseteq \cV$, and 
$\sigma$ be a linear $\cC$-substitution.
We define a set $\Cosubst[\cC]{\sigma}$ of substitutions as follows:
$
\Cosubst[\cC]{\sigma} = \{ \rho \mid \Dom(\rho) = \Dom(\sigma), ~ \rho \ne \sigma, 
%~ \forall x \in \Dom(\rho).\ x\rho \in \Cocterm{x\sigma} \cup \{x\sigma\}
~ \forall x \in \Dom(\sigma).\ x\rho \in  \Cocterm[\cC]{x\sigma} \cup \{x\sigma\}
\}
$.
\end{definition}
% Note that $\rho \in \Cosubst[\cC]{\sigma}$, which is not equivalent to $\sigma$, is obtained from $\sigma$ by replacing $x\sigma$ by a term in $\Cocterm[\cC]{x\sigma}$ for at least one variable $x \in \Dom(\sigma)$.
For a linear $\cC$-substitution $\sigma$ and a linear $\cC$-term $t$,
$\{ \rho \mid \rho \in \Cosubst[\cC]{\sigma}, \, t\rho \ne t\sigma \}$ is a finite complement of $\sigma$ w.r.t.\ $t$
(i.e.,
% $\GInst[\cC]{t} = \GInst[\cC]{t\sigma} \uplus \bigcup_{\rho \in \Cosubst[\cC]{\sigma},\, t\rho \ne t\sigma} \GInst[\cC]{t\rho}$.
$
% \bigcup_{\rho \in \Cosubst[\cC]{\sigma},\, t\rho \ne t\sigma} \GInst[\cC]{t\rho}
\GInst[\cC]{\{ t\rho \mid \rho \in \Cosubst[\cC]{\sigma},\, t\rho \ne t\sigma \}}
=
\GInst[\cC]{t} \setminus \GInst[\cC]{t\sigma}$),
which is a finite set of linear $\cC$-substitutions.
% (see Proposition~\ref{prop:Cosubsts-correctness}).

\begin{example}
For $\cCzlist'=\{\symb{nil},\symb{cons},\symb{0},\symb{1}\}$,
we have that 
$\Cosubst[\cCzlist']{\{ \var{xs} \,{\mapsto}\, \symb{nil}, \, y \,{\mapsto}\, \symb{0} \}}
=
\{ \{ \var{xs} \,{\mapsto}\linebreak \symb{nil}, \, y \,{\mapsto}\, \symb{1} \}, \, \{ \var{xs} \,{\mapsto}\, \symb{cons}(x',\var{xs}'), \, y \,{\mapsto}\, \symb{0} \}, \, \{ \var{xs} \,{\mapsto}\, \symb{cons}(x',\var{xs}'), \, y \,{\mapsto}\, \symb{1} \} \}$. % which is a complement of $\{ \var{xs} \mapsto \symb{nil}, \, y \mapsto \symb{0} \}$.
\end{example}

