\begin{restatable}[correctness of $\CTerm{s}{\phi} \ominus \CTerm{t}{\psi}$]%$\ominus$ over constrained patterns]%
{theorem}{ThmConstrainedPatternOminusPropertiesX}
\label{thm:constrained-pattern-ominus-propertiesX}
% Let % $\Sigma = \cD \uplus \cC$, and 
