For a value-free constrained pattern $\CTerm{s}{\phi}:\iota$ and a value-free constrained linear pattern $\CTerm{t}{\psi}$,
$\CTerm{s}{\phi} \ominus \CTerm{t}{\psi}$ is a finite set of value-free constrained patterns with sort $\iota$
such that
\begin{enumerate}
    \item $\GInst[\cC]{\CTerm{u}{\varphi}} \cap \GInst[\cC]{\CTerm{u'}{\varphi'}} = \emptyset$ for any different constrained patterns $\CTerm{u}{\varphi},\CTerm{u'}{\varphi'} \in 
    (\CTerm{s}{\phi} \ominus \CTerm{t}{\psi})$,
    \item if $\CTerm{s}{\phi}$ is linear, then $\CTerm{s}{\phi} \ominus \CTerm{t}{\psi}$ is a set of constrained linear patterns,
    \item $s < u$ for any constrained term $\CTerm{u}{\varphi} \in (\CTerm{s}{\phi} \ominus \CTerm{t}{\psi})$,
    \item $\max\{\Height{s},\Height{t}\} \geq \Height{u}$ for any term $\CTerm{u}{\varphi} \in (\CTerm{s}{\phi} \ominus \CTerm{t}{\psi})$,
        and
    \item $\GInst[\cC]{\CTerm{s}{\phi} \ominus \CTerm{t}{\psi}} = \GInst[\cC]{\CTerm{s}{\phi}} \setminus \GInst[\cC]{\CTerm{t}{\psi}}$.
\end{enumerate}
\end{restatable}
\begin{proof}[Sketch]
