such that $\Sigterm$ is finite and there is no constructor $c: \iota_1 \times \cdots \times \to \iota \in \cC_\cR$ with $\iota \in \cStheory$.
%$\{ t:\iota \in T(\cC)\setminus \Val \mid \iota \in \cStheory\} = \emptyset$.
Then, $\cR$ is quasi-reducible if and only if $\CopatternSet{\{ \CTerm{\tilde{\ell}}{\tilde{\phi}} \mid \ell \to r ~[\phi] \in \cR, ~ \mbox{$\ell$ is a pattern}\}} = \emptyset$.
Thus, quasi-reducibility is decidable for such LCTRSs with decidable built-in theories.%
\footnote{It is sufficient that all constraints of constrained rewrite rules in $\cR$ are in a class of a decidable theory.
For example, the integer theory is not decidable, but the constraints of $\cRflist$ and $\cRflist'$ are formulas of Presburger arithmetic.
}
\end{restatable}
\begin{proof}[Sketch]
Since the built-in theory is decidable, 
by the well-founded order in the proof of Theorem~\ref{thm:constrained-set-ominus-properties},
the set $\CopatternSet{\{ \CTerm{\tilde{\ell}}{\tilde{\phi}} \mid \ell \to r ~[\phi] \in \cR, ~ \mbox{$\ell$ is a pattern}\}}$ is computable, and thus
its emptiness is decidable.
Therefore, quasi-reducibility of $\cR$ is decidable.
% A complete proof can be seen in~\cite{NKN25frocosFULL}.
A complete proof can be seen in the appendix.
\qed
\end{proof}

\begin{example}
