\section*{Appendix}

Here, we derive the results quoted in section 6.
The autocorrelation (\ref{bacry}) of the Gaussian field $\tilde\phi$ of the MRW in background time $\hat t$ is:
$$\langle\tilde\phi(0)\tilde\phi(\hat t)\rangle=(\ln\tau-\ln\hat t)\ \ \ \Rightarrow  \ \ \ \langle\tilde\phi^2\rangle=\ln\tau$$
with correlation time $\tau$.
Physical time $T$ in (\ref{ptime}) and the moments $m_n$, viewed as stochastic processes (\ref{pmoment}) whose expectation value is $M_n=\langle m_n\rangle$, are defined as
\begin{eqnarray}
T(\hat T)&\equiv& \hat T\cdot e^{\alpha\psi(\hat T)}\ =\  \int_0^{\hat T}d\hat t\ e^{\alpha\tilde\phi(\hat t)},\label{A1}\\
m_2(\hat T)&\equiv& \hat T^{1-\Delta_i}\cdot e^{2\alpha_i\psi_2(\hat T)}\ 
\propto\ \int_0^{\hat T}d\hat t_1\ d\hat t_2\ \vert\hat t_1-\hat t_2\vert^{-1-\Delta_i}\ e^{\alpha_i\tilde\phi(\hat t)}\ e^{\alpha_i\tilde\phi(\hat s)},\label{A2}\\
m_n(\hat T)&\equiv& \hat T^{{n\over2}(1-\Delta_i)}\cdot e^{n\alpha_i\psi_n(\hat T)}\ 
\propto\  \int_0^{\hat T}d^n\hat t\ \prod_{k=1}^n e^{\alpha_i\tilde\phi(\hat t_k)}\cdot\langle\prod_{k=1}^n\dot{\hat\pi}_i(\hat t_k)\rangle. \label{A3}
\end{eqnarray}
To compute the Hurst exponents $H_n$ in physical time $T$ for the process shown in fig. 1, we need to know (i) the drifts, (ii) the variances, 
and (iii) the covariances and correlations of the "effective fields" $\psi, \psi_n$ as functions of $\hat T$. 
We will calculate them for $\hat T\ll\tau$ in the region $\alpha^2<1, \Delta_i<0, \alpha_i^2<\vert\Delta_i\vert$, where our integrals converge, 
and then analytically continue the results to general $\alpha,\Delta_i,\alpha_i$. \\

To compute the drift and variance of the Gaussian random variable $\psi$, we first apply Ito's lemma to the expectation values
$$\langle e^{\alpha\tilde\phi}\rangle=e^{{1\over2}\alpha^2\langle\tilde\phi^2\rangle}=\tau^{{1\over2}\alpha^2}\ \ \ ,
\ \ \ \langle e^{\alpha\psi}\rangle= e^{\alpha\langle\psi\rangle+{1\over2}\alpha^2\langle\psi^2\rangle_c},\ \ \ \text{where}\ \ \ \langle\psi^2\rangle_c=\langle\psi^2\rangle-\langle\psi\rangle^2$$
is the variance of the effective field $\psi(\hat T)$. Integrating (\ref{A1}) yields the relation  
\begin{eqnarray} 
\langle T\rangle =\hat T\cdot \langle e^{\alpha\tilde\phi}\rangle=\hat T\cdot \tau^{{1\over2}\alpha^2}\ \ \ 
\Rightarrow\ \ \ \alpha\langle\psi\rangle+{\alpha^2\over2}\langle\psi^2\rangle_c={\alpha^2\over2}\ln\tau.\label{first}
\end{eqnarray}
The simple solution $\langle\psi\rangle=0, \langle\psi^2\rangle_c=\alpha^2/2\cdot\ln\tau$ turns out not to be the correct one. To see this, we derive
a second relation between $\langle\psi\rangle$ and $\langle\psi^2\rangle_c$ by applying Ito's lemma to $\langle T^2\rangle$:
\begin{equation}
\langle T^2\rangle=\hat T^2\cdot\langle e^{2\alpha\psi}\rangle =\hat T^2\cdot e^{2\alpha\langle\psi\rangle+2\alpha^2\langle\psi^2\rangle_c}.\label{A4}
\end{equation}
On the other hand, inserting (\ref{A1}) for $T$ and performing the double integral yields
\begin{eqnarray}
\langle T^2\rangle &=&  \int_0^{\hat T}d\hat t_1\ d\hat t_2\ \vert\hat t_{12}\vert^{-\alpha^2}\ \tau^{2\alpha^2}
\ =\ C_1\cdot \hat T^{2-\alpha^2}\ \tau^{2\alpha^2},\ \ \ \text{where}\ \ \hat t_{12}\equiv \hat t_1-\hat t_2,\label{A5}
\end{eqnarray}
and $C_1=2/[(1-\alpha^2)(2-\alpha^2)]$ is an integration constant. 
Here, self-contractions of $\phi$ at the same point have contributed two factors of $\tau^{\alpha^2/2}$.
Combining (\ref{A5}) with (\ref{A4}) yields:
\begin{eqnarray}
{2\alpha\langle\psi\rangle+2\alpha^2\langle\psi^2\rangle_c}&=&-\alpha^2\ln \hat T+2\alpha^2\ln \tau +\ln C_1.\notag
\end{eqnarray}
Together with (\ref{first}), this yields the drift and variance of the effective field $\psi$:
\begin{eqnarray}
\langle\psi^2\rangle_c&=&(\ln\tau-\ln \hat T)\ +\ c_1\ \ \ ,
\ \ \ \alpha\langle\psi\rangle={\alpha^2\over2}\ln \hat T\ +\ b_1,\label{parphi}
\end{eqnarray}
where we have defined the new constants $c_1\equiv(\ln C_1)/\alpha^2,\ b_1=-(\ln C_1)/2$. We see that the gravitational dressing gives physical log-time an additional drift $\alpha^2/2$ 
in background log-time $\ln \hat T$, and a noise volatility $\alpha$ that shrinks to 0 at the correlation time.\\

Analoguously, we compute the scaling of the mean and variance of $\psi_2$ in the second moment (\ref{A2}) for $m_2$, 
once by using Ito's lemma and once by performing the integrals:
\begin{eqnarray}
\langle m_2\rangle&=&\hat T^{1-\Delta_i}\cdot \langle e^{2\alpha_i\psi_2}\rangle\ =\ \hat T^{1-\Delta_i}\cdot e^{2\alpha_i\langle\psi_2\rangle+2\alpha_i^2\langle\psi_2^2\rangle_c}\notag\\
&\propto&\int_0^{\hat T}d\hat t_1\ d\hat t_2\ \vert\hat t_{12}\vert^{-1-\Delta_i-\alpha_i^2}\ \tau^{\alpha_i^2+2\cdot{1\over2}\alpha_i^2}\ =\ B_2\cdot \hat T^{1-\Delta_i-\alpha_i^2}\ \tau^{2\alpha_i^2}  \label{A6}\\
\langle m_2^2\rangle &=&\hat T^{2-2\Delta_i}\cdot\langle  e^{4\alpha_i\psi_2}\rangle \ =\ \hat T^{2-2\Delta_i}\cdot e^{4\alpha_i\langle\psi_2\rangle+8\alpha_i^2\langle \psi_2^2\rangle_c}\notag\\
&\propto&\int d^4\hat t\ \vert\hat t_{12}\hat t_{34}\vert^{-1-\Delta_i-\alpha_i^2}\ \vert\hat t_{13}\hat t_{14}\hat t_{23}\hat t_{24}\vert^{-\alpha_i^2}\ \tau^{6\alpha_i^2+{4\over2}\alpha_i^2}
\ =\ C_2\cdot\hat T^{2-2\Delta_i-6\alpha_i^2}\ \tau^{8\alpha_i^2}  \notag
\end{eqnarray}
with integration constants $B_2,C_2$. Generalizing this to $m_n$ yields the two equations
\begin{eqnarray}
{n\alpha_i\langle\psi_2\rangle+{n^2\over2}\alpha_i^2\langle\psi_2^2\rangle_c}
&=&-{n(n-1)\over2}\alpha_i^2(\ln\hat T-\ln\tau)\ +\ {n\over2}\alpha_i^2\ln\tau\  +\ \ln B_n, \notag\\
{2n\alpha_i\langle\psi_2\rangle+2n^2\alpha_i^2\langle \psi_2^2\rangle_c}
&=&-n(2n-1)\alpha_i^2(\ln\hat T-\ln\tau)\ +\ n\alpha_i^2\ln\tau\   +\ \ln C_n. \notag
\end{eqnarray}
Combining them, one finds for the variances and drifts:
\begin{eqnarray}
\langle\psi_n^2\rangle_c&\sim& (\ln\tau-\ln\hat T)+{c_n},
\ \ \ \alpha_i\langle\psi_n\rangle\ \sim\  {\alpha_i^2\over2}\ln \hat T\ +b_n,\label{parphin}
\end{eqnarray}
with new constants 
$$c_n\equiv{\ln (C_n/B_n^2)\over n^2\alpha_i^2}\ ,\ \ \ b_n={\ln (B_n^4/C_n)\over2n}\ .$$
We observe that the effective field $\psi_n$ has drift $\alpha_i/2$ in log time. The variance of its noise shrinks linearly in log time and becomes zero at the correlation time,
analogously to that of $\psi$.\\

Finally, we derive the covariance and correlation of $\psi$ and $\psi_n$ in an analogous manner:
\begin{eqnarray}
\langle T,m_2\rangle &=&\hat T^{2-\Delta_i} \langle e^{\alpha\psi}e^{2\alpha_i\psi_2}\rangle\ 
=\ \hat T^{2-\Delta_i} e^{\alpha\langle\psi\rangle+2\alpha_i\langle\psi_2\rangle+{1\over2}\alpha^2\langle\psi^2\rangle
+2\alpha_i^2\langle\psi_2^2\rangle+2\alpha\alpha_i\langle\psi,\psi_2\rangle_c}.\label{cov}
\end{eqnarray}
On the other hand, inserting the three integrals in (\ref{A1},\ref{A2}) for $T$ and $m_2$ yields the scaling
\begin{eqnarray}
\langle T,m_2\rangle %&=&\int_0^{\hat T}d\hat t_1\ d\hat t_2\ d\hat t_3\ 
&=&\int_0^{\hat T}d^3\hat t\ \vert t_{23}\vert^{-1-\Delta_i-\alpha_i^2}\ \vert t_{12}t_{13}\vert^{-\alpha\alpha_i}\cdot\tau^{\alpha_i^2+2\alpha\alpha_i+{1\over2}(\alpha^2+2\alpha_i^2)}\notag\\
&=&D_2\cdot\hat T^{2-\Delta_i-2\alpha\alpha_i-\alpha_i^2}\ \tau^{2\alpha\alpha_i+2\alpha_i^2+{1\over2}\alpha^2},\ \ \ \text{where}\ \ D_2\in R\notag
\end{eqnarray}
is another integration constant. Combining this with (\ref{cov}) and using (\ref{parphi},\ref{parphin}) yields
$$\langle\psi,\psi_2\rangle_c=(\ln\tau-\ln \hat T) + d_2\ \ \ \text{with}\ \ \ d_2\equiv{1\over 2\alpha\alpha_i}\ln D_2.$$
The correlation is the covariance divided by the square roots of the two variances:
\begin{eqnarray}
\text{cor}(\psi,\psi_2)&=&  {\langle\psi,\psi_2\rangle_c\over\langle\psi^2\rangle_c^{1/2}\langle\psi_2^2\rangle_c^{1/2}}
 \ =\ {\big[\ln(\tau/\hat T)+d_2\big]\over \big[\ln(\tau/\hat T)+ c_1\big]^{1/2}\big[\ln(\tau/\hat T)+c_2\big]^{1/2}}\ \sim\ 1-o\Big({1\over\ln \tau/\hat T}\Big)\notag
\end{eqnarray}
(the sign in the last equation must be negative as correlations are $\le1$).
We see that the deviation of the correlation of $\psi$ and $\psi_2$ from 1 is small for $\hat T\ll\tau$. 
This also applies to the higher moments $m_n$ (we omit the derivation, which is completely analogous).\\

The integrals (\ref{A5}, \ref{A6}) diverge at $\hat t_1\rightarrow\hat t_2$ for $\alpha\ge1$ and for $\Delta_i+\alpha_i^2>0$, respectively. 
In the original 2+1-dimensional field theory, this is when the two random surfaces at $\hat t_1,\hat t_2$ coincide.
These divergences mirror divergences that already occur in the ``static limit", i.e., in the 2-dimensional field theory of section 4 without the time dimension,
when two operators at different points on the surface approach each other.  
In the renormalization process, these divergences are removed by counterterms.
We assume that the renormalized moments are analytic functions and that our results, including formulas (\ref{beta}, \ref{gam2}, \ref{hurstn}) of section 7,
can be continued to general values of $\alpha,\alpha_i$ and $\Delta_i$.
The same applies to the higher moments.

