\section{\label{app:threebody}Three body decays} 


The branching ratio of a three-body decay process can be evaluated from the following expression:

\begin{equation}
    \frac{d^2 \text{BR}_{\phi_{l/\nu}}({\texttt{m} \to l^{\pm}\nu_l\phi})}{dm_{12}^2 dm_{23}^2} = \frac{1}{(2\pi)^3 32 m_\texttt{m}^3 \Gamma_{\texttt{m}}} |\mathcal{M}_{\phi_{l/\nu}}({\texttt{m} \to l^{\pm}\nu_l\phi})|^2
    \label{eq:diffdecay}
\end{equation}

The matrix element squared for $\texttt{m} \to l^{\pm}\nu_l\phi$ for a neutrinophilic scalar is:

\begin{equation}
    \begin{aligned}
        |\mathcal{M}_{\phi_\nu}({\texttt{m} \to l^{\pm}\nu_l\phi})|^2 &=  \frac{4G_F^2 V_{uq}^2 f_{\texttt{m}}^2 y_{\nu}^2}{(-m_{12}^2 -m_{23}^2 + m_{\mu}^2 + m_{\texttt{m}}^2 + m_{\phi}^2)^2}\bigg((m_{12}^6 + m_{12}^4(m_{23}^2 - 2(m_{\phi}^2 + m_{\texttt{m}}^2) - m_l^2) \\&+ m_{12}^2(m_{23}^4 - m_{23}^2(2(m_{\phi}^2 + m_{\texttt{m}}^2) + m_l^2) + (m_\phi^2 + m_{\texttt{m}}^2)^2+2m_{\phi}^2m_l^2)\\ & m_l^2 (m_\phi^2(m_{23}^2 - m_{\texttt{m}}^2) + m_{\texttt{m}}^2(m_{\texttt{m}}^2 + m_l^2 - m_{23}^2) - m_{\phi}^4) \bigg)
    \end{aligned}
    \label{eq:neuphilic_matel}
\end{equation}

For the electrophilic(muonphilic) scalar where the scalar emanates from the electron(muon) leg, the matrix element squared is,
\begin{equation}
    \begin{aligned}
        |\mathcal{M}_{\phi_l}({\texttt{m} \to l^{\pm}\nu_l\phi})|^2 &= y_{22}^2 \frac{4G_F^2 V_{uq}^2 f_{\texttt{m}}^2}{(m_{23}^2 - m_{l}^2)^2} \bigg(m_{23}^2 (m_{12}^2 + m_{23}^2 - m_{\phi}^2) 
        (m_{23}^2 - m_{l}^2) +   
        2 m_{23}^2 m_{l}^2 (-m_{23}^2 + m_{\texttt{m}}^2) \\&- (m_{23}^2 - m_{\phi}^2 + m_{l}^2) (m_{23}^4 - m_{l}^2 m_{\texttt{m}}^2) \bigg)
    \end{aligned}
    \label{eq:lepphilic_matel}
\end{equation}
where the limits of integration are,
\begin{equation}
    \begin{aligned}
        m_{l}^2 \leq &m_{12}^2 \leq (m_\texttt{m} - m_{\phi})^2\\
        (E_{l}^* + E_{\phi}^*)^2 - (p_{l}^* + p_{\phi}^*)^2 \leq &m_{23}^2 \leq (E_{l}^* + E_{\phi}^*)^2 - (p_{l}^* - p_{\phi}^*)^2
    \end{aligned}
    \label{eq:m12lims}
\end{equation}

To integrate over $m_{23}^2$ while fixing the value of $m_{12}^2$, we choose a frame where $p_1 + p_2$ is at rest. The quantities with the star describe those in the rest frame of $p_1+p_2$. These quantities are as follows,

\begin{equation}
    \begin{aligned}
        E_l^* = \frac{m_{12}^2 + m_l^2}{2\sqrt{m_{12}}}&; \quad
        E_\phi^* = \frac{m_{\texttt{m}}^2 - m_{12}^2 - m_\phi^2}{2\sqrt{m_{12}}} \\
        p_{l,\phi}^* &= \sqrt{E_{l,\phi}^{*2} - m_{l,\phi}^2}
    \end{aligned}
    \label{eq:m23energies}
\end{equation}

The energy of the scalar in the rest frame of the decaying meson can be found for a given Dalitz variable.

\begin{equation}
    E_{\phi} = \frac{m_{\texttt{m}}^2 + m_{\phi}^2 - m_{12}^2}{2m_{\texttt{m}}} 
    \label{eq:energyphi}
\end{equation}

