\section{Introduction}\label{sec:int}

The projective splitting (PS) algorithm was originally proposed by Eckstein and Svaiter in \cite{ES08, ES09} and has since been studied and extended in various directions, including:
(i) PS variants for solving coupled and more general forms of monotone 
inclusions~\cite{Alg+14, ACS14, BC20, BC22};
(ii) asynchronous and block-iterative implementations~\cite{CE18};
(iii) modifications incorporating inertial effects in the iteration process~\cite{AGM24, CG17, Mac25};
(iv) PS-type algorithms with forward and forward-backward steps for subproblems~\cite{JE21, JE22};
(v) a proximal-Newton-type PS algorithm for solving inclusions with smooth operators~\cite{Alv25}; and
(vi) the analysis of convergence rates and iteration-complexity~\cite{EJ19, MS23}.

\mgap

The PS method is designed to numerically solve multi-term (finite-sum) monotone inclusion problems involving finitely many maximal monotone maps, as well as compositions with bounded linear operators (see problem \eqref{eq:probr} below). The main idea is to embed \eqref{eq:probr} into an enlarged product space, reformulating the monotone inclusion problem as a convex feasibility problem that seeks a point in an extended-solution set (see \eqref{eq:KTS}). Given the feasibility problem, cutting planes are constructed using affine 
functionals (see \eqref{eq:localiz} and \eqref{eq:sep.F} below) derived from 
elements in the graph of (the enlargements of) the maximal monotone operators associated with the original problem \eqref{eq:probr}. 
The new framework is more flexible than existing operator splitting methods and demonstrates promising numerical performance in certain 
applications (see, e.g. \cite{JE22}).

\mgap

It is well known that proximal algorithms typically converge weakly (see, e.g., \cite{Gul91, Roc76}), requiring modifications in the iteration mechanism to achieve strong convergence of iterates (see, e.g., \cite{BC01, BC11}). In the context of modern inexact relative-error proximal algorithms~\cite{MS10, SS99b}, this approach was first introduced in \cite{SS00}, where an inexact proximal-type algorithm with strong convergence guarantees for monotone inclusions was proposed.

\mgap

In this paper, we propose and analyze an inertial inexact PS algorithm with strong convergence guarantees. 
Our new PS variant (see Algorithm \ref{alg:iHPEP} below) maintains essentially all attractive properties of 
previous versions while ensuring strong convergence of iterates to the best approximation of the initial guess in the extended-solution set. To the best of our knowledge, this is the first time in the literature that an inertial inexact PS-type algorithm with strong convergence has been proposed. Furthermore, building on Algorithm \ref{alg:iHPEP}, we introduce two variants that incorporate forward-backward and forward-backward-forward (Tseng) steps for subproblems (see Algorithms \ref{alg:iHPEP-FB} and \ref{alg:iHPEP-Tseng-FB}).

\mgap

The rest of the paper is organized as follows. In Section \ref{sec:gn}, we introduce the general notation used in this paper and present some basic results. In Section \ref{sec:main}, we propose and analyze our main algorithm, namely Algorithm \ref{alg:iHPEP}. In Section \ref{sec:FB-TFB}, we introduce two variants of Algorithm \ref{alg:iHPEP} by incorporating forward-backward and forward-backward-forward (Tseng) steps for subproblems. 
Section \ref{sec:conc} is devoted to concluding remarks.
In Appendix \ref{app:well}, we prove that Algorithm \ref{alg:iHPEP} is well-defined, and in Appendix \ref{app:ar}, we provide some auxiliary results.


%\newpage
\section{General notation and some basic results}
\lab{sec:gn}

\subsection{General notation}

Let $\Ha$ be a Hilbert space with inner product $\inner{ \cdot}{ \cdot}$ and induced norm $\norm{\cdot} = \sqrt{\inner{\cdot}{ \cdot}}$.
%
The \emph{effective domain} and \emph{graph} of a set-valued map $T\colon \HH\tos \HH$ are defined, respectively, by $\Dom T = \set{x \in \HH \mid T(x) \neq \emptyset}$ and 
$\Gra T = \{(x,u) \in \Ha \times \Ha \mid u \in T(x)\}$.
%
A set-valued map $T \colon \Ha \tos \Ha$ is said to be \emph{monotone operator} if $\inner{x - y}{u - v} \geq 0$ for all $u \in T(x)$ and $v \in T(y)$, and \emph{maximal monotone} if it is monotone and its graph 
is not properly contained in the graph of any other monotone operator on $\Ha$. 
%
The inverse of $T \colon \Ha \tos \Ha$ is $T^{-1} \colon \Ha \tos \Ha$, defined at any $x \in \Ha$ by $u \in T^{-1}(x)$ if and only if $x \in T(u)$. 
%
The operator $\gamma T \colon \Ha \tos \Ha$, for $\gamma > 0$, is defined  by $(\gamma T)x := \gamma T(x):=\{\gamma u \mid u \in T(x) \}$.
%
The sum of $T \colon \Ha \tos \Ha$ and $S \colon \Ha \tos \Ha$ is defined by $(T+S)(x)=\{ u + v \mid u \in T(x),\; v \in S(x)\}$. 
%
The \emph{resolvent} of a maximal monotone operator $T \colon \Ha \tos \Ha$ is $J_T:=(T + I)^{-1}$, where $I$ denote the identity operator on $\Ha$. 
%
For a set-valued map $T \colon \Ha \tos \Ha$ and $\varepsilon \geq 0$, the $\varepsilon$-\emph{enlargement} of $T$, $T^{[\varepsilon]}\colon \Ha \tos \Ha$, is defined as
\begin{align} \lab{def:enlarg}
 T^{[\varepsilon]}(x) = \{u \in \Ha \mid \inner{x - y}{u - v} \geq - \varepsilon \enspace \mbox{ for all } (y, v) \in \Gra T\}.
\end{align}
%
Whenever necessary, we will identify single-valued maps $F\colon \Dom F \subseteq \HH \to \HH$ with its
set-valued representation $F: \HH \tos \HH$ by $F(x) = \set{F(x)}$.
%
For a nonempty closed and convex set $ C $, the \emph{orthogonal projection} operator onto $C$ is denoted by $P_C$, i.e., $P_C(x)$ is defined as the unique element in $C$ such that 
$\norm{x - P_C(x)} \leq \norm{x-y}$ for all $y \in C$. 
%The  \emph{normal cone} operator of $C$ is the set-valued map $N_C \colon \Ha \tos \Ha$ defined by $N_C(x)=\%{v \mid \inner{v}{y-x} \leq 0, \mbox{ for all }y\in C\}$ if $x \in C$ and $N_C(x) = \emptyset$ if $x \notin 	C$. 
%
\emph{Strong} and \emph{weak} convergence of sequences are denoted by the symbols $\to$ and $\wto$, respectively. 
%
The \emph{adjoint} of a bounded linear operator $ B $ on $ \HH $ is denoted by $ B^* $ and its \emph{norm} is
defined by $ \norm{B}\coloneqq \sup_{\norm{x}\leq 1}\,\norm{Bx} $.

\mgap

Now let $\HH_0, \HH_1,\ldots, \HH_{n-1}$ be real Hilbert spaces, let $\HH_n \coloneqq \HH_0$ and let $\inner{\cdot}{\cdot}$ and
 $\|\cdot\| = \sqrt{\inner{\cdot}{\cdot}}$ denote the inner product and norm (respectively) in 
 $\HH_i$ ($1\leq i\leq n$). Also, let $\HHH \coloneqq \HH_0\times \HH_1\times \dots\times \HH_{n-1}$ be endowed with the inner product and norm
defined, respectively, as follows (for some $\gamma >0$):
\begin{align} \label{eq:def.inner}
\inner{p}{p'}_{\gamma} = \gamma\inner{z}{z'}+\sum_{i=1}^{n-1}\inner{w_i}{w'_i},\quad
\norm{p}_\gamma = \sqrt{\inner{p}{p}_\gamma},
\end{align}
where $p = (z, w)$, $p' = (z', w')$, with $z, z'\in \HH_0$ and 
$w \coloneqq (w_1,\dots, w_{n-1}), w' \coloneqq (w'_1,\dots, w'_{n-1})\in \HH_1\times \ldots\times \HH_{n-1}$.
Elements in $\HHH$ will be denoted either by $p=(z, w_1,\dots, w_{n-1})$ or simply $p=(z,w)$, where $w=(w_1,\dots, w_{n-1})$, and we will use the notation
 \begin{align} \label{eq:def.wn}
 w_n = -\sum_{i=1}^{n-1}\,G_i^* w_i
\end{align}
whenever $p\in \HHH$ and $ G_i \colon \Ha_0 \to  \Ha_i $ is a bounded linear operator ($1\leq i \leq n-1$).


\subsection{Basic results}

In this subsection, we present some basic results needed for this paper. 
Let $\HH$ and $\GG$ denote real Hilbert spaces.
The following proposition
summarizes some properties of the $\varepsilon$-enlargement $T^{[\varepsilon]}$ (for a proof see, e.g.,  \cite{BSS99}).

\bprop \label{pr:teps}
Let $T, S \colon \Ha\tos \Ha$ be set-valued maps.  The following holds:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \lab{pr:teps.seg}  
If $\varepsilon_1 \leq \varepsilon_2$, then
$T^{[\varepsilon_1]}(x)\subseteq T^{[\varepsilon_2]}(x)$ for all $x \in \Ha$.
\item \lab{teps.ter}  $T^{[\varepsilon_1]}(x)+S^{[\varepsilon_2]}(x) \subseteq
(T+S)^{[\varepsilon_1+\varepsilon_2]}(x)$ for all $x \in \Ha$ and
$\varepsilon_1, \varepsilon_2\geq 0$.
\item \lab{teps.qua} $T$ is monotone if and only if $\Gra T  \subseteq \Gra T^{[0]}$.
\item \lab{pr:teps.qui} $T$ is maximal monotone if and only if $T = T^{[0]}$.
%\item \lab{teps.sex} If $f \colon \Ha\to \R\cup \{+\infty\}$ is proper lower semicontinuous and convex, then
%$\partial_\varepsilon f(x)\subseteq (\partial f)^{\varepsilon}(x)$ for
%all $x\in \Ha$ and $\varepsilon \geq 0$.
\item \lab{pr:teps.sab} 
If $T$ is maximal monotone, the sequence $(y_k,v_k,\varepsilon_k)$ is
such that $v_k\in T^{[\varepsilon_k]}(y_k)$, $y_k \wto y$,
$v_k \to v$ and $\varepsilon_k \to \varepsilon$, then
$v\in T^{[\varepsilon]}(y)$.
%\item \lab{teps.dom} If $u \in \partial f (x)$ and $y\in \dom f$, then $u \in \partial_{\varepsilon} f(y)$, where 
%$\varepsilon = f(y) - \left(f(x) + \Inner{y-x}{u}\right) $.
\end{enumerate}
\eprop

\mgap

Recall that $F \colon \Dom F\subseteq \HH \to \Ha$ is said to be 
$L^{-1}$-cocoercive if
\[
\inner{F(x)- F(y)}{x - y}\geq \dfrac{1}{L}\normq{F(x)- F(y)}\quad \mbox{for all} \quad x, y\in \Dom F.
\]

\mgap

\begin{lemma}\emph{(\cite[Lemma 2.2]{Sva14})}
\label{lem:trans}
Let $F \colon \Dom F\subseteq \HH \to \Ha$ be $L^{-1}$-cocoercive. 
Then, for every $z, z' \in \Dom F$,
\begin{align*}
F(z) \in F^{[\varepsilon]}(z'), \quad \mbox{with } \varepsilon = \dfrac{L\normq{z'-z}}{4}.
\end{align*}
\end{lemma}

The proof of the following lemma follows from the definition of $\varepsilon$-enlargements of set-valued maps combined with simple algebraic manipulations.

\begin{lemma}\label{lem:prope}
Let $A \colon \HH \tos \HH$ and $B \colon \GG \tos \GG$ be maximal monotone operators  and 
$\varepsilon^a$, $\varepsilon^b \geq 0$. Then, for all $x \in \HH$ and $y \in \GG$,
\begin{equation*}
A^{[\varepsilon^a]}(x) \times B^{[\varepsilon^b]}(y) \subseteq (A \times B)^{[\varepsilon^a + \varepsilon^b]}(x, y)
\end{equation*}
where $A\times B\colon \HH\times \GG \tos \HH\times \GG$ is defined by $(A \times B)(z, v) = A(z)\times B(v)$.
\emph{(}$\HH\times \GG$ endowed with the usual inner product.\emph{)}
\end{lemma}

\mgap

\blemm\label{lm:proj}
Let $C \subseteq \Ha$ be nonempty, closed and convex and 
let $P_C (\cdot)$ be the orthogonal projection onto $C$. 
Then, for all $x, y\in \Ha$ and $z\in C$,
\begin{align}
\label{eq:pne}
 &\Norm{P_C(x) - P_C(y) }^2 \leq \norm{x - y}^2 - \Norm{\left[x - P_C(x)\right] - \left[y - P_C(y)\right]}^2,\\[4mm]
\label{eq:pcr}
&\langle x - P_C(x), z - P_C(x) \rangle \leq 0.
\end{align}
\elemm

The standard inequality 

\begin{align}\label{eq:ineq.norm}
\Normq{\sum_{i=1}^n x_i} \leq n \sum_{i=1}^n \normq{x_i},
\end{align}
that holds for $x_1, x_2, \dots, x_n$ in $\Ha$, will also be needed in this paper.


