\begin{algorithm}%[H]
%\label{alg:iHPEP}
\caption{A strongly convergent inertial inexact PS algorithm for solving  \eqref{eq:probr}.}
%\DontPrintSemicolon
\SetAlgoLined
\KwInput{$(z^{-1}, w^{-1}_1, \ldots, w^{-1}_{n-1})  = (z^{0}, w^0_1, \ldots, w^0_{n-1})\in \boldsymbol{\Ha}$, scalars $0 \leq  \sigma < 1$ and  $\gamma > 0$.}
\For{ $k=0,1,\ldots$}{ 
Choose $\alpha_k \geq 0$, $\beta_k \geq 0$ and let
\begin{align}
\label{eq:ext.01z}
&\widehat z^{\,k} = z^k+\alpha_k(z^k-z^{k-1}), \quad \widetilde{z}^{\, k} = \widehat{z}^{k} + \beta_k (\widehat{z}^{\, k} - z^0 ),\\[3mm]
\label{eq:ext.02z}
&\widehat{w}_i^{\,k} = w_i^{k} + \alpha_k (w_i^k - w_i^{k-1}), \quad  \widetilde{w}^{\, k}_{i} = \widehat{w}^{\,k}_{i} + \beta_k (\widehat{w}^{\,k}_i - w^{0}_i) \quad (i =1, \ldots, n-1), \\[3mm]
\label{eq:ext.03z}
& \widetilde w_n^{\,k} = -\sum_{i=1}^{n-1}G_i^*\widetilde w_i^{\,k}.
\end{align}
For $i = 1, \ldots, n$, choose scalars $\lambda_i^k > 0$ and compute $(x_i^k, y_i^k, \varepsilon_i^k)\in \Ha\times \Ha\times \R_{+}$ such that
\begin{align}
\begin{aligned}\label{eq:proxT_i}
&y_i^k\in T^{[\varepsilon_{i}^{k}]}_i(x_i^k),\\[1mm]
&\normq{\lambda_i^k y_i^k + x_i^k - (G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k})}  + 2\lambda_i^{k}\varepsilon_{i}^{k}\leq \sigma^2\left(\Norm{G_i \widetilde{z}^k-x_i^k}^2+\Norm{\lambda_i^k( \widetilde{w}_i^k-y_i^k)}^2\right).
%\end{cases}
\end{aligned}
\end{align}
\If{$x_i^k = G_i x_n^k$ \emph{(}$i=1, \ldots, n-1$\emph{)} \emph{and} 
$\displaystyle \sum_{i=1}^{n-1}G_i^*y_i^k  + y_n^k = 0$}
 	{\Return 
 	\begin{align} \lab{eq:return}
 	(\overline z, \overline w_1, \ldots , \overline w_{n-1}) \coloneqq (x_n^k, y_1^k, \dots, y_{n-1}^k).
 	\end{align}}
Let the affine functional $\varphi_k(\cdot)$ be as in \eqref{eq:sep.F} (see also \eqref{eq:car.varphi}),
let
\begin{align}\label{def:pk}
p^{k} \coloneqq (z^{k}, w_1^{k}, \ldots, w_{n-1}^{k}),
\end{align}
set
\begin{align}\label{def:Hk-Wk}
\begin{aligned}
& H_k =\left\{p\in \boldsymbol{\Ha} \mid \varphi_{k}(p)\leq 0\right\},\\
& W_k =\left\{p\in \boldsymbol{\Ha} \mid \inner{p^0-p^k}{p-p^k}_{\gamma}\leq 0\right\},
\end{aligned}
\end{align}
and compute the next iterate
\begin{align}\label{eq:updt01}
(z^{k+1}, w_1^{k+1}, \ldots , w_{n-1}^{k+1}) = P_{H_k \cap W_k}(p^0).
\end{align}
}
\label{alg:iHPEP}
\end{algorithm}

