\mgap

\noindent
{\bf Additional notation.}  In order to facilitate the analysis of Algorithm \ref{alg:iHPEP}, we have to introduce some additional notation. Similarly to the definition of $\widetilde w_n^k$ as in \eqref{eq:ext.03z}, 
for the sequences $(w_i^k)$ and $(\widehat w_i^k)$ ($1\leq i \leq n$), we define
\begin{align} \lab{def:wwhat}
w_n^{\,k} \coloneqq -\sum_{i=1}^{n-1}G_i^*w_i^{\,k}\quad \mbox{and}\quad  \widehat w_n^{\,k} \coloneqq -\sum_{i=1}^{n-1}G_i^*\widehat w_i^{\,k}.
\end{align}
Also, similarly to the notation for $p^k$ as in \eqref{def:pk},
\begin{align}\label{eq:indetityp}
\wh p^{\,k} \coloneqq (\wh z^{\,k}, \wh w_1^{\,k}, \ldots , \wh w_{n-1}^{\,k}) \quad \mbox{and} \quad
 \wti p^{\,k} \coloneqq  (\wti z^{\,k}, \wti w_1^{\,k}, \ldots , \wti w_{n-1}^{\,k}).
\end{align}
From \eqref{eq:ext.01z}, \eqref{eq:ext.02z}, \eqref{def:pk} and \eqref{eq:indetityp}, we have
\begin{align*}
\wh p^{\,k} = p^k + \alpha_k (p^k - p^{k-1}) \quad \mbox{and} \quad 
\wti p^{\,k} = \wh p^k + \beta_k (\wh p^k - p^0).
\end{align*}
Furthermore, direct substitution of the first identity in \eqref{eq:ext.02z} into the second
identity in \eqref{def:wwhat} and of the second identity in \eqref{eq:ext.02z} into 
\eqref{eq:ext.03z} yields
\begin{align}\label{eq:identityw}
\wh w_n^{\,k} = w^{k}_n + \alpha_k ( w^{k}_n -  w_n^{k-1}) \quad \mbox{and} \quad
\wti w_n^{\,k} = \wh w^{\,k}_n + \beta_k (\wh w^{\,k}_n -  w_n^{0}).
\end{align}
Whenever it is convenient, we will also use the notation
\begin{align} \lab{def:ei}
e_i^k \coloneqq \lambda_i^k y_i^k + x_i^k - (G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k}),
\quad i = 1, \dots, n.
\end{align}
This implies that  the inequality in \eqref{eq:proxT_i} now reads as
\begin{align} \lab{eq:salg}
\normq{e_i^k}  + 2\lambda_i^{k}\varepsilon_{i}^{k}\leq \sigma^2\left(\Norm{G_i \widetilde{z}^k-x_i^k}^2+\Norm{\lambda_i^k( \widetilde{w}_i^k-y_i^k)}^2\right).
\end{align}
Regarding the just introduced notation, we also observe that, since $G_n$ is assumed to be equal the identity operator (see Assumption A2), definition \eqref{eq:ext.03z} gives us
\begin{align}\lab{eq:sumwtz}
\sum_{i=1}^n G_i^*\widetilde w_i^k = 0.
\end{align}

\mgap

\noindent
Next we make some remarks and comments about Algorithm \ref{alg:iHPEP}:

\begin{enumerate}[label = (\roman*)]
\item Algorithm \ref{alg:iHPEP} operates on the augmented space $\HHH = \HH_0\times \HH_1\times \dots\times \HH_{n-1}$; recall that the extended-solution set $\Sa_e$ is a subset of $\HHH$ and our main problem \eqref{eq:probr} is equivalent to the (convex feasibility) problem of finding a point $p = (z, w_1, \dots, w_{n-1})$ in $\Sa_e$. Also, recall that, by 
Lemma \ref{lem:grad.sep}\emph{\ref{lem:grad.sep.ter}}, the set $\Sa_e$ is a subset of the ``negative'' half-space defined by each affine functional $\varphi_k(\cdot)$ (see the definition of $H_k$ as in \eqref{def:Hk-Wk}). This explains the ``projective'' nature of Algorithm \ref{alg:iHPEP}, where the iteration is defined, as in \eqref{eq:updt01}, by successive projections on the intersection of the half-spaces $H_k$ and $W_k$. The main role of the latter half-space is to enforce the strong convergence of 
the sequences generated Algorithm \ref{alg:iHPEP} (see Theorem \ref{th:sconv} below).
\item The extrapolation steps defined in \eqref{eq:ext.01z}--\eqref{eq:ext.03z} promote \emph{inertial effects} on the iterations; these inertial effects are controlled by the parameters $\alpha_k$ and $\beta_k$.
We note that while the first extrapolation represented by $\wh z^k$ and $\wh w_i^k$  ($i = 1, \dots, n-1$) 
corresponds to the more typical type of extrapolation present in many inertial-based algorithms 
(see, e.g., \cite{AA01, Alv+20, AM20, AC20, AP19}), the second type 
$\wti z^k$ and $\wti w_i^k$ ($i=1, \dots, n$) is introduced by considering the particular iteration mechanism of Algorithm 1. 
Conditions on sequences $\seq{\alpha_k}$ and $\seq{\beta_k}$ to ensure the strong convergence and iteration-complexity of Algorithm \ref{alg:iHPEP} will be given in Assumption \ref{assu:ab} 
(see also Assumption \ref{assu:lambda}).
\item  At each iteration, Algorithm \ref{alg:iHPEP} demands the approximate solution of $n$ prox-subproblems, as in \eqref{eq:proxT_i}. These subproblems can be independently solved in parallel and inexactly within a relative-error criterion that is controlled by the parameter $\sigma\in [0, 1)$.  Note that if $\sigma = 0$, then, by 
\eqref{eq:proxT_i},  we have $\varepsilon_i^k = 0$ and 
$\lambda_i^k y_i^k + x_i^k - (G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k}) = 0$  for $i=1, \dots, n$. So, $y_i^k\in T_i(x_i^k)$ and 
$\lambda_i^k y_i^k + x_i^k = G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k}$
for all $i=1, \dots, n$ (recall that $T^{[0]} = T$). This means that, for a given $\lambda_i^k > 0$, the triple 
$(x_i^k, y_i^k, \varepsilon_i^k)$ defined as
\begin{align} \lab{eq:arflo}
x_i^k \coloneqq G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k} - \lambda_i^k y_i^k, \qquad
y_i^k \coloneqq (\lambda_i^k T_i + I)^{-1}(G_i \widetilde{z}^{\,k} + \lambda_i^k  \widetilde{w}_i^{\,k}),
\qquad \varepsilon_i^k \coloneqq 0
\end{align}
always satisfies the error criterion \eqref{eq:proxT_i}. The main limitation of \eqref{eq:arflo} is the computation of the exact resolvent $(\lambda_i^k T_i + I)^{-1}$ of each maximal monotone operator $T_i$, which may be 
expensive from a computational viewpoint. The relative-error criterion \eqref{eq:proxT_i} overcomes this limitation by allowing the computation of inexact solutions $(x_i^k, y_i^k, \varepsilon_i^k)$, which in practical situations can be achieved by some other ``inner solver'', depending on the specific structure of $T_i$ (the inequality in 
\eqref{eq:proxT_i} being used as a stopping criterion for the ``inner solver'');
see~\cite{Alv+20} for a practical implementation of a similar relative-error criterion in the context of the ADMM splitting algorithm).  
We also mention that \eqref{eq:proxT_i} is a generalization of a relative-error criterion for an inertial PS algorithm that appeared in~\cite{AGM24}. 
In Section \ref{sec:FB-TFB}, we will show how Algorithm \ref{alg:iHPEP} can be used as a framework for the design of new operator splitting methods, where a triple $(x_i^k, y_i^k, \varepsilon_i^k)$ satisfying \eqref{eq:proxT_i} can be computed directly by forward-backward/forward-backward-forward (Tseng) steps, under assumptions of cocoercivity/Lipschitz continuity on the operator $T_i$.
\item In Corollary \ref{cor:airflo}, we will show that if Algorithm \ref{alg:iHPEP} 
stops (see \eqref{eq:return}), then it follows that $(\overline z, \overline w_1, \dots, \overline w_{n-1})$ belongs to the extended-solution set $\Sa_e$; subsequently, in order to analyze the convergence of Algorithm \ref{alg:iHPEP}, we will assume that it generates ``infinite'' sequences (see Remark \ref{rem:620} below).
\item The definition of the next iterate $(z^{k+1}, w_1^{k+1}, \dots, w_{n-1}^{k+1})$ as in \eqref{eq:updt01} by the orthogonal projection of $p^0$ onto the intersection $H_k \cap W_k$ of the half-spaces $H_k$ and $W_k$ is one of the main ingredients to guarantee the strong convergence of Algorithm \ref{alg:iHPEP} (note that $H_k$ is a half-space in $\HHH$ by Lemma \ref{lem:grad.sep}\emph{\ref{lem:grad.sep.seg}}). In the context of inexact relative-error proximal-point methods, this idea traces back to~\cite{SS00} and was also recently 
exploited in~\cite{ACM24} (in the context of inertial methods). The computation of the orthogonal projection
in \eqref{eq:updt01} reduces (at most) to the solution of a $2\times 2$ linear 
system (see \cite[pp. 195 and 196]{SS00} and \cite[Propositions 28.18 and 28.19]{BC11}). Note also that the well-definiteness of the next iterate $(z^{k+1}, w_1^{k+1}, \ldots , w_{n-1}^{k+1})$ as in \eqref{eq:updt01} depends on the nonemptyness of the (closed and convex) set 
$H_k \cap W_k$. This will be discussed in more details in Appendix \ref{app:well} below (see Proposition \ref{pro:inclutionset}).
\item  It is worth mentioning here that the implementation as well as the guarantees of convergence of Algorithm \ref{alg:iHPEP} are independent of the computation of norms and inverses of the bounded linear operators $G_i$ $(1\leq i\leq n)$.
\end{enumerate}


%\newpage
\subsection{Convergence analysis of Algorithm \ref{alg:iHPEP}} 
\label{subsec:conv}

In this subsection, we study the strong convergence properties of Algorithm \ref{alg:iHPEP}. The main result is Theorem \ref{th:sconv} below. Other auxiliary results (Lemmas and Propositions) will also be stated and proved.
Assumptions \ref{assu:lambda} and \ref{assu:ab} (on the sequences of proximal
$\seq{\lambda_i^k}$ $(1\leq i\leq n)$ and inertial $\seq{\alpha_k}$
and $\seq{\beta_k}$ parameters, respectively) will be required in order to prove the convergence of 
Algorithm \ref{alg:iHPEP}.

\mgap

We begin with the following technical lemma:


\begin{lemma}\label{lem:varphi00}
Suppose iteration $k\geq 0$ is reached in \emph{Algorithm \ref{alg:iHPEP}} and 
let $\seq{\widetilde p^k}$ and $\varphi_k(\cdot)$ be as in \eqref{eq:indetityp} and \eqref{eq:sep.F}, respectively.
The following holds:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \label{lem:varphi00.seg} 
For all $i=1, \ldots,n$,
\begin{align}\label{ineq:eps_com}
\inner{ G_i \wti z^{\,k} - x_i^k }{ y^k_i - \wti w^{\, k}_i} - \varepsilon^{k}_i
\geq  \frac{1 - \sigma^2}{2 \lambda^k_i} \left ( \normq{G_i \wti z^{\, k} - x^k_i} + \normq{\lambda^k_i (\wti w^{\,k}_i -y^k_i)} \right).
\end{align}
\item \label{lem:varphi00.ter}
We have
\begin{align*}
\varphi_k(\wti p^{\, k}) \geq \dfrac{1 - \sigma^2}{2}\sum_{i=1}^{n} \left( \dfrac{1}{\lambda_i^k}\normq{G_i\wti z^{\, k} - x_i^k } + \lambda_i^k\normq{\wti w^{\,k}_i - y^k_i}  \right)\geq 0.
\end{align*}
\end{enumerate}
\end{lemma}
\begin{proof}
\emph{\ref{lem:varphi00.seg}} Using the identity $\inner{a}{b} = (1/2) (\normq{a} + \normq{b} - \normq{a-b})$ with $a = G_i \wti z^{\,k} - x^k_i$ and $b = \lambda^k_i (y_i^k - \wti w^{\,k}_i)$, we obtain
\begin{align*}
\inner{ G_i \wti z^{\,k} - x_i^k }{ \lambda^{k}_i(y^k_i - \wti w^{\, k}_i)} = \dfrac{1}{2} \Big( \normq{ G_i\wti z^{\, k}- x^k_i } + \normq{\lambda^{k}_i(y^k_i - \wti w^{\, k}_i)}- \normq{ \underbrace{G_i \wti z^{\,k} -x_i^k  - \lambda^{k}_i(y^k_i - \wti w^{\, k}_i)}_{-e^k_i} }\Big),
\end{align*}
where $e_i^k$ is as in \eqref{def:ei}. Subtracting $\varepsilon_i^k$ in both sides of the latter identity and using the error criterion (inequality) in \eqref{eq:proxT_i} we then find (see also \eqref{eq:salg})
\begin{align*}
%\label{ineq:eps}
\notag
\inner{ G_i \wti z^{\,k} - x_i^k }{ y^k_i - \wti w^{\, k}_i} - \varepsilon^{k}_i = & \dfrac{1}{2 \lambda^{k}_i} 
\left( \normq{ G_i \wti z^{\, k} - x_i^k } + \normq{\lambda^{k}_i (y^k_i - \wti w^{\, k}_i)} - 
\left[\normq{ e^k_i } + 2 \lambda^k_i \varepsilon^k_i\right] \right) \\
\geq & \frac{1- \sigma^2}{2 \lambda^k_i} \left ( \normq{G_i \wti z^{\, k} - x^k_i} + \normq{\lambda^k_i (\wti w^{\,k}_i -y^k_i)} \right),
\end{align*}
which finishes the proof of item \emph{\ref{lem:varphi00.seg}}.

\mgap

\emph{\ref{lem:varphi00.ter}} This follows by summing up the inequality \eqref{ineq:eps_com} for $i =1,\ldots,n$ and using the definitions of 
$\varphi_k(\cdot)$ and $\widetilde p^k$ (see Eqs. \eqref{eq:sep.F} and \eqref{eq:indetityp}).
\end{proof}

\mgap

Next we show that if Algorithm \ref{alg:iHPEP} stops, then it stops at a solution of problem \eqref{eq:probr}:

\bcoro \lab{cor:airflo}
If \emph{Algorithm \ref{alg:iHPEP}} returns $(\overline z, \overline w_1, \dots, \overline w_{n-1})$ as in 
\eqref{eq:return}, then $(\overline z, \overline w_1, \dots, \overline w_{n-1})$ belongs to the extended-solution set
$\Sa_e$. In particular, $\overline z$ is a solution of problem \eqref{eq:probr}.
\ecoro
\bproo
The proof is a direct consequence of Lemma \ref{lem:varphi00}\emph{\ref{lem:varphi00.ter}} and
items  \emph{\ref{lem:grad.sep.qui}} and \emph{\ref{lem:grad.sep.sex}}(ii) of 
Lemma \ref{lem:grad.sep}.
\eproo

\mgap

\brema \lab{rem:620}
\emph{
In view of Corollary \ref{cor:airflo} and Proposition \ref{pro:inclutionset} below, from now on in this section we assume that Algorithm \ref{alg:iHPEP}  doesn't stop, in this way generating ``infinite'' sequences. In particular, from now on in this section, by Lemma \ref{lem:grad.sep}\emph{\ref{lem:grad.sep.qui}}, we have
\begin{align} \lab{eq:620}
 \nabla \varphi_k \neq 0 \; \mbox{ for all } \;  k\geq 0.
\end{align}
}
\erema

\mgap

\begin{proposition}\label{pro:inva}
Let $\seq{p^{k}}$ be generated by \emph{Algorithm \ref{alg:iHPEP}} and let $d_{0,\gamma}$ denote the distance of $p^0$ to the extended-solution set $\Sa_e$ of \eqref{eq:probr}. The following statements hold:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \lab{pro:inva.a}For all $k \geq 0$, 
\begin{align*}
\normq{p^{k+1} - p ^0 }_{\gamma}  \geq \normq{p^k - p^0}_{\gamma} + \normq{p^{k+1} - p^k}_{\gamma}.
\end{align*}
\item \lab{pro:inva.b} 
For all $k \geq 0$,
\begin{align*}
\norm{p^k - p^0}_{\gamma} \leq d_{0,\gamma}.
\end{align*}
\item \lab{pro:inva.c} We have
\begin{align*}
\sum_{k=0}^\infty \normq{p^{k+1} - p^k}_{\gamma} \leq d_{0,\gamma}^2.
\end{align*}
\end{enumerate}
\end{proposition}
\begin{proof}
\emph{\ref{pro:inva.a}} Using Eq. \eqref{eq:pne} in Lemma \ref{lm:proj} (in the space $\HHH$ with the inner product as in \eqref{eq:def.inner}) with $C = W_k$, $x = p^{k+1}$ and $y = p^0$ we obtain
\begin{align*}
\normq{P_{W_k}(p^{k+1}) - P_{W_k}(p^0)}_{\gamma} \leq 
\normq{p^{k+1} - p^0}_{\gamma} - \normq{[\,p^{k+1} - P_{W_k}(p^{k+1})\,] - [\,p^0 - P_{W_k}(p^0)\,]}_{\gamma},
\end{align*}
where $W_k$ is as in \eqref{def:Hk-Wk}. Since $p^{k+1} =P_{W_{k}}(p^{k+1})$, because 
$p^{k+1}\in W_k$ (see \eqref{def:pk} and \eqref{eq:updt01}), and 
$p^k =  P_{W_k}(p^0)$ (see the definition of $W_k$), the latter inequality becomes
\begin{align*}
\normq{p^{k+1} - p^k}_{\gamma} \leq \normq{p^{k+1} - p^0}_{\gamma} - \normq{p^k - p^0}_{\gamma},
\end{align*}
which finishes the proof of item (a).

\mgap

\emph{\ref{pro:inva.b}} Assume that $k\geq 1$ (for $k = 0$ the result is trivial). 
From \eqref{def:pk} and \eqref{eq:updt01} we have $p^k = P_{H_{k-1}\cap W_{k-1}}(p^0)$. Now using Proposition \ref{pro:inclutionset} and the definition of the projection
$P_{H_{k-1} \cap W_{k-1}}(p^0)$ we obtain
\begin{align*}
\norm{p^k - p^0}_{\gamma}  = \norm{P_{H_{k-1} \cap W_{k-1}}(p^0) - p^0}_{\gamma} \leq \norm{P_{\Sa_e} (p^0) -p^0}_{\gamma} = d_{0,\gamma}.
\end{align*}

\mgap

\emph{\ref{pro:inva.c}}
This follows directly from items \emph{\ref{pro:inva.a}} and \emph{\ref{pro:inva.b}} combined with a telescopic sum argument.
\end{proof}

\mgap
\mgap

Next we make a boundedness assumption on the sequences of proximal parameters $\seq{\lambda_i^k}$ generated by Algorithm \ref{alg:iHPEP}:

\bassu \lab{assu:lambda}
For all $i =1, \dots, n$, the sequence $\seq{\lambda_i^k}$ generated by \emph{Algorithm \ref{alg:iHPEP}} satisfies 
\begin{align*}
\lambda_i^k\in [\,\underline \lambda\,, \overline \lambda\,] \quad \emph{for all}\quad k\geq 0,
\end{align*}
where $\overline \lambda \geq \underline \lambda >0$.
\eassu

\mgap

\begin{lemma}\label{lem:varphi}
Consider the sequences evolved by \emph{Algorithm \ref{alg:iHPEP}} and let $\seq{\wti p^{\, k}}$ 
be as in \eqref{eq:indetityp}. Also, let $\varphi_k(\cdot)$ be as in \eqref{eq:sep.F}. The following statements hold:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \lab{lem:varphi.seg} For all $k \geq 0$,
\begin{align}\label{varphi}
\varphi_k(\wti p^{\, k}) \geq \frac{(1 - \sigma^2)\min \{\underline{\lambda}, 1/\overline{\lambda}\}}{2} 
\sum_{i=1}^{n} \left ( \normq{G_i\wti z^{\, k} - x_i^k } + \normq{\wti w^{\,k}_i - y^k_i}  \right).
\end{align}
\item \lab{lem:varphi.ter}  For all $k \geq 0$,
\begin{align}\label{ine:gradient}
\varphi_k (\wti p^{\,k}) \geq \dfrac{1}{c} \normq{\nabla \varphi_k}_{\gamma}
\end{align}
where
\begin{align}\label{eq:constantc}
c  \coloneqq n \max_{i =1, \ldots,n}\normq{G_i} \left( \dfrac{4 \max \{1, 1/\gamma\}}{(1-\sigma^2) \min \{\underline{\lambda}, 1/\overline{\lambda}\}}\right).
\end{align}
\end{enumerate}
\end{lemma}
\begin{proof}
\emph{\ref{lem:varphi.seg}} This is a direct consequence of Lemma \ref{lem:varphi00}\emph{\ref{lem:varphi00.ter}} and
Assumption \ref{assu:lambda}.

\mgap

\emph{\ref{lem:varphi.ter}} Note first that, from \eqref{eq:sumwtz}, \eqref{eq:ineq.norm} and the fact that
$\norm{G_i} = \norm{G_i^\ast}$ ($1 \leq i \leq n$), we have

\begin{align}\label{ine:grad01}
\left \| \sum_{i=1}^{n} G_i^\ast y^k_i  \right \|^2 = \left \| \sum_{i=1}^{n} G_i^\ast(\wti w ^{\,k}_i - y_i^k)\right \|^2 \leq n  \max_{i=1, \ldots ,n} \normq{G_i} \sum_{i=1}^n \normq{\wti w^{\,k}_i - y_i^k}.
\end{align}

Likewise (recall that $G_n = I$),
\begin{align}\label{ine:grad02}
\nonumber
\sum_{i=1}^{n-1} \normq{ x_i^k  - G_ix_n^k} = & \sum_{i=1}^{n-1} \normq{x_i^k - G_i \wti z^{\, k} + G_i( \wti z^{\, k} -x_n^k)}\\
\nonumber
\leq & 2 \sum_{i=1}^{n-1} \left(  \normq{G_i \wti z^{\, k} - x_i^k} +  \normq{G_i (\wti z^{\, k} - x_n^k)} \right)\\
\nonumber
\leq & 2\left( \sum_{i=1}^{n-1}  \normq{G_i \wti z^{\, k} - x_i^k} + n \max_{i=1, \ldots , n} \normq{G_i} 
\normq{ \wti z^{\,k} - x_n^k}\right)\\
\leq & 2n  \max_{i=1, \ldots ,n}  \normq{G_i}  \sum_{i=1}^{n} \normq{G_i \wti z^{\, k} - x_i^k}.
\end{align}

Then, from \eqref{eq:norm.grad.pi_k},  \eqref{varphi}, \eqref{ine:grad01} and  \eqref{ine:grad02} we find
\begin{align*}
\normq{\nabla \varphi_k}_{\gamma}  & = \gamma^{-1} \left \| \sum_{i=1}^n G_i^\ast y_i^k\right \|^2 + \sum_{i=1}^{n-1} \Normq{x_i^k - G_i x_n^k} \\%[1mm]
%& \leq 2n \max_{i=1, \ldots,n} \normq{G_i}\sum_{i=1}^n \left( \normq{G_i\wti z^{\,k} - x_i^k} + \gamma^{-1} \normq{\wti w_i^{\,k} -%y_i^k} \right)\\%[1mm]
& \leq 2n \max_{i=1, \ldots,n} \normq{G_i} \max\{1, 1/\gamma\} \sum_{i=1}^n \left( \normq{G_i\wti z^{\,k} - x_i^k} +  \normq{\wti w_i^{\,k} -y_i^k} \right)\\%[1mm]
& \leq  n \max_{i=1, \ldots ,n} \normq{G_i} \left( \dfrac{4 \max\{1, 1/\gamma\}}{(1-\sigma^2)\min\{\underline{\lambda}, 
1/\overline{\lambda}\}}\right) \varphi_k(\wti p^{\,k})\\[1mm]
& = c\, \varphi_k(\wti p^{\,k}),
\end{align*}
which is clearly equivalent to \eqref{ine:gradient}.
\end{proof}

\mgap

\blemm  \lab{lem:kyoto}
Consider the sequences generated by \emph{Algorithm \ref{alg:iHPEP}}, let $\varphi_k(\cdot)$ be as in \eqref{eq:sep.F}
and let the constant $c > 0$ be as in \eqref{eq:constantc}. Then, for all $k\geq 0$,
\begin{enumerate}[label = \emph{(\alph*)}]
\item \lab{lem:kyoto.seg}
$\norm{\nabla \varphi_k}_{\gamma} \leq c\norm{p ^{k+1} - \wti p^{\,k}}_\gamma \quad
\mbox{and} \quad \varphi_k (\wti p^{\,k}) \leq c\normq{p^{k+1} - \wti p^{\,k}}_{\gamma}.$
\item \label{lem:kyoto.ter}
$ \sum_{i=1}^n \varepsilon_i^k \leq \Big(\dfrac{\sigma^2}{1-\sigma^2}\Big) c\normq{p^{k+1} -  \wti p^{\,k}}_\gamma.$
\end{enumerate}
\elemm
\bproo
\emph{\ref{lem:kyoto.seg}} 
To prove the first inequality, recall we are assuming that $\nabla \varphi_k \neq 0$ (see \eqref{eq:620}). Then, as a consequence of the definition of $H_k$ as in \eqref{def:Hk-Wk} and Lemma \ref{lem:grad.sep}\emph{\ref{lem:grad.sep.seg}}, we have
\begin{align*}
P_{H_k}(p) = p - \dfrac{\max\{0, \varphi_k(p)\}}{\normq{\nabla \varphi_k}_\gamma} \nabla \varphi_k \quad \mbox{for all} \quad p\in \HHH.
\end{align*}
Now using that $p^{k+1} \in H_{k}$ (see \eqref{def:pk} and \eqref{eq:updt01}) and  Lemma \ref{lem:varphi}\emph{\ref{lem:varphi.ter}}, we obtain
%
\begin{align}
\nonumber
\norm{p^{k+1} - \wti p^{\,k}}_{\gamma}  & \geq \norm{P_{H_k}(\wti p^{\,^k}) - \wti p^{\,k}}_{\gamma}\\[2mm]
\lab{eq:kyoto}
& = \frac{\varphi_k (\wti p^{\,k})}{\norm{\nabla \varphi_k}}_{\gamma}\\[2mm]
\nonumber
& \geq  c^{-1}\norm{\nabla \varphi_k}_{\gamma},
\end{align}
which finishes the proof of the first inequality. To prove the second one, combine \eqref{eq:kyoto} and the first inequality. 

\emph{\ref{lem:kyoto.ter}} From the inequality in the error criterion \eqref{eq:proxT_i}, we obtain the bound, for all $i = 1, \dots, n$,
\[
 \varepsilon_{i}^{k}\leq \frac{\sigma^2}{2}\left(\frac{1}{\lambda_i^k}\norm{G_i \widetilde{z}^k-x_i^k}^2
 +\lambda_i^k\norm{\widetilde{w}_i^k - y_i^k}^2\right).
\]
Summing up the above bounds for $i = 1, \dots, n$ and 
using Lemma \ref{lem:varphi00}\emph{\ref{lem:varphi00.ter}} we find
\[
\sum_{i=1}^n\varepsilon_i^k\leq \dfrac{\sigma^2}{1 - \sigma^2}\varphi_k(\widetilde p^k).
\]
To finish the proof of item \emph{\ref{lem:kyoto.ter}}, just combine the latter inequality and the second one in item 
\emph{\ref{lem:kyoto.seg}}.
\eproo

\mgap

From now on, we assume that the sequences $\seq{\alpha_k}$ and 
$\seq{\beta_k}$ given in Algorithm \ref{alg:iHPEP} satisfy the following conditions:

\begin{assumption} 
\lab{assu:ab}
\begin{enumerate}[label = \emph{(\alph*)}]
\item \lab{assu:ab.seg} The sequence $\seq{\alpha_k}$ is bounded, i.e.,
\[
 \overline{\alpha} \coloneqq \sup_{k\geq 0}\, \alpha_k < +\infty.
\]
\item \lab{assu:ab.teg} The sequence $\seq{\beta_k}$ belongs to $\ell_2$, i.e.,
\[
  \overline s \coloneqq \sum_{k=0}^\infty\,\beta^2_k < +\infty.
\]
We will also use the notation
\[
 \overline{\beta} \coloneqq \sup_{k\geq 0}\, \beta_k < +\infty.
\]
\end{enumerate}
\end{assumption}

\mgap
\mgap


The following result is fundamental for both the convergence and iteration-complexity analysis of
Algorithm \ref{alg:iHPEP}. The proof, which will be skipped here, follows the same outline of the proof of \cite[Proposition 3.4(b)]{ACM24}.

\mgap

\begin{proposition} \lab{pr:sumfin}
Let $\seq{p^k}$ be generated by \emph{Algorithm \ref{alg:iHPEP}}, let $\seq{\widetilde p^{\,k}}$ be as
in \eqref{eq:indetityp} and let $d_{0,\gamma}$ denote the distance of $p^0$ to the solution set $\Sa_e$ of \eqref{eq:probr}. Also, let $\overline{\alpha}$, $\overline{\beta}$ and $\overline{s}$ be as in \emph{Assumption \ref{assu:ab}}. Then
\begin{align}\label{ineq:bounded}
\sum_{k=0}^\infty\,\norm{p^{k+1} - \widetilde p^{\,k}}_{\gamma}^2 \leq \Omega_{(\alpha, \beta)}\, d_{0,\gamma}^2
\end{align}
where
\begin{align}\lab{eq:def.omega}
\Omega_{(\alpha, \beta)} \coloneqq (1 + \overline \alpha)\Big[ (1 + \overline \beta)\big[ 1 + \overline \alpha (1 + \overline \beta) \big] + \overline s \Big].
\end{align}
\end{proposition}

\mgap
\mgap

\begin{proposition}\label{pro:lim}
Consider the sequences generated by \emph{Algorithm \ref{alg:iHPEP}}. Then the following holds:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \label{pro:lim.seg} $y_n^k + \sum_{i=1}^{n-1} G_i^\ast y_i^k \to 0$ and, for $i=1, \ldots ,n$, we have $x_i^k - G_i x_n^k \to 0$.
\item \label{pro:lim.ter} For $i=1, \ldots ,n$, we have $\varepsilon_i^k \to 0$.
\item \lab{pro:lim.qua} For $i=1, \ldots ,n$, we have $G_i \wti z^{\, k} - x_i^k \to 0$ and $\wti w^{\, k}_i - y_i^k \to 0$.
\item \lab{pro:lim.qui}  For $i=1, \ldots ,n$, we have $G_i \widehat z^{\, k} - x_i^k \to 0$ and $\widehat w^{\, k}_i - y_i^k \to 0$.
\item\lab{pro:lim.sex} For $i=1, \ldots ,n$, we have $G_i z^k - x_i^k \to 0$ and $w_i^k - y_i^k \to 0$.
\end{enumerate}
\end{proposition}
\begin{proof}
\emph{\ref{pro:lim.seg}} This follows from the first 
inequality in Lemma \ref{lem:kyoto}\emph{\ref{lem:kyoto.seg}} combined with \eqref{eq:norm.grad.pi_k} and \eqref{ineq:bounded}(recall that $G_n = I$).

\mgap

\emph{\ref{pro:lim.ter}} This is a direct consequence 
of Lemma \ref{lem:kyoto}\emph{\ref{lem:kyoto.ter}}
 and  \eqref{ineq:bounded}. 

\mgap

\emph{\ref{pro:lim.qua}} This follows from the second inequality in Lemma \ref{lem:kyoto}\emph{\ref{lem:kyoto.seg}}, Proposition \ref{pr:sumfin} and Lemma \ref{lem:varphi}\emph{\ref{lem:varphi.seg}}.

\mgap

\emph{\ref{pro:lim.qui}} Using the triangle inequality and the second identity in \eqref{eq:ext.01z}, we obtain
\begin{align}\label{ineq:n1}
\notag
\norm{G_i \wh z^k - x_i^k} &  \leq \norm{\wti z^{\,k} - \wh z^{\,k}}\norm{G_i} + \norm{G_i \wti z^{\,k} -x_i^k}\\
& = \beta_k \norm{\wh z^{\,k} - z^0 }\norm{G_i} + \norm{G_i\wti z^{\,k} - x_i^k}, \quad i=1, \ldots,n.
\end{align}
By a similar argument, we also have
\begin{align}\label{ineq:n2}
\notag
\norm{\wh w_i^{\,k} - y_i^k} & \leq \norm{ \wti w _i^{\,k}-\wh w_i^{\,k} } + \norm{ \wti w_i^{\,k} - y_i^k}\\
& = \beta_k \norm{ \wh w_i^{\,k} - w_i^0} + \norm{ \wti w_i^{\,k} - y_i^k}, \quad i=1, \ldots , n-1.
\end{align}
Note also that, using the inequality \eqref{eq:ineq.norm}, the second 
identity in \eqref{eq:ext.02z} and \eqref{eq:ext.03z},
\begin{align}\label{ineq:n3}
\notag
\frac{1}{2} \normq{y_n^k - \wh w_n^{\,k}} & \leq \normq{ \wti w_n^{\,k} - \wh w_n^{\,k}} + \normq{y_n^k - \wti w^{\,k}_n}\\
\notag
& = \Normq{\sum_{i=1}^{n-1} G_i^{\ast}( \wti w^{\,k}_i - \wh w^{\,k}_i)} +   \normq{y_n^k - \wti w^{\,k}_n}\\
&  \leq n\,\max_{i=1, \ldots, n-1} \normq{G_i} \beta_k^2 \sum_{i=1}^{n-1} \normq{\widehat w^{\,k}_i - w_i^0} + 
\normq{y_n^k - \wti w^{\,k}_n}.
\end{align}

 Since the sequence $\seq{p^k}$ is bounded (see Proposition \ref{pro:inva}\emph{\ref{pro:inva.b}}), it follows from \eqref{def:pk}
 and \eqref{def:wwhat}  that $\seq{z^k}$ and $\seq{w_i^k}$ are also bounded, for $i=1, \dots, n$. Hence, 
 $\seq{\wh z^k}$, $\seq{\widetilde w_i^k}$ and 
 $\seq{\wh w_i^k}$ ($i=1, \dots, n$) are bounded as 
 well (use \eqref{eq:ext.01z}--\eqref{eq:ext.03z} and the boundedness 
 of $ \seq{\alpha_k} $ and $ \seq{\beta_k} $). Also, from Assumption \ref{assu:ab}\emph{\ref{assu:ab.teg}} we know that $\beta_k \to 0$. Consequently, the desired result follows from \eqref{ineq:n1}--\eqref{ineq:n3} and item 
 \emph{\ref{pro:lim.qua}}.

 \mgap

\emph{\ref{pro:lim.sex}} Similarly to the proof of item \emph{\ref{pro:lim.qui}}, we have the inequalities
\begin{align}\label{ineq:n3.5}
\notag
\norm{G_iz^k  - x_i^k} & \leq \norm{z^k - \wh z^{\,k}} \norm{G_i} + \norm{G_i \wh z^{\,k} - x_i^k}\\[2mm]
& = \alpha_k \norm{z^k - z^{k-1}} \norm{G_i} + \norm{ G_i \wh z^{\,k} - x_i^k}, \quad i=1, \dots, n.
\end{align}
and
\begin{align}\label{ineq:n3.6}
\notag
\norm{w_i^k - y_i^k} & \leq \norm{w_i^{\,k} - \wh w_i^k} + \norm{\wh w_i^{\,k} - y_i^k}\\[2mm]
& = \alpha_k\norm{w_i^k - w_i^{k-1}} + \norm{\wh w_i^{\,k} - y_i^k}, \quad i=1, \dots, n, &&\mbox{[by \eqref{eq:ext.02z} and \eqref{eq:identityw}]}.
\end{align}
Hence, using the fact that $z^k - z^{k-1}\to 0$ and $w_i^k - w_i^{k-1}\to 0$, $i=1, \dots, n$ (because of
Proposition \ref{pro:inva}\emph{\ref{pro:inva.c}} combined with Eqs. \eqref{eq:def.inner}, \eqref{def:pk} and \eqref{def:wwhat})
and the limitation of $\seq{\alpha_k}$ we obtain the desired result directly from \eqref{ineq:n3.5}, \eqref{ineq:n3.6}
and item \emph{\ref{pro:lim.qui}}.
\end{proof}


\mgap
\mgap

\begin{lemma}\label{lem:wcp}
Every weak cluster point of the sequence $\seq{p^k}$ as in \eqref{def:pk} belongs to $\Sa_e$.
\end{lemma}
\begin{proof}
Let $\overline p = (\overline z, \overline w_1, \ldots, \overline w_{n-1}) \in \HHH$ be a weak cluster point of the sequence
$\seq{p^k}$ (recall that $\seq{p^k}$ is bounded, 
by Proposition \ref{pro:inva}\emph{\ref{pro:inva.b}}) and let $\seq{p^{k_j}}$ be a subsequence of $\seq{p^k}$ such that $p^{k_j} \wto \overline p$, i.e,
\begin{align}\label{eq:weakcon}
z^{k_j} \wto \overline z\quad \mbox{ and }\quad w_i^{k_j} \wto \overline w_i, \quad i = 1, \ldots ,n - 1.
\end{align}
Using Proposition \ref{pro:lim}\emph{\ref{pro:lim.sex}}, \eqref{eq:weakcon} and the fact that $G_n = I$ 
(see Assumption A2 above), we also obtain
\begin{align*}%\label{eq:weakcon02}
x_n^{k_j} \wto \overline z \quad \mbox{and} \quad y_i^{k_j} \wto \overline w_i, \quad i=1, \ldots, n-1.
\end{align*}
In view Algorithm \ref{alg:iHPEP}'s definition we have  $y_i^{k_j}\in T_i^{[\varepsilon_i^{k_j}]}(x_i^{k_j})$
($1\leq i\leq n$), and from 
Proposition \ref{pro:lim} (items \emph{\ref{pro:lim.seg}} and \emph{\ref{pro:lim.ter}}) we also have
$x_i^{k_j} - G_ix_n^{k_j} \to 0$ ($1\leq i\leq n-1$), 
$y_n^{k_j} + \sum_{i=1}^{n-1}\,G_i^*y_i^{k_j} \to 0$
and $ \veps_i^{k_j} \to 0 $.
Hence, from Corollary \ref{cor:proof},
\begin{align*}
\overline w_i \in T_i (G_i \overline z),\quad i = 1, \ldots, n-1,\quad
 -\sum_{i=1}^{n-1}\,G_i^* \overline w_i \in T_n(\overline z),
\end{align*}
which, in view of the definition of $\mathcal{S}_e$ as in \eqref{eq:KTS}, gives exactly the inclusion
$\overline p\in \mathcal{S}_e$, i.e., every weak cluster point of $\seq{p^k}$ belongs to $\mathcal{S}_e$.
\end{proof}

\mgap
\mgap

Now we prove the strong convergence of  Algorithm \ref{alg:iHPEP}:

\mgap
\mgap

\begin{theorem}[Strong convergence of Algorithm \ref{alg:iHPEP}] \label{th:sconv}
Let the sequence $\seq{p^k}$ be generated by \emph{Algorithm \ref{alg:iHPEP}}, as given in \eqref{def:pk}, 
let the extended-solution set $\mathcal{S}_e$ be as in \eqref{eq:KTS} and suppose 
\emph{Assumptions} \emph{A1--A3}, \emph{\ref{assu:lambda}} and \emph{\ref{assu:ab}} hold. Also, let the sequence $\seq{w_n^k}$ be as in \eqref{def:wwhat}.

Then $\seq{p^k}$ converges strongly to $p^* \coloneqq (z^*, w_1^*, \dots, w_{n-1}^*)$, where $p^*$ denotes the orthogonal projection of $p^0$ onto $\mathcal{S}_e$, $\seq{z^k}$ converges 
strongly to \emph{(}the solution of Problem \eqref{eq:probr}\emph{)} $z^*$
and $\seq{w_i^k}$ converges strongly to $w_i^*$ $(1\leq i\leq n)$, where
$w_n^* \coloneqq -\sum_{i=1}^{n-1}\,G_i^* w_i^*$. Moreover, 
for $i =1, \ldots, n$, the sequences $\seq{x_i^k}$ and $\seq{y_i^k}$ converge strongly to 
$G_i z^*$ and $w_i^*$, respectively.
\end{theorem}
\begin{proof}
\noindent
{\bf Step 1.} We first prove that $p^k\to p^*$. To this end, note that in 
view of Proposition \ref{pro:inva}\emph{\ref{pro:inva.b}} and the fact that 
$d_{0, \gamma} = \norm{p^* - p^0}_\gamma$, we have
\begin{align}\label{eq:xkb}
\norm{p^k - p^0}_{\gamma} \leq \norm{p^{\ast} - p^0}_{\gamma} \quad \mbox{for all}\quad k\geq 0.
\end{align}
Thus, $\seq{p^k}$ is bounded and, by Lemma \ref{lem:wcp}, its weak cluster points belong to $\Sa_e$. 
Then, let $\seq{p^{k_j}}$ be a subsequence of $\seq{p^k}$ and $\overline{p}$ be a weak cluster point of
$\seq{p^k}$ belonging to $\mathcal{S}_e$\,:
\begin{align*}
\overline p\in \mathcal{S}_e,\quad p^{k_j} \rightharpoonup \overline{p}.
\end{align*}
Since $\norm{\cdot}_{\gamma}$ is lower semicontinuous in the weak topology on $\boldsymbol{\Ha}$, we obtain
\begin{align}\label{eq:ast}
\norm{\overline{p} - p^0}_{\gamma} \leq \liminf \norm{p^{k_j} - p^0}_{\gamma} \leq \limsup \norm{p^{k_j} - p^0}_{\gamma} \leq \norm{p^{\ast} -p^0}_{\gamma},
\end{align}
where we used \eqref{eq:xkb} in the latter inequality. Since, by definition, 
$p^{\ast} = P_{\Sa_e}(p^0)$ and $\overline{p} \in \Sa_e$, it follows directly from \eqref{eq:ast} that 
$\overline{p} = p^{\ast}$. Thus, $p^k \wto p^*$, and from \eqref{eq:xkb}, we have
\begin{align*}
\norm{p^* - p^0}_{\gamma} \leq \liminf \norm{p^k - p^0}_{\gamma} \leq \limsup \norm{p^k - p^0}_{\gamma} \leq \norm{p^{\ast} - p^0}_{\gamma}.
\end{align*}
Hence, $\norm{p^k - p^0}_{\gamma} \to  \norm{p^{\ast} - p^0}_{\gamma}$. Since $p^k - p^0 \wto p^* - p^0$, it then follows that $p^k - p^0 \to p^* - p^0$, which implies $p^k \to p^*$.

\mgap

{\bf Step 2.} The result $z^k \to z^*$ and $w_i^k \to w_i^*$ ($1\leq i\leq n$) is a direct consequence of the convergence $p^k \to p^*$ and the definitions $p^k = (z^k, w_1^k, \dots, w_{n-1}^k)$, 
$p^* = (z^*, w_1^*, \dots, w_{n-1}^*)$, $w_n^k = -\sum_{i=1}^{n-1}G_i^*w_i^k$ and 
$w_n^* = -\sum_{i=1}^{n-1}\,G_i^* w_i^*$. To finish the proof of the theorem, it remains to prove that
$\seq{x_i^k}$ and $\seq{y_i^k}$ converge strongly to 
$G_i z^*$ and $w_i^*$, respectively, for all $i =1, \dots, n$. To this end, note that this result follows directly from Proposition \ref{pro:lim}\emph{\ref{pro:lim.sex}} and the fact that $z^k \to z^*$ and $w_i^k \to w_i^*$ ($1\leq i\leq n$) .
\end{proof}


\subsection{Iteration-complexity analysis of Algorithm \ref{alg:iHPEP}}
\lab{subsec:itec}

In this subsection we study the iteration-complexity of Algorithm \ref{alg:iHPEP}.
To this purpose, we first introduce the following notion of approximate solution for 
problem \eqref{eq:probr}: $\{x_i\}_{i=1}^n$, $\{y_i\}_{i=1}^n$ and $\{\varepsilon_i\}_{i=1}^n$, 
where $x_i, y_i \in \HH_i$ and $\varepsilon_i \in \R_+$ ($i=1, \ldots ,n$), define an approximate solution of \eqref{eq:probr}  with tolerance $\rho > 0$ if 
\begin{align}\label{errortolerance}
\begin{aligned}
& y_i \in T_i^{[\varepsilon_i]}(x_i), \quad i=1, \ldots,n, \quad \sum_{i=1}^{n} \varepsilon_i \leq \rho, \quad  \Norm{\sum_{i=1}^{n-1}G_i^\ast y_i + y_n} \leq \rho,\\[2mm]
& \norm{x_i - G_i x_n} \leq \rho, \quad i=1, \ldots, n-1.
\end{aligned}
\end{align}
It is easy to check that if we set $\rho = 0$ in \eqref{errortolerance}, then it follows that $x_n$ is a solution of
\eqref{eq:probr}.

Next we present our result on the iteration-complexity of Algorithm \ref{alg:iHPEP}. We wish to estimate the number of iterations that  Algorithm \ref{alg:iHPEP} requires to find $\{x_i\}_{i=1}^n$, $\{y_i\}_{i=1}^n$ and $\{\varepsilon_i\}_{i=1}^n$ satisfying \eqref{errortolerance}, for a given tolerance $\rho > 0$.

\mgap

\begin{theorem}[Pointwise iteration-complexity of Algorithm \ref{alg:iHPEP}]\label{theo:ite-com}
Consider the sequences evolved by \emph{Algorithm \ref{alg:iHPEP}}, let $d_{0,\gamma}$ denote the distance of $p^0$ to the solution set $\Sa_e$ as in \eqref{eq:KTS} and let 
the constant $\Omega_{(\alpha, \beta)} > 0$ be as in \eqref{eq:def.omega}. 
Also, suppose \emph{Assumptions 
A1--A3, \ref{assu:lambda}} and \emph{\ref{assu:ab}} hold.
Then, for all $k \geq 0$, there exists $\ell \in \{0,1, \ldots,k\}$ such that
\begin{subnumcases}{ }
y_i^\ell \in T_i^{[\varepsilon_i^\ell]}(x_i^\ell), \quad i =1, \ldots ,n, & \lab{peryj} \\[3mm]
\Norm{\sum_{i=1}^{n-1}G_i^\ast y_i^\ell + y_n^\ell} \leq  
\dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) d_{0,\gamma}}{\sqrt{k+1}} 
\left( \dfrac{4 \sqrt{\gamma} \max\{1, 1/\gamma\}\sqrt{\Omega_{(\alpha, \beta)}}}{(1-\sigma^2) \min \{\underline{\lambda}, 1/\overline{\lambda}\}}\right), & \label{des:v_jcom} \\[3mm]
\norm{x_i^\ell - G_i x_n^\ell} \leq \dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) d_{0,\gamma}}{\sqrt{k+1}} 
\left( \dfrac{4 \max \{1, 1/\gamma\}\sqrt{\Omega_{(\alpha, \beta)}}}{(1-\sigma^2) \min \{\underline{\lambda}, 1/\overline{\lambda}\}}\right),\quad i=1,\ldots, n-1, & \label{des:e_jcom}  \\[3mm]
\sum_{i=1}^n \varepsilon_i^\ell \leq  
\dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) d_{0,\gamma}^2}{k+1}\left( \dfrac{4\sigma^2 \max \{1, 1/\gamma\}
\Omega_{(\alpha, \beta)}}{(1-\sigma^2)^2 \min \{\underline{\lambda}, 1/\overline{\lambda}\}}\right). \lab{eq:wind}
\end{subnumcases}
\end{theorem}
\bproo
Direct use of the first inequality in item \emph{\ref{lem:kyoto.seg}} and item \emph{\ref{lem:kyoto.ter}}
of Lemma \ref{lem:kyoto} yields, for all $j\geq 0$,
\begin{align} \lab{eq:vacation}
\Delta_j \coloneqq \max\left\{ \dfrac{\normq{\nabla \varphi_j}_\gamma}{c^2}, 
\dfrac{1 - \sigma^2}{c \,\sigma^2}\sum_{i=1}^n\,\varepsilon_i^j\right\}\leq \normq{p^{j+1} - \widetilde p^j}_\gamma
\end{align}
which in turn combined with Proposition \ref{pr:sumfin} gives
\begin{align*}
\sum_{j=0}^k\,\Delta_j \leq \Omega_{(\alpha, \beta)} d_{0,\gamma}^2
\end{align*}
where $\Omega_{(\alpha, \beta)}$ is as in \eqref{eq:def.omega}. So, choosing $\ell \in \set{0, \dots, k}$ such that
$\Delta_\ell = \min_{j=0, \dots, k}\,\Delta_j$ we find
\begin{align}\lab{eq:vacation02}
(k + 1) \Delta_\ell \leq \Omega_{(\alpha, \beta)} d_{0,\gamma}^2.
\end{align}
From \eqref{eq:vacation} and \eqref{eq:vacation02},
\begin{align} \lab{eq:vacation03}
 \normq{\nabla \varphi_\ell}_\gamma\leq \dfrac{c^2\Omega_{(\alpha, \beta)} d_{0,\gamma}^2}{k+1}
 \quad \mbox{and} \quad 
 \sum_{i=1}^n\,\varepsilon_i^\ell\leq \dfrac{c\,\sigma^2\Omega_{(\alpha, \beta)} d_{0,\gamma}^2}{(1 - \sigma^2)(k+1)}.
\end{align}
(Recall that $c$ is defined as in \eqref{eq:constantc}.) Now combining the first inequality in \eqref{eq:vacation03}
and \eqref{eq:norm.grad.pi_k} we also find
\begin{align*}
\gamma^{-1}\left\|\sum_{i=1}^{n-1}G_i^*y_i^\ell + y_n^\ell\right\|^2 + \sum_{i=1}^{n-1}\norm{x_i^\ell - G_ix_{n}^\ell}^2
\leq \dfrac{c^2\Omega_{(\alpha, \beta)} d_{0,\gamma}^2}{k+1},
\end{align*}
which in turn, after some simple algebra, yields \eqref{des:v_jcom} and \eqref{des:e_jcom}. Note also that \eqref{eq:wind}  follows directly from the second inequality in \eqref{eq:vacation03}. To finish the proof of the theorem, note that 
\eqref{peryj} follows from Algorithm \ref{alg:iHPEP}'s definition (see the inclusions in \eqref{eq:proxT_i}).
\eproo



