\section{Variants of the strongly convergent inertial projective splitting algorithm with forward-backward
and forward-backward-forward steps} \label{sec:FB-TFB}

In this section we consider a structured version of the monotone inclusion problem \eqref{eq:probr}, where 
each maximal monotone operator $T_i$ has a splitting  structure: $T_i = F_i + B_i$ for all $i =1, \dots, n$. 
More precisely, we consider the inclusion problem 
\begin{align}\label{eq:Smip}
0\in \sum_{i=1}^{n}G_i^*(\underbrace{F_i + B_i}_{T_i})G_i(z),
\end{align}
where $n\geq 2$ and the following holds:
\begin{itemize}
\item [B1.] $F_i \colon \Dom F_i \subseteq \Ha_i \to \Ha_i$ is a single-valued continuous monotone map.
\item [B2.] $B_i \colon \Ha_i \tos \Ha_i$ is a set-valued maximal monotone operator such that 
$\Dom B_i \subseteq C_i \subseteq \Dom F_i$, where $C_i$ is a nonempty closed and convex subset of $\Ha_i$.
\item [B3.] Assumption A2 of Section \ref{sec:main} holds on the bounded linear operators 
$G_i$ ($1\leq i\leq n$).
\item [B4.] The solution set of \eqref{eq:Smip} is nonempty.
\end{itemize}
Under mild assumptions on the functions $f_i(\cdot)$ and $g_i(\cdot)$ ($1\leq i\leq n$), problem \eqref{eq:Smip} encompasses
the finite-sum convex minimization problem
\[
\min_{x \in \Ha_0} \sum_{i=1}^n f_i(G_ix) + g_i(G_ix)
\]
where, for $i=1, \dots, n$, $f_i \colon \Ha_i \to \R\cup\{+\infty\}$ is a proper closed and convex function and 
$g_i \colon \Ha_i \to \mathbb{R}$ is a sufficiently smooth finite convex function. 

\mgap

\brema \lab{rem:adapter}
\emph{
Assumptions B1 and B2 above guarantee that $T_i = F_i + B_i$ ($1\leq i\leq n$) is 
maximal monotone (see, e.g., \cite{MS11}). This combined with B3 and B4 gives us that the conditions on Assumptions A1--A3 of Section \ref{sec:main} are met in the setting of the present section. 
Hence, one can apply the results of Section \ref{sec:main} to problem \eqref{eq:Smip}.} 
\erema

Assuming that the resolvents $(B_i + I)^{-1}$ of $B_i(\cdot)$ ($1\leq i \leq n$) are easy to 
evaluate, in this section we propose two variants of Algorithm \ref{alg:iHPEP} for (numerically) solving \eqref{eq:Smip}, namely:
\begin{itemize}
\item [1.]  One with forward-backward steps for subproblems, assuming
$F_i(\cdot)$ is $L_i^{-1}$-cocoercive on $\Dom F_i$, i.e., for $i = 1, \dots, n$,
\begin{align}\label{ineq:cocoercivity}
\inner{F_i(x) - F_i(y)}{ x - y}  \geq \frac{1}{L_i} \normq{F_i(x) - F_i(y)} \quad \mbox{for all} \quad x, y \in \Dom F_i,
\end{align}
where $L_i >0$. The proposed algorithm appears as Algorithm \ref{alg:iHPEP-FB} below and the main results on its convergence and iteration-complexity are summarized in Theorem \ref{theo:FBComplexity}.
\item [2.] A second variant with forward-backward-forward (Tseng) steps for the case where 
$F_i (\cdot)$ is $L_i$-Lipschitz continuous, i.e., for $i = 1, \dots, n$,
\begin{align}\label{ineq:lipschitz}
\norm{F_i(x) - F_i(y)} \leq L_i \norm{ x - y} \quad \mbox{for all} \quad  x,y \in \Dom F_i,
\end{align}
where $L_i > 0$. The method is presented as Algorithm \ref{alg:iHPEP-Tseng-FB} below, and the main results on its strong convergence and iteration-complexity are summarized in Theorem \ref{theo:TFBComplexity}.
\end{itemize}



\subsection{A variant of the strongly convergent inertial projective splitting algorithm with forward-backward 
steps} \label{subsec:F-B}

In this subsection, assuming that B1--B4 and \eqref{ineq:cocoercivity} hold, we propose 
Algorithm \ref{alg:iHPEP-FB} to numerically solve \eqref{eq:Smip}.

\mgap

\begin{algorithm}%[H]
%\label{alg:iHPEP-FB}
\caption{A variant of the strongly convergent inertial PS algorithm with forward-backward 
steps for solving \eqref{eq:Smip}.}
%\DontPrintSemicolon
\SetAlgoLined
\KwInput{$(z^{-1}, w^{-1}_1, \ldots, w^{-1}_{n-1})  = (z^{0}, w^0_1, \ldots, w^0_{n-1})\in \boldsymbol{\Ha}$, 
scalars $0 < \sigma < 1$ and $\gamma > 0$. For $i=1, \dots, n$, set $\lambda_i = 2 \sigma^2/L_i$.}
\For{ $k=0,1,\ldots$}{ 
Choose $\alpha_k \geq 0$, $\beta_k \geq 0$ and let
\begin{align}
\label{eq:ext.01zFB}
&\widehat z^{\,k} = z^k+\alpha_k(z^k-z^{k-1}), \quad \widetilde{z}^{\, k} = \widehat{z}^{k} + \beta_k (\widehat{z}^{\, k} - z^0 ),\\[3mm]
\label{eq:ext.02zFB}
&\widehat{w}_i^{\,k} = w_i^{k} + \alpha_k (w_i^k - w_i^{k-1}), \quad  \widetilde{w}^{\, k}_{i} = \widehat{w}^{\,k}_{i} + \beta_k (\widehat{w}^{\,k}_i - w^{0}_i) \quad (i =1, \ldots, n-1), \\[3mm]
\label{eq:ext.03zFB}
& \widetilde w_n^{\,k} = -\sum_{i=1}^{n-1}G_i^*\widetilde w_i^{\,k}.
\end{align}
For $i=1, \ldots,n$, let $\overline{z}_i^{\,k} \coloneqq P_{C_i}(G_i\wti z^{\,k})$ and compute
\begin{align}
\label{eq:proxFB_i}
\begin{cases}
x_i^k \coloneqq (\lambda_i B_i+I)^{-1}\left(G_i \widetilde{z}^{\,k} + \lambda_i \widetilde w_i^k - \lambda_i F_i(\overline{z}^{\,k}_i)\right),&\\[3mm]
y_i^k \coloneqq \dfrac{1}{\lambda_i}(G_i \wti z^{\,k}_i + \lambda_i \wti w_i^{\,k}-x_i^k).
\end{cases}
\end{align}
\If{$x_i^k = G_i x_n^k$ \emph{(}$i=1, \ldots, n-1$\emph{)} \emph{and} 
$\displaystyle \sum_{i=1}^{n-1}G_i^*y_i^k  + y_n^k = 0$}
 	{\Return 
 	\begin{align} \lab{eq:returnFB}
 	(\overline z, \overline w_1, \ldots , \overline w_{n-1}) \coloneqq (x_n^k, y_1^k, \dots, y_{n-1}^k).
 	\end{align}}
For $i =1, \dots, n$, let 
\begin{align}\label{eq:epsilon1}
\varepsilon_i^k \coloneqq \dfrac{L_i\normq{x_i^k -  \overline{z}^{\,k}_i}}{4}.
\end{align}
Let the affine functional $\varphi_k(\cdot)$ be as in \eqref{eq:sep.F} (see also \eqref{eq:car.varphi}),
let
\begin{align}\label{def:pk3}
p^{k} \coloneqq (z^{k}, w_1^{k}, \ldots, w_{n-1}^{k}),
\end{align}
set
\begin{align}\label{def:3Hk-Wk}
\begin{aligned}
& H_k =\left\{p\in \boldsymbol{\Ha} \mid \varphi_{k}(p)\leq 0\right\},\\
& W_k =\left\{p\in \boldsymbol{\Ha} \mid \inner{p^0-p^k}{p-p^k}_{\gamma}\leq 0\right\},
\end{aligned}
\end{align}
and compute the next iterate
\begin{align}\label{eq:FBupdt01}
(z^{k+1}, w_1^{k+1}, \ldots , w_{n-1}^{k+1}) = P_{H_k \cap W_k}(p^0).
\end{align}
}
\label{alg:iHPEP-FB}
\end{algorithm}

We  now make some comments regarding Algorithm \ref{alg:iHPEP-FB}:

\begin{enumerate}[label = (\roman*)]
\item Algorithm \ref{alg:iHPEP-FB} is essentially Algorithm \ref{alg:iHPEP} for solving the structural inclusion 
\eqref{eq:Smip} where the triple $(x_i^k, y_i^k, \varepsilon_i^k)$ ($1\leq i\leq n$) satisfying the relative-error condition \eqref{eq:proxT_i} is explicitly computed according to \eqref{eq:proxFB_i} and \eqref{eq:epsilon1}; see Proposition \ref{pro:error-FB} below. We mention that the idea of exploiting structural properties in operator splitting methods by forward-backward steps goes back at least to~\cite{LM79, Pas79},
also appearing more recently (see, e.g., \cite{MS10}) in connection with modern inexact relative-error proximal-point algorithms. 
\item Since Algorithm \ref{alg:iHPEP-FB} is a special instance Algorithm \ref{alg:iHPEP}, it follows that almost all comments and remarks just before or right after the latter algorithm also apply to the former 
(see comments/remarks (i)--(vi) following Algorithm \ref{alg:iHPEP}). 
\item In view of the assumption that the resolvents $(B_i + I)^{-1}$ of $B_i(\cdot)$ ($1\leq i\leq n$) are easy to evaluate, we  obtain that the computation of $x_i^k$ as in \eqref{eq:proxFB_i} essentially depends on the evaluation of the linear operator $G_i$ at $\widetilde z^k$ and of the (monotone) operator $F_i(\cdot)$ at 
$\overline z_i^k$. The main reason to introduce the orthogonal projection $\overline z_i^k$ is to recover feasibility of $G_i \widetilde z^k$ with respect to the $\Dom F_i$ of $F_i(\cdot)$ (see Assumption B2). 
If $\Dom F_i$ is equal to the whole space $\HH_i$, then one could simply set $\overline z_i^k = G_i \widetilde z^k$
and no extra projection onto $C_i$ would be required in the implementation of Algorithm \ref{alg:iHPEP-FB}.
\end{enumerate}

Next we prove that Algorithm \ref{alg:iHPEP-FB} is in fact a special instance of Algorithm \ref{alg:iHPEP}:

\begin{proposition}\label{pro:error-FB}
Let $(x_i^k, y_i^k)$ and $\varepsilon_i^k$ \emph{(}$1\leq i\leq n$\emph{)} be as in \eqref{eq:proxFB_i}
and \eqref{eq:epsilon1}, respectively, and let $\widetilde z^k$ and $\widetilde w_i^k$ \emph{(}$1\leq i\leq n$\emph{)} be as in \eqref{eq:ext.01zFB}--\eqref{eq:ext.03zFB}. Also, let $\lambda_i = 2\sigma^2/L_i$
be defined as in the input of \emph{Algorithm \ref{alg:iHPEP-FB}}. The following holds for all $i=1, \ldots ,n$ and  $k \geq 0$:
\begin{align}\label{relationFB}
\begin{aligned}
& y_i^k \in (F_i^{[\varepsilon_i^k]} + B_i)(x_i^k) \subseteq (F_i + B_i)^{[\varepsilon_i^k]}(x_i^k),\\[2mm]
& \lambda_i y_i^k + x_i^k - (G_i \widetilde{z}^{\,k} + \lambda_i  \widetilde{w}_i^{\,k}) = 0, \quad 
2 \lambda_i \varepsilon_i^k \leq \sigma^2 \normq{G_i \wti z^{k} - x_i^k}.
\end{aligned}
\end{align}
In particular, \emph{Algorithm \ref{alg:iHPEP-FB}} is a special instance of \emph{Algorithm \ref{alg:iHPEP}} 
 \emph{(}with $\lambda_i^k \equiv \lambda_i = 2\sigma^2/L_i$ for all $1\leq i\leq n$\emph{)} for solving \eqref{eq:Smip}.
\end{proposition}
\begin{proof}
Using \eqref{eq:proxFB_i}, the definition of the resolvent $(\lambda_i B_i + I)^{-1}$ and some simple algebraic manipulations we find
$ y_i^k \in F_i(\overline z_i^k) + B_i(x_i^k)$,
which in turn combined with Lemma \ref{lem:trans} and the definition of 
$\varepsilon_i^k$ (see \eqref{eq:epsilon1}) gives the first inclusion in \eqref{relationFB}; 
the second one follows from the first and Proposition \ref{pr:teps}(\emph{\ref{teps.ter}} and \emph{\ref{pr:teps.qui}}).
The identity in \eqref{relationFB} follows directly from the definition of $y_i^k$ as in 
\eqref{eq:proxFB_i}. To finish the proof of \eqref{relationFB}, it remains to prove the inequality. To this end, note that \eqref{eq:epsilon1}, the definition of $\lambda_i$ as $\lambda_i = 2\sigma^2/L_i$ and some simple algebra yield
\begin{align*}
2\lambda_i \varepsilon_i^k \leq \sigma^2\normq{x_i^k - \overline z_i^k}\leq \sigma^2 \normq{G_i \wti z^{k} - x_i^k},
\end{align*}
where in the second inequality we used the definition $\overline{z}_i^{\,k} \coloneqq P_{C_i}(G_i\wti z^{\,k})$ and the inclusion $x_i^k\in C_i$ (because $x_i^k\in \Dom B_i\subseteq C_i$). The last statement of the proposition follows from \eqref{relationFB} and the definitions of Algorithms \ref{alg:iHPEP} and \ref{alg:iHPEP-FB}.
\end{proof}

\mgap

\brema \lab{rem:seifu}
\emph{
In view of Proposition \ref{pro:error-FB} and Corollary \ref{cor:airflo}, from now on in this subsection 
we will assume that Algorithm \ref{alg:iHPEP-FB} doesn't stop.
}
\erema

\mgap

\brema \lab{rem:1042}
\emph{
Using the definition of $\lambda_i^k \equiv \lambda_i = 2\sigma^2/L_i$ in Algorithm \ref{alg:iHPEP-FB}, we see that the condition in Assumption \ref{assu:lambda} is satisfied with
\begin{align} \lab{eq:def.up}
 \underline \lambda \coloneqq \dfrac{2\sigma^2}{\overline L}\quad \mbox{and} \quad
 \overline \lambda \coloneqq \dfrac{2\sigma^2}{\underline L},
\end{align}
where
\begin{align} \lab{eq:def.L}
\overline L \coloneqq \displaystyle \max_{i=1,\dots, n} L_i \quad \mbox{and} \quad
\underline L \coloneqq \displaystyle \min_{i=1,\dots, n} L_i.
\end{align}
}
\erema

\mgap

In what follows we summarize the main results on the strong convergence and iteration-complexity of Algorithm \ref{alg:iHPEP-FB}: 

\begin{theorem}[Strong convergence and iteration-complexity of Algorithm \ref{alg:iHPEP-FB}] \label{theo:FBComplexity}
Consider the sequences evolved by \emph{Algorithm \ref{alg:iHPEP-FB}}, let $d_{0,\gamma}$ denote the distance of $p^0$ to extended-solution set $\Sa_e \neq \emptyset$, let $\overline L, \underline L > 0$ be as in \eqref{eq:def.L} and let $\Omega_{(\alpha, \beta)} > 0$ be as in \eqref{eq:def.omega}. Suppose assumptions \emph{B1--B4} and
\emph{\ref{assu:ab}} are valid (see also \emph{Remarks \ref{rem:adapter} and \ref{rem:1042}}), and that the (cocoercivity) condition 
\eqref{ineq:cocoercivity} also holds for $F_i(\cdot)$ ($1\leq i\leq n$).
Then the following statements are true:
\begin{enumerate}[label = \emph{(\alph*)}]
\item \emph{(}Strong convergence\emph{)} All statements of \emph{Theorem \ref{th:sconv}} also hold for \emph{Algorithm \ref{alg:iHPEP-FB}}.
\item \emph{(}Iteration-complexity\emph{)} For all $k \geq 0$, there exists $\ell \in \{0,1, \ldots,k\}$ such that
\begin{align*}
\begin{cases}
y_i^\ell \in (F_i^{[\varepsilon_i^\ell]} + B_i)(x_i^\ell), \quad i =1, \ldots ,n, & \\[3mm]
\Norm{\sum_{i=1}^{n-1}G_i^\ast y_i^\ell + y_n^\ell} \leq  
\dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) 
\max\left\{\dfrac{\overline L}{2\sigma^2}, \dfrac{2\sigma^2}{\underline L}\right\}d_{0,\gamma}}{\sqrt{k+1}} 
\left( \dfrac{4\sqrt{\gamma} \max\{1, 1/\gamma\}\sqrt{\Omega_{(\alpha, \beta)}}}{1-\sigma^2}\right), 
&\\[4mm]
\norm{x_i^\ell - G_i x_n^\ell} \leq \dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) 
\max\left\{\dfrac{\overline L}{2\sigma^2}, \dfrac{2\sigma^2}{\underline L}\right\} d_{0,\gamma}}{\sqrt{k+1}} 
\left( \dfrac{4 \max \{1, 1/\gamma\}\sqrt{\Omega_{(\alpha, \beta)}}}{1-\sigma^2}\right), &\\[5mm]
\hspace{10cm} i=1,\ldots, n-1, &\\[3mm]
\sum_{i=1}^n \varepsilon_i^\ell \leq  \dfrac{n \Big(\displaystyle \max_{i =1, \ldots,n}\normq{G_i}\Big) \max\left\{\dfrac{\overline L}{2\sigma^2}, \dfrac{2\sigma^2}
{\underline L}\right\}d_{0,\gamma}^2}{k+1}\left( \dfrac{4\sigma^2 \max \{1, 1/\gamma\}
\Omega_{(\alpha, \beta)}}{(1-\sigma^2)^2}\right).
\end{cases}
\end{align*}
 \end{enumerate}
\end{theorem}
\begin{proof}
The proof follows directly from Proposition \ref{pro:error-FB}, Remarks \ref{rem:adapter}, \ref{rem:seifu} and \ref{rem:1042}, and Theorems \ref{th:sconv}
and \ref{theo:ite-com}.
\end{proof}


\subsection{A variant of the strongly convergent inertial projective splitting algorithm with forward-backward-forward (Tseng) steps}\label{subsec:TF-B}

In this subsection, assuming that B1--B4 and \eqref{ineq:lipschitz} hold, we propose a 
variant of Algorithm \ref{alg:iHPEP} (Algorithm \ref{alg:iHPEP-Tseng-FB} below) tailored for the structured inclusion \eqref{eq:Smip}.

\mgap

\begin{algorithm}%[H]
%\label{alg:iHPEP-Tseng-FB}
\caption{A variant of the strongly convergent inertial PS algorithm with forward-backward-forward 
steps for solving \eqref{eq:Smip}.}
%\DontPrintSemicolon
\SetAlgoLined
\KwInput{$(z^{-1},w^{-1}_1,\ldots,w^{-1}_{n-1})  = (z^0,w^0_1,\ldots,w^0_{n-1})\in \boldsymbol{\Ha}$, scalars 
$0 < \sigma<1$ and $\gamma >0$. For $i = 1, \dots, n$, set $\lambda_i =  \sigma/L_i$.}
\For{ $k=0,1,\ldots$}{ 
Choose $\alpha_k \geq 0$, $\beta_k \geq 0$ and let
\begin{align}
\label{eq:ext.01zTFB}
&\widehat z^{\,k} = z^k+\alpha_k(z^k-z^{k-1}), \quad \widetilde{z}^{\, k} = \widehat{z}^{k} + \beta_k (\widehat{z}^{\, k} - z^0 ),\\[3mm]
\label{eq:ext.02zTFB}
&\widehat{w}_i^{\,k} = w_i^{k} + \alpha_k (w_i^k - w_i^{k-1}), \quad  \widetilde{w}^{\, k}_{i} = \widehat{w}^{\,k}_{i} + \beta_k (\widehat{w}^{\,k}_i - w^{0}_i) \quad (i =1, \ldots, n-1), \\[3mm]
\label{eq:ext.03zTFB}
& \widetilde w_n^{\,k} = -\sum_{i=1}^{n-1}G_i^*\widetilde w_i^{\,k}.
\end{align}
For $i=1, \dots, n$, let $\overline{z}_i^k \coloneqq P_{C_i}(G_i \wti z^{\,k})$ and compute  
\begin{align} \label{eq:proxTFB_i}
\begin{cases}
x_i^k = (\lambda_i B_i+I)^{-1}\left(G_i \widetilde{z}^{\,k} + \lambda_i \wti w_i^k - \lambda_i F_i(\overline{z}_i^k)\right),&\\[3mm]
y_i^k = \dfrac{G_i \wti z^{\,k} + \lambda_i \wti w_i^k -x_i^k}{\lambda_i} + F_i(x_i^k) - F_i(\overline{z}_i^k).
\end{cases}
\end{align}
\If{$x_i^k = G_i x_n^k$ \emph{(}$i=1, \ldots, n-1$\emph{)} \emph{and} 
$\displaystyle \sum_{i=1}^{n-1}G_i^*y_i^k  + y_n^k = 0$}
 	{\Return 
 	\begin{align} \lab{eq:returnTFB}
 	(\overline z, \overline w_1, \ldots , \overline w_{n-1}) \coloneqq (x_n^k, y_1^k, \dots, y_{n-1}^k).
 	\end{align}}
For $i =1, \dots, n$, set
\begin{align}\label{eq:epsilon1T}
\varepsilon_i^k \coloneqq 0.
\end{align}
Let the affine functional $\varphi_k(\cdot)$ be as in \eqref{eq:sep.F} (see also \eqref{eq:car.varphi}),
let
\begin{align}\label{def:Tpk3}
p^{k} \coloneqq (z^{k}, w_1^{k}, \ldots, w_{n-1}^{k}),
\end{align}
set
\begin{align}\label{def:T3Hk-Wk}
\begin{aligned}
& H_k =\left\{p\in \boldsymbol{\Ha} \mid \varphi_{k}(p)\leq 0\right\},\\
& W_k =\left\{p\in \boldsymbol{\Ha} \mid \inner{p^0-p^k}{p-p^k}_{\gamma}\leq 0\right\},
\end{aligned}
\end{align}
and compute the next iterate
\begin{align}\label{eq:Tupdt01}
(z^{k+1}, w_1^{k+1}, \ldots , w_{n-1}^{k+1}) = P_{H_k \cap W_k}(p^0).
\end{align}
}
\label{alg:iHPEP-Tseng-FB}
\end{algorithm}

\mgap 

Next we make some remarks regarding Algorithm \ref{alg:iHPEP-Tseng-FB}:
\begin{enumerate}[label = (\roman*)]
\item As it was the case for Algorithm \ref{alg:iHPEP-FB}, Algorithm \ref{alg:iHPEP-Tseng-FB} is also a special instance of Algorithm \ref{alg:iHPEP} (see Proposition \ref{pro:error-TFB} below). More precisely, Algorithm \ref{alg:iHPEP-Tseng-FB} is essentially 
Algorithm \ref{alg:iHPEP} for solving \eqref{eq:Smip} where the triple $(x_i^k, y_i^k, \varepsilon_i^k)$ ($1\leq i\leq n$) satisfying condition \eqref{eq:proxT_i} is also explicitly computed but now according to \eqref{eq:proxTFB_i}
and \eqref{eq:epsilon1T}. The idea of using forward-backward-forward steps as \eqref{eq:proxTFB_i} was introduced by P. Tseng in the seminal paper~\cite{Tse00} (see also \cite{MS10}).
\item As it was also observed for Algorithm \ref{alg:iHPEP-FB},  since Algorithm \ref{alg:iHPEP-Tseng-FB} is a special instance Algorithm \ref{alg:iHPEP}, it follows that almost all the comments/remarks (i)--(vi) 
just before or right after Algorithm \ref{alg:iHPEP} also apply to Algorithm \ref{alg:iHPEP-Tseng-FB}.
\item Algorithm \ref{alg:iHPEP-Tseng-FB} operates in a more flexible setting, regarding the monotone inclusion problem \eqref{eq:Smip} -- because cocoercivity is more restrictive than Lipschitz continuity (see \eqref{ineq:cocoercivity} and \eqref{ineq:lipschitz}) --, at the cost, when compared to 
\eqref{eq:proxFB_i}, of an extra evaluation of the single-valued operator $F_i(\cdot)$ at $x_i^k$.
\end{enumerate}

\mgap

Algorithm \ref{alg:iHPEP-Tseng-FB} is also a special instance of Algorithm \ref{alg:iHPEP}:


\begin{proposition}\label{pro:error-TFB}
Let $(x_i^k, y_i^k)$ \emph{(}$1\leq i\leq n$\emph{)} be as in \eqref{eq:proxTFB_i} and let $\widetilde z^k$ and $\widetilde w_i^k$ \emph{(}$1\leq i\leq n$\emph{)} be as in \eqref{eq:ext.01zTFB}--\eqref{eq:ext.03zTFB}. Also, let $\lambda_i = \sigma/L_i$
be defined as in the input of \emph{Algorithm \ref{alg:iHPEP-Tseng-FB}}.
The following holds, for all $i=1, \ldots ,n$ and  $k \geq 0$:
\begin{align}\label{relationTFB}
\begin{aligned}
& y_i^k \in  (F_i + B_i)(x_i^k),\\[1mm]
& \norm{\lambda_i y_i^k + x_i^k  - (G_i \wti z^{\,k} + \lambda_i \wti w_i^k)} \leq 
\sigma\norm{G_i \wti z^{\,k}_i - x_i^k}.
\end{aligned}
\end{align}
In particular, \emph{Algorithm \ref{alg:iHPEP-Tseng-FB}} is special instance of \emph{Algorithm \ref{alg:iHPEP}}
\emph{(}with $\lambda_i^k \equiv \lambda_i = \sigma/L_i$ for all $i =1, \dots, n$\emph{)} for solving \eqref{eq:Smip}.
\end{proposition}
\begin{proof}
The proof follows the same pattern as that of Proposition~\ref{pro:error-FB}. For convenience, we present a sketch.
From \eqref{eq:proxTFB_i} and some simple algebraic manipulations, we obtain the inclusion in \eqref{relationTFB}.
To proof the inequality, note first that, from the identity in \eqref{eq:proxTFB_i}, we have 
$ \lambda_i y_i^k + x_i^k  - (G_i \wti z^{\,k} + \lambda_i \wti w_i^k) = \lambda_i (F_i(x_i^k) - F_i(\overline z_i^k)) $, which in turn yields the desired result as a consequence of the $ L_i $-Lipschitz continuity of $ F_i(\cdot) $ and the definition of
$ \lambda_i $. The final claim of the proposition follows directly from \eqref{relationTFB} and the definitions of Algorithms~\ref{alg:iHPEP-Tseng-FB} and~\ref{alg:iHPEP}.
\end{proof}

