		\title{Iteration Steps of 3x+1 Problem}

		\author{Youchun Luo\corref{cor1}}
		\cortext[cor1]{Email: yc-luo24@mails.tsinghua.edu.cn}

		\affiliation{organization={Tsinghua Shenzhen International Graduate School, Tsinghua University},%Department and Organization
			city={Shenzhen},
			state={Guangdong},
			postcode={518055},
			country={China}}

		\begin{abstract}
			On the 3x+1 problem, given a positive integer $N$, let $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $ be the total iteration steps, the odd iteration steps and the even iteration steps when $N$ iterates to 1(except 1) respectively. Trivially, we have $D\left( N \right) =O\left( N \right) +E\left( N \right) $. In this paper, we propose a so-called weak residue conjecture(i.e., $\frac{2^{E\left( N \right)}}{3^{O\left( N \right)}\cdot N}\le 2$). We prove that if 3x+1 conjecture is true and the weak residue conjecture is true, there exist non-trivial relationships among $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $, i.e., $O\left( N \right) =\left[ \log _62\cdot D\left( N \right) -\log _6N \right] $(it implies that we can calculate $O\left( N \right) $, $E\left( N \right) $ directly by $D\left( N \right) $ only, of course given $N$), and 5 more similar equations are derived simultaneously.
		\end{abstract}

		%\begin{highlights}
			%\item A nontrivial relationship among the total iteration steps $D\left( N \right) $, the odd iteration steps $O\left( N %\right) $ and the even iteration steps $E\left( N \right) $ of the 3x+1 problem is derived in this paper.
		%\end{highlights}

		%\begin{keyword}
			%Collatz Conjecture \sep Residue \sep Odd iteration steps \sep Even iteration steps % 用 \sep 分隔关键词
		%\end{keyword}

	\end{frontmatter}

	\section{Introduction}
	The 3x+1 problem is most simply stated in terms of the Collatz function $C\left( N \right) $ \textcolor{red}{\textbf{\citep{Lagarias1985,Lagarias2012}}}
	:
	\begin{equation}
	\begin{split}
		C(N)=\left\{ \begin{array}{c}
			3N+1,\mathrm{   if }N\equiv 1\left( \mathrm{mod}2 \right)\\\\
			\frac{N}{2},\mathrm{   if }N\equiv 0\left( \mathrm{mod}2 \right)\\
		\end{array} \right.
	\end{split}
	\label{eq:combined}
	\end{equation}
	The 3x+1 problem(or Collatz Conjecture) is to prove that starting from any positive integer, some iterate of this function takes the value 1. Numerical computation has verified Collatz Conjecture for all $N\le 5.78\times 10^{18}$ \textcolor{red}{\textbf{\citep{Silva2010}}}.
	For any positive integer $N$, let $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $ be the total iteration steps, the odd iteration steps and the even iteration steps when $N$ iterates to 1(except 1) respectively. The even iteration steps $E\left( N \right) $ actually equals to the total stopping time $\sigma _{\infty}\left( N \right) $ \textcolor{red}{\textbf{\citep{Leavens1992}}}:
	\begin{equation}
		E\left( N \right) =\sigma _{\infty}\left( N \right)
	\label{eq:emc}
	\end{equation}
	Literature studying the total stopping time $\sigma _{\infty}\left( N \right) $ can be found in \textcolor{red}{\textbf{\citep{Andaloro2000,Ladue2018}}}.
	Obviously, there exists a trivial relationship:
	\begin{equation}
		D\left( N \right) =O\left( N \right) +E\left( N \right)
		\label{eq:emc}
	\end{equation}
	For example, the iteration of 7:
	$$7\rightarrow 22\rightarrow 11\rightarrow 34\rightarrow 17\rightarrow 52\rightarrow 26\rightarrow 13\rightarrow 40\rightarrow 20\rightarrow 10\rightarrow $$
	$$5\rightarrow 16\rightarrow 8\rightarrow 4\rightarrow 2\rightarrow 1$$
	Thus, 
	$$D\left( 7 \right) =16, O\left( 7 \right) =5, E\left( 7 \right) =11$$

	We will prove a nontrivial relationship among $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $ by introducing the so-called Residue. According to Eric Roosendaal’s definition \textcolor{red}{\textbf{\citep{Roosendaal2025}}}, the Residue of $N$:
	\begin{equation}
	Res(N)=\frac{2^{E(N)}}{3^{O(N)}\cdot N}
	\label{eq:emc}
	\end{equation}
	For the lower bound of Residue, $Res\left( N \right) \ge 1$ was proved by \textcolor{red}{\textbf{\citep{Andrei2000,Monks2002}}}. In this paper, we give a different proof of $Res\left( N \right) \ge 1$ in the second section. For the upper bound of Residue, Roosendaal proposes the strong residue conjecture: $Res(N)\le Res(993)$. Where $Res\left( 993 \right)=1.253142144……$, Roosendaal hasn't found any number up $3\times 10^{19}$ with a higher residue either. As a complementary, we calculate large intervals: $10^{20}\sim10^{20}+10^8$, $10^{50}\sim10^{50}+10^8$, $10^{200}\sim10^{200}+10^8$, it shows that $Res\left( N \right) $ is all within interval [1,1.26). Therefore, the strong residue conjecture is most likely true. For the main purpose of this paper, we propose the \textbf{Weak Residue Conjecture} (\textbf{WRC}):
	\begin{equation}
	Res(N)\le 2
	\label{eq:emc}
	\end{equation}

	In the third section, we obtain an upper bound of $Res\left( N \right) $: when $O\left( N \right) \ge 20$, it holds that
	\begin{equation}
		Res\left( N \right) <O\left( N \right) ^{\small{\frac{1}{9}}}
		\label{eq:emc}
	\end{equation}
	As a corollary, when $O\left( N \right) \le 512$, it always holds that $Res\left( N \right) <2$.

	In the fourth section, for the main purpose of this paper, we establish the non-trivial relationship among $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $. We prove that if 3x+1 conjecture is true and the \textbf{WRC} is true, given the positive integer $N$, know one of $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $, then the other two can be calculated by using formulas below:
	\begin{equation}
		\begin{aligned}
	O\left( N \right) &=\left[ \log _62\cdot D\left( N \right) -\log _6N \right] \\
	E\left( N \right) &=\left\{ \begin{array}{c}
		\left[ \log _63\cdot D\left( N \right) +\log _6N \right] +1\mathrm{    if }N\ne 2^k\\\\
		\left[ \log _63\cdot D\left( N \right) +\log _6N \right] \mathrm{        if }N=2^k\\
	\end{array} \right.\\
	D\left( N \right) &=\left\{ \begin{array}{c}
		\left[ \log _26\cdot O\left( N \right) +\log _2N \right] +1\mathrm{    if }N\ne 2^k\\\\
		\left[ \log _26\cdot O\left( N \right) +\log _2N \right] \mathrm{        if }N=2^k\\
	\end{array} \right.\\
	E\left( N \right) &=\left\{ \begin{array}{c}
		\left[ \log _23\cdot O\left( N \right) +\log _2N \right] +1\mathrm{    if }N\ne 2^k\\\\
		\left[ \log _23\cdot O\left( N \right) +\log _2N \right] \mathrm{        if }N=2^k\\
	\end{array} \right.\\
	D\left( N \right) &=\left[ \log _36\cdot E\left( N \right) -\log _3N \right] \\
	O\left( N \right) &=\left[ \log _32\cdot E\left( N \right) -\log _3N \right] \\
		\end{aligned}
	\end{equation}
	The formulas above depict nontrivial relationships among $D\left( N \right) $, $O\left( N \right) $, $E\left( N \right) $. For example, when $N=7$, we know $D\left( 7 \right) =16$, using the formulas above, we can calculate $O\left( 7 \right) ,E\left( 7 \right) $ directly:
	$$O\left( 7 \right) =\left[ \log _62\cdot D\left( 7 \right) -\log _67 \right] =\left[ 5.10361 \right] =5$$
	$$E\left( 7 \right) =\left[ \log _63\cdot D\left( 7 \right) +\log _67 \right] +1=\left[ 11.8964 \right] =11$$


	\section{Proof of $Res\left( N \right) \ge 1$}
	To study Residue analytically, we should introduce another expression of $Res\left( N \right)$.
	\begin{lemma}
		Suppose that $3x+1$ conjecture is true, if $N_1$ is an odd integer, then the residue of $N_1$:
		\begin{equation}
			Res\left( N_1 \right) =\prod_{j=1}^i{\left( 1+\frac{1}{3N_j} \right)}
			\label{eq:emc}
		\end{equation}
		where $N_j$ is the $\mathit{j}$-th odd integer when $N_1$ iterate to $1$ (except $1$), and odd iteration steps equal to $i$.
	\end{lemma}

	\begin{proof}
		If $N_1$ is an odd integer, then the residue of $N_1$ is:
	$$Res\left( N_1 \right) =\frac{2^{E(N_1)}}{3^{O(N_1)}\cdot N_1}$$
	We suppose that the iteration from $N_1$ to 1 generates $i$ terms odd integers(except 1), that is

	$$O\left( N_1 \right) =i$$
	The iteration from $N_1$ to the next odd integer $N_2$ via $m$ terms even integers. Simply,

	$$N_2=\frac{3N_1+1}{2^m}$$
	And the iteration from $N_2$ to 1 generates $i-1$ terms odd integers(except 1), that is
	$$O\left( N_2 \right) =O\left( N_1 \right) -1$$
	The iteration from $N_2$ to 1 generates $E\left( N_1 \right) -m$ terms even integers, that is
	$$E\left( N_2 \right) =E\left( N_1 \right) -m$$
	Therefore, the residue of $N_2$:

	$$Res\left( N_2 \right) =Res\left( \frac{3N_1+1}{2^m} \right) =\frac{2^{E(N_2)}}{3^{O(N_2)}\cdot N_2}=\frac{2^{E(N_1)-m}}{3^{O(N_1)-1}\cdot \frac{3N_1+1}{2^m}}$$
	We obtain:
	$$Res\left( N_2 \right) =\frac{2^{E(N_1)-m}}{3^{O(N_1)-1}\cdot \frac{3N_1+1}{2^m}}=\frac{2^{E(N_1)}}{3^{O(N_1)}\cdot N_1}\cdot \frac{1}{1+\frac{1}{3N_1}}=Res\left( N_1 \right) \cdot \frac{1}{1+\frac{1}{3N_1}}$$
	Repeat the process till the last odd integer(the $\mathit{i}$-th odd integer) $N_i$, we have
	$$Res\left( N_i \right) =Res\left( N_1 \right) \cdot \frac{1}{1+\frac{1}{3N_1}}\cdot \frac{1}{1+\frac{1}{3N_2}}\cdot \mathrm{ }\cdots \cdots \mathrm{ }\cdot \frac{1}{1+\frac{1}{3N_{i-1}}}$$
	It follows that
	$$Res\left( N_1 \right) =Res\left( N_i \right) \cdot \prod_{j=1}^{i-1}{\left( 1+\frac{1}{3N_j} \right)}$$
	Since the $\mathit{i}$-th odd integer $N_i$ is the last odd integer, so it must have form
	$$3N_i+1=2^k$$
	so
	$$N_i=\frac{2^k-1}{3}$$
	The residue of $N_i$:
	$$Res\left( N_i \right) =Res\left( \frac{2^k-1}{3} \right) =\frac{2^k}{3\cdot \frac{2^k-1}{3}}=\frac{2^k}{2^k-1}=1+\frac{1}{3N_i}$$
	Finally, we have
	$$Res\left( N_1 \right) =\prod_{j=1}^i{\left( 1+\frac{1}{3N_j} \right)}$$
	\end{proof}
	As a consequence of Lemma 1, we prove $Res\left( N \right) \ge 1$.	
	\begin{theorem}
		Suppose that $3x+1$ conjecture is true, then:
		\begin{equation}
			Res\left( N \right) \ge 1
			\label{eq:emc}
		\end{equation}
	\end{theorem}

	\begin{proof}
		\textbf{Case1}: If $N=N_1$ is an odd integer, according to Lemma 1, we have
		$$Res\left( N_1 \right) =\prod_{j=1}^i{\left( 1+\frac{1}{3N_j} \right)}>1$$

		\textbf{Case2}: If $N$ is an even integer, and $N\ne 2^k(k\in N^*)$, so $N$ must have form
		$$N=2^s\cdot N_{odd}$$
		Where $s\ge 1$, $N_{odd}$ is an odd integer. The residue of $N$
		$$Res(N)=\frac{2^{E(N)}}{3^{O(N)}\cdot 2^s\cdot N_{odd}}=\frac{2^{E(N_{odd})+s}}{3^{O(N)}\cdot 2^s\cdot N_{odd}}=\frac{2^{E(N_{odd})}}{3^{O(N)}\cdot N_{odd}}=Res(N_{odd})$$

		$$Res\left( N \right) =Res\left( N_{odd} \right) >1$$

		\textbf{Case3}: If $N$ is an even integer, and $N=2^k(k\in N^*)$, then $E(N)=k, O(N)=0, Res(2^k)=1$.
	\end{proof}


	\section{An upper bound of $Res\left( N \right) $}

	Research of the upper bound of $Res\left( N \right) $ hasn't been found in the literature. We give an upper bound of $Res\left( N \right) $ in this section.

	\begin{definition}
		We call the iteration from $N$ to $1$ a $N$-branch, i.e.,
		$$N\rightarrow \cdots \cdots \rightarrow 4\rightarrow 2\rightarrow 1$$
		Call the sequence of all the odd integers (except $1$) in $N$-branch a $N$-odd-branch $\left\{ N_j|1\le j\le i \right\} $, i.e.,
		$$N_1\rightarrow \cdots \cdots \rightarrow N_j\rightarrow \cdots \cdots \rightarrow N_i$$
		If $N$ is an even integer, $N=2^s\cdot N_{odd}$, $N_{odd}$ is an odd integer, then $N_1=N_{odd}$. If $N$ is an odd integer, then $N_1=N$.
	\end{definition}

	\begin{lemma}
		Given $N$ and its $N$-odd-branch $\left\{ N_j|1\le j\le i \right\} $, then $N_j\left( 2\le j\le i \right) $ cannot be divided by $3$.
	\end{lemma}


	\begin{proof}
		For any $k\left( 2\le k\le i \right) $ and $N_k$, suppose that $N_k$ can be divided by 3, suppose that $N_k=3·\left( 2n+1 \right) =6n+3$. There exists $N_{k-1}$, such that $N_k\gets N_{k-1}$, according to “3x+1” law, $\exists m\in N^*$, such that
		$$N_k=\frac{3N_{k-1}+1}{2^m}$$
		Then
		$$N_{k-1}=\frac{2^mN_k}{3}-\frac{1}{3}=2^m\left( 2n+1 \right) -\frac{1}{3}$$
		Obviously $N_{k-1}$ is not an integer, it’s a contradiction‌.
	\end{proof}

	\begin{lemma}
		If we have 
		$$\sum_{j=1}^i{\frac{1}{N_j}}\le a$$
		then it holds
		$$Res\left( N \right) <e^{\frac{a}{3}}$$
	\end{lemma}

	\begin{proof}
		According to \text{Lemma 1}, we have
		$$Res\left( N \right) =\prod_{j=1}^i{\left( 1+\frac{1}{3N_j} \right)}$$
		Using logarithm function
		$$\ln Res\left( N \right) =\ln \prod_{j=1}^i{\left( 1+\frac{1}{3N_j} \right)}=\sum_{j=1}^i{\ln \left( 1+\frac{1}{3N_j} \right)}<\frac{1}{3}\sum_{j=1}^i{\frac{1}{N_j}}$$
		Since $\sum_{j=1}^i{\frac{1}{N_j}}\le a$, hence
		$$\ln Res\left( N \right) <\frac{a}{3}$$
		Therefore
		$$Res\left( N \right) <e^{\frac{a}{3}}$$
	\end{proof}

	\begin{lemma}
		For all $n\in N^*$, we have
		\begin{equation}
			\ln n+\gamma <\sum_{k=1}^n{\frac{1}{k}}<\ln n+\gamma +\frac{1}{2n}
			\label{eq:emc}
		\end{equation}
		where $\gamma$ is Euler constant.
	\end{lemma}

		\begin{proof}
			Since we have
			$$\sum_{k=1}^n{\frac{1}{k}}=\ln n+\gamma +\frac{1}{2n}+\sum_{k=1}^m{\left( -1 \right) ^k\frac{B_k}{2k\cdot n^{2k}}}+\left( -1 \right) ^{m+1}\theta \frac{B_{m+1}}{\left( 2m+2 \right) \cdot n^{2m+2}}$$
			where $\theta \in \left( 0,1 \right) $, $B_k$ is the k-th Bernoulli number. Lemma 4 is obviously true.
		\end{proof}

		\begin{lemma}
			For any $m\in N^*$, it holds that
			\begin{equation}
				\sum_{
					\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
				}^{\scriptstyle 6m+3}{\frac{1}{k}}<\ln \left( 3^{\frac{1}{2}}2^{\frac{2}{3}} \right) +\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{5}{6m}
				\label{eq:emc}
			\end{equation}
		\end{lemma}

	\begin{proof}
		For any $m\in N^*$, according to Lemma 4, we have
		$$\sum_{k=1}^{6m+3}{\frac{1}{k}}<\ln\mathrm{(}6m+3)+\gamma +\frac{1}{2(6m+3)}$$
		$$\sum_{2\le k,k\,\,is\,\,even}^{6m+2}{\frac{1}{k}}=\frac{1}{2}\sum_{k=1}^{3m+1}{\frac{1}{k}}>\frac{1}{2}\ln\mathrm{(}3m+1)+\frac{\gamma}{2}$$
		Thus
		$$\sum_{1\le k,k\,\,is\,\,odd}^{6m+3}{\frac{1}{k}}=\sum_{k=1}^{6m+3}{\frac{1}{k}}-\sum_{2\le k,k\,\,is\,\,even}^{6m+2}{\frac{1}{k}}<\ln\mathrm{(}\frac{6m+3}{\sqrt{3m+1}})+\frac{\gamma}{2}+\frac{1}{2(6m+3)}$$
		Similarly, according to Lemma 4, we can obtain that
		$$\sum_{1\le k,k\,\,is\,\,odd}^{2m+1}{\frac{1}{k}}=\sum_{k=1}^{2m+1}{\frac{1}{k}}-\sum_{2\le k,k\,\,is\,\,even}^{2m}{\frac{1}{k}}>\ln\mathrm{(}2m+1)+\gamma -\frac{1}{2}\ln m-\frac{1}{2}\gamma -\frac{1}{4m}$$
		Then, we have
\allowdisplaybreaks
\begin{align*}
	\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+3}{\frac{1}{k}}&=\sum_{1\le k,k\,\,is\,\,odd}^{6m+3}{\frac{1}{k}}-\frac{1}{3}\sum_{1\le k,k\,\,is\,\,odd}^{2m+1}{\frac{1}{k}}-1 \\
	&<\ln \left( \frac{\left( 6m+3 \right) m^{\small{\frac{1}{6}}}}{\sqrt{3m+1}\left( 2m+1 \right) ^{\small{\frac{1}{3}}}} \right) +\frac{\gamma}{3}-1+\frac{1}{12m}+\frac{1}{2\left( 6m+3 \right)}\\
	&<\ln \left( \frac{3^{\frac{1}{2}}2^{\frac{2}{3}}(m+1)^{\frac{2}{3}}}{m^{\frac{1}{3}}} \right) +\frac{\gamma}{3}-1+\frac{1}{12m}+\frac{1}{2(6m+3)} \\
	&=\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{1}{3}\ln \left( m(\frac{m+1}{m})^2 \right) +\frac{\gamma}{3}-1+\frac{1}{12m}+\frac{1}{2(6m+3)} \\
	&=\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{1}{3}\ln m+\frac{2}{3}\ln\mathrm{(}\frac{m+1}{m})+\frac{\gamma}{3}-1+\frac{1}{12m}+\frac{1}{2(6m+3)} \\
	&<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{2}{3m}+\frac{1}{12m}+\frac{1}{2(6m+3)} \\
	&<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{5}{6m}
\end{align*}
Thus
$$\sum_{
	\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
}^{\scriptstyle 6m+3}{\frac{1}{k}}<\ln \left( 3^{\frac{1}{2}}2^{\frac{2}{3}} \right) +\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{5}{6m}$$
	\end{proof}

	\begin{theorem}
		Suppose that $3x+1$ conjecture is true, if $O\left( N \right) \ge 20$, then
		\begin{equation}
			Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}
			\label{eq:emc}
		\end{equation}
	\end{theorem}

	\begin{proof}
		Let’s consider the sum
		$\sum_{
			\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
		}^{\scriptstyle 6m+3}{\frac{1}{k}}$ and 
		$\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
		}^{\scriptstyle 6m+5}{\frac{1}{k}}$. 
		The sum $\sum_{
			\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
		}^{\scriptstyle 6m+3}{\frac{1}{k}}$ contains smallest $2m$ terms odd integers not equal to 0(mod 3). The sum $\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
		}^{\scriptstyle 6m+5}{\frac{1}{k}}$ contains smallest $2m+1$ terms odd integers not equal to 0(mod 3).

	\textbf{Case 1}: There are $2m$ terms in $\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+3}{\frac{1}{k}}$, then $O\left( N \right) =i=2m$. According to Lemma 2, there exist two situations:

	(1) All $N_j$ can not be divided by 3, since $\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+3}{\frac{1}{k}}$ contains smallest $2m$ terms odd integers, so we have
$$\sum_{j=1}^{2m}{\frac{1}{N_j}}\le \sum_{
	\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
}^{\scriptstyle 6m+3}{\frac{1}{k}}$$
	(2) $N_1=0\left( mod\,\,3 \right) $, so the possible value of $N_1$ can be 3,9,15,21,27,33,39,$\cdots \cdots $. Then we consider that if $N_1\ge 39$, so we have
	$$\sum_{j=1}^{2m}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+3}{\frac{1}{k}}+\frac{1}{39}$$
	According to Lemma 5, if $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, then
	$$\sum_{j=1}^{2m}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+3}{\frac{1}{k}}+\frac{1}{39}<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-\frac{38}{39}+\frac{1}{3}\ln m+\frac{5}{6m}$$
	According to Lemma 3, we have
	\begin{align*}
		Res\left( N \right) &<e^{\ln\mathrm{(}3^{\frac{1}{6}}2^{\frac{2}{9}})+\frac{\gamma}{9}-\frac{38}{117}+\frac{1}{9}\ln m+\frac{5}{18m}} \\
		&=3^{\frac{1}{6}}2^{\frac{2}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}m^{\frac{1}{9}}e^{\frac{5}{18m}} \\
		&=\underset{0.999467\cdots \cdots}{\underbrace{3^{\frac{1}{6}}2^{\frac{1}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}}}e^{\frac{5}{9O(N)}}\,\,O(N)^{\frac{1}{9}}
	\end{align*}
	If $\,\,O(N)\ge 1043$, then
	$$0.999467<3^{\frac{1}{6}}2^{\frac{1}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}e^{\frac{5}{9O(N)}}<0.99999981$$
	Thus, when $\,\,O(N)\ge 1043$ and $O\left( N \right) $ is an even integer, $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, we have
	$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}$$

	\textbf{Case 2}: According to Lemma 5, we have
	\begin{align*}
\sum_{
	\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
}^{\scriptstyle 6m+5}{\frac{1}{k}}&<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{5}{6m}+\frac{1}{6m+5} \\
	&<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-1+\frac{1}{3}\ln m+\frac{1}{m}
	\end{align*}
	There are $2m+1$ terms in $\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+5}{\frac{1}{k}}$, then $O\left( N \right) =i=2m+1$. According to Lemma 2, there exist two situations:

	(1) All $N_j$ can not be divided by 3, since $\sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+5}{\frac{1}{k}}$ contains smallest $2m+1$ terms odd integers, so we have
	$$\sum_{j=1}^{2m+1}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+5}{\frac{1}{k}}$$
	(2) $N_1=0\left( mod\,\,3 \right) $, so the possible value of $N_1$ can be 3,9,15,21,27,33,39,$\cdots \cdots $. Then we consider that if $N_1\ge 39$, so we have
	$$\sum_{j=1}^{2m+1}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle 6m+5}{\frac{1}{k}}+\frac{1}{39}$$
	Therefore, if $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, then
	\begin{align*}
		\sum_{j=1}^{2m+1}{\frac{1}{N_j}}&\le \sum_{
			\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
		}^{\scriptstyle 6m+5}{\frac{1}{k}}+\frac{1}{39} \\
	&<\ln\mathrm{(}3^{\frac{1}{2}}2^{\frac{2}{3}})+\frac{\gamma}{3}-\frac{38}{39}+\frac{1}{3}\ln m+\frac{1}{m}
	\end{align*}
	According to Lemma 3, we have
	\begin{align*}
		Res(N)&<e^{\ln\mathrm{(}3^{\frac{1}{6}}2^{\frac{2}{9}})+\frac{\gamma}{9}-\frac{38}{117}+\frac{1}{9}\ln m+\frac{1}{3m}} \\
		&=3^{\frac{1}{6}}2^{\frac{2}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}m^{\frac{1}{9}}e^{\frac{1}{3m}} \\
		&=3^{\frac{1}{6}}2^{\frac{1}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}e^{\frac{2}{3(O(N)-1)}}\left( O(N)-1 \right) ^{\frac{1}{9}} \\
		&<\underset{0.999467\cdots \cdots}{\underbrace{3^{\frac{1}{6}}2^{\frac{1}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}}}e^{\frac{2}{3(O(N)-1)}}O(N)^{\frac{1}{9}}
	\end{align*}
	If $O\left( N \right) \ge 1253$, then
	$$0.999467<3^{\frac{1}{6}}2^{\frac{1}{9}}e^{\frac{\gamma}{9}-\frac{38}{117}}e^{\frac{2}{3(O(N)-1)}}<0.99999964$$
	Thus, when $O\left( N \right) \ge 1253$ and $O\left( N \right) $ is an odd integer, $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, we have
	$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}$$
	Combine Case1 and Case2, when $O\left( N \right) \ge 1253$, $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, we have
		$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}$$

	We can verify that: when $20\le O\left( N \right) \le 1252$, $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, it holds
	$$\left( 1+\frac{1}{3\times 39} \right) \cdot 
	\prod_{
		\scriptstyle 5\le j,j\,\,is\,\,odd \atop \scriptstyle j\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle O(N)}{\left( 1+\frac{1}{3j}\right)}<O\left( N \right) ^{\frac{1}{9}}$$
	Since
	$$Res\left( N \right) =\prod_{j=1}^{O(N)}{\left( 1+\frac{1}{3N_j} \right)}\le \left( 1+\frac{1}{3\times 39} \right) \cdot \prod_{
		\scriptstyle 5\le j,j\,\,is\,\,odd \atop \scriptstyle j\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle O(N)}{\left( 1+\frac{1}{3j}\right)}$$
	Thus, when $O\left( N \right) \ge 20$, $N_1\notin \left\{ 3,9,15,21,27,33 \right\} $, it holds
		$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}$$

	We consider $O\left( N \right) \ge 20$, $N_1\in \left\{ 3,9,15,21,27,33 \right\} $. When $N_1=3,9,15,21,27,33$, the corresponding $O\left( N \right) =2,6,5,1,41,8$. Thus, only $N_1=27$ satisfies that $O\left( N \right) \ge 20$ and $N_1\in \left\{ 3,9,15,21,27,33 \right\} $. When $N_1=27$,
	$$Res\left( 27 \right) =1.1988\cdots \cdots <O\left( 27 \right) ^{\frac{1}{9}}=1.5107\cdots \cdots $$
	Finally, we prove that if $O\left( N \right) \ge 20$, it holds
	$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}$$

	\end{proof}

	Although it's difficult to prove \textbf{WRC} completely, we still have:
	\begin{corollary}
		Suppose that $3x+1$ conjecture is true, if $O\left( N \right) \le 512$, then
		$Res\left( N \right) <2$.
	\end{corollary}

	\begin{proof}
		According to Theorem 2, when $20\le O\left( N \right) \le 512$, we have
		$$Res\left( N \right) <O\left( N \right) ^{\frac{1}{9}}\le 512^{\frac{1}{9}}=2$$
	For any $O\left( N \right) \le 19$, there exist two situations:

	(1) All $N_j$ can not be divided by 3, so we have
	$$\sum_{j=1}^{O(N)}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle O(N)}{\frac{1}{k}}\le \sum_{
	\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{19}{\frac{1}{k}}$$

	(2) $N_1=0\left( mod\,\,3 \right) $, it must have
	$$\sum_{j=1}^{O(N)}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{\scriptstyle O(N)}{\frac{1}{k}}+\frac{1}{3}\le \sum_{
	\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{19}{\frac{1}{k}}+\frac{1}{3}$$
	Combine these two situations, we have
	$$\sum_{j=1}^{O(N)}{\frac{1}{N_j}}\le \sum_{
		\scriptstyle 5\le k,k\,\,is\,\,odd \atop \scriptstyle k\ne 0\left( mod\,\,3 \right)
	}^{19}{\frac{1}{k}}+\frac{1}{3}=1.3046\cdots \cdots $$
	According to Lemma 3, we have
	$$Res\left( N \right) <e^{\frac{1.3047}{3}}<1.55$$
	\end{proof}


	\section{Main Results}	
	In this section, we reveal the potential amazing relationship among $D\left( N \right)$, $O\left( N \right)$, $E\left( N \right)$. Usually, $D\left( N \right)$, $O\left( N \right)$, $E\left( N \right)$ randomly varies when $N$ increases. By studying the residue's property, we reveal 6 definite equations.
	\begin{theorem}
	Given a positive integer $N$, suppose that $3x+1$ conjecture is true, and if the \textbf{WRC} is true, know one of $D\left( N \right) , O\left( N \right) , E\left( N \right) $, then the other two can be calculated by using formulas below:
	\begin{align}
		O\left( N \right) &=\left[ \log _62\cdot D\left( N \right) -\log _6N \right] \label{eq1} \\
		E\left( N \right) &=\left\{ \begin{array}{c}
			\left[ \log _63\cdot D\left( N \right) +\log _6N \right] +1\mathrm{    if }N\ne 2^k\\\\
			\left[ \log _63\cdot D\left( N \right) +\log _6N \right] \mathrm{        if }N=2^k\\
		\end{array} \right. \label{eq2} \\
		D\left( N \right) &=\left\{ \begin{array}{c}
			\left[ \log _26\cdot O\left( N \right) +\log _2N \right] +1\mathrm{    if }N\ne 2^k\\\\
			\left[ \log _26\cdot O\left( N \right) +\log _2N \right] \mathrm{        if }N=2^k\\
		\end{array} \right. \label{eq3} \\
		E\left( N \right) &=\left\{ \begin{array}{c}
			\left[ \log _23\cdot O\left( N \right) +\log _2N \right] +1\mathrm{    if }N\ne 2^k\\\\
			\left[ \log _23\cdot O\left( N \right) +\log _2N \right] \mathrm{        if }N=2^k\\
		\end{array} \right. \label{eq4} \\
		D\left( N \right) &=\left[ \log _36\cdot E\left( N \right) -\log _3N \right] \label{eq5} \\
		O\left( N \right) &=\left[ \log _32\cdot E\left( N \right) -\log _3N \right] \label{eq6}
	\end{align}
	\end{theorem}

	\begin{proof}
		\textbf{Equation \eqref{eq1}}: Since $1\le Res\left( N \right) \le 2$, $1\le \frac{2^{E\left( N \right)}}{3^{O\left( N \right)}\cdot N}=\frac{2^{D(N)-O(N)}}{3^{O(N)}\cdot N}\le 2$, using logarithm function, we have
		$$0\le \log _2\frac{2^{D(N)-O(N)}}{3^{O(N)}\cdot N}\le 1$$
		It follows that
			\begin{equation}
			0\le D(N)-\log _26\cdot O(N)-\log _2N\le 1
			\label{eq7}
			\end{equation}
		We obtain
		$$\frac{D(N)-\log _2N}{\log _26}-\frac{1}{\log _26}\le O(N)\le \frac{D(N)-\log _2N}{\log _26}$$
		The interval has only one integer
		$$O\left( N \right) =\left[ \frac{D(N)-\log _2N}{\log _26} \right]=\left[ \log _62\cdot D\left( N \right) -\log _6N \right]$$

		\textbf{Equation \eqref{eq2}}: Since $1\le Res\left( N \right) \le 2$, $1\le \frac{2^{E(N)}}{3^{O(N)}\cdot N}=\frac{2^{E(N)}}{3^{D(N)-E(N)}\cdot N}\le 2$, using logarithm function, we have
		$$0\le \log _2\frac{2^{E(N)}}{3^{D(N)-E(N)}\cdot N}\le 1$$
		It follows that
			\begin{equation}
			0\le \log _26\cdot E(N)-\log _23\cdot D(N)-\log _2N\le 1
			\label{eq8}
			\end{equation}
		We obtain
		$$\frac{\log _2(3^{D(N)}\cdot N)}{\log _26}\le E(N)\le \frac{\log _2(3^{D(N)}\cdot N)}{\log _26}+\frac{1}{\log _26}$$

		\textbf{Case 1}: If $N\ne 2^k$, $\frac{\log _2(3^{D(N)}\cdot N)}{\log _26}$ is not an integer. Suppose that $\frac{\log _2(3^{D(N)}\cdot N)}{\log _26}=m$ is an integer, we have
		$$3^{D(N)}\cdot N=6^m$$
		Since $D(N)>E(N)\ge m$, then
		$$N=\frac{2^m}{3^{D(N)-m}}$$
		Obviously $N$ is not an integer, it’s a contradiction. So, we obtain
		$$E\left( N \right) =\left[ \frac{\log _2(3^{D(N)}\cdot N)}{\log _26} \right] +1=\left[ \log _63\cdot D\left( N \right) +\log _6N \right] +1$$

		\textbf{Case 2}: If $N=2^k$, then $D(N)=E(N)=k$,
		$$E\left( N \right) =\left[ \log _63\cdot D\left( N \right) +\log _6N \right] $$

		\textbf{Equation \eqref{eq3}}: According to \textcolor{red}{\textbf{\eqref{eq7}}}, we have
		$$\log _2(6^{O(N)}\cdot N)\le D(N)\le \log _2(6^{O(N)}\cdot N)+1$$
		\textbf{Case 1}: If $N\ne 2^k$, $\log _2(6^{O(N)}\cdot N)$ is not an integer. Thus
		$$D\left( N \right) = \left[ \log _2\left( 6^{O(N)}\cdot N \right) \right] +1=\left[ \log _26\cdot O\left( N \right) +\log _2N \right] +1$$
		\textbf{Case 2}: If $N=2^k$, then $D(N)=k, O(N)=0$:
		$$D\left( N \right) = \left[ \log _2\left( 6^{O(N)}\cdot N \right) \right]=\left[ \log _26\cdot O\left( N \right) +\log _2N \right] $$

		\textbf{Equation \eqref{eq4}}: Since $1\le Res\left( N \right) \le 2$, $1\le \frac{2^{E(N)}}{3^{O(N)}\cdot N}\le 2$, using logarithm function, we have
		$$0\le \log _2\frac{2^{E(N)}}{3^{O(N)}\cdot N}\le 1$$
		It follows that		
			\begin{equation}
			0\le E(N)-\log _23\cdot O(N)-\log _2N\le 1
			\label{eq9}
			\end{equation}
		We obtain
		$$\log _2(3^{O(N)}\cdot N)\le E(N)\le \log _2(3^{O(N)}\cdot N)+1$$
		\textbf{Case 1}: If $N\ne 2^k$, $\log _2(3^{O(N)}\cdot N)$ is not an integer. Thus
		$$E(N)=\left[ \log _2(3^{O(N)}\cdot N) \right] +1=\left[ \log _23\cdot O\left( N \right) +\log _2N \right] +1$$
		\textbf{Case 2}: If $N=2^k$, then $E(N)=k, O(N)=0$
		$$E(N)=\left[ \log _2(3^{O(N)}\cdot N) \right]=\left[ \log _23\cdot O\left( N \right) +\log _2N \right] $$

		\textbf{Equation \eqref{eq5}}: According to \textcolor{red}{\textbf{\eqref{eq8}}}, we have
		$$\frac{\log _26\cdot E(N)-\log _2N}{\log _23}-\frac{1}{\log _23}\le D(N)\le \frac{\log _26\cdot E(N)-\log _2N}{\log _23}$$
		The interval has only one integer
		$$D\left( N \right) =\left[ \frac{\log _26\cdot E(N)-\log _2N}{\log _23} \right] =\left[ \log _36\cdot E\left( N \right) -\log _3N \right]$$

		\textbf{Equation \eqref{eq6}}: According to \textcolor{red}{\textbf{\eqref{eq9}}}, we have
		$$\frac{E(N)-\log _2N}{\log _23}-\frac{1}{\log _23}\le O(N)\le \frac{E(N)-\log _2N}{\log _23}$$
		The interval has only one integer
		$$O\left( N \right) =\left[ \frac{E(N)-\log _2N}{\log _23} \right] =\left[ \log _32\cdot E\left( N \right) -\log _3N \right]$$
	\end{proof}


