\begin{document}
\title{Hamiltonian linking and Symplectic packing}
\begin{abstract}
  In this short note, we make an observation relating symplectic packings of the standard symplectic ball by two sets and Hamiltonian linking.
\end{abstract}
\maketitle

\section{Introduction}
\label{sec:introduction}

\subsection{Statement of results}
\label{sec:statement-results}

Denote by $G$ be the group of compactly supported Hamiltonian diffeomorphisms of $\R^{2n}$, i.e., the group of time-1 maps of compactly supported Hamiltonian isotopies.

Let us say that two disjoint compact subsets $K_{1},K_{2}\subset \R^{2n}$ are \emph{Hamiltonian unlinked} provided there is $\varphi\in G$ such that:
\begin{equation*}
  \varphi(K_{1})\text{ and }\varphi(K_{2})\text{ lie on opposite sides of a hyperplane}.
\end{equation*}
Otherwise we say they are \emph{Hamiltonian linked}.

There is an obvious obstruction to being Hamiltonian unlinked, namely the two sets must be unlinkable via a compactly supported smooth isotopy.

Denote by $c(K_{i})$ the \emph{spectral capacity of $K_{i}$}, which is simply the Floer theory version\footnote{Generating function capacities are known to equal Floer homology capacities; see \cite{viterbo-arXiv-1996,hermann-BSMF-2004}.} of Viterbo's generating function capacity introduced in \cite{viterbo-mathann-1992}; in this paper we follow the conventions of \cite{alizadeh-atallah-cant-arXiv-2024,cant-zhang-arXiv-2024}. This is a normalized symplectic capacity. Then:
\begin{theorem}\label{theorem:main}
  Suppose $K_{1},K_{2}\subset B(a)$ are compact disjoint subsets of the standard symplectic ball (of capacity $a>0$). Either:
  \begin{enumerate}
  \item $K_{1},K_{2}$ are Hamiltonian linked,
  \item $c(K_{1})+c(K_{2})\le a$;
  \end{enumerate}
  in other words, if two sets are Hamiltonian unlinked, then they obey a packing inequality; if two sets break the packing inequality, then they must be Hamiltonian linked.
\end{theorem}
\emph{Remark}. The same result holds if $B(a)$ is replaced by a domain $\Omega$ satisfying $a=c(\Omega)=\gamma(\Omega)$, where $\gamma(\Omega)$ is the \emph{spectral diameter} (i.e., the diameter of the space of isotopies supported in $\Omega$ with respect to Viterbo's spectral metric). In \cite{alizadeh-atallah-cant-arXiv-2024} it is shown that $a=c(B(a))=\gamma(B(a))$.

\begin{corollary}\label{corollary:linking-small-ball}
  Let $K\subset \bd B(a)$ be a compact set with capacity $c(K)=b$ (there exist examples where $K$ is a Lagrangian and $b=a/2$). Then the smaller ball $B(c)\subset B(a)$ is Hamiltonian linked with $K$ if $c>a-b$.\hfill$\square$
\end{corollary}
In dimension $n=1$, this follows from smooth topology. In higher dimensions $n>1$, the sets $K$ and $B(c)$ can be chosen to be smoothly unlinked, and so it produces a camel type theorem: {\itshape the ball $B(c)$ cannot be isotoped to $v+B(c)$ through balls of capacity $c$ in the complement of $K$, if $v$ is sufficiently large.}

Let us say that a compact domain $\Omega\subset \C^{n}$ is \emph{boundary minimal} if:
\begin{equation*}
  c(\Omega\setminus U)< c(\Omega)
\end{equation*}
for all open sets $U$ such that $U\cap \bd \Omega\ne \emptyset$. Then we recover a result of \cite{ziltener-imrn-2016} (in the case $\Omega=B(a)$); his argument used displacement energy while ours uses the packing versus linking theorem.
\begin{corollary}\label{cor:gamma-is-c-implies-bm}
  Any domain $\Omega$ satisfying $c(\Omega)=\gamma(\Omega)$ is boundary minimal.
\end{corollary}
\begin{proof}[Proof of Corollary \ref{cor:gamma-is-c-implies-bm}]
  If $U$ is open and has non-empty intersection with $\bd \Omega$, then inside of $U\cap \Omega$ one can find a small ball which is unlinked with $\Omega\setminus U$. The result then follows from the packing inequality.
\end{proof}
Boundary minimality is interesting as it implies the following closing-type lemma (see \cite{irie-JMD-2015,chaidez-datta-prasad-tanny-JMD-2024,xue-arxiv-2022} for similar results):
\begin{lemma}\label{lemma:closing}
  Suppose that $\Omega\subset \C^{n}$ is a symplectically embedded Liouville domain which is boundary minimal. Let $\alpha$ be the intrinsic contact form on $\bd\Omega$ (using the Liouville domain structure of $\Omega$). Then, for any non-empty open subset $V\subset \bd\Omega$ and any non-negative non-constant function $f$ supported in $V$, there is a Reeb orbit $\gamma$ for the Reeb flow associated to $e^{-sf}\alpha$ which passes through $V$, for some $s\in (0,1]$. Moreover:
  \begin{equation*}
    \text{period of }\gamma+\Gamma(\gamma)<c(\Omega)
  \end{equation*}
  where $\Gamma$ is the cohomology class $[\lambda_{\C^{n}}-\lambda_{\Omega}]\in H^{1}_{\mathrm{dR}}(\Omega)$. In particular, if the embedding is exact, one can bound the period of $\gamma$ from above and conclude there is an orbit of $\alpha$ with period $\le c(\Omega)$ passing through any point of $\bd\Omega$.
\end{lemma}
This is proved in \S\ref{sec:proof-lemma-closing}. As explained to the author by S.\@~Matijevi\'c, the last sentence of the lemma, together with the results of \cite{abbondandolo-kang-duke-2022,abbondandolo-benedetti-GAFA-2023}, implies the following characterization of uniformly convex Zoll domains:
\begin{theorem}\label{theorem:convex-zoll}
  A uniformly convex domain $\Omega$ is Zoll if and only if it is boundary minimal.
\end{theorem}
\begin{proof}
  If a uniformly convex domain is boundary minimal, Lemma \ref{lemma:closing}, and the fact that $c(\Omega)$ is the shortest period of a Reeb orbit (proved in \cite{abbondandolo-kang-duke-2022}) imply that $\Omega$ is Zoll. Conversely, \cite{abbondandolo-benedetti-GAFA-2023} proved that a uniformly convex Zoll domain is a local maximizer for the systolic ratio. Shrinking the domain slightly will decrease the volume, and so the systole must also decrease. Since small variations remain uniformly convex, it follows (again from \cite{abbondandolo-kang-duke-2022}) that $c(\Omega)$ decreases, as desired.
\end{proof}

Our next result concerns the areas of $J$-holomorphic disks with boundary on Lagrangians. Here $J$ is an $\omega$-tame (and standard at infinity) almost complex structure (we call such a $J$ \emph{admissible}).
\begin{corollary}\label{corollary:lagrangian-hbar}
  Let $K\subset \bd B(a)$ be a subset with capacity $b$. Then each Lagrangian $L$ in the interior of $B(a)$ either:
  \begin{enumerate}
  \item bounds a $J$-holomorphic disk with area at most $a-b$,
  \item is linked with $K$,
  \end{enumerate}
  where $J$ is any admissible almost complex structure.
\end{corollary}
When $n=1$ the result is trivial as every subset of $B(a)$ is smoothly linked with $K$, or $b=0$. On the other hand, when $n>1$, the result is symplectic in nature, as $K$ and $L$ are smoothly unlinked unless $K\ne \bd B(a)$. We prove Corollary \ref{corollary:lagrangian-hbar} in \S\ref{sec:proof-corollary-lag-hbar}.

\emph{Remark}. Perhaps, when $n>1$, every Lagrangian $L$ in the interior of $B(a)$ is unlinked with some $K$ with $c(K)\ge a/2$, in which case one proves the conjecture about the areas of disks being less than $a/2$; see \S\ref{sec:further-questions}.

Our next result discusses a case when sets are automatically unlinked.
\begin{lemma}\label{lemma:starshaped-unlinked}
  If $K_{1}$ and $K_{2}$ are disjoint compact sets, each symplectomorphic to a starshaped set, then they are Hamiltonian unlinked.
\end{lemma}
This is shown in \S\ref{sec:proof-lemma-starshaped-unlinked}. Theorem \ref{theorem:main} then yields:
\begin{corollary}
  Suppose $a=c(\Omega)=\gamma(\Omega)$. Two disjoint sets $K_{1},K_{2}\subset \Omega$, each of which is symplectomorphic to a starshaped set, satisfy the packing inequality $c(K_{1})+c(K_{2})\le a$.\hfill$\square$
\end{corollary}
In fact, the proof of Theorem \ref{theorem:main} shows that two disjoint sets $K_{1},K_{2}$ which obey the maximum formula for spectral invariants also obey the packing inequality. It is known that the class of pairs of subsets of $\R^{2n}$ which obey the maximum formula contains all pairs of the images of two embeddings of Liouville domains which are:
\begin{enumerate}
\item exact \cite{humiliere-le-roux-seyfaddini-2016}, or
\item $\pi_{1}$-injective on the boundary \cite{ganor-tanny-AGT-2023},
\end{enumerate}
We note that \cite{humiliere-le-roux-seyfaddini-2016} also proves the the maximum formula for the generating function capacity for a pair of subsets of $\R^{2n}$ which are separated by a hyperplane.

