\caption{ProbNES algorithm} \label{alg:main_alg}
\begin{algorithmic}[1]
\State \textbf{inputs}: Number of random points at initialisation $N_0$, step size $\mu$, total number of iterations $T$, batch size $N$, initial prior distribution $\nu_{\theta_0} \in p(\mathcal{X})$ parameterised by $\theta_0 \in \Theta$, Gaussian Process (GP) kernel $\kb$ and objective function to optimise $f$.
\State \textbf{output}: Minimiser $x^*$ of the function $f(x), x \in \mathcal{X}$. 
\State \textbf{initialise} Initialise data $\mathcal{D} \leftarrow \{\}$, initialise GP surrogate model. 

%\For {$t = 0, ..., T - 1$}
\State \textbf{for} $t = 0, ..., T - 1$ \textbf{do}
    \State $\quad$ Select $N$ points $\{x_i\}_i$ actively via a batch BQ.
    \label{alg_line:batch_BQ}
    \State $\quad$ evaluate $y_i = f(x_i)$.
    \State $\quad$ Update $\mathcal{D} \leftarrow \mathcal{D} \cup \{(x_i, y_i)\}_{i=1:N}$
    \State $\quad$ Update GP on a subset of active points $\Tilde{\mathcal{D}}$.
    \label{alg_line:local_model}
    \State $\quad$ Compute the expected gradient $\db_t = \mathbb{E}\left[\nabla_{\theta} g(\theta_t)\right]$.
    \label{alg_line:gradient}
    \State $\quad$ Compute the Fisher Information Matrix $\boldsymbol{F}(\theta_t)$
    \State $\quad$ Update $\theta_{t+1} \leftarrow \theta_{t} + \mu \boldsymbol{F}^{-1}(\theta_t)\db_t $
\State \textbf{end for}

\State \textbf{return} Point $x^*$ that optimises $f(.)$ from all observations.
\end{algorithmic}
