\section{Gaussian Formulae}

In this section we provide formulae regarding the multivariate normal distribution that are required in the computation of the covariance structure in the probabilistic method of lines.
\subsection{Multivariate Normal Distribution Density}
The probability density function of a multivariate normal distribution $\Xb \sim \mathcal{N}(\mub, \Sigmab)$ in $\mathbb{R}^{D}$ is:
\begin{equation}
    \nu_{\mub, \Sigmab}(\x) = \frac{1}{\sqrt{|2\pi\Sigmab|}} e^{ -\frac{1}{2}(\x - \mub)^{T}\Sigmab^{-1}(\x - \mub)}
\end{equation}
\subsection{Multivariate Normal Distribution Density under Linear Transformations}
Let $\Xb \sim \mathcal{N}(\mub, \Sigmab)$, then, the linear transformation of $\Xb$ is also normally distributed: $$\mathbf{Y} = \mathbf{A}\Xb + \mathbf{b} \sim \mathcal{N}(\mathbf{A}\mub + \mathbf{b}, \mathbf{A}\Sigmab\mathbf{A}^{T})$$

\begin{proof}
    See section 8.1.4 in \cite{petersen2008matrix}.
\end{proof}
\subsection{Product of Two Normal Densities}
Let $\nu_1(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$ and $\nu_2(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, we have:
\begin{equation}
    \nu_1(\x) \nu_2(\x) = \frac{1}{\left(2\pi\right)^{D} \sqrt{|\Sigmab_1||\Sigmab_2|}} \times \exp \left(-\frac{1}{2} \left( (\x - \nub)^{T} \Pib^{-1} (\x - \nub) - \nub^{T}\Pib^{-1}\nub + \mub_1^{T}\Sigmab_{1}^{-1} \mub_1 + \mub_2^{T}\Sigmab_{2}^{-1} \mub_2 \right) \right)
\end{equation}
With
\begin{equation*}
\begin{split}
    \Pib &= \left( \Sigmab_{1}^{-1} + \Sigmab_{2}^{-1}\right)^{-1} = \Sigmab_{1}\left( \Sigmab_{1} + \Sigmab_{2}\right)^{-1}\Sigmab_{2} = \Sigmab_{2}\left( \Sigmab_{1} + \Sigmab_{2}\right)^{-1}\Sigmab_{1} \\
    \nub &= \Pib \Sigmab_{1}^{-1}\mub_1 + \Pib \Sigmab_{2}^{-1}\mub_2 \\
    &= \Sigmab_{2}\left(\Sigmab_{1} + \Sigmab_{2}\right)^{-1}\mub_{1} + \Sigmab_{1}\left(\Sigmab_{1} + \Sigmab_{2}\right)^{-1}\mub_{2}
\end{split}
\end{equation*}
This formulation can be rewritten as:
\begin{equation} \label{eq:productgauss}
\begin{split}
    \nu_1(\x) \nu_2(\x) &= \frac{1}{\left(2\pi\right)^{D} \sqrt{|\Sigmab_1||\Sigmab_2|}} \times \exp \left(-\frac{1}{2} \left( \left(\x - \nub\right)^{T} \Pib^{-1} \left(\x - \nub\right) + \left(\mub_1 - \mub_2\right)^{T} \left(\Sigmab_1 + \Sigmab_2\right)^{-1} \left(\mub_1 - \mub_2\right) \right)\right) \\
    &= \mathcal{N}(\x; \nub,    \Pib) \mathcal{N}(\mub_1; \mub_2, \Sigmab_{1} + \Sigmab_{2})
\end{split}
\end{equation}
\begin{proof}
    See section 8.1.8 from \cite{petersen2008matrix}.
\end{proof}
\subsection{Integration of Two Multivariate Normal Distributions}
Let $\nu_1(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$ and $\nu_2(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, we have:
\begin{equation} \label{eq:productint}
    \int_{\mathbb{R}^{D}} \nu_1(\x) \nu_2(\x)d\x = \mathcal{N}\left(\mub_1;\mub_2, \Sigmab_1 + \Sigmab_2\right)
\end{equation}
\begin{proof}
    Immediate result after integrating the first term in equation \ref{eq:productgauss}.
\end{proof}

\subsection{First Moment of Products of Multivariate Normal Distributions}
Let $\nu_1(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$ and $\nu_2(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, we have:
\begin{equation}
\begin{split}
    \int_{\mathbb{R}^{D}} \x \nu_1(\x) \nu_2(\x)d\x &= \nub \mathcal{N}\left(\mub_1;\mub_2, \Sigmab_1 + \Sigmab_2\right) \\
    &= \Pib \Sigmab_{1}^{-1}\mub_1 \mathcal{N}\left(\mub_1;\mub_2, \Sigmab_1 + \Sigmab_2\right) + \Pib \Sigmab_{2}^{-1}\mub_2 \mathcal{N}\left(\mub_2;\mub_1, \Sigmab_1 + \Sigmab_2\right)
\end{split}
\end{equation}
With $\nub$ defined in A.2.
\begin{proof}
\begin{equation}
\begin{split}
    \int_{\mathbb{R}^{D}} \x \nu_1(\x) \nu_2(\x)d\x &= \left( \underbrace{\int_{\mathbb{R}^{D}} \x \mathcal{N}(\x; \nub, \Pib) d\x}_{=\mathbb{E}[X], X \sim \mathcal{N}(\nub, \Pib)} \right) \mathcal{N}(\mub_1; \mub_2, \Sigmab_{1} + \Sigmab_{2}) \\
    &= \nub \mathcal{N}(\mub_1; \mub_2, \Sigmab_{1} + \Sigmab_{2})
\end{split}
\end{equation}
\end{proof}
\subsection{Second Moment of Products of Multivariate Normal Distributions}
Let $\nu_1(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$, $\nu_2(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, and $\otimes$ the outer product operator. We have:
\begin{equation}
    \int_{\mathbb{R}^{D}} \left( \x \otimes \x \right) \nu_1(\x) \nu_2(\x)d\x = \left( \Pib + \nub \otimes \nub \right)\mathcal{N}\left(\mub_1;\mub_2, \Sigmab_1 + \Sigmab_2\right)
\end{equation}
With 
\begin{equation*}
    \Pib + \nub \nub^{T} = \Pib + \Pib \Sigmab_{1}^{-1}\mub_1 \mub_{1}^{T} \Sigmab_{1}^{-1} \Pib + \Pib \Sigmab_{2}^{-1}\mub_2 \mub_{2}^{T} \Sigmab_{2}^{-1} \Pib + \Pib \Sigmab_{1}^{-1}\mub_1 \mub_{2}^{T} \Sigmab_{2}^{-1} + \Pib \Sigmab_{2}^{-1}\mub_2 \mub_{1}^{T} \Sigmab_{1}^{-1} \Pib
\end{equation*}
\begin{proof}
\begin{equation}
\begin{split}
     & \int_{\mathbb{R}^{D}} \left( \x \otimes \x \right) \nu_1(\x) \nu_2(\x)d\x = \left( \underbrace{\int_{\mathbb{R}^{D}} \left( \x \otimes \x \right) \mathcal{N}(\x; \nub, \Pib) d\x}_{=(1)} \right) \mathcal{N}(\mub_1; \mub_2, \Sigmab_{1} + \Sigmab_{2}) \\
    (1) &= \int_{\mathbb{R}^{D}} \left( \left(\x - \nub \right) \otimes \left(\x - \nub \right) + \left(\x - \nub \right) \otimes \nub + \nub \otimes \left(\x - \nub \right) + \nub \otimes \nub\right) \mathcal{N}(\x; \nub, \Pib) d\x \\
    &= \Pib + \nub \otimes \nub
\end{split}
\end{equation}
\end{proof}
\subsection{Third Moment of Products of Multivariate Normal Distributions} \label{appendix:thirdmoment}
Let $\nu_1(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$, $\nu_2(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, and $\otimes$ the outer product operator. We have:
\begin{equation}
    \int_{\mathbb{R}^{D}} \left( \x \otimes \x \otimes \x \right) \nu_1(\x) \nu_2(\x)d\x = \left(\nub \otimes \nub \otimes \nub + \sum\limits_{\tau \in \Taub_3} \tau(\nub \otimes \Pib)\right) \mathcal{N}\left(\mub_1;\mub_2, \Sigmab_1 + \Sigmab_2\right)
\end{equation}
Where $\nub$ and $\Pib$ are defined in A.2 and $\Taub_3 = \left\{ \tau_c : c \in \mathcal{C}_{3} \right\}$, where $\mathcal{C}_{3}$ is the set of cyclic permutation over $[3]$, is the set of operators over 3D tensor that perform cyclic permutation of the indices.
\begin{proof}
\begin{equation}
\begin{split}
    \x \otimes \x \otimes \x &= \left(\x - \nub \right) \otimes \left(\x - \nub \right) \otimes \left(\x - \nub \right) \\
    &+ \nub \otimes \left(\x - \nub \right) \otimes \left(\x - \nub \right) + \left(\x - \nub \right) \otimes \nub \otimes \left(\x - \nub \right) + \left(\x - \nub \right) \otimes \left(\x - \nub \right) \otimes \nub \\
    &+ \nub \otimes \nub \otimes \left(\x - \nub \right) + \nub \otimes \left(\x - \nub \right) \otimes \nub + \left(\x - \nub \right) \otimes \nub \otimes \nub \\
    &+ \nub \otimes \nub \otimes \nub \\
\end{split}
\end{equation}
The first and third line integrates to zero as every term of the 3D tensor involves an odd number of the dimensions of the centered multivariate random variable $\Xb - \mub$, which gives the result.
\end{proof}
\subsection{Derivative of multivariate normal distribution with respect to its parameters}
Let $\nu(\x) = \sum\limits_{i \in [K]} \alpha_i \mathcal{N}(\mub_i, \Sigmab_i)$:
\begin{equation}
\begin{split}
    \frac{\partial \ln{\nu(\x)} }{\partial \alpha_j} &= \frac{\alpha_j \mathcal{N}(\mub_j, \Sigmab_j)}{\sum\limits_{i \in [K]} \alpha_i \mathcal{N}(\mub_i, \Sigmab_i)} \frac{1}{\alpha_j} \\
    \frac{\partial \ln{\nu(\x)} }{\partial \mub_j} &= \frac{\alpha_j \mathcal{N}(\mub_j, \Sigmab_j)}{\sum\limits_{i \in [K]} \alpha_i \mathcal{N}(\mub_i, \Sigmab_i)} \big[\Sigmab_j^{-1}(\x - \mub_j) \big] \\
    \frac{\partial \ln{\nu(\x)} }{\partial \Sigmab_j} &= \frac{\alpha_j \mathcal{N}(\mub_j, \Sigmab_j)}{\sum\limits_{i \in [K]} \alpha_i \mathcal{N}(\mub_i, \Sigmab_i)} \frac{1}{2} \big[-\Sigmab_j^{-1} +\Sigmab_j^{-1}(\x - \mub_j)(\x - \mub_j)^{T}\Sigmab_j^{-1} \big]
\end{split}
\end{equation}
\begin{proof}
    See section 8.4.2 in \cite{petersen2008matrix}.
\end{proof}



\section{Bayesian Quadrature formula} \label{appendix:formula}
\subsection{Quadrature}
\textbf{Multivariate Normal Distribution.} \\
If $\nu(\x) = \mathcal{N}(\x; \mub, \Sigmab)$ and $k(\x, \x') = \theta \mathcal{N}(\x; \x', \Lambda)$ and $f \sim \mathcal{GP}(\mb, \kb)$ then closed form solution are available for the computation of the distribution of F:
\begin{equation}
\begin{split}
    \tb(\x_{i}) & = \theta \mathcal{N}(\x_{i}; \mub,\Sigmab + \Lambda) \\
    \mathbf{R} & = \theta (\det 2\pi(2\Sigmab + \Lambda))^{-\frac{1}{2}}
