\begin{equation}
\begin{split}
    \tb(\x_{i}) & = \sum\limits_{i \in [K]} \alpha_i \mathcal{N}(\x_{i}; \mub_i, \Sigmab_i + \Lambda) \\
    \mathbf{R} & = \sum\limits_{i, j \in [K]} \alpha_i \alpha_j(\det 2\pi(\Sigmab_i + \Sigmab_j + \Lambda))^{-\frac{1}{2}}
\end{split}
\end{equation}



