    \left[\boldsymbol{\mathcal{T}}_{kX}\right]_{i, \Sigmab} &= \frac{1}{2} \left(\Lambda + \Sigmab_k\right)^{-1}\left(\left(\Lambda + \Sigmab_k\right) - \left(\x_i - \mub_k \right)\left(\x_i - \mub_k \right)^{T}\right)\left(\Lambda + \Sigmab_k\right)^{-1} \mathcal{N}(\x_i; \mub_k, \Lambda + \Sigmab_k)
\end{split}
\end{equation*}
\fi


\subsection{Covariance Structure of Quadrature Gradient}
\label{appendix:probaline}

We recall the covariance structure of the gradient vector of the integral of the objective function with respect to the search distribution in the space of distribution parameters from \ref{eq:covariancestructure}
\begin{equation}
\begin{split}
    \mathbb{E}(g(\theta)) &= \int_{\X} \mathbf{m}_{post}(\x)d\nu_{\theta}(\x)\\
    &= \m + \mathbf{t}_{kX}^{T}\left[\kb_{XX} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1} \left(\mathbf{Y} - \mathbf{m}(\Xb) \right)\\
    \mathbb{E}(\nabla_{\theta} g(\theta)) &= \int_{\X} \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta}(\x) \mathbf{m}_{post}(\x)d\nu_{\theta}(\x)\\
    &= \boldsymbol{\mathcal{M}} + \boldsymbol{\mathcal{T}}_{kX}^{T}\left[\kb_{XX} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1} \left(\mathbf{Y} - \mathbf{m}(\Xb) \right)\\
    \text{Cov}(g(\theta_1), g(\theta_2)) &= \iint_{\X} \kb_{post}(\x, \x')d\nu_{\theta_1}(\x)d\nu_{\theta_2}(\x') \\
    &= \mathbf{R}_{12} - \mathbf{t}_{1X}^{T}\left[\kb_{XX} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1}\mathbf{t}_{2X}\\
    \text{Cov}(g(\theta_1), \nabla_{\theta} g(\theta_2)) &= \iint_{\X} \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta_{2}}(\x') \kb_{post}(\x, \x') d\nu_{\theta_1}(\x)d\nu_{\theta_2}(\x') \\
    &= \mathbf{R}_{12'} - \mathbf{t}_{1X}^{T}\left[\kb_{XX} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1} \boldsymbol{\mathcal{T}}_{2X}\\
    \text{Cov}(\nabla_{\theta} g(\theta_1),  \nabla_{\theta} g(\theta_2)) &= \iint_{\X} \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta_1}(\x) \otimes \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta_2}(\x') \kb_{post}(\x, \x') d\nu_{\theta_1}(\x)d\nu_{\theta_2}(\x') \\
    &= \mathbf{R}_{1'2'} - \boldsymbol{\mathcal{T}}_{1X}^{T}\left[\kb_{XX} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1}\boldsymbol{\mathcal{T}}_{2X}
\end{split}
\end{equation}
We define $\nu_{\theta_1}(\x) = \mathcal{N}(\x; \mub_1, \Sigmab_1)$, $\nu_{\theta_t}(\x) = \mathcal{N}(\x; \mub_2, \Sigmab_2)$, $k(\x, \x') = \mathcal{N}(\x; \x', \Lambda)$, $\m(\x) = \mathbf{v} \in \mathbb{R}^{d}$ and $f \sim \mathcal{GP}(\m, \kb)$. We suppose we have a data set $\mathcal{D}$ of points observed from the evaluation function. Let $\Gammab = \Lambda + \Sigmab_1 + \Sigmab_2$ and $\gammab = \Gammab^{-1}(\mub_1 - \mub_2)$, $\Taub_3$ defined in \ref{appendix:thirdmoment}, $\Taub = \left\{\left(1, 2, 3, 4 \right), \left(2, 1, 3, 4 \right), \left(1, 2, 4, 3 \right), \left(2, 1, 4, 3 \right), \left(2, 3, 1, 4 \right), \left(1, 4, 2, 3 \right) \right\}$, and $\boldsymbol{\mathcal{S}} = \left\{\left(1, 2, 3, 4 \right), \left(1, 3, 2, 4 \right), \left(1, 4, 2, 3 \right) \right\}$. Then, the quantities involved in eq \ref{eq:covariancestructure} are:
\begin{subequations}
\begin{align}
    \mb &= \mathbf{v}  \label{eq:Ea}\\
    \boldsymbol{\mathcal{M}} &= \boldsymbol{0} \label{eq:Eb}\\
    \mathbf{R}_{12} &= \mathcal{N}(\mub_{1}; \mub_2, \Gammab)\label{eq:Ec}\\
    \mathbf{R}_{12'\mub} &= \gammab \mathcal{N}(\mub_1; \mub_2, \Gammab)\label{eq:Ed}\\
    \mathbf{R}_{12'\Sigmab} &= -\frac{1}{2}\left(\Gammab^{-1} - \gammab \otimes \gammab\right) \mathcal{N}(\mub_1; \mub_2, \Gammab)\label{eq:Ee}\\
    \mathbf{R}_{1'2'\mub\mub} &=\left(\Gammab^{-1} - \gammab \otimes \gammab\right) \mathcal{N}(\mub_1; \mub_2, \Gammab)\label{eq:Ef}\\
    \mathbf{R}_{1'2'\mub\Sigmab} &= \frac{1}{2} \left( \sum\limits_{\tau \in \Taub_3} \tau(\gammab \otimes \Gammab^{-1}) - \gammab \otimes \gammab \otimes \gammab \right)\mathcal{N}(\mub_1; \mub_2, \Gammab)\label{eq:Eg}\\
    \mathbf{R}_{1'2'\Sigmab\Sigmab} &= \frac{1}{4}\left(\gammab \otimes \gammab \otimes \gammab \otimes \gammab - \sum\limits_{\tau \in \Taub} \left[ \gammab \otimes \Gammab^{-1} \otimes \gammab \right]_{\tau} + \sum\limits_{\sigma \in \boldsymbol{\mathcal{S}}} \left[ \Gammab^{-1}\otimes \Gammab^{-1} \right]_{\sigma} \right) \mathcal{N}(\mub_1; \mub_2, \Gammab)\label{eq:Eh}\\
    \mathbf{t}_{kX} &= \mathcal{N}(\Xb; \mub_k, \Lambda + \Sigmab_k)\label{eq:Ei}\\
    \left[\boldsymbol{\mathcal{T}}_{kX}\right]_{i, \mub} &= \left(\Lambda + \Sigmab_k\right)^{-1} \left(\x_i - \mub_k\right) \mathcal{N}(\x_i; \mub_k, \Lambda + \Sigmab_k)\label{eq:Ej}\\
    \left[\boldsymbol{\mathcal{T}}_{kX}\right]_{i, \Sigmab} &= \frac{1}{2} \left(\Lambda + \Sigmab_k\right)^{-1}\left(\left(\x_i - \mub_k \right)\left(\x_i - \mub_k \right)^{T} - \left(\Lambda + \Sigmab_k\right)\right)\left(\Lambda + \Sigmab_k\right)^{-1} \mathcal{N}(\x_i; \mub_k, \Lambda + \Sigmab_k) \label{eq:Ek}
\end{align}
\end{subequations}

\begin{proof} Let $D \in \mathbb{N}^{*}$, $D \geq k \in \mathbb{N}^{*}$, $\left( d_i \right)_{1\leq i \leq D} \in \mathbb{N}^{*}$. Let's define the matrix product over tensor dimensions:
\begin{equation}
\begin{split}
    *_{k} : \mathbb{R}^{d_k \times d_k} \times \mathbb{R}^{\prod\limits_{i = 1}^{D} d_i} & \rightarrow \mathbb{R}^{\prod\limits_{i = 1}^{D} d_i} \\
     \left( \Sigmab, \mathcal{T} \right) &\mapsto  \Tilde{\mathcal{T}}\\
\end{split}
\end{equation}
with
\begin{equation}
    \left[\Tilde{\mathcal{T}} \right]_{i_1, \dots, i_D} = \sum\limits_{l = 1}^{d_k} \Sigmab_{i_k, l} \left[\mathcal{T} \right]_{i_1, \dots, i_{k-1}, l, \dots, i_{k+1},\dots,  i_D}
\end{equation}
Let's now derive all the equations:\\
\ref{eq:Ea}:
\begin{equation*}
\m_t = \int_{\X} \m(\x) d\nu_{\theta_{t}}(\x) = \m \int_{\X} d\nu_{\theta_{t}}(\x) = \m
\end{equation*}
\ref{eq:Eb}: 
\begin{equation*}
\boldsymbol{\mathcal{M}} = \int_{\X} \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta}(\x) \m(\x) d\nu_{\theta}(\x) = \m \int_{\X} \nabla_{\theta} \nu_{\theta}|_{\theta}(\x) d\x = \m \nabla_{\theta} 1 = 0
\end{equation*}
\ref{eq:Ec}:
\begin{equation*}
\begin{split}
\mathbf{R}_{12} &= \iint_{\X} \kb(\x, \x')d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') = \iint_{\X} \mathcal{N}(\x; \x', \Lambda) \mathcal{N}(\x; \mub_1, \Sigmab_1) \mathcal{N}(\x'; \mub_2, \Sigmab_2)d\x d\x' \\ 
&= \int_{\X}  \mathcal{N}(\x'; \mub_1, \Lambda + \Sigmab_1) \mathcal{N}(\x'; \mub_2, \Sigmab_2)d \x' = \mathcal{N}(\mub_1; \mub_2, \Gammab)
\end{split}
\end{equation*}
\ref{eq:Ed}:
\begin{equation*}
\begin{split}
\mathbf{R}_{12'\mub} &= \iint_{\X} \nabla_{\theta} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') = \iint_{\X} \big[\Sigmab_2^{-1}(\x - \mub_2) \big] \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
&= \Sigmab_2^{-1} \int_{\X} \mathcal{N}(\x; \mub_1, \Sigmab_1) \int_{\X} \x' \mathcal{N}(\x'; \x - \mub_2, \Lambda) \mathcal{N}(\x'; \mathbf{0}, \Sigmab_2) d \x' d \x \\
&= \Sigmab_2^{-1} \int_{\X} \Sigmab_2 \left( \Sigmab_2 + \Lambda \right)^{-1} \left(\x - \mub_{2}\right) \mathcal{N}(\x - \mub_2; \mathbf{0}, \Sigmab_2 + \Lambda) \mathcal{N}(\x; \mub_1, \Sigmab_1) d \x \\
&= \left(\Sigmab_1 + \Sigmab_2 + \Lambda \right)^{-1} \left( \mub_1 - \mub_2 \right) \mathcal{N}(\mub_1; \mub_2,  \Sigmab_1 + \Sigmab_2 + \Lambda) \\
\end{split}
\end{equation*}
\ref{eq:Ee}:
\begin{equation*}
\begin{split}
\mathbf{R}_{12'\Sigmab} &= \iint_{\X} \nabla_{\Sigmab} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
&= \iint_{\X} \frac{1}{2}\big[-\Sigmab_2^{-1} +\Sigmab_2^{-1}(\x - \mub_2)(\x - \mub_2)^{T}\Sigmab_2^{-1} \big] \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
&= -\frac{1}{2}\Sigmab_2^{-1} \mathbf{R}_{12} + \frac{1}{2} \Sigmab_2^{-1} \underbrace{\iint_{\X} (\x - \mub_2)(\x - \mub_2)^{T} \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x')}_{(1)} \Sigmab_2^{-1} \\
(1) &= \int_{\X} \left( \Pib_{2} + \nub_{2} \otimes \nub_{2} \right) \mathcal{N}(\x; \mub_2, \Sigmab_2 + \Lambda) \mathcal{N}(\x; \mub_1,  \Sigmab_1) d \x \text{ with } \left\{
    \begin{array}{ll}
        \Pib_{2} = \left( \Lambda^{-1} + \Sigmab_{2}^{-1} \right)^{-1} \\
        \nub_{2} = \Sigmab_{2}\left( \Lambda + \Sigmab_{2} \right)^{-1}\left( \x - \mub_{2}\right)
    \end{array}
\right. \\
&= \Pib_2 \mathcal{N}(\mub_1; \mub_2, \Sigmab_1 + \Sigmab_2 + \Lambda) \\
&+ \Sigmab_{2}\left( \Lambda + \Sigmab_{2} \right)^{-1} \underbrace{\int_{\X} (\x - \mub_2)(\x - \mub_2)^{T} \mathcal{N}(\x; \mub_1,  \Sigmab_1) \mathcal{N}(\x; \mub_2,  \Lambda + \Sigmab_2) d \x}_{(2)} \left( \Lambda + \Sigmab_{2} \right)^{-1} \Sigmab_{2} \\
(2) &= \int_{\X} \x \x^{T} \mathcal{N}(\x; \mub_1 - \mub_2,  \Sigmab_1) \mathcal{N}(\x; \Lambda + \Sigmab_2) d \x \\
&= \left( \Pib_{1} + \nub_{1} \otimes \nub_{1} \right) \mathcal{N}(\mub_1; \mub_2, \Sigmab_1 + \Sigmab_2 + \Lambda) \text{ with } \left\{
    \begin{array}{ll}
        \Pib_{1} = \Sigmab_{1} \left(\Sigmab_1 + \Sigmab_2 + \Lambda \right)^{-1}\left( \Sigmab_2 + \Lambda \right) \\
        \nub_{1} = \Pib_{1} \Sigmab_{1}^{-1}\left( \mub_{1} - \mub_{2}\right)
    \end{array}
\right. \\
\mathbf{R}_{12'\Sigmab} &= \frac{1}{2}\left[ \underbrace{-\Sigmab_{2}^{-1} + \Sigmab_{2}^{-1} \left( \Pib_2 + \Pib_2 \Lambda^{-1} \left( \Pib_1 + \nub_1 \otimes \nub_1 \right) \Lambda^{-1} \Pib_2 \right) \Sigmab_{2}^{-1}}_{(3)} \right] \mathcal{N}(\mub_1; \mub_2, \Gammab)\\
(3) &= \underbrace{-\Sigmab_{2}^{-1} + \left( \Sigmab_{2} + \Lambda \right)^{-1} \Lambda \Sigmab_{2}^{-1}}_{= -\left( \Sigmab_{2} + \Lambda \right)^{-1}} + \left( \Sigmab_{2} + \Lambda \right)^{-1} \Sigmab_1 \Gammab^{-1} + \Gammab^{-1} \left( \mub_1 - \mub_2 \right) \left( \mub_1 - \mub_2 \right)^{T} \Gammab^{-1} \\
&= \underbrace{-\left( \Sigmab_{2} + \Lambda \right)^{-1} + \left( \Sigmab_{2} + \Lambda \right)^{-1} \Sigmab_1 \Gammab^{-1}}_{=-\Gammab^{-1}} + \Gammab^{-1} \left( \mub_1 - \mub_2 \right) \left( \mub_1 - \mub_2 \right)^{T} \Gammab^{-1} \\
\mathbf{R}_{12'\Sigmab} &= -\frac{1}{2}\left(\Gammab^{-1} - \gammab \otimes \gammab\right) \mathcal{N}(\mub_1; \mub_2, \Gammab)
\end{split}
\end{equation*}
\ref{eq:Ef}:
\begin{equation*}
\begin{split}
\mathbf{R}_{1'2'\mub\mub} &= \iint_{\X} \nabla_{\mub} \ln{\nu_{\theta}}|_{\theta_{t_1}}(\x) \otimes \nabla_{\mub} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
 &= \int_{\X} \nabla_{\mub} \ln{\nu_{\theta}}|_{\theta_{t_1}}(\x) \otimes \int_{\X} \nabla_{\mub} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') \nu_{\theta_{t_2}}(\x') d \x' \nu_{\theta_{t_1}}(\x) d\x \\
 &= \Sigmab_{1}^{-1} \underbrace{\int_{\X} \left(\x - \mub_1 \right) \left(\x - \mub_2 \right)^{T} \mathcal{N}(\x; \mub_1,  \Sigmab_1) \mathcal{N}(\x; \mub_2,  \Sigmab_2 + \Lambda) d\x}_{(1)} \left( \Sigmab_{2} + \Lambda \right)^{-1}\\
 (1) &= \left[\Sigmab_1 \Gammab^{-1}\left(\Sigmab_2 + \Lambda \right) + \Sigmab_1 \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \Gammab^{-1} \Sigmab_1 - \Sigmab_1 \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \right] \\ 
 & \hspace{350pt} \times \mathcal{N}(\mub_1; \mub_2,  \Gammab) \\
 \mathbf{R}_{1'2'\mub\mub} &= \left[ \Gammab^{-1} + \underbrace{\Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \Gammab^{-1} \Sigmab_1 \left( \Sigmab_2 + \Lambda \right)^{-1} - \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \left( \Sigmab_2 + \Lambda \right)^{-1}}_{= - \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \Gammab^{-1}} \right] \\
 & \hspace{350pt} \times \mathcal{N}(\mub_1; \mub_2,  \Gammab) \\
 &= \left[ \Gammab^{-1}-\Gammab^{-1} \left(\mub_1 - \mub_2 \right) \left(\mub_1 - \mub_2 \right)^{T} \Gammab^{-1}\right] \mathcal{N}(\mub_1; \mub_2, \Gammab)
\end{split}
\end{equation*}
\ref{eq:Eg}:
\begin{equation*}
\begin{split}
\mathbf{R}_{1'2'\mub\Sigmab} &= \iint_{\X} \nabla_{\mub} \ln{\nu_{\theta}}|_{\theta_{t_1}}(\x) \otimes \nabla_{\Sigmab} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
&= \int_{\X} \Sigmab_{1}^{-1} \left(\x - \mub_1 \right) \otimes \frac{1}{2} \left(\Lambda + \Sigmab_2\right)^{-1} \left[ \left(\x - \mub_2 \right) \left(\x - \mub_2 \right)^{T} - \left(\Lambda + \Sigmab_2\right) \right] \left(\Lambda + \Sigmab_2\right)^{-1} \\
& \hspace{250pt} \mathcal{N}(\x; \mub_1, \Sigmab_1)  \mathcal{N}(\x; \mub_2, \Sigmab_2 + \Lambda) d\x \\
&= \frac{1}{2} \Sigmab_{1}^{-1} *_{1} \left(\Lambda + \Sigmab_2\right)^{-1} *_{2} \left(\Lambda + \Sigmab_2\right)^{-1} *_{3}  \int_{\X} \left(\x - \mub_1 \right) \otimes \left(\x - \mub_2 \right) \otimes \left(\x - \mub_2 \right)\\
& \hspace{180pt} \underbrace{\hspace{70pt} \mathcal{N}(\x; \mub_1, \Sigmab_1)  \mathcal{N}(\x; \mub_2, \Sigmab_2 + \Lambda) d\x}_{(1)} \\
&- \frac{1}{2} \Sigmab_{1}^{-1} \underbrace{\int_{\X} \left(\x - \mub_1 \right) \mathcal{N}(\x; \mub_1, \Sigmab_1)  \mathcal{N}(\x; \mub_2, \Sigmab_2 + \Lambda) d\x}_{(2)} \otimes \left(\Lambda + \Sigmab_2\right)^{-1}\\
(1) &= \int_{\X} \x \otimes \x \otimes \x \mathcal{N}(\x; \mub_1 - \mub_2, \Sigmab_1) \mathcal{N}(\x; \boldsymbol{0}, \Sigmab_2 + \Lambda) d\x\\
&\hspace{50pt} -\left(\mub_1 - \mub_2 \right) \otimes \int_{\X} \x \otimes \x \mathcal{N}(\x; \mub_1 - \mub_2, \Sigmab_1 )\mathcal{N}(\x; \boldsymbol{0}, \Sigmab_2 + \Lambda) d\x \\
&= \mathcal{N}(\mub_1; \mub_2, \Gammab) \left( \nub \otimes \nub \otimes \nub + \sum\limits_{\tau \in \Taub_3} \tau(\nub \otimes \Pib) -\left(\mub_1 - \mub_2 \right) \otimes \left(\Pib + \nub \otimes \nub \right) \right) \\
& \text{ with } \left\{
    \begin{array}{ll}
        \Pib = \Sigmab_{1} \Gammab^{-1}\left( \Sigmab_2 + \Lambda \right) \\
        \nub = \Pib \Sigmab_{1}^{-1}\left( \mub_{1} - \mub_{2}\right)
    \end{array}
\right. \\
(2) &= \Sigmab_1 \Gammab^{-1} \left(\mub_2 - \mub_1 \right) \mathcal{N}(\mub_1; \mub_2, \Gammab)\\
\mathbf{R}_{1'2'\mub\Sigmab} &= \frac{1}{2} \Sigmab_{1}^{-1} *_{1} \left(\Lambda + \Sigmab_2\right)^{-1} *_{2} \left(\Lambda + \Sigmab_2\right)^{-1} *_{3} (1) - \frac{1}{2} \Sigmab_{1}^{-1} (2) \otimes  \left(\Lambda + \Sigmab_2\right)^{-1} \\
&= \frac{1}{2} \mathcal{N}(\mub_1; \mub_2, \Gammab) \Bigg \{ \\
(a) \quad & \Sigmab_{1}^{-1} \left(\Lambda + \Sigmab_2\right) \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \\
(b) \quad &+ \Sigmab_{1}^{-1} \left(\Lambda + \Sigmab_2\right) \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \left(\Lambda + \Sigmab_2\right)^{-1} \Sigmab_{1} \Gammab^{-1}\\
(c) \quad &+ \sigma \left( \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1}\right)\\
(d) \quad &+ \Gammab^{-1} \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right)\\
(e) \quad &- \Sigmab_{1}^{-1} \left(\mub_1 - \mub_2 \right) \otimes \left( \Lambda + \Sigmab_2 \right)^{-1} \Sigmab_{1} \Gammab^{-1}\\
(f) \quad &- \Sigmab_{1}^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right)\\
(g) \quad &- \Sigmab_{1}^{-1} \left(\mub_2 - \mub_1 \right) \otimes \left(\Lambda + \Sigmab_2\right)^{-1} \Bigg\}\\
(a) + (f) &= \left[\Sigmab_{1}^{-1} \left(\Lambda + \Sigmab_2\right) \Gammab^{-1} - \Sigmab_{1}^{-1} \right] \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right)\\
&= -\Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right) \otimes \Gammab^{-1} \left(\mub_1 - \mub_2 \right)\\
(b) + (e) &= \left[\Sigmab_{1}^{-1} \left(\Lambda + \Sigmab_2\right) \Gammab^{-1} - \Sigmab_{1}^{-1} \right]\left(\mub_1 - \mub_2 \right) \otimes \left(\Lambda + \Sigmab_2\right)^{-1} \Sigmab_{1} \Gammab^{-1}\\
&= -\Gammab^{-1}\left(\mub_1 - \mub_2\right) \otimes \left(\Lambda + \Sigmab_2\right)^{-1} \Sigmab_{1} \Gammab^{-1}\\
(b) + (e) + (g)&= -\Gammab^{-1}\left(\mub_1 - \mub_2\right) \otimes \left[ \left(\Lambda + \Sigmab_2\right)^{-1} \Sigmab_{1} \Gammab^{-1} - \left(\Lambda + \Sigmab_2\right)^{-1} \right]\\
&= \Gammab^{-1}\left(\mub_1 - \mub_2\right) \otimes \Gammab^{-1}\\
\mathbf{R}_{1'2'\mub\Sigmab} &= \frac{1}{2} \left( \sum\limits_{\tau \in \Taub_3} \tau(\gammab \otimes \Gammab^{-1}) - \gammab \otimes \gammab \otimes \gammab \right)\mathcal{N}(\mub_1; \mub_2, \Gammab)
\end{split}
\end{equation*}
\ref{eq:Eh}:
\begin{equation*}
\begin{split}
\mathbf{R}_{1'2'\Sigmab\Sigmab} &= \iint_{\X} \nabla_{\Sigmab} \ln{\nu_{\theta}}|_{\theta_{t_1}}(\x) \otimes \nabla_{\Sigmab} \ln{\nu_{\theta}}|_{\theta_{t_2}}(\x') \kb(\x, \x') d\nu_{\theta_{t_1}}(\x)d\nu_{\theta_{t_2}}(\x') \\
