\section{Natural Gradient} \label{appendix:naturalgradient}
If $\theta$, $\theta^{'} \in \Theta$ then we can define a distance over distributions as:
\begin{equation}
    KL(P_{\theta^{'}} || P_{\theta}) = \int_x \ln{\frac{P_{\theta^{'}}(dx)}{P_{\theta}(dx)}}P_{\theta^{'}}(dx)
\end{equation} Its expansion defines the Fisher Information matrix:
\begin{equation}
    KL(P_{\theta + \delta \theta} || P_{\theta}) = \frac{1}{2}\sum \boldsymbol{F}_{ij}(\theta) \delta \theta_i \delta \theta_j + O(\delta \theta^{3})
\end{equation}
\begin{equation} \label{eq:fisher}
    \boldsymbol{F}_{ij}(\theta) = -\int \frac{\partial^{2} \ln{P_{\theta}(x)}}{\partial \theta_i \partial \theta_j} P_{\theta}(dx)
\end{equation}
If $g : \Theta \rightarrow \mathbb{R}$ is a smooth function pf the parameter space then its natural gradient is:
\begin{equation}
    \widetilde{\nabla}_{\theta} g = \boldsymbol{F}^{-1} \frac{\partial g(\theta)}{\partial \theta}
\end{equation}
By construction, the natural gradient descent is intrinsic: it does not depend on the chosen parametrization $\theta$ of $P_{\theta}$. This perspective has been studied in the context of optimisation \cite{ollivier2017information}. The resulting algorithm, called IGO (Information Geometric Optimisation) exploit parameterization invariance via natural gradient descent and function invariance to monotonic transformation via rank comparison. When \cite{ollivier2017information} seek monoticity invariance by replacing $f$ in \ref{eq:parame} we will instead leverage bayesian modelling via Gaussian Processes to leverage function prior information. 

\textbf{Multivariate Gaussian Distribution}

In the case of multivariate Gaussian distributions $\mathcal{N}\left(\mub(\theta), \Sigmab(\theta) \right)$, the Fisher Information Matrix has the form:
\begin{equation*}
    \boldsymbol{F}_{i, j} = \frac{\partial\mub^{T}}{\partial\theta_i} \Sigmab^{-1}\frac{\partial\mub}{\partial \theta_j} + \frac{1}{2}tr\left(\Sigmab^{-1} \frac{\partial\Sigmab}{\partial\theta_i} \Sigmab^{-1} \frac{\partial\Sigmab}{\partial\theta_j}\right)
\end{equation*}

Given the parameterisation $\theta = (\mub, \text{vech}(\Sigmab))$ where $\text{vech}(\Sigmab) = \left(\Sigmab_{1:n, 1}, \Sigmab_{1:n, 2}, \dots, \Sigmab_{1:n, n}\right)$, we have $\boldsymbol{F}\left(\theta\right) = \begin{bmatrix}
\Sigmab^{-1} & \mathbf{0} \\
\mathbf{0} & \frac{1}{2} \Sigmab^{-1} \otimes_{K} \Sigmab^{-1} 
\end{bmatrix}$ where $\otimes_{K}$ is the Kronecker product. Hence, we have $\boldsymbol{F}^{-1}\left(\theta\right) = \begin{bmatrix}
\Sigmab & \mathbf{0} \\
\mathbf{0} & 2 \Sigmab \otimes_{K} \Sigmab 
\end{bmatrix}$.

\section{Probabilistic Evolutionary Search Formula and Proofs}
\label{appendix:probes}

\paragraph{xNES.} 
The algorithm xNES \citep{wierstra2014natural} uses an `exponential' parametrization of the input distribtution. With $\Sigmab^{t} = \mathbf{A}^{t}\left(\mathbf{A}^{t}\right)^{T}$, the xNES updates are:
\begin{equation*}
\begin{split}
    \mub^{t+1} &= \mub^{t} + \eta_{m}\sum\limits_{i=1}^{n} w_i \left( \x_i - \mub^t\right) \\
    \A^{t+1} &= \A^{t} \exp \Bigg(\frac{\eta}{2} \\
    & \sum\limits_{i=1}^{n} w_i \left(\left(\mathbf{A}^{t}\right)^{-1} \left( \x_i - \mub^t \right) \left( \x_i - \mub^t \right)^{T} \left(\left(\mathbf{A}^{t}\right)^{-1}\right)^{T} - \I \right)\Bigg)
\end{split}
\end{equation*}

\begin{prop}[\textbf{Probabilistic xNES}]
The update for the probabilistic xNES is:
\begin{equation}
\begin{split}
    \mub^{t+1} &= \mub^{t} + \eta \Sigmab\left(\Sigmab + \Lambda\right)^{-1}\sum\limits_{i=1}^{N} w_i \left( \x_i - \mub^t\right) \\
    \R^{t+1} &= \R^{t} + \eta \left(\mathbf{A}^{t}\right)^{T}\left(\Sigmab^{t} + \Lambda\right)^{-1} \Bigg[\sum\limits_{i=1}^{N}w_i \\
    & \left(\left( \x_i - \mub^t \right) \left( \x_i - \mub^t \right)^{T} - \left(\Sigmab^{t} + \Lambda\right)\right) \Bigg] \left(\Sigmab^{t} + \Lambda\right)^{-1}\A^{t} \\
    \R^{t} &= \ln \left( \left(\mathbf{A}^{t}\right)^{-1} \Sigmab^{t} \left( \left(\mathbf{A}^{t}\right)^{T} \right)^{-1}\right)\\
    \mathbf{w} &= \left[\kb_{\Xb\Xb} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1} (\y  - \mb_{\Xb}) \odot \mathcal{N}\left(\Xb; \mub^{t}, \Lambda + \Sigmab^{t}\right)
\end{split}
\end{equation}
\end{prop}
\begin{proof}
We follow the argument given in the proof of Proposition 16 in \citet{ollivier2017information}.
\end{proof}

\paragraph{SNES.} 
The algorithm Separable NES (SNES; \citet{wierstra2014natural}) assumes the search distribution is given by a multivariate normal distribution with diagonal covariance matrix and is more suitable for high dimensional search space. With $\Sigmab^{t} = Diag(\boldsymbol{\sigma}_{t}^{2})$, the SNES updates are:
\begin{equation*}
\begin{split}
    \mub^{t+1} &= \mub^{t} + \eta\sum\limits_{i=1}^{n} w_i \left( \x_i - \mub^t\right) \\
    \boldsymbol{\sigma}_{t+1} &= \boldsymbol{\sigma}_{t} \exp \left(\frac{\eta}{2} \sum\limits_{i=1}^{n} w_i \left(\left( \left(\boldsymbol{\sigma}_{t}\right)^{-1} \left( \x_i - \mub^t \right) \right)^{2} - \I \right)\right)
\end{split}
\end{equation*}

\begin{prop}[\textbf{Probabilistic SNES}]
Let $\Lambda = Diag(\boldsymbol{\lambda}^{2})$ where $\boldsymbol{\lambda} = [\lambda_1, ..., \lambda_D]$. The update for the probabilistic SNES is:
\begin{equation}
\begin{split}
    \mub^{t+1} &= \mub^{t} + \eta \frac{\boldsymbol{\sigma}_{t}^{2}}{\boldsymbol{\lambda}^{2} + \boldsymbol{\sigma}_{t}^{2}}\sum\limits_{i=1}^{N} w_i \left( \x_i - \mub^t\right) \\
    \boldsymbol{\sigma}_{t+1} &= \boldsymbol{\sigma}_{t} \exp \Bigg(\\
    & \hspace{35pt}\frac{\eta}{2}\frac{\boldsymbol{\sigma}_{t}^{2}}{\boldsymbol{\sigma}_{t}^{2} + \boldsymbol{\lambda}_{t}^{2}} \sum\limits_{i=1}^{n} w_i \left( \left( \frac{\x_i - \mub^t}{\sqrt{\boldsymbol{\sigma}_{t}^{2} + \boldsymbol{\lambda}_{t}^{2}}} \right)^{2} - \boldsymbol{1} \right)\Bigg) \\
    \mathbf{w} &= \left[\kb_{\Xb\Xb} + \sigma_{noise}^{2}\mathbf{I}\right]^{-1} (\y  - \mb_{\Xb}) \odot \mathcal{N}\left(\Xb; \mub^{t}, \Lambda + \Sigmab^{t}\right)
    \end{split}
\end{equation}
\end{prop}
\begin{proof}
We follow the argument given in the proof of Proposition 16 in \cite{ollivier2017information}.
\end{proof}

\section{Experimental Details}

\subsection{Test Functions} \label{appendix:test_function}

We chose an initial distribution $\nu_{\theta} \sim \mathcal{N}(-\mathbf{1}, \mathbf{I})$. The synthetic test functions used are the following:

\textbf{Ackley}. The Ackley test function has analytical form: $f(x) = -A \exp(-B \sqrt{\frac{1}{d}\sum_{i=1}^d x_i^2}) - \exp(1/d \sum_{i=1}^d \cos(c x_i)) + A + exp(1)$. We chose the default parameters $d=2$ and $A = 20$, $B = 0.2$ and $C = 2\pi$ with optimum point at $\x = [0, \cdots, 0]$.


\textbf{Levy}. The Levy test function has analytical form: $f(x) = \sin^2(\pi w_1) + \sum_{i=1}^{d-1} (w_i-1)^2 (1 + 10 \sin^2(\pi w_i + 1)) + (w_d - 1)^2 (1 + \sin^2(2 \pi w_d))$. We chose the default parameters $d=2$ and $w_i = 1 + 0.25(\x_i - 1)$ with optimum point at $\x = [1, \cdots, 1]$.


\textbf{Styblinski Tang}. The Styblinski Tang test function has analytical form: $f(\x) = 0.5 * \sum_{i=1}^d (x_i^4 - 16x_i^2 + 5 x_i)$. We chose the default parameters $d=2$ with optimum point at $\x = [-2.903534, \cdots, -2.903534]$.


\textbf{Rastrigin}. The Rastrigin test function has analytical form: $f(x) = Ad + \sum_{i=1}^d (x_i^2 - A \cos{2\pi x_i})$. We chose the default parameters $d=2$ and $A = 10$ with optimum point at $\x = [0, \cdots, 0]$.


\textbf{Branin}. The Branin test function has analytical form: $f(x) = (x_2 - (b - 0.1 (1 - x_3))x_1^2 + c x_1 - r)^2 + 10(1-t) cos(x_1) + 10$. We chose the default parameters $d=2$ and $b = 5.1 / (4 \pi^2)$, $B = 0.2$ and $c = 5 / \pi$ $r = 6$, $t = 1 / (8 \pi)$ with infinitely many optimum.

\textbf{Griewank}. The Griewank test function has analytical form: $f(x) = \sum_{i=1}^d x_{i}^{2} / 4000 - \prod_{i=1}^d \cos(x_i / \sqrt{i}) + 1$ with optimum point at $\x = [0, \cdots, 0]$.

\textbf{Shekel}. The Shekel test function has analytical form: $f(x) = -\sum_{i=1}^{10} (\sum_{j=1}^4 (x_j - A_{ji})^2 + C_i)^{-1}$ with default parameter and with optimum point at $\x = [4, \cdots, 4]$.

\textbf{Three-Hump Camel Function}. The Three-Hump Camel Function test function has analytical form: $f(x) = 2x_{1}^{2} - 1.05 x_{1}^{4} + \x_{1}^{6}/6 + \x_{1}\x_{2} + \x_{2}^{2}$ with optimum point at $\x = [0, \cdots, 0]$.

\subsection{UCI Experiments} \label{appendix:uci}
For the UCI experiment we turned regression problems into an optimisation problem by training a surrogate model, namely a SVM model with RBF kernal model, that we optimise directly. We fit a multivariate distribution on the data and standardise them before fitting our surrogate model. As a result, we choose an initial distribution $\nu_{\theta} \sim \mathcal{N}(\mathbf{0}, \mathbf{I})$.

\textbf{Heart Disease}. This dataset consists of $d = 14$ features of patients and aims at predicting the probability of a heart disease being present in a given patient.

\textbf{Wine Quality}. This dataset predicts the quality of a certain wine given $d = 11$ features describing its chemical properties.

\textbf{Breast Cancer Wisconsin (Prognostic)}. This dataset predicts the probability for a patient to be diagnosed with breast cancer given $d = 30$ features that are computed from a digitised image of a fine needle aspirate (FNA) of a breast mass.  They describe characteristics of the cell nuclei present in the image.

\textbf{Fertility}. This dataset predicts normal or altered fertility from semen samples provided by individuals with $d = 11$ features relating to their health situation (e.g smoker, drinking alcohol ect...).

\textbf{Concrete Compressive Strength}. This dataset predicts the compressive strength of different concrete samples given $d = 9$ features related to its composition.

\textbf{Combined Cycle Power Plant}. This dataset predicts the energy output of a power plant given $d = 4$ internal characteristics: Temperature (T), Ambient Pressure (AP), Relative Humidity (RH) and Exhaust Vacuum (V).

\textbf{Appliances Energy Prediction}. This dataset predicts the energy use of appliances given $d = 28$ building characteristics gathered through sensors.

\textbf{Superconductivty Data}. This dataset predicts the critical temperature of different conductors given $d = 81$ features.

\textbf{Airfoil Self-Noise}. This dataset predicts the scaled sound pressure level, in decibels, of two and three-dimensional airfoil blade sections in an anechoic wind tunnel given $d = 5$ experimental parameters.

\textbf{Iranian Churn}. This dataset predicts whether a customer of a telecom company will end its relationship with the company given $d = 13$ characteristics, including call failures, complains, subscription length ect...

\subsection{Latent Space Optimisation} \label{appendix:lso}
In this task, we optimise a variable defined in the latent space of a pre-trained generative model in order to generate decoded samples which match a certain chosen class.

\textbf{Score Function}. The objective function was defined as follow: $f(\x) = \sum_{i = 1}^{d} w_i p_i$ where $\mathbf{p} = D(\x)$, with $D(\x)$ the selected decoder which output probability class and $w_i = \exp\left[-2\left(y_i - c\right)^{2}\right]$. This objective is maximised when the decoded data has a probability of being classified as $c$ is one.

\textbf{MNIST}. For MNIST dataset, we selected a VAE for the generative and a CNN for the classifier. Both architecture and pretrained weights can be found at $\href{https://botorch.org/tutorials/vae_mnist}{https://botorch.org/tutorials/vae_mnist}$. We chose two labels, one corresponding to the number two, the other to number five.

\textbf{CIFAR10}. For CIFAR10 dataset, we selected a GAN for the generative and a CNN for the classifier. Both architecture and pretrained weights can be found at \href{https://github.com/csinva/gan-vae-pretrained-pytorch/tree/master}{https://github.com/csinva/gan-vae-pretrained-pytorch/tree/master}. We chose two labels, one corresponding to the class frog, the other to the class horse.
\subsection{Hyperparameter Tuning}\label{appendix:hpo}
In this task we selected one hyperparameter tuning problem from the Profet suite, namely FCNet, which is generated via a meta-model built using a feed-forward neural network as a classification model and trained on 16 OpenML tasks. We also introduce a hyperparameter tuning task, GPmll consisting in optimising the hyperparameters of a Gaussian Process model fitting some data.

\textbf{FCNet} In this task, the objective function has six input parameters, corresponding to feed-forward hyperparameters learning rate, batch size, number of unit at layer one, probability of dropout at layer one, number of unit at layer two, probability of dropout at layer two. These parameter are transformed to be in the range $[0, 1]$. We considered an initial distribution $\nu_{\theta} \sim \mathcal{N}(\mathbf{0}, \mathbf{I})$ on a range [-3, 3] corresponding to three standard deviation that we scaled to fit the range $[0, 1]$.

\textbf{GPmll} In this task, the objective function has four input parameters, corresponding to the hyperparameters of a GP with constant mean and RBF kernel, namely the mean constant, likelihood noise, outputscale and the lengthscale. We took the default parameter set out in GPytorch on which we added a one standard deviation normal distribution. The marginal lilelihood is computed through fitting the GP to $100$ 1D points uniformly dispersed on the range $[0,1]$ and targets computed via $f(x) = \sin{2\pi x} + \epsilon$, $\epsilon \sim \mathcal{N}(0, 0.2)$.

\subsection{Locomotion Tasks}\label{appendix:rl}

\textbf{Cartpole}
This control task consists in maintaining a pole attached to a cart, which moves along a frictionless track. The pendulum is placed upright on the cart and the goal is to balance the pole by applying forces in the left and right direction on the cart. The observation space is four dimensional and consists in the Cart Position, Cart Velocity, Pole Angle and Pole Angular Velocity, and the action space consists in pushing the cart to the left or to the right. We optimise a linear policy of dimension $4$.

\textbf{Swimmer}
This control task consists in  moving swimmers as quickly as possible to the right. The swimmers are made up of three or more segments (called 'links'), connected by one fewer articulation points (referred to as 'rotors'). Each rotor links exactly two segments, forming a linear chain. The swimmer is placed in a two-dimensional pool and always starts from a fixed position (with some slight variation drawn from a uniform distribution). Applying torque to the rotors, leveraging fluid friction allows the swimmers to be propelled forward. This tasks has an action space of dimension $2$ (torque applied on first or second rotor) and an observation space of dimension $8$ corresponding to angles, velocity and angle velocities on various parts of the swimmers. We optimise a linear policy of dimension $16$.

In both tasks, we considered an initial distribution $\nu_{\theta} \sim \mathcal{N}(\mathbf{0}, \mathbf{3I})$ and bounds within $[-\mathbf{5}, \mathbf{5}]^{D}$ for our optimisation problem.

