\section{Gibbs sampler for the hierarchical decomposition model with two Besov priors}
\label{sec:gibbs-sampl-hier}

We here consider a hierarchical formulation in which the prior strength parameters $\lambda_g$ and $\lambda_h$ in \eqref{eq:Posterior_1} are treated as random variables with associated hyperpriors. This approach follows the same Bayesian framework as the model in Section~\ref{sec:hier-decomp-meth}. However, it suffers from identifiability issues which can lead to imbalanced decompositions, where one component dominates. We include the sampling scheme here for completeness and comparison.
% Bayesian statistics provides methods for doing inference on model parameters. One of such methods is hierarchical Bayes where the parameters are assumed to be random with associated hyperprior distributions and estimated as part of the inference of the posterior. We take a hierarchical Bayes approach to estimate the prior parameters $\lambda_{g}$ and $\lambda_{h}$.

%Similar to the approach in Section~\ref{sec:hier-decomp-meth}, we incorporate the prior strength parameters $\lambda_{g}$ and $\lambda_{h}$ as hyperparameters in \eqref{eq:Posterior_1} and introduce a hierarchical model.
We assume that both $\lambda_{g}$ and $\lambda_{h}$ follow Gamma distributions defined as
\begin{equation}
    \pi_{\text{hyp}}(\lambda_{g})\propto \lambda_{g}^{a_{1}-1}\exp\left(-b_{1}\lambda_{g}\right), \quad \pi_{\text{hyp}}(\lambda_{h})\propto \lambda_{h}^{a_{2}-1}\exp\left(-b_{2}\lambda_{h}\right),
\end{equation}
where $a_1$, $b_1$, $a_2$ and $b_2$ are all positive.
Then the joint posterior on the components and hyperparameters is
\begin{align}
    \pi_{\text{post}}(\mathbf{g},\mathbf{h},\lambda_{g},\lambda_{h}|\mathbf{y}=\mathbf{y}^{*})
     & \propto \pi_{\text{like}}(\mathbf{y}=\mathbf{y}^{*}|\mathbf{g},\mathbf{h})\pi_{\text{prior}}(\mathbf{g}|\lambda_{g})\pi_{\text{prior}}(\mathbf{h}|\lambda_{h})\pi_{\text{hyp}}(\lambda_{g})\pi_{\text{hyp}}(\lambda_{h}) \nonumber              \\
     & \propto \lambda_{g}^{n/p_{g}+a_{1}-1} \lambda_{h}^{n/p_{h}+a_{2}-1} \exp\Bigl(-\frac{1}{2\sigma^{2}} \|\mathbf{A}(\mathbf{g}+\mathbf{h})-\mathbf{y}^{*}\|_{2}^{2} \nonumber                                                                     \\
     & -\lambda_{g} \|\mathbf{S}_{g}\mathbf{W}_{\psi_{g}}\mathbf{g}\|_{p_{g}}^{p_{g}} - \lambda_{h}\|\mathbf{S}_{h}\mathbf{W}_{\psi_{h}}\mathbf{h}\|_{p_{h}}^{p_{h}} - b_{1}\lambda_{g} - b_{2}\lambda_{h}\Bigr). \label{eq:PosteriorBesovHierarhical}
\end{align}
The posterior in \eqref{eq:PosteriorBesovHierarhical} can be sampled using a similar Gibbs sampling method as in Algorithm~\ref{alg:Gibbs_Scheme} on four marginal distributions:
\begin{subequations} \label{eq:BesovMarginals}
    \begin{align}
        \pi_{1}(\mathbf{g}|\mathbf{y}^{*},\lambda_{g},\mathbf{h}) & \propto \exp\left(-\frac{1}{2\sigma^{2}}\|\mathbf{A}(\mathbf{g}+\mathbf{h})-\mathbf{y}^{*}\|_{2}^{2}-\lambda_{g}\|\mathbf{S}_{g}\mathbf{W}_{\psi_{g}}\mathbf{g}\|_{p_{g}}^{p_{g}}\right) \\
        \pi_{2}(\mathbf{h}|\mathbf{y}^{*},\lambda_{h},\mathbf{g}) & \propto \exp\left(-\frac{1}{2\sigma^{2}}\|\mathbf{A}(\mathbf{g}+\mathbf{h})-\mathbf{y}^{*}\|_{2}^{2}-\lambda_{h}\|\mathbf{S}_{h}\mathbf{W}_{\psi_{h}}\mathbf{h}\|_{p_{h}}^{p_{h}}\right) \\
        \pi_{3}(\lambda_{g}|\mathbf{g})                           & \propto \lambda_{g}^{n/p_{g}+a_{1}-1}\exp\left(-\lambda_{g}\|\mathbf{S}_{g}\mathbf{W}_{\psi_{g}}\mathbf{g}\|_{p_{g}}^{p_{g}}-b_{1}\lambda_{g}\right)                                     \\
        \pi_{4}(\lambda_{h}|\mathbf{h})                           & \propto \lambda_{h}^{n/p_{h}+a_{2}-1}\exp\left(-\lambda_{h}\|\mathbf{S}_{h}\mathbf{W}_{\psi_{h}}\mathbf{h}\|_{p_{h}}^{p_{h}}-b_{2}\lambda_{h}\right)
    \end{align}
\end{subequations}
We set $p_{g}=p_{h}=2$ and use RTO to sample $\pi_{1}$ and $\pi_{2}$. The marginals distributions $\pi_{3}$ and $\pi_{4}$ can be sampled directly according to Gamma distributions defined as follows
\begin{subequations}
    \begin{align}
        \lambda_{g}^{\text{sample}} & \sim \mathcal{G}(a_{1}+n/2,b_{1}+\|\mathbf{S}_{g}\mathbf{W}_{\psi_{g}}\mathbf{g}\|_{2}^{2}),\label{eq:Besov_param_1} \\
        \lambda_{h}^{\text{sample}} & \sim \mathcal{G}(a_{2}+n/2,b_{2}+\|\mathbf{S}_{h}\mathbf{W}_{\psi_{h}}\mathbf{h}\|_{2}^{2}).\label{eq:Besov_param_2}
    \end{align}
\end{subequations}

