\section{Maximal unbalanced collections in thermal quantum physics}\label{app:A}
In theoretical physics, \emph{thermal quantum field theory} is a set of methods
to calculate expectation values of physical observables of a \emph{quantum field
  theory} at finite temperature. Quantum field theory is a theoretical framework
that combines classical field theory (for example, Newtonian gravitation or
Maxwell's equations of electromagnetic fields), special relativity, and quantum
mechanics. Quantum field theory treats particles as excited states of their
underlying quantum fields, which are more fundamental than the particles. \\

Key objects of quantum field theory are the \emph{correlators}, also called
\emph{Green functions}, that are used to calculate various \emph{observables},
i.e., self-adjoint operators on the Hilbert \emph{space of states} $\bbH$ that
extract some physical properties from a particular state of the studied
system. These correlators are all encoded in a generating functional, called the
\emph{partition function}, analog to the way a sequence of coefficients in
combinatorics is encoded in a generating function. \\

With the \emph{imaginary time formalism}, the difference between the partition
function in thermal quantum field theory and in zero-temperature quantum field
theory is a thermal weight $e^{-\beta H}$, which is actually the action of a
\emph{time-evolution} operator $e^{-iHT}$, that operates a shift in time of
$-i\beta$. The physicists aim to extract the corresponding correlators from this
new partition function. In the computation, a function $\Phi$ appears, that
takes as an input a set of complex energies $\{z_i\}_{i \in I}$ satisfying
$\sum_{i \in I} z_i = 0$, called the \emph{imaginary Matsubara
  energies}. Physicists are interested in the analytic continuations of $\Phi$,
which exist only where
\[
\sum_{i \in J} z_i \not \in \mathfrak{Re}, \qquad \forall J \subseteq I.
\]
We remark that for a given subset of indices $J \subseteq I$, the set $H_J
\coloneqq \{z \in \bbC^{\lvert I \rvert} \mid \sum_{i \in J} z_i \in
\mathfrak{Re}\}$ is a hyperplane of the energy space. It has been proven (Evans,
\cite{eva92}) that the analytic continuations of $\Phi$, which produce
solutions called \emph{(thermal) generalised retarded functions} (Evans,
\cite{eva94}), and the regions of the hyperplane arrangement $\{H_J\}_{J
  \subseteq I}$, called the \emph{restricted all-subset arrangement} (Billera et
al., \cite{bimomowawi12}), are in bijection.

Thanks to the discussion in Section~\ref{sec:bcother}, we see that the generalised retarded functions, produced with the imaginary time formalism studying $n$-body problems, are then in bijection with the maximal unbalanced collections on $N$.


\section{Example of generation of minimal balanced collections}\label{app:B}
Let $N = \{a, b, c, d\}$ and $N' = N \cup \{e\}$. Let $S_1 = \{a, b\}$, $S_2 = \{a, c\}$, $S_3 = \{a, d\}$ and $S_4 = \{b, c, d\}$. Then $\calC = \{S_1, S_2, S_3, S_4\}$ is a minimal balanced collection with the following system of balancing weights $\lambda = \left(\frac{1}{3}, \frac{1}{3}, \frac{1}{3}, \frac{2}{3}\right)$. 

\paragraph{First case} Remark that the set $I = \{1, 4\}$ satisfies the equation $\lambda_I = 1$. Therefore, a minimal balanced collection can be constructed as follows:
\[
\calC' = \{\{a, b, e\}, \{a, c\}, \{a, d\}, \{b, c, d, e\}\}, \text{ with } \left( \frac{1}{3}, \frac{1}{3}, \frac{1}{3}, \frac{2}{3} \right).
\]

\paragraph{Second case} Let $I = \{4\}$. Then $\lambda_I = \frac{2}{3} < 1$. Therefore,
\[
\calC' = \{\{a, b\}, \{a, c\}, \{a, d\}, \{b, c, d, e\}, \{e\}\}, \text{ with } \left( \frac{1}{3}, \frac{1}{3}, \frac{1}{3}, \frac{2}{3}, \frac{1}{3} \right).
\]
is a minimal balanced collection on $N'$. 

\paragraph{Third case} Let $I = \{1, 2\}$ and $\delta = 4$. Then $\lambda_I = \frac{2}{3}$ and $1 - \lambda_{S_\delta} = \frac{1}{3}$. Therefore, $1 > \lambda_I > 1 - \lambda_{S_\delta}$ and the following minimal balanced collection can be constructed:
\[
\calC' = \{\{a, b, e\}, \{a, c, e\}, \{a, d\}, \{b, c, d\}, \{b, c, d, e\}\}, \text{ with } \left( \frac{1}{3}, \frac{1}{3}, \frac{1}{3}, \frac{1}{3}, \frac{1}{3} \right).
\]

\paragraph{Last case} For the last case, consider another framework. Let $N = \{a, b\}$, and $\calC^1 = \{\{a\}, \{b\}\}$, $\calC^2 = \{\{a, b\}\}$ be the only two minimal balanced collections on $N$. Let $\calC$ be the union $\calC = \{\{a\}, \{b\}, \{a, b\}\}$. 
\[
\mu = (1, 1, 0) \text{ and } \nu = (0, 0, 1).
\]
Observe that
\[
{\rm rk}(A^\calC) = {\rm rk} \left( \begin{bmatrix} 1 & 0 & 1 \\ 0 & 1 & 1 \end{bmatrix} \right) = 2 = k-1.
\]
Finally, let $I = \{1, 2\}$. Then $\mu_I = 2$, $\nu_I = 0$, and
\[
t^I = \frac{1 - \mu_I }{\nu_I - \mu_I} = \frac{1}{2} \in \ ]0, 1[. 
\]
The following collection may therefore be constructed:
\[
\calC' = \{\{a, c\}, \{b, c\}, \{a, b\}\}, \text{ with} 
\]
\[
\begin{array}{rcl}
\lambda^{\calC'}_{\{a, c\}} & = (1-t^I)\mu_{\{a, c\}} + t^I\nu_{\{a, c\}} = \frac{1}{2}\mu_{\{a, c\}} & = \frac{1}{2}, \\
\lambda^{\calC'}_{\{b, c\}} & = (1-t^I)\mu_{\{b, c\}} + t^I\nu_{\{b, c\}} = \frac{1}{2}\mu_{\{b, c\}} & = \frac{1}{2}, \\
\lambda^{\calC'}_{\{a, b\}} & = (1-t^I)\mu_{\{a, b\}} + t^I\nu_{\{a, b\}} = \frac{1}{2}\nu_{\{a, b\}} & = \frac{1}{2}.
\end{array}
\]

\section{Algorithms for checking various properties of coalitions and
  collections}\label{app:C}
These algorithms refer to results given in Section~\ref{sec:prop}.

\begin{breakablealgorithm}
\caption{Exactness checking subroutine} \label{alg:exact}
\begin{algorithmic}[1]
\Require A coalition $S$, a balanced game $(N,v)$, the set $\bbB(N)$
\Ensure The Boolean value: `$S$ is exact'
\Procedure{IsExact}{$S$, $\bbB(N)$, $(N,v)$}
\State Define $v^S$ such that $v^S(T) = v(T)$ for all $T \in 2^N \setminus \{S^c\}$, and $v^S(S^c) = v(N) - v(S)$
\For{$(\calB, \lambda) \in \bbB(N)$}
\If{$\sum_{T \in \calB} \lambda_T v^S(T) > v(N)$}
\Return \textbf{False}
\EndIf
\EndFor 
\Return \textbf{True}
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}


\begin{breakablealgorithm}
\caption{Strict vital-exactness checking algorithm} \label{sve}
\begin{algorithmic}[1]
\Require A coalition $S$, a balanced game $(N,v)$, the set $\bbB(N)$
\Ensure The Boolean value: `$S$ is strictly vital-exact'
\Procedure{IsStrictlyVitalExact}{$S$,  $\bbB(N)$}, $(N,v)$
\For{$\calB \in \bbB(N)$}
\If{$\sum_{T \in \calB} \lambda^\calB_T v^S(T) > v(N)$}
\Return \textbf{False}
\ElsIf{$\sum_{T \in \calB} \lambda^\calB_T v^S(T) = v(N)$}
\For{$T \in \calB$}
\If{$T \cap S^c = \varnothing$}
\Return \textbf{False}
\EndIf
\EndFor
\EndIf
\EndFor
\Return \textbf{True}
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\begin{breakablealgorithm}
\caption{Extendability checking algorithm} \label{extendable}
\begin{algorithmic}[1]
\Require A coalition $S$, a balanced game $(N,v)$
\Ensure The Boolean value: `$S$ is extendable'
\Procedure{IsExtendable}{$S$, $(N,v)$}
\State $\bbB(S^c) \gets$ \Call{Peleg}{$\lvert S^c \rvert$}
\For{$\xi \in {\rm ext}(C(S,v))$}
\State define the reduced game $v_{S^c, \xi}$
\For{$\calB \in \bbB(S^c)$}
\If{$\sum_{T \in \calB} \lambda^\calB_T v_{S^c, \xi}(T) > v(N) - v(S)$}
\Return \textbf{False}
\EndIf
\EndFor
\EndFor
\Return \textbf{True}
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\newpage

\begin{breakablealgorithm}
\caption{Feasibility checking algorithm} \label{feasible}
\begin{algorithmic}[1]
\Require A balanced game $(N,v)$, its support $\calF$, a set $\calS \subseteq
\calF$, the set $\bbB(N)$
\Ensure The Boolean value: `$\calS$ is feasible'
\Procedure{IsFeasible}{$\calS$, $\calF$, $\bbB(N)$, $(N,v)$}
\For{$\calB \in \bbB(N)$ \textbf{such that} $\calB \subseteq 
    (\calF\setminus \calS)\cup\calS^c$} {\bf do}
\If{$\calB \cap \calS^c \neq \varnothing$ \textbf{and} $\sum_{S \in \calB}\lambda_S^\calB v^\calS(S) \geq v(N)$}
\Return \textbf{False}
\ElsIf{$\calB \cap \calS^c = \varnothing$ \textbf{and} $\sum_{S \in \calB}\lambda_S^\calB v^\calS(S) > v(N)$}
\Return \textbf{False}
\EndIf
\EndFor
\Return \textbf{True}
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\section{Algorithms for checking core stability}\label{app:D}

\begin{breakablealgorithm}
\caption{Association/admissibility subroutine} \label{asso}
\begin{algorithmic}[1]
\Require A set of coalition $\calS$, the set of minimal balanced collections $\bbB(N)$, the set $\calF$
\Ensure The set $\bbC(\calS)$
\Procedure{Admissibles}{$\calS$, $\calF$, $\bbB(N)$}
\For{$S \in \calS$}
\State $\calA(S) \gets \emptyset$
\For{$(\calB, \lambda) \in \bbB(N)$}
\If{$\calB \subseteq \{\{j\} \mid i \in S\} \cup \{S^c\} \cup (\calF \setminus 2^S)$ \textbf{and} $\calB \cap \{\{j\} \mid j \in S\} \neq \emptyset$}
\State $\calB^* \gets \calB \setminus \{\{j\} \mid j \in S\}$
\If{$\calB^* \cap \calS \neq \emptyset$ \textbf{or} $\calB^* \cap \calS^c = \emptyset$}
\State Add $\calB$ to $\calA(S)$
\EndIf
\EndIf
\EndFor
\EndFor
\Return $\bigtimes_{S \in \calS} \calA(S)$
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\begin{breakablealgorithm}
\caption{Omega computation subroutine} \label{omega}
\begin{algorithmic}[1]
\Require A set of coalition $\calS$, a collection $(\calB_S)_{S \in \calS} \in \bbC(\calS)$, the set $\calF$
\Ensure The set $\Omega = \Omega_A \cup \Omega_B \cup \Omega_C$
\Procedure{Omega}{$\calS$, $(\calB_S)_{S \in \calS}$}
\State $\Omega_A \gets \emptyset$, $\Omega_B \gets \emptyset$, $\Omega_C \gets \emptyset$
\For{$S \in \calF$}
\If{\textbf{not} $S \in \calS$}
\State Add $\bfone^S$ to $\Omega_B$
\Else
\State Add $\bfone^{S^c}$ to $\Omega_A$ and $z \gets \vec{o}_{\bbR^N}$
\For{$i \in S$}
\If{$\{i\} \in \calB_S$}
\State $z_j \gets \lambda^\calB_{\{i\}}$
\EndIf
\EndFor
Add $z$ to $\Omega_C$
\EndIf
\EndFor
\Return $(\Omega_A, \Omega_B, \Omega_C)$
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\begin{breakablealgorithm}
\caption{Minimal balanced sets computation algorithm} \label{balancedsets}
\begin{algorithmic}[1]
\Require A set $\Omega=\Omega_A\cup \Omega_B\cup \Omega_C$
\Ensure The sets $\bbB(\Omega)$ and $\bbB_0(\Omega)$
\Procedure{IsMinimalBalanced}{$Z$}
\If{${\rm rk}(A^Z) = {\rm rk}(A^Z_\bfone) = \lvert Z \rvert$}
\State $\lambda \gets$ \Call{LinAlgSolve}{$A^Z$}
\If{$\lambda > 0$}
\Return \textbf{True}
\EndIf
\EndIf
\Return \textbf{False}
\EndProcedure
\Procedure{BalancedSets}{$\Omega$}
\For{$Z \subseteq \Omega$ \textbf{such that} $\lvert Z \rvert \leq n$}
\If{\Call{IsMinimalBalanced}{$Z$}}
\State add $Z$ to $\bbB(\Omega)$
\For{$z \in Z$}
\If{$z \in \Omega_A \setminus \Omega_C$}
\State Add $Z$ to $\bbB_0(\Omega)$
\EndIf
\EndFor
\EndIf
\EndFor
\Return $(\bbB(\Omega),$ $\bbB_0(\Omega)$)
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}

\begin{breakablealgorithm}
\caption{Nested balancedness checking subroutine} \label{nestedbalancedness}
\begin{algorithmic}[1]
\Require A feasible collection $\calS$, the game $(N,v)$, its support $\calF$, and the set $\bbB(N)$
\Ensure The Boolean value: `$\calS$ satisfies the conditions of Theorem \ref{final}' 
\Procedure{IsGSConditionSatisfied}{$\calS$, $\calF$, $\bbB(N)$, $(N,v)$}
\State $\bbC(\calS) \gets$ \Call{Admissibles}{$\calS$, $\calF$, $\bbB(N)$}
\For{$(\calB_S)_{S \in \calS} \in \bbC(\calS)$}
\State $(\Omega_A, \Omega_B, \Omega_C) \gets$ \Call{Omega}{$\calS$, $(\calB_S)_{S \in \calS}$}
\State $(\bbB(\Omega), \bbB_0(\Omega)) \gets$ \Call{BalancedSets}{$\Omega_A \cup \Omega_B \cup \Omega_C$}
\If{$\displaystyle \max_{Z \in \bbB(\Omega)} \psi(Z) \leq v(N)$ \textbf{and} $\displaystyle \arg \max_{Z \in \bbB(\Omega)} \psi(Z) \not \in \bbB_0(\Omega)$}
\Return \textbf{False}
\EndIf
\If{$\displaystyle \max_{Z \in \bbB(\Omega)} \psi(Z) < v(N)$ \textbf{and} $\displaystyle \arg \max_{Z \in \bbB(\Omega)} \psi(Z) \in \bbB_0(\Omega)$}
\Return \textbf{False}
\EndIf
\EndFor
\Return \textbf{True}
\EndProcedure
\end{algorithmic}
\end{breakablealgorithm}


