\subsection{Assumptions and Conditions}

To analyze the convergence rate of Adam, we list the main assumption as follows.

\textbf{Assumption A} [Bounded Infimum]. \emph{ There exists a constant $F^* > -\infty$, and the objective function follows $F(\bm{x}) \ge F^* $ for any $\bm{x} \in {\mathbb R}^d $. }

\textbf{Assumption B.1} [$L$-Smoothness] \emph{There exists a constants $L \ge 0$, and then for any $\bm{x}, \bm{y} \in {\mathbb R}^d $, the gradient of the objective function follows}
\begin{equation}
\small
 \Vert \nabla F(\bm{y}) - \nabla F(\bm{x}) \Vert_2 \le L  \Vert \bm{x} - \bm{y} \Vert_2.
\end{equation}

\textbf{Assumption B.2} [$(L_0, L_1)$-Smoothness] \emph{There exist constants $L_0, L_1\ge 0$, and then for any $\bm{x}, \bm{y} \in {\mathbb R}^d $ , the gradient of the objective function follows}
\begin{equation}
\small
 \Vert \nabla F(\bm{y}) - \nabla F(\bm{x}) \Vert_2 \le (L_0 + L_1 \Vert \nabla F(\bm{x}) \Vert_2) \Vert \bm{x} - \bm{y} \Vert_2.
\end{equation}

\textbf{Assumption B.3} [ $(L_0, L_1,q)$-Smoothness] \emph{There exist constants $L_0, L_1>0$ and $0\le q \le 1$, and then for any $\bm{x}, \bm{y} \in {\mathbb R}^d $ , the gradient of the objective function follows}
\begin{equation}
\small
 \Vert \nabla F(\bm{y}) - \nabla F(\bm{x}) \Vert_2 \le (L_0 + L_1 \Vert \nabla F(\bm{x}) \Vert_2^q) \Vert \bm{x} - \bm{y} \Vert_2.
\end{equation}

When $q = 1$, the generalized $(L_0, L_1, q)$-smoothness (Assumption B.3) is reduced to the $(L_0, L_1)$-smoothness (Assumption B.2). When $L_1 = 0$ or $q = 0$, the generalized $(L_0, L_1, q)$-smoothness (Assumption B.3) is reduced to the standard $L$-smoothness (Assumption B.1).  $(L_0, L_1)$-smoothness was originally defined in \citep{Clipped_SGD_Proof_2019} as a bound on the second-order Hessian function. Following \cite{Imprv_clipping_SGD_2020}, we reformulate the $(L_0, L_1)$-smoothness as an affine form of the gradient norm for first-order differentiable functions. Subsequently, \cite{Relaxed_Adam_proof_2024} first introduced the generalized $(L_0, L_1, q)$-smoothness to analyze the convergence of Adam, followed by \cite{Separa_Adam_proof_2024} and \cite{Adam_weak_assum_2025}.


\textbf{Assumption C.1 }[ Bounded Variance]. \emph{There exists a positive constant $\sigma_0 >0$, and then for any  $\bm{x}_t\in {\mathbb R}^d $, the noisy gradient of the objective function obeys}
\begin{equation}
\small
{\mathbb E} [\nabla f(\bm{x};\zeta)]= \nabla F(\bm{x}), ~~~~~~ {\mathbb E} [\Vert \nabla f(\bm{x};\zeta) - \nabla F(\bm{x}) \Vert_2^2] \le \sigma_0^2.
\end{equation}

\textbf{Assumption C.2 }[  Affine Variance]. \emph{There exist constants $\sigma_0, \sigma_1  \ge 0$, and then for  $\bm{x}\in {\mathbb R}^d $, the noisy gradient of the objective function obeys}
\begin{equation}
\small
{\mathbb E} [\nabla f(\bm{x};\zeta_t)]= \nabla F(\bm{x}), ~~~~~~ {\mathbb E} [\Vert \nabla f(\bm{x};\zeta_t) - \nabla F(\bm{x}) \Vert_2^2] \le \sigma_0^2 + \sigma_1^2 \Vert \nabla F(\bm{x}) \Vert_2^2.
\end{equation}

\textbf{Assumption C.3 }[  $p$-Affine Variance]. \emph{There exist constants $\sigma_0, \sigma_1 \ge 0$ and $0\le p \le 2$, and then $\bm{x}\in {\mathbb R}^d $ at any time, the noisy gradient of the objective function obeys}
\begin{equation}
\small
{\mathbb E} [\nabla f(\bm{x};\zeta_t)]= \nabla F(\bm{x}), ~~~~~~ {\mathbb E} [\Vert \nabla f(\bm{x};\zeta_t) - \nabla F(\bm{x}) \Vert_2^2] \le \sigma_0^2 + \sigma_1^2 \Vert \nabla F(\bm{x}) \Vert_2^p.
\end{equation}


When $p = 2$, the $p$-affine variance (Assumption C.3) is reduced to the affine variance (Assumption C.2). When $\sigma_1 = 0$ or $p = 0$, the  $p$-affine variance (Assumption C.3) is reduced to the bounded variance (Assumption C.1). The affine variance (Assumption C.2) was originally studied in \citep{SGD_affine_var_2000} to analyze the convergence behavior of SGD. It was later applied to analyze AdaGrad \citep{AdaGrad-Norm_affine_var_2022, AdaGrad_affine_var_2023} and a simplified Adam \citep{Separa_Adam_proof_2024}.

 To the best of our knowledge, Assumption B.3 and Assumption C.3 are the weakest assumptions for analyzing the convergence of Adam among the existing literatures.

 In addition, we also list the following required conditions.

  \textbf{Condition 1}  \emph{At any $t$-th iteration in {Algorithm 1},  the gradients satisfy $\sqrt{ \frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t) \Vert_2^2} \le \frac{C_0}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t) \Vert_2$ with $ 1 \le C_0 \ll \sqrt{T} $.}


 \textbf{Condition 2}  \emph{At any $t$-th iteration in {Algorithm 1},  the coordinates of the update in Adam , i.e., $u_t = \frac{\vert \bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}+\epsilon}(j\in[d])$ are independently and identically distributed (i.i.d). }



 \textbf{Condition 3} \emph{ At any $t$-th iteration in {Algorithm 1}, the gradient satisfies $\Vert \nabla F(\bm{x}_t) \Vert_1 =  \frac{\sqrt{d}}{{C_1}} \Vert \nabla F(\bm{x}) \Vert_2$ with $ 1 \le C_1 \ll \sqrt{d} $.}

Condition 1 is easily satisfied when the gradients $\Vert \nabla F(\bm{x}_t) \Vert_2$ decrease at a rate of ${\cal O} \left(\frac{1}{t^{\alpha}}\right)$ for all $0 < \alpha < \frac{1}{2}$, and the number of iterations is sufficiently large. We summarize this in the following proposition.

 \begin{proposition}
 If $\Vert \nabla F(\bm{x}_t) \Vert_2$ decreases at  the rate of ${\cal O } \left(\frac{1}{t^{\alpha}}\right)$ for $0\le \alpha < \frac{1}{2}$ and $T \ge 8$, then it holds that
 \begin{equation}
 \small
 \frac{\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t) \Vert_2^2}{ \left(\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t)\Vert_2\right)^2} \le {\cal O } \left(\frac{2(1-\alpha)^2}{1-2\alpha}\right).
 \end{equation}
 \end{proposition}



\cite{SGD_lower_bound_2023} has demonstrated that the optimal convergence rate of $\Vert \nabla F(\bm{x}_t) \Vert_2$ in non-convex stochastic optimization is $O\left(\frac{1}{T^{\sfrac{1}{4}}}\right)$, which lies in the range $[0, \frac{1}{2})$. We choose a sufficiently large $T$ in practice, meaning $T$ is greatly larger than $\frac{2(1-\alpha)^2}{1 - 2\alpha}$. Therefore, Condition 1 commonly holds in practice.



 {Condition 2} commonly holds in practice, and we empirically validated it in our experiments, as shown in Figure \ref{Figure.1}. Specifically, we employed Adam to train ResNet-50 on ImageNet and GPT-2 (350M) on OpenWebText. During training, we recorded $\sfrac{\bm{m}_t^{(j)}}{\sqrt{\bm{v}_t^{(j)}}}$ for each coordinate in certain layers. To verify whether $\sfrac{\vert \bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}}$ for each coordinate is drawn from the same distribution, we used the two-sample Kolmogorov-Smirnov (KS) test.
In this test, two groups of 10,000 samples were uniformly drawn from all coordinates of the layer, and these groups were used to run the two-sample KS test. We repeated this procedure 1,000 times and reported the mean $p$-value. As illustrated in Figure \ref{Figure.1}, the mean $p$-value is significantly larger than the significance level of 0.05, strongly suggesting that $\sfrac{\bm{m}_t^{(j)}}{\sqrt{\bm{v}_t^{(j)}}}$ for each coordinate in the layers is independently drawn from an identical distribution.



