\section{Main Result}


%\subsection{Convergence of Adam under Weak Assumptions}

In this section, we present our results on the convergence of Adam under two scenarios: 1). Assumption B.3 ($(L_0, L_1, q)$-smoothness) without reliance on Conditions 1-3. 2). Assumptions B.3 ($(L_0, L_1, q)$-smoothness) and C.3 ($p$-affine variance) with the inclusion of Conditions 1-3.

We first state the preliminary result  in Theorem \ref{lemma_convergence}.

\begin{theorem}
Let $\{x_t\}_{t=0}^{T-1}$ be generated by  Algorithm 1. Suppose that Assumptions A,  B.3,  and C.3, along with Condition 1,  hold. Define $u_t^{(j)} := \sfrac{\vert \bm{m}_t^{(j)} \vert}{(\sqrt{\bm{v}_t^{(j)}}+\epsilon)}$, $R:=\sfrac{(1-\beta_1)}{\sqrt{(1-\beta_2)(1-\frac{\beta_1^2}{\beta_2}})}$ , $\hat{L}:=L_0+(1-q)L_1$,  and $\hat{\sigma} := \sigma_0+ \sqrt{\frac{2-p}{2}}$. Choose $\beta_1 <\sqrt{\beta_2}$. Then,  it holds  for any $T \in {\mathbb N^{+}}$,
\begin{equation}
\small
\hspace{-5pt}
\begin{aligned}
& \frac{1}{T}\left(\sum_{t=0}^{T-1} {\mathbb E} [\Vert\bm{u}_t \circ \nabla F(\bm{x}_t) \Vert_1]- \left(\frac{\gamma R^2dqL_1}{2}+ {{2}C_0R\sqrt{d}\sigma_1\sqrt{p(1-\beta_1)}}+ \frac{2\gamma R^2{d}qL_1 }{1-\beta_1}\right)\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2]\right)  \\
&\le  \frac{ F(\bm{x}_{0}) - F^*}{\gamma T} +  \frac{2R\sqrt{d}\left \Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T(1-\beta_1)} + {2\sqrt{1-\beta_1}R\sqrt{d}} \hat{\sigma}
+ \frac{2\gamma R^2 d \hat{L} }{1-\beta_1} + \frac{\gamma R^2{d}\hat{L}  }{2T}.
\end{aligned}
%\label{Eq.lemma_conv}
\label{conv_result}
\end{equation}
\label{lemma_convergence}
\vspace{-25pt}
\end{theorem}

When Assumption C.3 is replaced with Assumption C.1, Condition 1 becomes unnecessary, as detailed in the proof of Theorem \ref{lemma_convergence}. Building on the general result established in Theorem \ref{lemma_convergence}, we derive specific convergence bounds for the Adam algorithm under Assumptions A, B.3, and C.1, without requiring Conditions 1, 2, or 3.


\begin{corollary}[Convergence of Adam without Condition 1-3] Let $\{x_t\}_{t=0}^{T-1}$ be generated by  Algorithm 1. Suppose that  Assumptions A,  B.3 and C.1  hold. Define $u_t^{(j)} := \sfrac{\vert \bm{m}_t^{(j)} \vert}{(\sqrt{\bm{v}_t^{(j)}}+\epsilon)}$, $R:=\sfrac{1-\beta_1}{\sqrt{(1-\beta_2)(1-\sfrac{\beta_1^2}{\beta_2}})}$ and $\hat{L}:=L_0+(1-q)L_1$. Choose $\gamma=\frac{C_2}{T^{3/4}d^{\sfrac{1}{2}}}$, $\beta_1 < \sqrt{\beta_2}$, $1-\beta_1= \frac{C_3}{T^{\sfrac{1}{2}}}$ and $0< v \le \min_{t,j} u_{t}^{(j)} $. Then,  it holds  for any $T \in {\mathbb N^{+}}$ and $T \ge (\frac{4C_2 R^2d^{\sfrac{1}{2}}qL_1}{C_3v} +  (\frac{C_2 R^2d^{\sfrac{1}{2}}qL_1}{v})^{\sfrac{1}{3}})^4$,
\begin{equation}
\small
\begin{aligned}
\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_1] \le& \frac{1}{v}\left(\frac{2( F(\bm{x}_{0})- F(\bm{x}^*))}{C_2T^{\sfrac{1}{4}}d^{\sfrac{1}{2}}} + \frac{4Rd^{\sfrac{1}{2}}\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{C_3T^{\sfrac{1}{2}}} \right. \\
+&\left.\frac{4C_3Rd^{\sfrac{1}{2}}\sigma_0}{T^{\sfrac{1}{4}}} +  \frac{4C_2 R^2d^{\sfrac{1}{2}}\hat{L}}{C_3T^{\sfrac{1}{4}}} + \frac{C_2R^2d^{\sfrac{1}{2}}\hat{L}}{T^{\sfrac{7}{4}}}\right).
\end{aligned}
\end{equation}
\label{theorem_convergence}
\vspace{-20pt}
\end{corollary}

Given the generic result in  Theorem \ref{lemma_convergence}, we derive the more comprehensive convergence bound of Adam under assumptions of Assumptions A, B.3 and C.3 with Condition 1, 2 and 3.

\begin{corollary} [Convergence of Adam with Condition 1-3]
Let $\{x_t\}_{t=0}^{T-1}$ be generated by  Algorithm 1. Suppose Assumptions A,  B.3 and C.3, along Conditions 1,2 and 3,  hold. Define $u_t := \sfrac{\vert \bm{m}_t^{(j)} \vert}{(\sqrt{\bm{v}_t^{(j)}}+\epsilon)}$, $R:=\sfrac{1-\beta_1}{\sqrt{(1-\beta_2)(1-\sfrac{\beta_1^2}{\beta_2}})}$, $\hat{L}:=L_0+(1-q)L_1$,  and $\hat{\sigma} := \sigma_0+ \sqrt{\frac{2-p}{2}}$.

\textbf{Case 1: General Setting with no Access to Oracles}

Choose  $\gamma=\frac{{C}_2}{T^{3/4}d^{\sfrac{1}{2}}}$, $\beta_1 <
  \sqrt{\beta_2}$, $1-\beta_1= \frac{C_3}{T^{\sfrac{1}{2}}}$,  and $0<\bar{v}\le \min_t \mathbb E [\bm{u}_t^{(j)}]  $.  Then, it holds for any $T \in {\mathbb N^{+}}$ and  $T \ge (\frac{4C_0C_1 {C}_3{\sfrac{1}{2}}p^{\sfrac{1}{2}}R\sigma_1}{\bar{v}}+\frac{4C_1{C_2} R^2qL_1}{{C}_3\bar{v}} +  (\frac{C_1{C}_2 R^2qL_1}{\bar{v}})^{\sfrac{1}{3}})^4$,
\begin{equation}
\small
\begin{aligned}
\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2] \le& \frac{C_1}{\bar{v}}\left(\frac{2( F(\bm{x}_{0})- F(\bm{x}^*))}{C_2T^{\sfrac{1}{4}}d^{\sfrac{1}{2}}} + \frac{4R\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{C_3T^{\sfrac{1}{2}}}
+ \frac{4C_3R\hat{\sigma}}{T^{\sfrac{1}{4}}} +  \frac{4C_2 R^2\hat{L}}{C_3T^{\sfrac{1}{4}}} + \frac{C_2R^2\hat{L}}{T^{\sfrac{7}{4}}} \right).
\end{aligned}
\end{equation}

\textbf{Case 2: Lowest-Bound Setting with Access to Oracles}
\vspace{5pt}

Choose  $\hat{C}_2=\frac{(F(\bm{x}_{0}) - F^*)^{\sfrac{3}{4}}}{2^{\sfrac{1}{4}}R\hat{\sigma}^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{4}}}$,  $\hat{C}_3=\frac{2^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{2}}(F(\bm{x}_{0}) - F^*)^{\sfrac{1}{2}}}{\hat{\sigma}}$, $\gamma=\frac{\hat{C}_2}{T^{3/4}d^{\sfrac{1}{2}}}$, $\beta_1 <
  \sqrt{\beta_2}$, $1-\beta_1= \frac{\hat{C}_3}{T^{\sfrac{1}{2}}}$, and  $0<\bar{v} \le \min_t \mathbb E [\bm{u}_t^{(j)}]  $.  Then,  for any $T \in {\mathbb N^{+}}$ and $T \ge (\frac{4C_0C_1 \hat{C}_3{\sfrac{1}{2}}p^{\sfrac{1}{2}}R\sigma_1}{\bar{v}}+\frac{4C_1\hat{C_2} R^2qL_1}{\hat{C}_3\bar{v}} +  (\frac{C_1\hat{C}_2 R^2qL_1}{\bar{v}})^{\sfrac{1}{3}})^4$ the right-hand side of Eq. (\ref{conv_result}) reaches the lowest bound, \emph{i.e.},
\begin{equation}
\small
\begin{aligned}
\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2] \le& \frac{C_1} {\bar{v}} \left( \frac{512^{\sfrac{1}{4}} R\hat{\sigma}^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{4}}(F(\bm{x}_{0}) - F^*)}{T^{\sfrac{1}{4}}} + \frac{2C_1\hat{C}_3R\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T^{\sfrac{3}{4}}} +  \frac{  \hat{C_2}  R^2\hat{L}  }{T^{\sfrac{7}{4}}}\right).
\end{aligned}
\end{equation}
\label{theorem_convergence_1}
\vspace{-20pt}
\end{corollary}

We have some observations from Theorem \ref{lemma_convergence}, Corollary \ref{theorem_convergence}  and Corollary \ref{theorem_convergence_1} below.

%\begin{tcolorbox}[colback=cyan!5!white]
\textbf{Finding 1.}                                                                                                                                                                  To the best of our knowledge, we are the first to formally analyze Adam under the weak assumptions of generalized non-uniform $(L_0, L_1, q)$-smoothness (Assumption B.3) and $p$-affine variance (Assumption C.3). We also prove that $\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2]$ for Adam achieves a tighter bound of {\small ${\cal O} \left(\frac{1}{T^{\sfrac{1}{4}}}\right)$}, compared to the previous {\small ${\cal O} \left(\frac{\ln T}{T^{\sfrac{1}{4}}}\right)$} \citep{Adam_type_proof_2018,Simple_Adam_proof_2020,Prac_Adam_proof_2022, Relaxed_Adam_proof_2024}. Furthermore, earlier works demonstrated that Adam's convergence rates were  dependent on the model dimensionality $d$ and the numerical-stability $\epsilon$ \citep{Adam_type_proof_2018,Simple_Adam_proof_2020,Prac_Adam_proof_2022, Relaxed_Adam_proof_2024}, which makes them unsuitable to analyze large-scale LLM training. However, as shown in Corollary \ref{theorem_convergence_1}, we prove that Adam achieves dimension-free and $\epsilon$-free convergence, similar to SGD \citep{Opt_Review_2018}. Notably, previous studies required a learning rate of $\gamma = 1 - O(\frac{1}{T})$ to reach the optimal convergence rate of {\small ${\cal O} \left(\frac{\ln T}{T^{\sfrac{1}{4}}}\right)$}. This causes $\bm{v}_t$ to closely resemble a plain average of the past $T$ squared gradients, reducing Adam almost to AdaGrad \citep{Simple_Adam_proof_2020}. By contrast, we only require the learning rate to satisfy $\gamma = 1 - O(\frac{1}{T^{\sfrac{3}{4}}})$, which better aligns with Adam's original design.
%\end{tcolorbox}

%\begin{tcolorbox}[colback=cyan!5!white]
\textbf{Finding 2.} In the proof of Theorem \ref{lemma_convergence}, Condition 1 is no longer necessary when Assumption C.1 is used. As demonstrated in Corollary \ref{theorem_convergence}, even in the absence of Conditions 1, 2, and 3, and assuming no access to the oracle values $L_0$, $L_1$, $\sigma_0$, and $\sigma_1$, we can still theoretically establish that $\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E} [\Vert \nabla F(\bm{x}_t) \Vert_2]$ for Adam converges at the rate of $O\left(\frac{1}{T^{\sfrac{1}{4}}}\right)$, under the assumptions of  $(L_0, L_1, q)$-smoothness and  affine variance.
%\end{tcolorbox}

%\begin{tcolorbox}[colback=cyan!5!white]
\textbf{Finding 3.} The momentum coefficients $\beta_1$ and $\beta_2$ play a crucial role in Adam's convergence. As shown in Theorem \ref{lemma_convergence}, when $\beta_1 = \beta_2 = 0$, Adam reduces to signSGD, which converges at best to a bounded region where $\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2] \le O(\frac{1}{T^{\sfrac{1}{4}}} + \sigma_0)$. This result aligns with prior work \citep{signSGD_2018}. In contrast, sufficiently large values of $\beta_1$ and $\beta_2$ ensure Adam achieves the convergence rate of $O(\frac{1}{T^{\sfrac{1}{4}}})$. For SGD, however, momentum has minimal impact on the optimal theoretical convergence rate, as both momentum-SGD and vanilla SGD converge at $O(\frac{1}{T^{\sfrac{1}{4}}})$ \citep{Opt_Review_2018,SGDM_convergence_2020}.
%\end{tcolorbox}

%\begin{tcolorbox}[colback=cyan!5!white]
\textbf{Finding 4.}  Case 2 in Corollary \ref{theorem_convergence_1} states that Adam's learning rate must satisfy $\gamma = O(\frac{1}{\sqrt{d}})$ to achieve the optimal convergence rate. This implies that, with fixed other hyperparameters, larger model sizes require smaller optimal learning rates. This observation has been empirically validated by practitioners training the Llama family of models across different sizes \citep{Llama2023,llama2_2023,llama3_2024}. Interestingly, a similar theoretical conclusion appears in the work on Maximal Update Parametrization ($\mu P$) \citep{MuP_2022}.
