 \le & {\cal O } \left(\frac{1}{T}\int_{t=0}^{T-1}  \frac{1}{t^{2\alpha}} dt \right) \\
  = & {\cal O } \left( \frac{T^{1-2\alpha} -1} {T(1-2\alpha)} \right)  \\
 \le & {\cal O } \left( \frac{c^2} {1-2\alpha} \cdot \frac{1}{T^{2\alpha}}\right).
 \end{aligned}
 \end{equation}

 and

 \begin{equation}
 \begin{aligned}
\left(\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t)\Vert_2\right)^2 = & {\cal O } \left( \left(\frac{1}{T}\sum_{t=0}^{T-1} \frac{1}{t^{\alpha}}\right)^2 \right) \\
\ge & {\cal O } \left(\left(\frac{1}{T}\int_{t=2}^{T+1} \frac{1}{t^{\alpha}} dt\right)^2\right) \\
\ge & {\cal O } \left(\frac{1}{(1-\alpha)^2}\cdot\left(\frac{1}{T^{2\alpha}} - \frac{2^{1-\alpha}}{T^{1+\alpha}}\right)\right).
\end{aligned}
 \end{equation}

It is easy to verify that when $T \ge {2^{\frac{2-\alpha}{1-\alpha}}}$, $\frac{2^{1-\alpha}}{T^{1+\alpha}}\le \frac{1}{2}\cdot\frac{1}{T^{2\alpha}}$. Moreover, we can obtain ${2^{\frac{2-\alpha}{1-\alpha}}}\le 8$ due to $0\le \alpha < \frac{1}{2}$. Hence, when $T \ge 8$, we have

\begin{equation}
 \frac{\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t) \Vert_2^2}{ \left(\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(\bm{x}_t)\Vert_2\right)^2} \le {\cal O } \left( \frac{2(1-\alpha)^2}{1-2\alpha} \right).
\end{equation}


\subsection{Useful Lemmas}


\begin{lemma}
Under Assumption B.3, for any $\bm{x}, \bm{y} \in {\mathbb R}^d $, the function obeys

\begin{equation}
F(\bm{y}) \le  F(\bm{x}) + \langle \nabla F(\bm{x}), \bm{y} -\bm{x} \rangle + \frac{L_0 + L_1\Vert \nabla F(\bm{x}) \Vert_2^q}{2}\Vert \bm{y} - \bm{x}\Vert_2^2.
\end{equation}
\label{lamma_smooth}
\end{lemma}
\textbf{Proof.}  For any $\bm{x}, \bm{y} \in {\mathbb R}^d $, we have
\begin{equation}
\begin{aligned}
F(\bm{y}) = & F(\bm{x}) + \int_{0}^1 \langle \nabla F(\bm{x} + t(\bm{y}-\bm{x})), \bm{y}-\bm{x} \rangle dt \\
= & F(\bm{x}) + \langle \nabla F(\bm{x}), \bm{y}-\bm{x} \rangle + \int_{0}^1 \langle \nabla F(\bm{x} + t(\bm{y}-\bm{x}))-\nabla F(\bm{x}), \bm{y}-\bm{x} \rangle dt \\
\overset{(i)}{\le} & F(\bm{x}) + \langle \nabla F(\bm{x}), \bm{y}-\bm{x} \rangle + \int_0^1 \Vert \nabla F(\bm{x} + t(\bm{y}-\bm{x}))-\nabla F(\bm{x})\Vert_2 \Vert\bm{y}-\bm{x}\Vert_2 dt \\
\overset{(ii)}{\le} & F(\bm{x}) + \langle \nabla F(\bm{x}), \bm{y}-\bm{x} \rangle + (L_0 + L_1 \Vert \nabla  F(\bm{x}) \Vert_2^q)\Vert\bm{y}-\bm{x}\Vert_2^2 \int_0^1 t d_t \\
=&  F(\bm{x}) + \langle \nabla F(\bm{x}), \bm{y} -\bm{x} \rangle + \frac{L_0 + L_1\Vert \nabla F(\bm{x}) \Vert_2^q}{2}\Vert \bm{y} - \bm{x}\Vert_2^2,
\end{aligned}
\end{equation}
where$(i)$ holds due to Cauchy-Schwarz inequality, and  $(ii)$ holds due to Assumption 2.


\begin{lemma}
 Let the sequences $\{\bm{m}_t\}$ and $ \{\bm{v}_t\}$ be generated by Adam in Algorithm 1 with omitted bias correction. If the moving average coefficients $\beta_1, \beta_2$ are constant and satisfy $\beta_1^2 <
  \beta_2$, then

  (1) For any $j \in [d]$,  it holds that
  \begin{equation}
  \frac{\vert\bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}+\epsilon} \le  \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}}.
  \end{equation}

  (2) The maximal value of $\frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}}$ is lower bounded by $1$, and  upper bounded by $\sqrt{\frac{1-\beta_1}{1-\beta_2}}$ when $\beta_1 \le \beta_2$.

  \label{lemma.1}
  \end{lemma}


\textbf{Proof.} (1) Recalling Adam, we know
  \begin{equation}
  \begin{aligned}
  & \bm{m}_t^{(j)} = (1-\beta_1)\sum_{k=1}^t \beta_1^{t-k} \bm{g}_k^{(j)} \\
  & \bm{v}_t^{(j)} = (1-\beta_2)\sum_{k=1}^t \beta_2^{t-k} (\bm{g}_k^{(j)})^2.
  \end{aligned}
  \end{equation}
  Then,
  \begin{equation}
  \begin{aligned}
  \frac{\vert\bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}+\epsilon} \le & \frac{1-\beta_1}{\sqrt{1-\beta_2}}\cdot \frac{\vert\sum_{k=1}^t \beta_1^{t-k} \bm{g}_k^{(j)}\vert}{\sqrt{\sum_{k=1}^t \beta_2^{t-k} (\bm{g}_k^{(j)})^2}} \\
  \overset{(i)}{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_2}}\cdot \frac{\sum_{k=1}^t \beta_1^{t-k} \vert\bm{g}_k^{(j)}\vert}{\sqrt{\sum_{k=1}^t \beta_2^{t-k} (\bm{g}_k^{(j)})^2}} \\
  \overset{(ii)}{\le}& \frac{1-\beta_1}{\sqrt{1-\beta_2}}\cdot \frac{\sqrt{\sum_{k=1}^t \beta_2^{t-k} (\bm{g}_k^{(j)})^2}\sqrt{\sum_{k=1}^t\frac{\beta_1^{2(t-k)}}{\beta_2^{t-k}}}}{\sqrt{\sum_{k=1}^t \beta_2^{t-k} (\bm{g}_k^{(j)})^2}} \\
  =& \frac{1-\beta_1}{\sqrt{1-\beta_2}}\cdot  \sqrt{\sum_{k=1}^t\frac{\beta_1^{2(t-k)}}{\beta_2^{t-k}}} \\
  \overset{(iii)}{\le}& \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}},
  %\le & \frac{(1-\beta_1)}{(1-\beta_1^t)\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}},
  \end{aligned}
  \end{equation}
  where $(i)$ holds due to the fact $\vert\bm{a}^{(j)} + \bm{b}^{(j)}\vert \le \vert\bm{a}^{(j)}\vert + \vert\bm{b}^{(j)}\vert $; $(ii)$ holds due to Cauchy-Schiwaz inequality; $(iii)$ holds due to $\beta_1^2 \le \beta_2$.

(2)  The maximal value of $\frac{\vert\bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}}$ is lower bounded by
\begin{equation}
  \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}} \ge  \frac{1-\beta_1}{{1-\frac{1}{2}(\beta_2 + \frac{\beta_1^2}{\beta_2})}} \ge { \frac{1-\beta_1}{1-\beta_1}} = 1,
\end{equation}
where the first and second inequality reaches the lower bound if and only $\beta_1 = \beta_2$.

When $\beta_1 \le \beta_2$, the maximal value of $\frac{\vert\bm{m}_t^{(j)}\vert}{\sqrt{\bm{v}_t^{(j)}}}$ is upper bounded by
\begin{equation}
  \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}} \le \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1\beta_2}{\beta_2}}} = \frac{\sqrt{1-\beta_1}}{\sqrt{1-\beta_2}}.
\end{equation}


\begin{lemma}
For any random variable $ {\mathcal Z}$ and a constant $C$, there exists
\begin{equation}
  {\mathbb E}[\vert{\rm Sign}({\mathcal Z})- {\rm Sign}(C)\vert] \le \frac{2{\mathbb E}[\vert {\mathcal Z} - C \vert]}{\vert C \vert}.
\end{equation}
\label{lamma_3}
\end{lemma}

\textbf{Proof.} Using Markov'equality, we direct obtain
\begin{equation}
  \begin{aligned}
  {\mathbb E}[\vert{\rm Sign}({\mathcal Z})- {\rm Sign}(C)\vert]  = & 2{\mathbb P}[{\mathbb I}({\rm Sign}({\mathcal Z}) \neq {\rm Sign}(C))] \\
  \le& 2{\mathbb P}[\vert {\mathcal Z} - C \vert \ge \vert C \vert]  \\
  \le& \frac{2{\mathbb E}[\vert {\mathcal Z} - C \vert]}{\vert C \vert}.
  \end{aligned}
\end{equation}


\begin{lemma}
Let $a, b, c >0$ and $0<\alpha<\beta$. If $x\ge ({a+b^{\sfrac{\alpha}{\beta}}})^{\sfrac{1}{\alpha}}$, then $\frac{a}{x^{\alpha}} + \frac{b}{x^{\beta}} \le 1$. The bound is tight up to the factor of 2 since $\frac{({a+b^{\sfrac{\alpha}{\beta}}})^{\sfrac{1}{\alpha}}}{2} \le \max({a}, {b^{\sfrac{1}{\gamma}}}) \le ({a+b^{\sfrac{\alpha}{\beta}}})^{\sfrac{1}{\alpha}} $.
\label{lamma_4}
\end{lemma}

\textbf{Proof.} Let $s=x^\alpha$ and $\gamma=\frac{\beta}{\alpha}\ge 1$, then the inequality becomes
\begin{equation}
\frac{a}{s} + \frac{b}{s^{\gamma}} \le 1
\label{S.18}
\end{equation}


If $s^*$ is a solution of Eq. (\ref{S.18}), it should satisfy
\begin{equation}
s^* \ge \max({a}, {b^{\sfrac{1}{\gamma}}}).
\label{S.19}
\end{equation}

When we set $s_+ = {a+b^{\sfrac{1}{\gamma}}}$, it is easy to verify that
\begin{equation}
\frac{a}{s_+} + \frac{b}{s_+^{\gamma}} = \frac{a}{a+b^{\sfrac{1}{\gamma}}} + \frac{b}{(a+b^{\sfrac{1}{\gamma}})^\gamma} \le \frac{a}{a+b^{\sfrac{1}{\gamma}}}+\frac{b^{\sfrac{1}{\gamma}}}{a+b^{\sfrac{1}{\gamma}}} = 1.
\end{equation}

On the other hand, it is also easy to verify that $s_- = \frac{a+b^{\sfrac{1}{\gamma}}}{2}$ does not satisfy Eq. (\ref{S.19}), which means that $s_+$ is at most a factor of $2$ worse than the smallest solution of Eq. (\ref{S.18}), so $x_+= ({a+b^{\sfrac{\alpha}{\beta}}})^{\sfrac{1}{\alpha}}$ is at most a factor of $2$ worse than the smallest solution of $\frac{a}{x^{\alpha}} + \frac{b}{x^{\beta}} \le 1$.


\subsection{ Proof of Theorem 3.1}

\textbf{Proof.} Following Lemma \ref{lamma_smooth} with $\bm{x}_{t+1}\rightarrow \bm{y}$ and $\bm{x}_{t}\rightarrow \bm{x}$, we have
\begin{equation}
F(\bm{x}_{t+1}) \le  F(\bm{x}_t) + \langle \nabla F(\bm{x}_t), \bm{x}_{t+1} -\bm{x}_t \rangle + \frac{L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q}{2}\Vert \bm{x}_{t+1} - \bm{x}_t\Vert_2^2.
\end{equation}
Recalling the update rule $\bm{x}_{t+1} = \bm{x}_t - \gamma \frac{\bm{m}_t}{\sqrt{\bm{v}_t}+\epsilon} = \bm{x}_t - \gamma \frac{\vert \bm{m}_t \vert}{\sqrt{\bm{v}_t}+\epsilon} \circ \frac{\bm{m}_t}{|\bm{m}_t|} = \bm{x}_t - \gamma \bm{u}_t \circ {\rm Sign}(\bm{m}_t) $, we further obtain
\begin{equation}
\begin{aligned}
F(\bm{x}_{t+1}) \le &  F(\bm{x}_t) - \langle \nabla F(\bm{x}_t), \gamma \bm{u}_t \circ {\rm Sign}(\bm{m}_t) \rangle + \frac{(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)\gamma^2}{2}\Vert \bm{u}_t \Vert_2^2 \\
= & F(\bm{x}_t) - \langle \nabla F(\bm{x}_t), \gamma \bm{u}_t \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle + { \left\langle \nabla F(\bm{x}_t), \gamma \bm{u}_t \circ ({\rm Sign}(\nabla F(\bm{x}_t)) - {\rm Sign}(\bm{m}_t) )\right\rangle}  \\
&+\frac{\gamma^2(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2}\Vert \bm{u}_t \Vert_2^2 \\
\le &  F(\bm{x}_t) - \langle \nabla F(\bm{x}_t), \gamma \bm{u}_t \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle + \gamma{R} { \left\langle \nabla F(\bm{x}_t), {\rm Sign}(\nabla F(\bm{x}_t)) - {\rm Sign}(\bm{m}_t) \right\rangle}  \\
&+\frac{\gamma^2 R^2d(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2},
\end{aligned}
\label{Eq.s_7}
\end{equation}
where the last inequality holds due to $\bm{u}_t^{(j)} \le \frac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}}={R}, \forall j\in[d]$ according to {Lemma \ref{lemma.1}}.

Taking the expectation at the $t$ iteration, we obtain
\begin{equation}
\begin{aligned}
{\mathbb E}[{F(\bm{x}_{t+1})}] \le& F(\bm{x}_t) - \gamma\langle \nabla F(\bm{x}_t), {\mathbb E} [\bm{u}_t] \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle + \gamma{R} { \left\langle \nabla F(\bm{x}_t), {\mathbb E}[{\rm Sign}(\nabla F(\bm{x}_t)) - {\rm Sign}(\bm{m}_t)] \right\rangle}  \\
&+\frac{\gamma^2 R^2d(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2} \\
%\overset{(i)}{\le}& F(\bm{x}_t) - \gamma\bar{u}_t \Vert \nabla F(\bm{x}_t) \Vert_1 + \gamma\sqrt{R} { \left\langle \nabla F(\bm{x}_t), {\mathbb E}[{\rm Sign}(\nabla F(\bm{x}_t)) - {\rm Sign}(\bm{m}_t)] \right\rangle}  \\
%&+\frac{\gamma^2 Rd(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2} \\
%\overset{(ii)}{\le}& F(\bm{x}_t) -  \frac{\gamma\bar{u}_t\sqrt{d}}{C_0} \Vert \nabla F(\bm{x}_t) \Vert_2 + \gamma\sqrt{R} { \left\langle \nabla F(\bm{x}_t), {\mathbb E}[{\rm Sign}(\nabla F(\bm{x}_t)) - {\rm Sign}(\bm{m}_t)] \right\rangle}  \\
%&+\frac{\gamma^2 Rd(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2} \\
\overset{(i)}{\le} & F(\bm{x}_t) - \gamma\langle \nabla F(\bm{x}_t),  {\mathbb E} [\bm{u}_t] \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle  + 2\gamma{R} \; {\mathbb E}[\Vert \bm{m}_t -  \nabla F(\bm{x}_t)\Vert_1] \\
& +\frac{\gamma^2 R^2d(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2} \\
\overset{(ii)}{\le}& F(\bm{x}_t) - \gamma\langle \nabla F(\bm{x}_t),  {\mathbb E} [\bm{u}_t] \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle + 2\gamma R\sqrt{d} \; {\mathbb E}[\Vert \bm{m}_t -  \nabla F(\bm{x}_t)\Vert_2] \\
&+\frac{\gamma^2 R^2d(L_0 + L_1\Vert \nabla F(\bm{x}_t) \Vert_2^q)}{2} \\
\overset{(iii)}{\le}& F(\bm{x}_t) - \gamma\langle \nabla F(\bm{x}_t),  {\mathbb E} [\bm{u}_t] \circ {\rm Sign}(\nabla F(\bm{x}_t)) \rangle + 2\gamma R\sqrt{d} \; {\mathbb E}[\Vert \bm{m}_t -  \nabla F(\bm{x}_t)\Vert_2] \\
&+\frac{\gamma^2 R^2d(L_0 + L_1((1-q)+q{\mathbb E}[\Vert \nabla F(\bm{x}_t) \Vert_2]))}{2},
\end{aligned}
\end{equation}
%where $(i)$ holds since we define $\bar{u}_{t} = {\mathbb E}[\frac{1}{d}{\sum_{j=1}^du_t^{(j)}}]=\frac{{\mathbb E}[\Vert\bm{u}_t\Vert_1]}{d}$ and apply \textbf{Condition 1};$(ii)$ holds resulting from \textbf{Condition 2};
where $(i)$ holds due to ${\mathbb E}[\vert {\rm Sign}(\nabla F(\bm{x}_t^{(j)})) - {\rm Sign}(\bm{m}_t^{(j)})\vert] \le 2\frac{{\mathbb E}[\vert \nabla F(\bm{x}_t^{(j)}) - \bm{m}_t^{(j)}\vert ]}{\vert\nabla F(\bm{x}_t^{(j)})\vert}(\forall j \in [d])$ according to {Lemma \ref{lamma_3}}; $(ii) $holds owing to the fact $\Vert \bm{a}\Vert_1\le \sqrt{d}\Vert \bm{a}\Vert_2$ for any $\bm{a} \in {\mathbb R}^d$; $(iii)$ holds due to the fact $a^q \le (1-q) + qa$ according to Young's inequality.

Taking expectation from the $1$-st iteration to the $T$-th iteration and then summing them, we have
\begin{equation}
\begin{aligned}
{\mathbb E}[{F(\bm{x}_{t+1})}] \le & F(\bm{x}_1) - \gamma  \sum_{t=0}^{T-1} {\mathbb E} [\Vert \bm{u}_t \circ \nabla F(\bm{x}_t) \Vert_1]  + 2\gamma R\sqrt{d} \; \sum_{t=0}^{T-1}{\mathbb E}[\Vert \bm{m}_t -  \nabla F(\bm{x}_t)\Vert_2] \\
&+\sum_{t=0}^{T-1}\frac{\gamma^2 Rd(L_0 + L_1((1-q)+q\Vert \nabla F(\bm{x}_t) \Vert_2))}{2}.
\end{aligned}
\end{equation}

Rearranging the both sides and applying the facts that ${F(\bm{x}_{t+1})} \ge F^*$, we obtain

\begin{equation}
\begin{aligned}
&\frac{1}{T}\sum_{t=0}^{T-1}{\mathbb E} [\Vert\bm{u}_t \circ \nabla F(\bm{x}_t) \Vert_1]- \frac{\gamma R^2qL_1{d}}{2T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2] \\
\le & \frac{ F(\bm{x}_{0}) - F^*}{\gamma T}
 + \frac{2R\sqrt{d}}{T}\sum_{t=0}^{T-1} {\mathbb E} [\Vert \bm{m}_t - \nabla F(\bm{x}_t)\Vert_2]
+ \frac{\gamma R^2{d}(L_0+(1-q)L_1)  }{2T}.
\end{aligned}
\label{Eq.s_9}
\end{equation}


Recalling $\bm{m}_t = \beta_1\bm{m}_{t-1} + (1-\beta_1)\bm{g}_t$, we obtain

\begin{equation}
\begin{aligned}
 \bm{m}_t - \nabla F(\bm{x}_t) =&  \left(\beta_1\bm{m}_{t-1} + (1-\beta_1)\bm{g}_t\right) - \nabla F(\bm{x}_t) \\
=& \beta_1(\bm{m}_{t-1} - \nabla F(\bm{x}_{t-1})) +(1-\beta_1)(\bm{g}_t -  \nabla F(\bm{x}_{t}))
 - \beta_1(\nabla F(\bm{x}_t) - \nabla F(\bm{x}_{t-1})).
\end{aligned}
\end{equation}


Utilizing recursion, we further have
\begin{equation}
\begin{aligned}
 \bm{m}_t - \nabla F(\bm{x}_t) =& -\beta_1^t\nabla F(\bm{x}_{0})+ (1-\beta)\sum_{k=1}^t \beta_1^{t-k} (\bm{g}_k -  \nabla F(\bm{x}_k))
  - \sum_{k=1}^t \beta_1^{t-k+1}(\nabla F(\bm{x}_k) - \nabla F(\bm{x}_{k-1})),
\end{aligned}
\end{equation}
where $\bm{m}_1 - \nabla F(\bm{x}_{0}) = -\beta_1 \nabla F(\bm{x}_{0})+(1-\beta_1)(\bm{g}_1-\nabla F(\bm{x}_{0}))$ due to $\bm{m}_0=0$.

Hence,
\begin{equation}
\begin{aligned}
\frac{1}{T}\sum_{t=0}^{T-1} {\mathbb E}\left[\Vert \bm{m}_t - \nabla F(\bm{x}_t) \Vert_2\right]  \le & \underbrace{\frac{1}{T}\sum_{t=0}^{T-1} \beta_1^t\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}_{{\cal T}_1}+ \underbrace{\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} {\mathbb E}\left[\left\Vert\sum_{k=1}^t \beta_1^{t-k} \left(\bm{g}_k -  \nabla F(\bm{x}_k)\right)\right\Vert_2 \right]}_{{\cal T}_2} \\
 &+  \underbrace{\frac{1}{T}\sum_{t=0}^{T-1} {\mathbb E}\left[\left\Vert \sum_{k=1}^t \beta_1^{t-k+1}(\nabla F(\bm{x}_k) - \nabla F(\bm{x}_{k-1}))\right\Vert_2 \right]}_{{\cal T}_3} \\
\end{aligned}
\label{Eq.s_11}
\end{equation}

In terms of ${\cal T}_1$, we obtain
\begin{equation}
{\cal T}_1 = \frac{1}{T}\sum_{t=0}^{T-1} \beta_1^t\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2 \le \frac{\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T(1-\beta_1)}.
\end{equation}



As for ${\cal T}_2$, we have
\begin{equation}
\begin{aligned}
{\cal T}_2 =&\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} {\mathbb E}\left[\left\Vert\sum_{k=1}^t \beta_1^{t-k} (\bm{g}_k -  \nabla F(\bm{x}_k))\right\Vert_2 \right] \\
\overset{(i)}{\le} & \frac{1-\beta_1}{T}\sum_{t=0}^{T-1}\sqrt{{\mathbb E}\left[\left\Vert\sum_{k=1}^t \beta_1^{t-k} (\bm{g}_k -  \nabla F(\bm{x}_k))\right\Vert_2^2\right]} \\
\overset{(ii)}{=} & \frac{1-\beta_1}{T}\sum_{t=0}^{T-1}\sqrt{\sum_{k=1}^t \beta_1^{2(t-k)} {\mathbb E}\left[\left\Vert\bm{g}_k -  \nabla F(\bm{x}_k)\right\Vert_2^2\right]} \\
\overset{(iii)}{\le} &\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}(\sigma_0^2 + \sigma_1^2 \Vert \nabla F(x_k) \Vert_2^p)} \\
\overset{(iv)}{\le} &\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}\sigma_0^2} + \frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}\sigma_1^2 \Vert \nabla F(x_k) \Vert_2^p} \\
\overset{(v)}{\le} &\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}\sigma_0^2} + \frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}\sigma_1^2\left(\frac{2-p}{2} + \frac{p}{2} \Vert \nabla F(x_k) \Vert_2^2\right)} \\
\overset{(vi)}{\le} &\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \beta_1^{2(t-k)}\sigma_0^2} +\frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \frac{(2-p)\sigma_1^2}{2}\beta_1^{2(t-k)}} \\
&+ \frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \frac{p}{2} \beta_1^{2(t-k)}\sigma_1^2\Vert \nabla F(x_k) \Vert_2^2} \\
\overset{(vii)}{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_1^2}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}}\sigma_1 \right)
+ \frac{1-\beta_1}{T}\sum_{t=0}^{T-1} \sqrt{\sum_{k=1}^t \frac{p\sigma_1^2}{2} \beta_1^{2(t-k)} \Vert \nabla F(x_k) \Vert_2^2}  \\
\overset{(viii)}{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_1^2}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}} \sigma_1 \right) + (1-\beta_1)\sqrt{\frac{1}{T}\sum_{t=0}^{T-1} \sum_{k=1}^t \frac{p\sigma_1^2}{2} \beta_1^{2(t-k)} \Vert \nabla F(x_k) \Vert_2^2}  \\
\overset{(ix)}{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_1^2}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}}\sigma_1 \right) + (1-\beta_1)\sqrt{ \frac{p\sigma_1^2}{2} \cdot\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(x_t) \Vert_2^2 \sum_{k=t}^T \beta_1^{2(t-k)}}  \\
{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_1^2}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}}\sigma_1\right) + \frac{\sqrt{p}\sigma_1(1-\beta_1)}{\sqrt{2(1-\beta_1^2)}}\sqrt{ \frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(x_t) \Vert_2^2}  \\
\overset{(x)}{\le} & \frac{1-\beta_1}{\sqrt{1-\beta_1^2}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}}\sigma_1\right)  + \frac{C_0\sqrt{p}\sigma_1(1-\beta_1)}{\sqrt{2(1-\beta_1^2)}} \cdot\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(x_t) \Vert_2\\
\le & \sqrt{1-\beta_1}\left(\sigma_0 + \sqrt{\frac{2-p}{2}} \sigma_1\right) + {C_0\sigma_1\sqrt{p(1-\beta_1)}} \cdot\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(x_t) \Vert_2 \\
\end{aligned}
\end{equation}
where  $(i)$ holds due to the fact $({\mathbb E}[Z])^2 \le {\mathbb E}[Z^2] $; $(ii)$ holds owing to ${\mathbb E}[\bm{g}_k -  \nabla F(\bm{x}_k)]=\bm{0} $ according to Assumption A; $(iii)$ holds resulting from ${\mathbb E}\left[\left\Vert\bm{g}_k -  \nabla F(\bm{x}_k)\right\Vert_2^2\right]\le \sigma^2$ according to Assumption C.3; $(iv)$ holds due to the fact $\sqrt{a+b} \le \sqrt{a}+\sqrt{b}$; $(v)$ holds resulting from the fact that $a^p \le \frac{2-p}{2} + \frac{p}{2} a^2, 0\le p \le 2$ according to Young's inequality; $(vi)$ holds due to using the fact $\sqrt{a+b} \le \sqrt{a}+\sqrt{b}$ again;$(vii)$ holds due to the fact  $\sum_i^{T}{a_i}\le \sqrt{T}\sqrt{\sum_i^T a_i^2} $ according to Cauchy-Schwaz inequality; $(viii)$ holds owing to $\sum_{k=1}^t \beta_1^{2(t-k)} \le \frac{1}{1-\beta_1^2}$; $(ix)$ holds thanks to the fact $\sum_{i=1}^n \sum_{j=1}^i f(i,j)g(j)  = \sum_{j=1}^n g(j)\sum_{i=j}^n f(i,j)$; $(x)$ holds because of {Condition 1}.

Now we turn attention to ${\cal T}_3$, \emph{i.e.},
\begin{equation}
\begin{aligned}
{\cal T}_3 = & \frac{1}{T}\sum_{t=0}^{T-1} {\mathbb E}\left[\left\Vert \sum_{k=1}^t \beta_1^{t-k+1}(\nabla F(\bm{x}_k) - \nabla F(\bm{x}_{k-1}))\right\Vert_2 \right] \\
\overset{(i)}{\le} & \frac{1}{T}\sum_{t=0}^{T-1}\sum_{k=1}^t\beta_1^{t-k+1}{\mathbb E}\left[\left\Vert \nabla F(\bm{x}_k) - \nabla F(\bm{x}_{k-1}) \right\Vert_2 \right] \\
\overset{(ii)}{\le} & \frac{1}{T}\sum_{t=0}^{T-1} \sum_{k=1}^t\beta_1^{t-k+1}{\mathbb E}\left[(L_0 + L_1\Vert \nabla F(\bm{x}_{k}) \Vert_2)\Vert\bm{x}_k - \bm{x}_{k-1} \Vert_2 \right] \\
\overset{(iii)}{=}&\frac{1}{T}\sum_{t=0}^{T-1}\sum_{k=1}^t\beta_1^{t-k+1}{\mathbb E}\left[\gamma(L_0 + L_1\Vert \nabla F(\bm{x}_{k}) \Vert_2)\Vert \bm{u}_{t-1} \Vert_2 \right])\\
\overset{(iv)}{\le} & \frac{1}{T}\sum_{t=0}^{T-1} L_1\gamma R\sqrt{d}\sum_{k=1}^t\beta_1^{t-k+1} + \frac{\beta^2L_1\gamma R\sqrt{d}}{T}\sum_{k=1}^t\beta_1^{t-k+1}{\mathbb E}[\Vert \nabla F(\bm{x}_{k}\Vert_2^q)] \\
\le & \frac{\gamma L_0 R \sqrt{d}}{1-\beta} + \frac{\gamma L_1 R\sqrt{d}}{T}\sum_{t=0}^{T-1}\sum_{k=1}^t\beta_1^{t-k+1}((1-q)+q{\mathbb E}[\Vert\nabla F(\bm{x}_{k})\Vert_2]) \\
\overset{(v)}{\le} & \frac{\gamma (L_0+(1-q)L_1) R \sqrt{d}}{1-\beta} + \frac{\gamma qL_1 R\sqrt{d}}{T}\sum_{t=0}^{T-1}\sum_{k=1}^t\beta_1^{t-k+1}{\mathbb E}[\Vert\nabla F(\bm{x}_{k})\Vert_2] \\
\overset{(vi)}{=}& \frac{\gamma (L_0+(1-q)L_1) R \sqrt{d}}{1-\beta_1} + \frac{\gamma qL_1 R\sqrt{d}}{T}\sum_{k=1}^T{\mathbb E}[\Vert\nabla F(\bm{x}_{k})\Vert_2]\sum_{t=k}^T \beta_1^{t-k+1} \\
\le & \frac{\gamma (L_0+(1-q)L_1) R \sqrt{d}}{1-\beta_1} + \frac{\gamma qL_1 R\sqrt{d}}{(1-\beta_1)T}\sum_{t=0}^{T-1}{\mathbb E}[\Vert\nabla F(\bm{x}_{t})\Vert_2] \\
\end{aligned}
\label{Eq.s_14}
\end{equation}
where $(i)$ holds due to the fact $\Vert \bm{a} + \bm{b} \Vert_2 \le \Vert \bm{a} \Vert_2 + \Vert\bm{b}\Vert_2$; $(ii)$ holds owing to Assumption B.3; $(iii)$ holds due to the update rule; $(iv)$ holds depending on $\bm{u}^{(j)} \le \sfrac{1-\beta_1}{\sqrt{1-\beta_2}\sqrt{1-\frac{\beta_1^2}{\beta_2}}} = R$ according to Lemma \ref{lemma.1}; $(v)$ holds thanks to the fact that $a^q \le (1-q) + qa$ according to Young's inequality;  $(vi)$ holds resulting from the fact that $\sum_{i=1}^n\sum_{j=1}^i \bm{a}_{i,j}= \sum_{j=1}^n\sum_{i=j}^n \bm{a}_{i,j}$.

Combining Eq.(\ref{Eq.s_11}) - Eq.(\ref{Eq.s_14}), we have
\begin{equation}
\begin{aligned}
\frac{1}{T}\sum_{t=1}^{T}{\mathbb E}\left[\Vert \bm{m}_t - \nabla F(\bm{x}_t) \Vert_2\right]  \le & \frac{\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T(1-\beta_1)}+ {\sqrt{1-\beta_1}}\left(\sigma_0 + \sqrt{\frac{2-p}{2}} \sigma_1\right) \\
+& {C_0\sigma_1\sqrt{p(1-\beta_1)}} \cdot\frac{1}{T}\sum_{t=0}^{T-1} \Vert \nabla F(x_t) \Vert_2 \\
 +& \frac{\gamma R \sqrt{d} (L_0+(1-q)L_1) }{1-\beta_1} + \frac{\gamma R \sqrt{d} qL_1}{1-\beta_1}\cdot \frac{1}{T}\sum_{t=0}^{T-1}{\mathbb E}[\Vert\nabla F(\bm{x}_{t})\Vert_2]\\
\end{aligned}
\label{Eq.s_15}
\end{equation}

Combining  Eq.(\ref{Eq.s_9}) and Eq.(\ref{Eq.s_15}), we obtain
\begin{equation}
\begin{aligned}
& \frac{1}{T}\left(\sum_{t=0}^{T-1} {\mathbb E} [\Vert\bm{u}_t \circ \nabla F(\bm{x}_t) \Vert_1]- \left(\frac{\gamma R^2dqL_1}{2}+ {{2}C_0R\sqrt{d}\sigma_1\sqrt{p(1-\beta_1)}}+ \frac{2                                                                                                      \gamma R^2{d}qL_1 }{1-\beta_1}\right)\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2]\right)  \\
\le & \frac{ F(\bm{x}_{0}) - F^*}{\gamma T} +  \frac{2R\sqrt{d}\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T(1-\beta_1)} + {2R\sqrt{d}\sqrt{1-\beta_1}}\left(\sigma_0+ \sqrt{\frac{2-p}{2}} \sigma_1\right) \\
