\section{Proof of Corollary 3.3}

\textbf{Proof.} (1)  Choosing $\bar{v} = \min_t \mathbb E [\bm{u}_t^{(j)}] $, we have
\begin{equation}
\begin{aligned}
\sum_{t=0}^{T-1} {\mathbb E} [\Vert\bm{u}_t \circ \nabla F(\bm{x}_t) \Vert_1] =  & \sum_{t=0}^{T-1} \sum_{j=1}^d{\mathbb E} [ \vert\bm{u}_t^{(j)} \nabla F(\bm{x}_t^{(j)}) \vert]  \\
\overset{(i)}{=} & \sum_{t=0}^{T-1} \sum_{j=1}^d{\mathbb E} [ \bm{u}_t^{(j)}] {\mathbb E} [\vert \nabla F(\bm{x}_t^{(j)}) \vert]  \\
\overset{(ii)}{=} & \sum_{t=0}^{T-1}{\mathbb E} [ \bm{u}_t^{(j)}] \sum_{j=1}^d {\mathbb E} [\vert \nabla F(\bm{x}_t^{(j)}) \vert]  \\
= & \sum_{t=0}^{T-1} {\mathbb E} [ \bm{u}_t^{(j)}] {\mathbb E} [ \Vert (\nabla F(\bm{x}_t)) \Vert_1] \\
\overset{(iii)}{\ge} & \bar{v}\sum_{t=0}^{T-1} {\mathbb E} [ \Vert (\nabla F(\bm{x}_t)) \Vert_1]  \\
\overset{(iv)}{=}& \frac{\bar{v}\sqrt{d}}{C_1}\sum_{t=0}^{T-1}{\mathbb E} [\Vert (\nabla F(\bm{x}_t)) \Vert_2],
\end{aligned}
\end{equation}
where $(i)$ holds due to $\bm{u}_t^{(j)}$ and $\vert \nabla F(\bm{x}_t^{j}) \vert$ are mutually independent; $(ii)$ holds owing to applying Condition 2; $(iii)$ holds due to the condition $\bar{v} \le \min_{t} {\mathbb E} [ \bm{u}_t^{(j)}]$ ; $(iv)$ holds depending on Condition 3.


Then, we simplify the conclusion in Theorem \ref{lemma_convergence} as
\begin{equation}
\small
\begin{aligned}
 & \left(\bar{v}-\left(\frac{\gamma C_1R^2\sqrt{d}qL_1}{2} + {{2}C_0C_1R\sigma_1\sqrt{p(1-\beta_1)}} + \frac{2\gamma C_1 R^2\sqrt{d}qL_1 }{1-\beta_1}\right) \right)\cdot \frac{1}{T}\sum_{t=0}^{T-1} {\mathbb E} [\Vert \nabla F(\bm{x}_t) \Vert_2] \\
\le & \frac{ C_1(F(\bm{x}_{0}) - F^*)}{\gamma T\sqrt{d}} +  \frac{2C_1R\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T(1-\beta_1)}
 + {2C_1\sqrt{1-\beta_1}R}\hat{\sigma}
+ \frac{2\gamma C_1R^2 \sqrt{d} \hat{L} }{1-\beta_1} + \frac{\gamma C_1 R^2\sqrt{d}\hat{L}}{2T}.
\end{aligned}
\label{Eq.s_41}
\end{equation}

Choosing  $\gamma=\frac{C_2}{T^{\sfrac{3}{4}}d^{\sfrac{1}{2}}}$, $1-\beta_1= \frac{C_3}{T^{\sfrac{1}{2}}}$ and $T \ge (\frac{4C_2 R^2qL_1}{C_3\bar{v}} +  {4}C_0C_1\sqrt{C_3}R\sigma_1\sqrt{p} +  (\frac{C_2 R^2qL_1}{\bar{v}})^{\sfrac{1}{3}})^4$, following Lemma \ref{lamma_4}, it holds that
\begin{equation}
\frac{\gamma C_1R^2\sqrt{d}qL_1}{2} + {{2}C_0C_1R\sigma_1\sqrt{p(1-\beta_1)}} + \frac{2\gamma C_1 R^2\sqrt{d}qL_1 }{1-\beta_1} \le \frac{\bar{v}}{2}.
\end{equation}


