%\begin{equation}
%v-\frac{\gamma R^2dL_2}{2}-\frac{2\gamma(1-p)R^2\sqrt{d}L_2}{1-\beta} \ge \frac{v}{2}.
%\end{equation}

Then, we reformulate Eq. (\ref{Eq.s_41}) as

\begin{equation}
