\ge& \left(\frac{4 C_1(F(\bm{x}_{0}) - F^*)}{\gamma T \sqrt{d}}\right)^{\sfrac{1}{4}}\cdot \left({4C_1\sqrt{1-\beta_1}R}\hat{\sigma}\right)^{\sfrac{1}{2}} \cdot \left( \frac{8C_1\gamma R^2 \sqrt{d} \hat{L} }{1-\beta_1}\right)^{\sfrac{1}{4}} \\
= &  \frac{512^{\sfrac{1}{4}} C_1R\hat{\sigma}^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{4}}(F(\bm{x}_{0}) - F^*)}{T^{\sfrac{1}{4}}},
