\\
& \beta_1 = 1 - \frac{2^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{2}}(F(\bm{x}_{0}) - F^*)^{\sfrac{1}{2}}}{T^{\sfrac{1}{2}}\hat{\sigma}}.
