When it is chosen $T \ge (\frac{4C_0C_1\hat{C}_3^{\sfrac{1}{2}}p^{\sfrac{1}{2}}R\sigma_1}{v}+\frac{4C_1\hat{C_2} R^2qL_1}{\hat{C}_3v} +  (\frac{C_1\hat{C}_2 R^2qL_1}{v})^{\sfrac{1}{3}})^4$ where $\hat{C}_2=\frac{(F(\bm{x}_{0}) - F^*)^{\sfrac{3}{4}}}{2^{\sfrac{1}{4}}R\hat{\sigma}^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{4}}}$ and $C_3=\frac{2^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{2}}(F(\bm{x}_{0}) - F^*)^{\sfrac{1}{2}}}{\hat{\sigma}}$, following Lemma \ref{lamma_4}, it holds that
\begin{equation}
\frac{\gamma C_1R^2\sqrt{d}qL_1}{2} + {{2}C_0C_1R\sigma_1\sqrt{p(1-\beta_1)}} + \frac{2\gamma C_1 R^2\sqrt{d}qL_1 }{1-\beta_1} \le \frac{v}{2}.
\end{equation}

Then, we reformulate Eq. (\ref{Eq.s_41}) as

\begin{equation}
\begin{aligned}
\frac{1}{T}\sum_{t=0}^{T-1} \mathbb E [\Vert\nabla F(\bm{x}_t)\Vert_2] \le& \frac{C_1} {\bar{v}} \left( \frac{512^{\sfrac{1}{4}} R\hat{\sigma}^{\sfrac{1}{2}}\hat{L}^{\sfrac{1}{4}}(F(\bm{x}_{0}) - F^*)}{T^{\sfrac{1}{4}}} + \frac{2C_1\hat{C}_3R\left\Vert \nabla F(\bm{x}_{0})\right\Vert_2}{T^{\sfrac{3}{4}}} +  \frac{  \hat{C_2}  R^2\hat{L}  }{T^{\sfrac{7}{4}}}\right).
