\title[On preservation of relative resolutions for  
poset representations]{On preservation of relative resolutions \\ for poset representations}

%\author{Toshitaka Aoki\textsuperscript{*} \and Shunsuke Tada} 
\author[Toshitaka Aoki]{Toshitaka Aoki\textsuperscript{*}}
