$$
\Wc_p^{p, \lambda_{K}}(P, {Q}) = \frac{1}{K} \sum_{k=1}^K \big[W_p(P(\cdot|x_k), {Q}(\cdot|x_k))\big]^p.
$$
Then, as $K \rightarrow \infty$, we have
$$
\sqrt{K}\big[\Wc_p^{p, \lambda_{K}}(P, {Q}) - \Wc_p^{p, \lambda}(P, {Q})\big] \xrightarrow{\mathcal{D}} B,
$$
where $B$ is a zero-mean Gaussian process with variance function
$$
\mathbf{var}(B) = \int_\mathcal{X} \big[W_p^p(P(\cdot|x), {Q}(\cdot|x)) - \Wc_p^{p, \lambda}(P, {Q})\big]^2 \lambda(\D x).
$$
\end{theorem}


