\[
\hat\mu=\sum_{i=1}^{m} w_{x}^{(i)} \delta_{x^{(i)}}, \quad \hat\nu=\sum_{j=1}^{n} w_{y}^{(j)} \delta_{y^{(j)}}.
\]
