\begin{equation*} \label{12}
\min _{\pi \in {R}_{+}^{m \times n}}\  \sum_{i=1}^m\sum_{j=1}^n  D_{i j} \pi_{i j} \quad
\text {s.t.} \quad  \pi^\top \1_{m}=w_{x}, \quad  \pi \1_{n}=w_{y}.
