As the sequences of kernels $P_m$ and $Q_n$ converge weakly to $P$ and $Q$ respectively, by the weak convergence property of ITD stated in \cite[Thm 3.7]{lin2023integrated}, we obtain $\mathcal{W}_p^{\lambda_k}(P_m, Q_n) \to \mathcal{W}_p^{\lambda_k}(P, Q)$ as $m,n \to \infty$, for every fixed $k$. Similarly, as $m,n \to \infty$, we can also obtain 
\begin{equation}\label{eq:QtildeQ}
    \mathcal{W}_p^{\lambda}(P_m, Q_n) \to \mathcal{W}_p^{\lambda}(P, Q).
\end{equation}

Let $\varphi_p(x) = W_p(P(\cdot|x), Q(\cdot|x))$. By applying the triangle inequality for $W_p$, for all $x,x'\in \Xc$, we obtain
\begin{equation}\label{eq:triangu}
    \varphi_p(x) \leq W_p(P(\cdot|x), P(\cdot|x')) + W_p(P(\cdot|x'), Q(\cdot|x')) + W_p(Q(\cdot|x'), Q(\cdot|x)).
\end{equation}
If the kernels $P$ and $Q$ satisfy the Lipschitz continuous assumption, then:
\begin{equation}\label{lipschitz}
 |\varphi_p(x) - \varphi_p(x')| \leq W_p(P(\cdot|x), P(\cdot|x')) + W_p(Q(\cdot|x'), Q(\cdot|x)) \leq (L_P + L_{Q})d(x,x').   
\end{equation}
This shows that $\varphi_p(x)$ is Lipschitz continuous with respect to $x$. If $\lambda_k \xrightarrow{} \lambda$ converges weakly, we have for the $p$th power of the integrated transportation distance:
\begin{equation*}
\big( \mathcal{W}_p^{\lambda_k}(P, Q)\big)^p = \int (\varphi_p(x))^p \lambda_k(\D x) \longrightarrow \int (\varphi_p(x))^p \lambda(\D x) = \big( \mathcal{W}_p^{\lambda}(P, Q)\big)^p
\end{equation*}
Therefore, we have:
\begin{equation}\label{eq:lambda}
  \lim_{k \to \infty} \mathcal{W}_p^{\lambda_k}(P, Q) = \mathcal{W}_p^\lambda(P, Q).  
\end{equation}

By combining the results from \eqref{eq:QtildeQ} and \eqref{eq:lambda}, we conclude that
$$
\lim_{k \to \infty} \lim_{m,n \to \infty} \mathcal{W}_p^{\lambda_k}(P_m, Q_n) = \lim_{k \to \infty} \mathcal{W}_p^{\lambda_k}(P, Q) = \mathcal{W}_p^\lambda(P, Q).
$$
If the sequences of kernels $(P_m)_{m \geq 1}$ and $(Q_n)_{n \geq 1}$ are Lipschitz continuous, we also obtain:
$$
\lim_{m,n \to \infty} \lim_{k \to \infty} \mathcal{W}_p^{\lambda_k}(P_m, Q_n) = \lim_{m,n \to \infty} \mathcal{W}_p^\lambda(P_m, Q_n) = \mathcal{W}_p^\lambda(P, Q).
$$
Therefore, for sequences of Lipschitz continuous kernels $(P_m)_{m \geq 1}$ and $(Q_n)_{n \geq 1}$, we conclude:
$$\lim_{k,m,n \to \infty} \mathcal{W}_p^{\lambda_k}(P_m, Q_n) = \mathcal{W}_p^\lambda(P, Q).$$
\subsection{Proof of Theorem \ref{thm:process}}
Define $\varphi_p(x) = W_p(P(\cdot|x), Q(\cdot|x))$. By the Lipschitz continuity of $P$ and $Q$ and the triangle inequality, for all $x,x'\in \mathcal{X}$ we obtain:
\[
|\varphi_p(x) - \varphi_p(x')|  \leq (L_P + L_{Q}) d(x, x'),
\]
where $d$ is the metric on $\mathcal{X}$. 


Now, consider the function $f(x) = \varphi_p^p(x) = W_p^p(P(\cdot|x), Q(\cdot|x))$. By applying a similar analytical technique as in \eqref{eq:triangu} and \eqref{lipschitz}, we can show that $f$ is also Lipschitz continuous:
\[
|f(x) - f(x')| = |\varphi_p^p(x) - \varphi_p^p(x')| \leq p R^{p-1} (L_P + L_{Q}) d(x, x'),
\]
where we used the fact that $W_p$ is bounded by $R$.

Now, leveraging the Lipschitz continuity and boundedness of $f(\cdot)$, for every $\epsilon>0$, there exists a constant $C$ such that bracketing entropy satisfies
\begin{equation*}
    \log N(\epsilon,\mathcal{F},L_2) \leq \frac{C}{\epsilon},
\end{equation*}
where $\mathcal{F}$ is the set of all functions $f$. Thus, the class $\mathcal{F}$ is Donsker,
we can apply the Donsker theorem, a powerful extension of the Central Limit Theorem to class of measurable functions (see, e.g., Chapter 19 in \cite{Vaart_1998}).  Let $\mathbb{P}_K$ be the empirical measure based on $x_1, \ldots, x_K$, and $\mathbb{P}$ be the measure corresponding to $\lambda$. Then:
\[
\sqrt{K}(\mathbb{P}_K f - \mathbb{P} f) = \sqrt{K}(\mathcal{W}_p^{p,\lambda_{K}}(P, Q) - \mathcal{W}_p^{p,\lambda}(P, Q)) \xrightarrow{\mathcal{D}} N(0, \sigma^2),
\]
where $\sigma^2 = \mathbf{var}_\lambda(f(X)) = \mathbf{E}_\lambda[f^2(X)] - (\mathbf{E}_\lambda[f(X)])^2$.
Expanding this variance term:
\begin{align*}
\sigma^2 &= \int_\mathcal{X} f^2(x) \lambda(\D x) - \left(\int_\mathcal{X} f(x) \lambda(\D x)\right)^2 \\
&= \int_\mathcal{X} W_p^{2p}(P(\cdot|x), Q(\cdot|x)) \lambda(\D x) - \left(\int_\mathcal{X} W_p^p(P(\cdot|x), Q(\cdot|x)) \lambda(\D x)\right)^2 \\
&= \int_\mathcal{X} \left[W_p^p(P(\cdot|x), Q(\cdot|x)) - \mathcal{W}_p^{p,\lambda}(P, Q)\right]^2 \lambda(\D x).
\end{align*}
This completes the proof, showing that the empirical integrated transportation distance converges in distribution to a Gaussian random variable with the specified mean and variance.

