where $\sum_{i=1}^{m}\widetilde{\pi}_{ij}^k=\frac{1}{n},$ for all $j=1,\ldots,n$ and $\sum_{j=1}^{n}\widetilde{\pi}_{ij}^k=\frac{1}{m},$ for all $i=1,\ldots,m$. Suppose $D_x=\max_{k=1,\ldots,K }\{\|{\bf x}^k\|^2,{\bf x}^k\sim P^k\}$ and $D_y=\max_{k=1,\ldots,K }\{\|{\bf y}^k\|^2,{\bf y}^k\sim Q^k\}$ are finite. Then, we can verify the bounded difference property:
\begin{equation*}
    \begin{aligned}
 \sup_{\tilde{\boldsymbol{x}}^1_{1}\in \mathcal{X} } |\widetilde{G}-G|\leq &\frac{1}{K}\left\{\sum_{j=1}^{n}{\pi}_{1j}^1\left(\|\tilde{\boldsymbol{x}}^1_{1}-\boldsymbol{y}_j^1\|^2-\|{\boldsymbol{x}}^1_{1}-\boldsymbol{y}_j^1\|^2\right)\right\}\\ \leq & \frac{4D_x+D_y}{Km}.
 \end{aligned}
\end{equation*}
Similarly, for other variables ${\bf{x}}^k_i$ updated to $\tilde{\bf{x}}^k_i$, then we can also define $\tilde{G}$ and obtain the corresponding bound  $ \sup_{\tilde{\boldsymbol{x}}_i^{k}\in \mathcal{X} }|\widetilde{G}-G| = \frac{4D_x+D_y}{Km}$. For changes in ${\bf{y}}^k_j$, we have  $\sup_{\tilde{\boldsymbol{y}}_j^{k}\in \mathcal{X} }|\widetilde{G}-G|=\frac{4D_y+D_x}{Kn}$.  According to Lemma \ref{lm:Mc}, it holds that
 \begin{equation*}
     \mathbf{P}\left(\widehat{\mathrm{ITD}}^2-\mathbf{E}\left(\widehat{\mathrm{ITD}}^2\right) >t\right)\leq \exp\left(-\frac{2Kmnt^2}{{m(D_x+4D_y)^2+n(4D_x+D_y)^2}}\right).
 \end{equation*}

\subsection{Proof of Theorem \ref{thm:alter}}
For each client $k$, we denote the aggregated dataset as $\mathcal{Z}^k_{m+n}=\{{\bf x}_1^k,\ldots,{\bf x}_m^k,{\bf y}_1^k,\ldots,{ \bf x}_n^k\}$. Using the Chebyshev's inequality, it holds that
\begin{equation*}
\begin{aligned}
 & \mathbf{P}\left(\widehat{\mathrm{ITD}}^2-\mathbf{E}\left(\widehat{\mathrm{ITD}}^2\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n}\right)\right.\left.\geq \alpha^{-1} \mathbf{var}\left(\widehat{\mathrm{ITD}}^2\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n}\right)\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n}\right) \leq \alpha.   
\end{aligned}
\end{equation*}
Denote the empirical permutation distribution function as $P^{k,\pi}_m$ and ${Q}^{k,\pi}_n$ for each client.  By the definition of  critical value $c_{1-\alpha}^{m,n,K}$ of permutation procedure, then
\begin{equation*}
 c_{1-\alpha}^{m,n,K}\leq  \mathbf{E}\left( \widehat{\mathrm{ITD}}^{2,\pi}\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n}\right)+\sqrt{\frac{ \mathbf{var}\left( \widehat{\mathrm{ITD}}^{2,\pi}\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n} \right) }{\alpha}}.
\end{equation*}
For each client $k = 1, \ldots, K$, note that the sample set $\{\mathbf{x}^k_i\in \mathbb{R}^d, i=1, \ldots, m\}$ and $\{\mathbf{y}^k_i\in \mathbb{R}^d, i=1, \ldots, n\} $. Applying the results of Theorem 1 of \cite{fournier2015rate},  if $P^k$ and $Q^k$ have densities and have finite $q$ moments, there exists a constant $C$, we obtain
%\begin{equation*}
  % \mathbf{E}\left( \widehat{\mathrm{ITD}}^{2,\pi}\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n} \right) = C\{ (n\land m)^{-2/d}+(n\land m)^{-1/2}\}.
%\end{equation*}
   \[
 \mathbf{E}\left( \widehat{\mathrm{ITD}}^{2,\pi}\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n} \right) :=c_{1-\alpha}^*  = C
\begin{cases} 
(n\land m)^{-1/2}+(n\land m)^{-(q-2)/q}, & \text{if } d \leq 3,q\neq 4,  \\
(n\land m)^{-1/2}\{\log(1+m) \lor \log(1+n)\}+(n\land m)^{-(q-2)/q}, & \text{if } d = 4,q\neq 4, \\
 (n\land m)^{-2/d}+(n\land m)^{-(q-2)/q}, & d\geq 5,
\end{cases}
\]
where $m\land n= \min\{m,n\}$ and $\log(1+m) \lor \log(1+n)=\max\{\log(1+m) , \log(1+n)\}$.
Based on Lemma \ref{lm:varper},
        \begin{equation*}
        \mathbf{var}\left( \widehat{\mathrm{ITD}}^{2,\pi}\mid \mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n} \right) \leq \frac{\max_{1\leq k\leq K}\{C(P^{\pi,k},Q^{\pi,k})\}}{Km}+\frac{\max_{1\leq k\leq K}\{C(Q^{\pi,k},P^{\pi,k})\}}{Kn}.
    \end{equation*}
It holds that $c_{1-\alpha}^*\geq c_{1-\alpha}^{m,n,K}$. 
%Define a new quantity $c_{1-\alpha}^*$ as follows
%\begin{equation*}
   % c_{1-\alpha}^*=C\{ (n\land m)^{-2/d}+(n\land m)^{-1/2}\},
%\end{equation*}
As $m,n\rightarrow \infty$, we deduce that%$K=o\{ (m\land n)^{-2/d}\}$ and
\begin{equation*}
    c_{1-\alpha}^*\rightarrow 0.
\end{equation*}

Under alternative hypothesis $H_1$, it holds that 
\begin{equation}\label{eq:alter}
  \frac{1}{2} \mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right)\geq \delta>0.   
\end{equation}
There exist $n_0,m_0$ such that $n\geq n_0,m\geq m_0$, we have
\begin{equation*}
 \frac{1}{2} \mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right)\geq c_{1-\alpha}^*.
\end{equation*}
By Chebshey's inequality, we have
\begin{equation*}
    \begin{aligned}
       & \mathbf{P}\left(\widehat{\mathrm{ITD}}^2\geq c_{1-\alpha}^{m,n,K} \mid H_1 \right)\\
        \geq & \mathbf{P}\left(\widehat{\mathrm{ITD}}^2\geq c_{1-\alpha}^* \mid H_1 \right)\\
        = & \mathbf{P}\left(\widehat{\mathrm{ITD}}^2-\mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right) \geq c_{1-\alpha}^* -\mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right)\mid H_1 \right)\\
         \geq & 1-\mathbf{P}\left(\widehat{\mathrm{ITD}}^2-\mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right) \leq  -\frac{1}{2}\mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right)\mid H_1 \right)\\
         \geq & 1-\frac{4\mathbf{var}\left(\widehat{\mathrm{ITD}}^2\right) }{\left\{\mathbf{E}\left( \widehat{\mathrm{ITD}}^2\mid H_1\right)\right\}^2}.
    \end{aligned}
\end{equation*}
By Lemma \autoref{lm:var} and \eqref{eq:alter},
\begin{equation*}
    \begin{aligned}
       & \mathbf{P}\left(\widehat{\mathrm{ITD}}^2\geq c_{1-\alpha}^{m,n,K} \mid H_1 \right)\\
        \geq &1-\frac{4\left\{\frac{C(P^k,{Q}^k)}{Km}+\frac{C({Q}^k,P^k)}{Kn}\right\}}{\delta^2}.
    \end{aligned}
\end{equation*}
As $m,n\rightarrow \infty$, we deduce that % and $K=o\{\log n (m\land n)\}$
\begin{equation*}
    \begin{aligned}
       & \lim_{K,m,n\rightarrow \infty}\mathbf{P}\left(\widehat{\mathrm{ITD}}^2\geq c_{1-\alpha}^{m,n,K} \mid H_1 \right)=1.
    \end{aligned}
\end{equation*}


