\section{Lemmas and their proofs}
We list McDiarmid's inequality \citep{McDiarmid1998} as follows, which provides the bounded difference for concentration bounds. Let $\mathcal{X}^{m}$ denote the $m$-fold product of $\mathcal{X}$.
	\begin{lemma}[McDiarmid's inequality]
		\label{lm:Mc}
	Consider a mapping $g: \mathcal{X}^{m} \rightarrow \mathbb{R}$ that satisfies the bounded difference property with constants $g_l$, for all $x_l\in \mathcal{X}$ with $l \in\{1, \ldots, m\}$, i.e.,
		$$
		\sup _{ \tilde{x} \in \mathcal{X}}\left|g\left(x_{1}, \ldots, x_{l-1}, x_l,x_{l+1},\ldots, x_{m}\right)-g\left(x_{1}, \ldots x_{l-1}, \tilde{x}, x_{l+1}, \ldots, x_{m}\right)\right| \leq g_{l},
		$$
		where $g_{l}<\infty$. Suppose $(X_1,X_2,\ldots,X_m)$ is an i.i.d. sample from $X$. Then, for all $t>0$,
		$$\mathbf{P}\left(g(X_1,X_2,\ldots,X_m)-\mathbf{E}\left\{g(X_1,X_2,\ldots,X_m)\right\}>t\right)<\exp \left(-{2 t^{2}}\bigg/{\sum_{l=1}^{m} g_{l}^{2}}\right).$$
	\end{lemma}


\begin{lemma}\label{lm:var}
If $P^k$ and $Q^k$ have densities and have finite fourth moments, for $k=1,\ldots,K$, let $\omega_k=\frac{1}{K}$, then %denote $m=\min\{m_1,\ldots,m_K\}$ and $n=\min\{n_1,\ldots,n_K\}$,
\begin{equation*}
 \mathbf{var}\left(\widehat{\mathrm{ITD}}^2\right)\leq \frac{\max_{1\leq k\leq K}\{C(P^k,{Q}^k)\}}{Km}+\frac{\max_{1\leq k\leq K}\{C({Q}^k,P^k)\}}{Kn},      
\end{equation*}
 where $C(P^k,{Q}^{k})=8\left[\mathbf{E}(\|{\bf x}_1^k-{\bf x}_2^k\|^2\|{\bf x}_1^k\|^2)+\{\mathbf{E}(\|{\bf x}_1^k-{\bf x}_2^k\|^4)\}^{1/2}\{\int_{\mathbb{R}^d}\|y\|^4d Q^k(y) \}^{1/2}\right]$. 



\end{lemma}
\begin{proof}
Since the independence of the samples among $\mathcal{Z}^1_{m+n},\ldots,\mathcal{Z}^K_{m+n}$, we have %    Recall that $m=\min\{m_1,\ldots,m_K\}$ and $n=\min\{n_1,\ldots,n_K\}$. 
   \begin{equation*}
   \begin{aligned}
    & \mathbf{var}\left(\widehat{\mathrm{ITD}}^2\right)\\ =&\sum_{k=1}^K\omega_k^2\mathbf{var}\left([{W}_2(P^k_{m}, {Q}^k_{n})]^2\right)\\ \leq & \frac{\max_{1\leq k\leq K}\{C(P^k,{Q}^k)\}}{Km}+\frac{\max_{1\leq k\leq K}\{C({Q}^k,P^k)\}}{Kn}, 
        \end{aligned}
   \end{equation*}
   where the last inequality follows from Theorem 3.3 of \cite{del2019central}.
\end{proof}

