 \section{SC\(^*\)-\(C_0\), SC\(^*\)-\(C_1\), Weakly SC\(^*\)-\(C_0\), and Weakly SC\(^*\)-\(R_0\) Spaces}
\subsection{Definition}  A topological space \( X \) is called:
\begin{enumerate}
    \item SC$^*$-C$_0$ if, for $x, y \in X$, $x \ne y$, there exists $G \in SC^*(X)$ such that $SC^*\text{cl}(G)$ contains only one of $x$ and $y$ but not the other.

    \item SC$^*$-C$_1$ if, for $x, y \in X$, $x \ne y$, there exist $G, H \in SC^*(X)$ such that 
    $x \in SC^*\text{cl}(G)$, $y \in SC^*\text{cl}(H)$ but 
    $x \notin SC^*\text{cl}(H)$ and $y \notin SC^*\text{cl}(G)$.

    \item weakly SC$^*$-C$_0$ if, $\bigcap\limits_{x \in X} SC^*\text{ker}(x) = \emptyset$, where $SC^*\text{ker}(x) = \bigcap \{ G : x \in G \in SC^*(X) \}$.

    \item weakly SC$^*$-R$_0$ if, $\bigcap\limits_{x \in X} SC^*\text{cl}(\{x\}) = \emptyset$.
\end{enumerate}




\subsection{Theorem} 
\begin{enumerate}
    \item Every $SC^*$-$C_1$ space is $SC^*$-$C_0$.
\item Every $SC^*$-$C_0$($SC^*$-$C_1$) space is semi-$C_0$(semi-$C_1$).
\item Every weakly $SC^*$-$R_0$ space is weakly semi-$R_0$ and weakly pre-$R_0$.
\item Every $w$-$C_0$ space is weakly $SC^*$-$C_0$.
\item Every weakly $SC^*$-$C_0$ space is weakly semi-$C_0$ and weakly pre-$C_0$.
\item Every $SC^*$-$C_0$ ($SC^*$-$C_1$) space is semi-$T_0$ (semi-$T_1$).
\item Every weakly $R_0$ space is weakly $SC^*$-$R_0$.
\item weakly $SC^*$-$R_0$ness and weakly $SC^*$-$C_0$ness are independent notions.
\end{enumerate}

\subsection{Remark}
$(X, \tau_2)$ is $SC^*$-$C_0$ but not $SC^*$-$C_1$. $(X, \sigma_1)$ is semi-$C_0$, semi-$C_1$, but neither $SC^*$-$C_1$ nor $SC^*$-$C_0$. $(Y,\sigma)$ is weakly semi-$R_0$ but not weakly $SC^*$-$R_0$. $(X, \tau_2)$ is weakly $SC^*$-$C_0$ but not weakly $SC^*$-$R_0$. $(X, \tau_1)$ is weakly $SC^*$-$R_0$ but not weakly $SC^*$-$C_0$.

\subsection{Theorem}
A topological space $X$ is weakly $SC^*$-$R_0$ if and only if $SC^*$ker$(x) \neq X$ for each $x \in X$.
\begin{proof}
    \textbf{Necessity:} If there is some $x_0 \in  X$ with $SC^*ker(x_0)$ = $X$, then $X$ is the only $SC^*$-open set containing $x_0$. This implies that $x_0 \in SC^*cl(\{x\})$ for every $x\in X$. Hence $\bigcap _{x\in X}$ $SC^*cl(\{x\})\neq \phi$, a contradiction.
\\
\textbf{Sufficiency:} If $X$ is not weakly $SC^*$-$R_0$, then choose some $x_0\in$ $\bigcap _{x\in X}$ $SC^*ker(x).$ This implies that every $SC^*$- neighbourhood of $x_0$ contains every point of $X$. Hence  $SC^*ker(x_0)$ = $X$.
\end{proof}


\subsection{Theorem.}
A topological space $X$ is weakly $SC^*$-$C_0$ if and only if for each $x \in X$, there exists a proper $SC^*$-closed set containing $x_0$.

\begin{proof}
    \textbf{Necessity:} Suppose there is some $x_0 \in  X$ such that $X$ is the only $SC^*$-closed set containing $x_0$. Let $U$ be any proper $SC^*$-open subset of $X$ containing a point $x$. This implies that $C(U) \neq X$. Since $C(U)$ is S$C^*$-closed, we have $x_0 \in C(U)$. So $x_0 \in  U$. Thus $x_0\in$ $\bigcap _{x\in X}ker(x)$ for any point $x$ of $X$, is a contradiction.
\\
\textbf{Sufficiency:} If $X$ is not weakly $SC^*$-$C_0$, then choose $x_0\in $ $\bigcap _{x\in X}SC^*ker(x)$ so $x_0$ belongs to $SC^*ker(x)$ for any $x \in X$. This implies that $X$ is the only $SC^*$-open set, which contains the point $x_0$, is a contradiction.
\end{proof}


\subsection{Theorem.}
Every $SC^*$-$C_0$ ($SC^*$-$C_1$) space is weakly $SC^*$-$C_0$.
\begin{proof}
     If $x, y \in X$ such that $x \neq y$, where $X$ is a $SC^*$-$C_0$ space, then without loss of generality, we can assume that there exists $U \in SC^*(X)$ such that $x \in SC^*cl(U)$ but $y \notin SC^*cl(U)$. This implies that $U\neq \phi$. Hence we can choose $z$ in $U$.\\ Now,
 $SC^*ker(z) \cap SC^*ker(y) \subseteq U \cap (SC^*cl(U))\subseteq (SC^*cl(U)) \cap C(SC^*cl(U))$ = $\phi$.\\ Hence $\bigcap _{x\in X}ker(x)$ = $\phi$. Since every $SC^*$-$C_1$ space is also $SC^*$-$C_0$, it is also clear that every $SC^*$-$C_1$ space is weakly $SC^*$-$C_0$.
\end{proof}
\subsection{Remark.} The converse of the above theorem need not be true since $(Z, \eta_1)$ is weakly $SC^*$-$C_0$ but not $SC^*$-$C_0$. The space $(Y, \sigma)$ is both $SC^*$-$C_0$ and weakly $SC^*$-$C_0$ but not $SC^*$-$C_1$.

\subsection{Theorem} The property of being an $SC^*$-$C_0$ space is not hereditary.
\begin{proof}
     Consider the space $(Y, \sigma)$. Let $S$ = $\{a, c\}$ and $\sigma^*_1$ be the relative topology on $S$. It is easy to verify that $(Y, \sigma)$ is $SC^*$-$C_0$ but it’s subspace $(S, \sigma^*_1)$ is not $SC^*$-$C_0$.
 \end{proof}
\section{\( H^* \)-Separation Axioms}

\subsection{Remark.} Every $\alpha$-closed (resp. $\alpha$-open) set is $H^*$-closed (resp. $H^*$-open) set.\\
     For definitions stated above, we have the following diagram:

\vspace{.1cm}

    closed $\Longrightarrow$ $\alpha$-closed  $\Longrightarrow$ $g\alpha$-closed $\Longrightarrow$ $\alpha g$-closed\\

\hspace{2.2cm} $\Downarrow \hspace{2.2cm} \Downarrow \hspace{2.2cm} \Downarrow$\\

\hspace{1.1cm} $H^*$-closed $\Longrightarrow$ $gH^*$-closed $\Longrightarrow$ $H^*g$-closed
\vspace{.4cm}\\
However the converses of the above are not true as may be seen by the following examples:

\subsubsection{Example.}
Let $X$ = $\{a,b,c,d\}$ and $\tau$ = $\{\phi, X, \{a\}, \{b\}, \{a,b\}, \{a,b,c\}\}$. Then $A$ = $\{c\}$ is $\alpha$-closed set as well as $H^*$-closed set but not closed set in $X$.

\subsubsection{Example.}
Let $X$ = $\{a,b,c,d\}$ and $\tau$ = $\{\phi, X, \{a\}, \{b\}, \{a,b\}, \{a,b,c\}\}$. Then $A$ = $\{c\}$ is $\alpha$-closed set as well as $gH^*$-closed set but not closed set in $X$.

\subsection{Remark.}
\textbf{(i).} A subset $A$ of $X$ is $H^*g$-open in $X$ iff $F \subset \tau^{H^*}$-$int(A)$ whenever $F \subset A$ and $A$ is closed in $X$.\\     
\textbf{(ii).} A subset $A$ of $X$ is $gH^*$-closed (resp. $gH^*$-open) in $X$ iff $A$ is $g$-closed (resp. $g$-open) in $X$.


\section[\texorpdfstring{$H^*$-$T_1$, $H^*$-$T_{\frac{1}{2}}$, $H^*$-$T_b$ and $H^*$-$T_d$-Spaces}{H*-T1, H*-T1/2, H*-Tb and H*-Td-Spaces}]{\boldmath $H^*$-$T_1$, $H^*$-$T_{\frac{1}{2}}$, $H^*$-$T_b$ and $H^*$-$T_d$-Spaces}

\subsection{Definition} A topological space $X$ is said to be:
    \begin{enumerate}
        \item 
        \textbf{$H^*$-$T_1$} if for any distinct pair of points $x$ and $y$ in $X$, there exists a $H^*$-open set $U$ in $X$ containing $x$ but not $y$ and open $H^*$-open set $V$ in $X$ containing $y$ but not $x$.
        \item A \textbf{$T_\frac{1}{2}$}\cite{levine1963semi} if every $g$-closed set is closed.
        \item A \textbf{ $H^*$-$T_\frac{1}{2}$} if every $gH^*$-closed set is $H^*$-closed.
        \item A \textbf{ $H^*$-$T_b$} if every $H^*g$-closed set is closed.
        \item A \textbf{ $H^*$-$T_d$} if every $H^*g$-closed set is $g$-closed.
    \end{enumerate}

\vspace{.1cm}

   $T_1$ \hspace{.2cm} $ \Longrightarrow$ \hspace{.2cm} $ T_\frac{1}{2}$ \hspace{.2cm} $\Leftarrow$ \hspace{.2cm} $H^*$-$T_b$ \hspace{.2cm} $\Longrightarrow$ \hspace{.2cm} $H^*$-$T_d$\\

\hspace{.2cm} $\Downarrow \hspace{1.3cm} \Downarrow$ \\

\hspace{.1cm} $H^*$-$T_1$ $\Longrightarrow$ $H^*$-$T_\frac{1}{2}$
\vspace{.2cm}
\\
It can be explained by the following example:

\subsubsection{Example.} 
An \( H^* \)-\( T_b \) space need not be \( H^* \)-\( T_1 \). Let \( X = \{a, b, c, d\} \) and 
\[
\tau = \{\emptyset, X, \{a\}, \{b\}, \{a, b\}, \{a, b, c\}\}.
\]
Since \( \{a, b\} \) is not \( H^* \)-closed, the space is not \( H^* \)-\( T_1 \), and hence it is not \( T_1 \).

However, the family of all \( H^*g \)-closed sets coincides with the family of all closed sets; hence, the space is \( H^* \)-\( T_b \).

\subsection{Theorem}
\textbf{(i).} $X$ is a $T_\frac{1}{2}$ iff for each $x \in X$, $\{x\}$ is open or closed in $X$.
  \\
  \textbf{(ii).} $X$ is a $H^*$-$T_\frac{1}{2}$ space iff for each $x \in X$, $\{x\}$ is $H^*$-open or $H^*$-closed in $X$. i.e., $X$ is a $H^*$-$T_\frac{1}{2}$ iff a space $(X, \tau^{H^*})$ is $T_\frac{1}{2}$-space.

\subsection{Theorem.} 
\textbf{(i).} If $A$ is $H^*g$-closed, then $H^*$-$cl(A) - A$ does not contain non-empty closed set.\\
\textbf{(ii).} For each x$ \in X$, $\{x\}$ is closed or its complement $X - \{x\}$ is $H^*g$-closed in $X$.\\   
\textbf{(iii).} For each $x\in X$, $\{x\}$ is $H^*$-closed or its complement $X- \{x\}$ is $gH^*$-closed in $X$.

\subsection{Theorem}
\textbf{(i).} Every $H^*$-$T_b$ space is $H^*$-$T_d$ and $T_\frac{1}{2}$.\\
\textbf{(ii).} Every $T_i$ - space is $H^*$ -$T_i$, where $i $=$ 1, \frac{1}{2}$.\\
\textbf{(iii).} Every $H^*$-$T_i$ space is $H^*$-$T_\frac{1}{2}$.

\begin{proof}
    \textbf{(i).} It is obtained from \textbf{Definition 5.1}[(2), (4) and (5)] and \textbf{Remark 4.2.} (i) and (ii).\\
    \textbf{(ii).} Let $X$ be a $T_1$ (resp. $T_\frac{1}{2}$)-space and let $x\in X$. Then $\{x\}$ is closed (resp. open or closed by \textbf{Theorem 5.2.(i)}. Since every open set is $H^*$-open, $\{x\}$ is $H^*$-closed (resp. $H^*$-closed or $H^*$-open) in $X$. This implies that $X$ is $T_1$ (resp. $T_\frac{1}{2}$) by \textbf{Theorem 5.2.(ii)}. Therefore $X$ is $H^*$-$T_1$ (resp. $H^*$-$T_\frac{1}{2}$).\\
    \textbf{(iii).} Let $X$ be a $H^*$-$T_1$ space. Then $X$ is $T_1$. By \textbf{Theorem 5.3} of Levine\cite{levine1970generalized} $X$ is $T_\frac{1}{2}$ and hence $X$ is $H^*$-$T_\frac{1}{2}$.
\end{proof}

\subsection{Proposition.}
\textbf{(i).} If $X$ is $H^*$-$T_b$ then for each $x \in X$, $\{x\}$ is $H^*$-closed or open in $X$.\\
\textbf{(ii).} If $X$ is $H^*$-$T_d$ then for each $x \in X$, $\{x\}$ is $H^*$-closed or $g$-open in $X$.

\begin{proof}
   \textbf{(i).} Suppose that, for an $x \in X$, $\{x\}$ is not $H^*$-closed. By \textbf{Theorem 5.2.(iii)} and \textbf{Remark 4.2. (i) and (ii)}, $X - \{x\}$ is $H^*g$-closed set. Therefore $X - \{x\}$ closed by using assumption and hence $\{x\}$ is open.\\
   \textbf{(ii).} Suppose that, for a $x \in X$, $\{x\}$ is not closed. By \textbf{Theorem 5.3.(ii)}, $X - \{x\}$ is $H^*g$-closed set. Therefore by using assumption $X - \{x\}$ is $g$-closed and hence $\{x\}$ is $g$-open.
\end{proof}

\section{Separation Axioms $H^*$-$T_b$ and $H^*$-$T_d$ of Spaces Are Preserved Under Homomorphisms}

\subsection{Definition.} 
A map $f : X \rightarrow Y$ is said to be:
    \begin{enumerate}
        \item \textbf{pre $H^*$-closed} if for each $H^*$-closed set of $F$ of $X$, $f(F)$ is an $H^*$ closed set in $Y$.\index{pre $H^*$-closed}
        \item \textbf{$H^*$-irresolute} if for each $H^*$-closed set $F$ of $Y$, $f^{-1}(F)$ is $H^*$-closed in $X$.\index{$H^*$-irresolute}
    \end{enumerate}

\subsection{Theorem} \textbf{(i).}  A map $f : X \rightarrow Y$ pre $H^*$-closed (resp. pre $H^*$-open) iff its induced map $f : (X, \tau^{H^*})\rightarrow (Y, \sigma^{H^*})$ is a closed (resp. open) map.\\
    \textbf{(ii).} A map $f : X \rightarrow Y$ pre is $H^*$-irresolute iff its induced map \(f : (X, \tau^{H^*})\to (Y, \sigma^{H^*})\) is continuous.


\subsection{Theorem} \textbf{(i).}  A map $f : X\rightarrow Y$ is a homomorphism, then $f$ is an $H^*$-homomorphism.\\
    \textbf{(ii).} If $X$ is $H^*$-$T_b$ (resp. $H^*$-$T_d$ and $f : X\rightarrow Y$ is a homomorphism, then $Y$ is $H^*$-$T_b$ (resp. $H^*$-$T_d$).

\begin{proof}
    \textbf{(i).} Since $f : X \rightarrow Y$ is a homomorphism, then $f$ and $f ^{-1}$ are both open and $H^*$-continuous  bijection. It follows from \textbf{Theorem 4.16} of Noiri \cite{noiri1984alphacontinuous} that $f$ and $f^{-1}$ are $H^*$-irresolute. Therefore, $f$ is $H^*$-irresolute and $f$ is pre $H^*$-closed.\\
    \textbf{(ii).} Let $f : X \rightarrow Y$ is a homomorphism and let $F$ be an $H^*g$-closed set of $Y$ Then by \textbf{a.} $f^{-1} : Y \rightarrow X$ is a continuous and pre $H^*$-closed bijection. Hence by \textbf{Theorem 6.2. (i)} $f^{-1}(F)$ is $H^*g$-closed in $X$. Since $X$ is $H^*$-$T_b$ (resp. $H^*$-$T_d$), 
$f^{-1} (F)$ is closed (resp. $g$-closed) in $X$. Since $f$ is closed onto (resp. closed and continuous) map, $F$ is closed (resp. $g$-closed) by \textbf{Theorem 6.1} of Levine\cite{levine1970generalized} in $Y$. Hence $Y$ is $H^*$-$T_b$ (resp. $H^*$-$T_d$).

\end{proof}



\section*{Conclusion}

The research in topology over last two decades has reached a high level in many directions. By researching generalizations of closed sets, some new separation axioms have been founded and they turn out to be useful in the study of digital topology. Therefore, \(SC^*\) and \(H^*\)-separation axioms are defined by using \(SC^*\) and \(H^*\)-closed sets will have many possibilities of applications in digital topology and computer graphics.



