% For any $\omega \in \Omega$, it is clear that the sequence of random vectors $\{\bX^{(k)}\}_{k \in \N}$ such that $\bX^{(k)} \sim \wF^{N}(\omega)$ satisfies Assumption \ref{ass:UI} and \ref{ass:quantile}. The results follow directly from Theorem \ref{thm:1}.
%  \end{proof}
It  the total loss $S$ is not degenerate, then the function   $\beta \mapsto \ES_\beta(S)$  is  strictly decreasing. 
By Proposition \ref{prop:consistency},  under  Assumption  \ref{ass:UI},  the empirical estimators $ \widehat{\DQES}(N) $  is strongly consistent. If $S$ is  constant, then $\wDQVaR(N)=0$ a.s. Hence,  if the portfolio $\bX$ satisfies Assumption \ref{ass:quantile} and the total loss $S$ has continuous and strictly decreasing quantile function, $\wDQVaR(N)$ is also a strongly consistent estimator.

  In the next section, we further explore the asymptotic normality of the empirical estimators for  DQs based on VaR and ES.









\section{Asymptotic normality on i.i.d. data}\label{sec:4}

We first collect the alternative formulas  for $\DQVaR$ and  $\DQES$  from Theorem 4 of \cite{HLW25}.



\begin{proposition}\label{prop:3}
 For a given $\alpha\in(0,1)$, $\mathrm{DQ}^{\mathrm{VaR}}_{\alpha}$ have the alternative formula
\begin{equation}\label{eq:DQ_VaR}\mathrm{DQ}^{\mathrm{VaR}}_{\alpha}(\textbf{X})=\frac{1}{\alpha}\mathbb{P}\left(S>\sum_{i=1}^{n}\rm{VaR}_{\alpha}(X_i)\right).\end{equation}
For a given $\alpha \in (0,1)$, if $\p(\sum_{i=1}^n  X_i>\sum_{i=1}^n \ES_\alpha(X_i) )>0$, then 
$${\rm DQ}^{\ES}_\alpha(\mathbf X)= \frac{1}{\alpha}\min_{r\in (0,\infty)} \E\left[\left(r \sum_{i=1}^n (X_i-\ES_\alpha(X_i))+1\right)_+\right],$$
and otherwise ${\rm DQ}^{\ES}_\alpha(\mathbf X)=0.$
 % For a given $\alpha \in(0,1/2)$, ${\rm DQ}^{\ex}_\alpha $   has the alternative formula \begin{equation} {\rm DQ}^{\ex}_\alpha (\mathbf X)  =\frac{1}{\alpha}\frac{\mathbb{E}\left[ (S-t) _+\right]}{\mathbb{E}\left[\left| (S-t) \right|\right]},\mbox{~where }S=\sum_{i=1}^n X_i \mbox{~and~}t=\sum_{i=1}^n \ex_\alpha(X_i).\end{equation}
\end{proposition}



Proposition \ref{prop:3} provides convenient formulas for computing the empirical estimators of $\DQVaR$ and $\DQES$.
Let $\bX^{(1)}, \dots, \bX^{(N)}$ be i.i.d. samples of $\bX=(X_1, \dots, X_n)$ where $\bX^{(k)}=(X_1^{(k)}, \dots, X_n^{(k)})$ for $k \in [N]$. For $i\in [n]$, let $\widehat x^{\VaR_\alpha}_i$ and $\widehat x^{\ES_\alpha}_i$  be the empirical estimators for $\VaR_\alpha(X_i)$ and $\ES_\alpha(X_i)$.
For a given $\alpha\in(0,1)$, the empirical estimator for $\mathrm{DQ}^{\mathrm{VaR}}_{\alpha}$ is given by 
\begin{equation}
\widehat{\DQVaR}(N)=\frac{1}{N\alpha}{\sum_{k=1}^N \id_{\{\sum_{i=1}^n X^{(k)}_i> \sum_{i=1}^n\widehat x^{\VaR_\alpha}_i\}}}.
\end{equation}
For a given $\alpha \in (0,1)$, if there exists $k \in [N]$ such that $\sum_{i=1}^n  X^{(k)}_i>\sum_{i=1}^n \widehat x^{\ES_\alpha}_i$, then  the empirical estimator for $\DQES$ is given by 
\begin{equation}
\widehat{\DQES}(N)= \frac{1}{N\alpha}\min_{r\in (0,\infty)} \sum_{k=1}^N\left[\left(r \sum_{i=1}^n (X^{(k)}_i-\widehat x^{\ES_\alpha}_i)+1\right)_+\right],\end{equation}
and otherwise ${\rm DQ}^{\ES}_\alpha(\mathbf X)=0.$
