\section{A further  discussion of DQ based on expectiles}\label{App:A}
We examine  the asymptotic normality of DQ based on expectiles.  The expectile at a given confident level $\alpha\in(0,1)$ for a loss random variable is the unique minimizer of an asymmetric quadratic loss. Mathematically, the expectile   of a loss random variable $X\in L^2$  at a confidence level $\alpha \in(0,1)$, denoted by $\ex_{\alpha}(X)$, is defined as the following minimizer:  \begin{equation}\label{eq:expectile}
\ex_{\alpha}(X)=\argmin_{x \in \mathbb{R}}   \left\{(1-\alpha) \mathbb{E}\left[(X-x)_{+}^{2}\right]+\alpha \mathbb{E}\left[(X-x)_{-}^{2}\right]\right\}
\end{equation}
where $(x)_+=\max\{0,x\}$ and  $(x)_+=\max\{0,-x\}$.
 By the first-order condition, $\ex_{\alpha}(X)$  is equal to the unique number $t$   satisfying 
\begin{equation}\label{eq:ex0} (1-\alpha) \mathbb{E}\left[(X-t)_{+}\right]=\alpha \mathbb{E}\left[(X-t)_{-}\right].
\end{equation}

The equation \eqref{eq:ex0} is well-defined for each $X \in L^1$, which serves as the natural domain for expectiles. We take \eqref{eq:ex0} as the definition of expectiles, and let $\X=L^1$ in the following context. 

Let $\bX^{(1)}, \dots, \bX^{(N)}$ be i.i.d. samples of $\bX=(X_1, \dots, X_n)$ where $\bX^{(k)}=(X_1^{(k)}, \dots, X_n^{(k)})$ for $k \in [N]$. For $i\in [n]$, let  $\widehat x^{\ex_\alpha}_i$ be the empirical estimators for  $\ex_\alpha(X_i)$.
 For a given $\alpha \in(0,1/2)$,  the empirical estimator for $\DQex$ is given by 
\begin{equation}
\widehat \DQex(N) =\frac{1}{\alpha}
\frac{\sum_{k=1}^N\left[ (S^{(k)}-t) _+\right]}{\sum_{k=1}^N\left[\left| (S^{(k)}-t) \right|\right]},\mbox{~where }S^{(k)}=\sum_{i=1}^n X^{(k)}_i \mbox{~and~}t=\sum_{i=1}^n \widehat x^{\ex_\alpha}_i.
\end{equation}
For a random variable $X\sim F$, we define  \begin{equation}\label{eq:tildeF}
 \widetilde{F}(y) = \frac{y F(y) - \int_{-\infty}^{y} x \, \d F(x)}{2 \left( y F(y) - \int_{-\infty}^{y} x \, \d F(x) \right) + \mathbb{E}[X] - y}. \end{equation}
  It is easy to check that $\widetilde F$ is a continuous distribution function that strictly increases its support. In this section, the tilde notation is used consistently in the following context, with each function following a similar transformation  as defined by \eqref{eq:tildeF}.

 Recall that $S\sim G$. Theorem 1 of \cite{HLWW24} shows that  ${\rm DQ}^{\ex}_\alpha (\mathbf X)$ can also be computed by
\begin{equation}\label{eq:DQ_ex}
\mathrm{DQ}^{\ex}_\alpha (\mathbf{X})=\frac{1-\widetilde{G}(t) }{\alpha},~~~\mathbf X\in \X^n,\end{equation}
where $t=\sum_{i=1}^n \ex_\alpha(X_i)$. Thus, \eqref{eq:DQ_ex} can be rewritten as 
$$
\DQex (\mathbf X) =\frac{1}{\alpha} \mathbb Q\left(\sum_{i=1}^{n}X_i> \sum_{i=1}^n \ex_{\alpha}(X_i)\right),~~~\mathbf X\in \X^n, 
$$
for some probability measure $\mathbb{Q}$,
which reveals  that $\mathrm{DQ}^{\ex}_\alpha(\mathbf{X})$ shares a structural similarity with $\mathrm{DQ}^{\VaR}_\alpha(\mathbf{X})$ given by \eqref{eq:DQ_VaR}.   While $\widetilde{G}$ is indeed a distribution function with a positive density function, the estimator $\widetilde{\widehat{G}^N}$, constructed from  i.i.d. samples of $X_i$ for $i=1,\dots,n$, does not serve as  an empirical distribution function for  $\widetilde{G}$. This discrepancy arises because $\widetilde{G}$ represents the distribution of a distinct random variable; hence, an empirical distribution function for $\widetilde{G}$ would need to be derived from samples of that specific variable.  Nonetheless, the following proposition establishes a result analogous to Bahadur’s representation.



\begin{lemma}
\label{lemma:ex}
Let $X^{(1)},\dots,X^{(N)}$ be an i.i.d. sample from $X\in L^1$ with $F$ as distribution function of $X$, and ${F}^N$ be the empirical distribution based on $X^{(1)},\dots,X^{(N)}$. 
Let $\widetilde{  F^N}$\footnote{We simplify the notation by using $\widetilde{  F^N}$  instead of $\widetilde{ \widehat F^N}$.}  and $\widetilde{F}$ be defined as in \eqref{eq:tildeF}, with  the positive density functions $\widetilde{f^N}$ and $\widetilde f$.
  Then as $k\to\infty$, we have
$$
\widetilde{  F^N}^{-1}(p)=\widetilde{F}^{-1}(p)+\frac{p-\widetilde{  F^N}(\widetilde{F}^{-1}(p))}{\widetilde f(\widetilde{F}^{-1}(p))}+\smallO_\p\left(\frac{1}{\sqrt{N}}\right),~~~~p\in(0,1).
$$
\end{lemma}
\begin{proof}
For $p\in(0,1)$ and $t\in \mathbb{R}$, let $\xi^N(t)=\widetilde{F}^{-1}(p)+t/\sqrt{N}$ and
$$
Z^N(t)=\frac{\sqrt{N}\left( \widetilde{F}(\xi^N(t))-\widetilde {F^N}(\xi^N(t))\right) }{\widetilde f(\widetilde{F}^{-1}(p))}, \; U^N(t)=\frac{\sqrt{N}\left( \widetilde{F}(\xi^N(t))-p\right) }{\widetilde f(\widetilde{F}^{-1}(p))}.
$$
For a fixed $t \in \R$, take $N$ large enough such that $\widetilde{F}^{-1}(p) \in (X_{[k]}, X_{[k+1]})$ for some $k \in [N]$ where $X_{[k]}$ is the $k$-th order statistics of $\{X^{(k)}\}_{k \in [N]}$ and $t/\sqrt{N}$ small enough, 
 by the  mean value theorem,  we have 
\begin{equation*}
\begin{aligned}
Z^N(t)-Z^N(0)&=\frac{\sqrt{N}\left( \widetilde{F}(\xi^N(t))-\widetilde {F^N}(\xi^N(t))-p+\widetilde {F^N}(\widetilde{F}^{-1}(p))\right) }{\widetilde f(\widetilde{F}^{-1}(p))}\\
&=\frac{\sqrt{N}\left( \left( \widetilde{f}(\widetilde{F}^{-1}(p))+\smallO_\p(1)\right) t/\sqrt{N}-\left( \widetilde{f^N}(\widetilde{F}^{-1}(p))+\smallO_\p(1)\right) t/\sqrt{N}\right) }{\widetilde f(\widetilde{F}^{-1}(p))}\\
&=t\left( 1-\frac{\widetilde {f^N}(\widetilde{F}^{-1}(p))}{\widetilde  f(\widetilde{F}^{-1}(p))}+\smallO_\p(1)\right). 
\end{aligned}
\end{equation*}
By direct calculation, we have
\begin{equation}\label{eq:wideF} \widetilde{f}(y)=\frac{F(y)\mathbb{E}[X]-\int_{-\infty}^{y}x\d F(x)}{\left( 2\left( yF(y)-\int_{-\infty}^{y}x\d F(x)\right)+\mathbb{E}[X]-y\right) ^2}. 
\end{equation}
and
 \begin{equation*} \widetilde{f^N}(y)=\frac{\wF^N(y)\displaystyle{\frac{\sum_{k=1}^N X^{(k)}}{N}}-\displaystyle{\frac{1}{N}\sum_{k=1}^N X^{(k)}\id_{\{X^{(k)} \le y\}}}}{\left( 2\left( y\wF^N(y)-\displaystyle{\frac{1}{N}\sum_{k=1}^N X^{(k)}\id_{\{X^{(k)} \le y\}}}\right)+\displaystyle{\frac{\sum_{k=1}^N X^{(k)}}{N}}-y\right) ^2}. \end{equation*}

As $N \to \infty$, we have $\wF^N(y) \to F(y)$, $\sum_{k=1}^N X^{(k)} \to \E[X]$ and $\sum_{k=1}^N X^{(k)}\id_{\{X^{(k)} \le y\}}/N \to \int_{-\infty}^{y}x\d F(x)$, $\p$- a.s. Therefore,
$$\frac{\widetilde{f^N}(\widetilde{F}^{-1}(p))}{\widetilde{f}(\widetilde{F}^{-1}(p))}\to 1, ~~\mathbb{P}\text{-a.s.}$$ 
Therefore, for a fixed $t\in\R$, $Z^N(t)-Z^N(0)=\smallO_\p(1)$. Meanwhile, by Taylor expansion, for any $t \in \R$, we have 
\begin{equation*}
U^N(t)=\frac{\sqrt{N}\left( \widetilde{F}(\xi^N(t))-p\right) }{\widetilde{f}(\widetilde{F}^{-1}(p))}
\to t, ~~~~\mbox{as}~~~ N \to \infty.
%={t}+\smallO\left(1\right).
%=\frac{\sqrt{N}\left( \left( \widetilde{f}(\widetilde{F}^{-1}(p))+\smallO(1)\right) t/\sqrt{N}\right)}{\widetilde{f}(\widetilde{F}^{-1}(p))}\to \smallO(t).
\end{equation*}
Set $\kappa^N=\sqrt{N}(\widetilde{ F^N}^{-1}(p) -\widetilde{F}^{-1}(p))$. 
We first show that $\kappa^N$ is bounded in probability.
For any $t \in \R$, we have 
\begin{align*}
\p(\kappa^N \le t)
% &=\p\left(\sqrt{N}\left(\widetilde{ F^N}^{-1}(p) -\widetilde{F}^{-1}(p)\right)\le t\right)\\
&=\p(p\le \widetilde{F^N}(\xi^N(t)))\\
% &=\p\left(p\le \frac{\xi^N(t) \frac{1}{N}\sum_{i=1}^N \id_{\{X^{(k)}\le \xi^N(t)\}} - \frac{1}{N}\sum_{k=1}^N X^{(k)}\id_{\{X^{(k)}\le \xi^N(t)\}}}{2 \left( \xi^N(t)\frac{1}{N}\sum_{i=1}^N \id_{\{X^{(k)}\le \xi^N(t)\}} - \frac{1}{N}\sum_{k=1}^N X^{(k)}\id_{\{X^{(k)}\le \xi^N(t)\}} \right) + \frac{1}{N}\sum_{k=1}^N X^{(k)} - \xi^N(t)}\right)\\
&=\p\left( \frac{1}{N}\sum_{k=1}^N\left((2p-1)\left( \xi^N(t)-X^{(k)}\right)\id_{\{X^{(k)}\le \xi^N(t)\}} +pX^{(k)} \right)- p\xi^N(t)\le  0\right)\\
&=\p\left( \frac{1}{N}\sum_{k=1}^N(1-p)\left( X^{(k)}-\xi^N(t)\right)\id_{\{X^{(k)}\le \xi^N(t)\}} +p\left( X^{(k)}-\xi^N(t)\right)\id_{\{X^{(k)}>\xi^N(t)\}}\le  0\right)\\
&\le \p\left( \frac{1}{N}\sum_{k=1}^N(1-p)\left( X^{(k)}-\xi^1(t)\right)\id_{\{X^{(k)}\le \xi^1(t)\}} +p\left( X^{(k)}-\xi^1(t)\right)\id_{\{X^{(k)}>\xi^1(t)\}}\le  0\right).
\end{align*}
By CLT, we have 
$$\frac{1}{N}\sum_{k=1}^N(1-p)\left( X^{(k)}-\xi^1(t)\right)\id_{\{X^{(k)}\le \xi^1(t)\}} +p\left( X^{(k)}-\xi^1(t)\right)\id_{\{X^{(k)}>\xi^1(t)\}} \sim \mathrm{N}(\mu(t), \sigma(t)^2)$$
with $\mu(t)=(1-p)\E\left[\left( X^{(k)}-\xi^1(t)\right)_-\right] +p\E\left[\left( X^{(k)}-\xi^1(t)\right)_+\right]$ and $\sigma(t)<\infty$. It is clear that $\mu(t) \to +\infty$ as $t \to -\infty$, which gives $\p(\kappa^N \le t)  \to 0$ as $t \to -\infty$. Similarly, we have $\p(\kappa^N > t)  \to 0$ as $t \to \infty$.
Hence, for any $\epsilon>0$, there exists a constant $t^*$ such that $\p(\vert \kappa^N\vert >t^*)\le \epsilon$ for all $N$.

Moreover,  for any $\varepsilon>0$ and $t \in \R$, we have 
$$
\mathbb{P}\left( \kappa^N\leq t,\;Z^N(0)\geq t+\varepsilon\right) =\mathbb{P}\left( Z^N(t)\leq U^N(t),\;Z^N(0)\geq t+\varepsilon\right)\to0,~~~ \mbox{as}~~~ N \to \infty.
$$
Similarly, we can get $\mathbb{P}\left( \kappa^N\geq t,\;Z^N(0)\leq t-\varepsilon\right)\to 0$. 


Let $a_i=-t^*+2ti/M$ for $i \in \{0, 1, \dots, M\}$. Then,  
\begin{align*}
\p\left(\vert \kappa^N-Z^N(0)\vert >\epsilon\right)&\le \p\left(\vert\kappa^N\vert>t^*\right)+\p\left(\vert \kappa^N\vert \le M,\vert \kappa^N-Z^N(0)\vert >\epsilon \right)\\
&\le \epsilon+\sum_{i=1}^M \p\left(a_{i-1}\le \kappa^N\le a_i, \vert \kappa^N-Z^N(0)\vert >\epsilon \right)\\
&\le \epsilon+\sum_{i=1}^M \p\left( \kappa^N\le a_i, Z^N(0)\ge a_i+\epsilon/2 \right)+\p\left( \kappa^N\ge a_{i-1}, Z^N(0)\le a_{i-1}-\epsilon/2 \right).
\end{align*}
This implies that  $\kappa^N-Z^N(0)= \smallO_\p(1)$, i.e.,  $$
\widetilde{  F^N}^{-1}(p)=\widetilde{F}^{-1}(p)+\frac{p-\widetilde{ F^N}(\widetilde{F}^{-1}(p))}{\widetilde{f}(\widetilde{F}^{-1}(p))}+\smallO_\p\left(\frac{1}{\sqrt{N}}\right),~~~~p\in(0,1),
$$ 
which completes the proof. 
\end{proof}




The following theorem characterizes the asymptotic normality of $\DQex$. 
\begin{theorem}\label{thm:6}
Let $\alpha \in (0,1/2)$ and $\bX^{(1)}, \bX^{(2)}, \dots$ are i.i.d. samples of $\bX=(X_1, \dots, X_n) \in \X^n$. Let $t=\sum_{i=1}^n \ex_\alpha(X_i)$, $\theta_1=\E[(S-t)_+]$ and $\theta_2=\E[\vert S-t\vert ]$ where $S=\sum_{i=1}^n X_i$.  Let $y_i=\widetilde{F}_i^{-1}(1-\alpha)$, $\mu_i=\mathbb{E}[X_i]$ and $\mu_i^{-}=\mathbb{E}[(X_i-y_i)_{-}]$ for $i\in[n]$. As $N \to \infty$, we have 
$$\sqrt{N} \left(\wDQex(N)-\DQex(\bX)\right) \lawto \mathrm{N}(0, \sigma^2_{\ex})$$
with  $ \sigma^2_\ex= \mathbf A^\top_\ex \Sigma_\ex\mathbf A_\ex$, where $\mathbf A_{\ex}=  \nabla h(\mathbf{v})\nabla g(\boldsymbol{\theta})^\top,$ and $\Sigma_\ex$ is the covariance matrix of random vector 
$$\left((S-t)_+, |S-t|, (y_1-X_1)\mathbb{I}_{\{X_1\leq y_1\}}, X_1,  \dots, (y_n-X_n)\mathbb{I}_{\{X_n\leq y_n\}}, X_n\right)^\top.$$ 
 Further, $\nabla h(\mathbf{v})$ is given by $$
\nabla h(\mathbf{v})^\top = 
\begin{pmatrix}
1 & 0 & \dfrac{1 - G(t)}{\widetilde{f}_1(y_1)} \cdot \dfrac{D_1 - 2\mu_1^-}{D_1^2} & \dfrac{1 - G(t)}{\widetilde{f}_1(y_1)} \cdot \dfrac{-\mu_1^-}{D_1^2} & \cdots & \dfrac{1 - G(t)}{\widetilde{f}_n(y_n)} \cdot \dfrac{D_n - 2\mu_n^-}{D_n^2} & \dfrac{1 - G(t)}{\widetilde{f}_n(y_n)} \cdot \dfrac{-\mu_n^-}{D_n^2} \\
0 & 1 & \dfrac{1 - 2G(t)}{\widetilde{f}_1(y_1)} \cdot \dfrac{D_1 - 2\mu_1^-}{D_1^2} & \dfrac{1 - 2G(t)}{\widetilde{f}_1(y_1)} \cdot \dfrac{-\mu_1^-}{D_1^2} & \cdots & \dfrac{1 - 2G(t)}{\widetilde{f}_n(y_n)} \cdot \dfrac{D_n - 2\mu_n^-}{D_n^2} & \dfrac{1 - 2G(t)}{\widetilde{f}_n(y_n)} \cdot \dfrac{-\mu_n^-}{D_n^2}
\end{pmatrix}$$ with $
D_i = 2\mu_i^- + \mu_i - y_i, (i = 1, \dots, n)
,$  and  $ \nabla g(\boldsymbol{\theta})=\left(1 / (\alpha\theta_2),-\theta_1 /\left(\alpha\theta^2_2\right)\right).$ 
\end{theorem}
\begin{proof}
 By Theorem 1 of  \cite{HLWW24}, we have 
\begin{equation*}\label{eq:ex}
\DQex(\bX) =\frac{1}{\alpha}
\frac{\mathbb{E}\left[ (S-t) _+\right]}{\mathbb{E}\left[\left| S-t \right|\right]}.
\end{equation*}

Let $t^N=\sum_{i=1}^n \widehat{ \ex_{i,\alpha}}(N)$ where $\widehat {\ex_{i,\alpha}}(N)$ is the empirical estimator of $\ex_\alpha(X_i)$ for $i \in [n]$. Let $\theta^N_1=\sum_{k=1}^N (S^{(k)}-t^N)_+/N$ and $\theta^N_2=\sum_{k=1}^N \vert S^{(k)}-t^N\vert/N$.
%By \eqref{eq:ex}, we have  $\alpha^N =\theta_1/\theta_2$.

For $\theta_1^N$, we have 
\begin{equation}\label{eq:theta1}
   \theta_1^N-\theta_1=\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t^N)_+-\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t)_++\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t)_+-\theta_1.
\end{equation}
Moreover,
\begin{equation}\label{theta1}
   \begin{aligned}
    \frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t^N)_+-\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t)_+&=\int_{-\infty}^{\infty}(x-t^N)_+\d \widehat G^N(x)-\int_\infty^{\infty}(x-t)_+\d \widehat G^N(x)\\
&=\int_{t^N}^{\infty}(x-t^N)\d \widehat G^N(x)-\int_t^{\infty}(x-t)\d \widehat G^N(x)\\
    &=\int_{t^N}^t(x-t^N)\d \widehat G^N(x) +\int_t^{\infty}(t-t^N)\d \widehat G^N(x)\\
    &=\int_{t^N}^t(x-t^N)\d  \widehat G^N(x)+(t-t^N)(1-\widehat G^N(t)).
\end{aligned} 
\end{equation}
Notice that
$$\int_{t^N}^t(x-t^N)\d \widehat G^N(x)\leq |(t-t^N)(\widehat G^N(t)-\widehat G^N(t^N))|=\smallO_\p(N^{-\frac{1}{2}}).$$
So \eqref{theta1} can be written into 
\begin{equation}
  \frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t^N)_+-\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t)_+=(t-t^N)(1-G(t))+\smallO_\p(N^{-\frac{1}{2}}). 
\end{equation}
Then we have
\begin{equation}
    \theta_1^N-\theta_1=\frac{1}{N}\sum_{k=1}^{N}(S^{(k)}-t)_+-\theta_1+(t-t^N)(1-G(t))+\smallO_\p(N^{-\frac{1}{2}}). 
\end{equation}
Similarly, for $\theta_2$ we can get
\begin{equation*}
    \theta_2^N-\theta_2=\frac{1}{N}\sum_{k=1}^{N}|S^{(k)}-t|-\theta_2+(t-t^N)(1-2G(t))+\smallO_\p(N^{-\frac{1}{2}}).
\end{equation*}
By Lemma \ref{lemma:ex}, we obtain
\begin{equation}\label{eq:tN}
\begin{aligned}
    t-t^N&=\sum_{i=1}^{n}\left(\widetilde{F}_i^{-1}(1-\alpha)-\widetilde{F_i^N}^{-1}(1-\alpha)\right)\\
&=\sum_{i=1}^n\frac{\widetilde{F^N_i}(\widetilde{F}_i^{-1}(1-\alpha))-(1-\alpha)}{\widetilde{f}_i(\widetilde{F}_i^{-1}(1-\alpha))}+\smallO_\p(N^{-\frac{1}{2}}).
\end{aligned}
\end{equation}
For simplicity, we denote $y_i=\widetilde{F}_i^{-1}(1-\alpha)$. With this notation, together with \eqref{eq:tildeF}, we have 
\begin{equation}\label{FiN}
    \begin{aligned}  \widetilde{F_i^N}(y_i)&=\frac{y_i F^N_i(y_i)-\int_{-\infty}^{y_i}x\d F^N_i(x)}{2\(y_i F^N_i(y_i)-\int_{-\infty}^{y_i}x\d \widehat{F}_i(x)\)+\widehat{x}^N_i-y_i}\\
 &=\frac{\frac{1}{N}\sum_{k=1}^N(y_i-X_i^{(k)})\mathbb{I}_{\{X_i^{(k)}\leq y_i\}}}{2\(\frac{1}{N}\sum_{k=1}^N(y_i-X_i^{(k)})\mathbb{I}_{\{X_i^{(k)}\leq y_i\}}\)+\frac{1}{N}\sum_{k=1}^{N}X_i^{(k)}-y_i},
    \end{aligned}
\end{equation}
where $\widehat x_i^N$ is the empirical estimators of $\E[X_i].$ Substituting \eqref{FiN} back into \eqref{eq:tN}, 
\begin{equation}
    t-t^N=\sum_{k=1}^N\frac{1}{\widetilde{f}_i(y_i)}\frac{\frac{1}{N}\sum_{k=1}^N(y_i-X_i^{(k)})\mathbb{I}_{\{X_i^{(k)}\leq y_i\}}}{2\(\frac{1}{N}\sum_{k=1}^N(y_i-X_i^{(k)})\mathbb{I}_{\{X_i^{(k)}\leq y_i\}}\)+\frac{1}{N}\sum_{k=1}^{N}X_i^{(k)}-y_i}-\frac{1-\alpha}{\widetilde{f}_i(y_i)}+\smallO_\p(N^{-\frac{1}{2}}).
\end{equation}

Define the function $h:\mathbb{R}^{2n+2}\to\mathbb{R}^2$ by
\[
  h(\mathbf{x}):=(h_1(\mathbf{x}),h_2(\mathbf{x}))=
  \begin{pmatrix}

      x_1+\left(1-G(t)\right)\displaystyle\sum_{i=1}^n\frac{1}{\widetilde{f}_i(y_i)}\frac{x_{2i+1}}{2x_{2i+1}+x_{2i+2}-y_i}\\ x_2+(1-2G(t))\displaystyle\sum_{i=1}^n\frac{1}{\widetilde{f}_i(y_i)}\frac{x_{2i+1}}{2x_{2i+1}+x_{2i+2}-y_i},
  \end{pmatrix}
\]
where $\mathbf{x}=(x_1, x_2, \dots, x_{2n+2})$. 
Let $\mu_i=\mathbb{E}[X_i]$ and $\mu_i^{-}=\mathbb{E}(X_i-y_i)_{-}$.    Define $\mathbf V\in\mathbb{R}^{2n+2}$  as 
\begin{equation*}
    \mathbf{V}=\left((S-t)_+, |S-t|, (y_1-X_1)\mathbb{I}_{\{X_1\leq y_1\}}, X_1,  \dots,(y_n-X_n)\mathbb{I}_{\{X_n\leq y_n\}}, X_n\right)^\top.
\end{equation*}
Suppose $\mathbf {V}^{(1)}$, $\mathbf {V}^{(2)},...$ are i.i.d. samples of $\mathbf V$, and let $\overline{\mathbf V}^N= \sum_{i=1}^N{\mathbf V}^{(k)}/N$. By multivariate central limit theorem, $\sqrt{N}\overline{V}^N\stackrel{d}{\longrightarrow}\mathrm{N}(\mathbf v, \Sigma_{\ex})$, where $\mathbf v=(\theta_1, \theta_2, \mu_1^-,\mu_1,\dots, \mu_n^-,\mu_n)^\top$, and $\Sigma_\ex$ is covariance matrix of $\mathbf{V}$.
 By Delta method, we have
\begin{equation}
    \sqrt{N}(\theta_1^N-\theta_1, \theta_2^N-\theta_2)^\top=\sqrt{N}(h(\overline{
\mathbf V}^N)-h(\mathbf v))+\smallO_\p(1)\stackrel{d}{\to}\mathrm{N}(0, \mathbf \nabla h(\mathbf{v}) ^\top\Sigma_\ex \nabla h(\mathbf{v})  )).
\end{equation}




Take $g\left(x_1, x_2\right)={x_1}/{ \alpha x_2}$, then we have   
 $ \nabla g(\boldsymbol{\theta} )=\left(1 /  \alpha \theta_2,-\theta_1 /\left( \alpha\theta^2_2\right)\right)$ with $\boldsymbol{\theta}=(\theta_1,\theta_2)$.   
 Note that 
\begin{equation}
\begin{aligned}
    &g\left(h(\overline{
\mathbf V}^N)-h(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})\right)%\\&=\frac{1{\alpha}\frac{h_1(\overline{\mathbf V}^N)-h_1(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})}{h_2(\overline{\mathbf V}^N)-h_2(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})}
\\
    &=\frac{1}{\alpha}\frac{h_1(\overline{ \mathbf V}^N)-h_1(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})}{h_2(\overline{ \mathbf V}^N)-h_2(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})}-\frac{1}{\alpha}\frac{h_1(\overline{ \mathbf V}^N)-h_1(\mathbf v)}{h_2(\overline{ \mathbf V}^N)-h_2(\mathbf v)}+\frac{1}{\alpha}\frac{h_1(\overline{ \mathbf V}^N)-h_1(\mathbf v)}{h_2(\overline{ \mathbf V}^N)-h_2(\mathbf v)}\\
    &=\frac{1}{\alpha}\frac{\left(h_2(\overline{
\mathbf V}^N)-h_2(\mathbf v)-h_1(\overline{
\mathbf V}^N)+h_1(\mathbf v)\right)\smallO_\p(\frac{1}{\sqrt{N}})}{\left(h_2(\overline{
\mathbf V}^N)-h_2(\mathbf v)+\smallO_\p(\frac{1}{\sqrt{N}})\right)(h_2(\overline{
\mathbf V}^N)-h_2(\mathbf v))}+\frac{1}{\alpha}\frac{h_1(\overline{
\mathbf V}^N)-h_1(\mathbf v)}{h_2(\overline{
\mathbf V}^N)-h_2(\mathbf v)}\\
    &=\frac{1}{\alpha}\frac{h_1(\overline{
\mathbf V}^N)-h_1(\mathbf v)}{h_2(\overline{
\mathbf V}^N)-h_2(\mathbf v)}+\smallO_\p(\frac{1}{\sqrt{N}}).
\end{aligned}    
\end{equation}
  Therefore, we have $\sqrt{N}\left(g(\mathbf{\theta}^N)-g(\mathbf{\theta})\right)=\sqrt{N}\left(g(h(\overline{
\mathbf V}^N)-h(\mathbf v))\right)+\smallO_\p(1)$.  Define  $\mathbf A_{\ex}=  \nabla h(\mathbf{v})\nabla g(\mathbf \theta) $.  Using the  Delta method again,  we have 
\begin{equation*}
    \sqrt{N}(\widehat{\mathrm{DQ}^{\ex}_{\alpha}}(N)-\DQex(\mathbf{X}))=\frac{\sqrt{N}}{\alpha }\left(\frac{\theta_1^N}{\theta_2^N}-\frac{\theta_1}{\theta_2}\right)\stackrel{d}{\to}\mathrm{N}(0,\sigma^2_\ex),
\end{equation*}
where $ \sigma^2_\ex= \mathbf A^\top_\ex \Sigma_\ex\mathbf A_\ex$. 
\end{proof}

