\begin{proof}[Proof of Proposition \ref{prop:1}]
The proof is straightforward for the fact that $X_i \laweq Y_i$, $i\in [n]$ and $\sum_{i=1}^n X_i \laweq \sum_{i=1}^n Y_i$ for any $\mathbf X=(X_1, \dots, X_n), \mathbf Y=(Y_1, \dots, Y_n) \in \X^n$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:1}]
Let $\bX=(X_1, \dots, X_n)$ and  $\bX^{(k)}=(X^{(k)}_1, \dots, X^{(k)}_n)$ for $k \in \N$.
Define the function $h: I \to \R$ and $h^k: I \to \R$ for every $k \in \N$  as 
 $$h(\beta)=\rho_{\beta}\left(\sum_{i=1}^n X_i\right)-\sum_{i=1}^{n}\rho_{\alpha}(X_i)~~~\mbox{and} ~~~h^k(\beta)=\rho_{\beta}\left(\sum_{i=1}^n X^{(k)}_i\right)-\sum_{i=1}^{n}\rho_{\alpha}(X^{(k)}_i),~~~\beta\in I.$$ 
Since $\bX^{(k)} \lawto \bX$, we have $X^{(k)}_i \lawto X_i$ for all $i\in [n]$ and $\sum_{i=1}^n X^{(k)}_i \lawto \sum_{i=1}^n X_i$.
If (a) or (b) holds, we have $\rho_\alpha(X^{(k)}_i) \to \rho_\alpha(X_i)$ for all $i\in [n]$ and $\rho_\beta(\sum_{i=1}^n X^{(k)}_i) \to \rho_\beta(\sum_{i=1}^n X_i)$  for all $\beta \in I$ as $k \to \infty$. Hence, $h^k(\beta) \to h(\beta)$ as $k \to \infty$ for all $\beta \in I$.
 Moreover, it is clear that $h$ and $h^k$, $k \in \N$, are decreasing functions. %Since $\mathbf X^{(k)} \lawto \mathbf X$, we have $X_i^{(k)} \lawto X_i$ for every $i\in [n]$ and $\sum_{i=1}^n X^{(k)}_i\lawto \sum_{i=1}^n X_i$. 
%Hence, for any  $\beta \in I$, we have $h^k(\beta) \to h(\beta)$ as $k \to \infty$. 

 If $\DQrho(\bX)=0$ or $\widetilde \alpha=\sup I$, the conclusion holds trivially. Without loss of generality, we assume that $\DQrho(\bX)>0$ and $\widetilde \alpha<\sup I$.
For a given  $\beta< \alpha^*=\inf\{\beta \in I: h(\beta)\le 0\}$, it is clear that $h(\beta)>0$. Hence, there exists $K_\beta$ such that $h^k(\beta)>0$ for all $k>K_\beta$. Since $h^k$, $k \in \N$,  are  decreasing functions, we have $\alpha^k=\inf\{\beta \in I: h^k(\beta)\le 0\}\ge \beta$ for all $k >K_\beta$, which implies $\liminf \alpha^k\ge \alpha^*$. By Definition \ref{def:DQ}, we have $\liminf_{k\to\infty}\DQrho(\mathbf X^{(k)})\ge \DQrho(\mathbf X)$.


For a given  $\beta> \widetilde\alpha=\sup\{\beta \in I: h(\beta)\ge 0\}$, we have  $h(\beta)<0$. Hence, there exists $K_\beta$ such that $h^k(\beta)<0$ for all $k>K_\beta$. Therefore, $\widetilde\alpha^k=\sup\{\beta \in I: h^k(\beta)\ge 0\}\le \beta$, which implies $\limsup_{k \to \infty} \widetilde\alpha^k\le \widetilde\alpha$. Since $\alpha^k \le \widetilde \alpha^k$, by Definition \ref{def:DQ}, we have $\limsup_{k\to\infty}\DQrho(\bX^{(k)})\le {\widetilde{\alpha}
}/{\alpha}$.

Next, assume $\rho_\beta(\sum_{i=1}^n X_i)$ is a strictly decreasing function.
In this case, we have $\alpha^*=\widetilde \alpha$. Therefore,
$$\frac{\alpha^*}{\alpha}=\liminf_{k\to\infty}\DQrho(\mathbf X^{(k)})\le  \limsup_{k\to\infty}\DQrho(\mathbf X^{(k)}) \le \frac{\widetilde\alpha}{\alpha},$$
which gives $\liminf_{k\to\infty}\DQrho(\bX^{(k)})=  \limsup_{k\to\infty}\DQrho(\bX^{(k)})=\DQrho(\bX)$.
\end{proof}

\subsection{Proofs in Section \ref{sec:4}}\label{app:2}


To show the asymptotical normality,  we first present two lemmas that will be helpful in the discussion of asymptotic distribution for DQ's empirical estimators.
A Gaussian process $\{B(t); t \in [0,1]\}$ is called Brownian bridge if $\E[B(t)]=0$ for all $t \in [0,1]$ and $\E[B(t_1)B(t_2)]=t_1 \wedge t_2- t_1t_2$ for any $t_1, t_2 \in [0,1]$.
\begin{lemma}[Theorem 3.1.1 in \citet{CM83}]\label{lem:1}
Let $U_1, U_2, \dots$ be a sequence of independently uniformly distributed random variables on $[0,1]$. For $N \in \mathbb N$ and $y \in \R$, let $E^N(y)=\sum_{k=1}^N\mathbb{I}_{\{U_k\leq y\}}/N$ and $\delta^N(y)=\sqrt{N}(E^N(y)-y)$.
There exists a probability space on which one can define a Brownian bridge $\{B^N(y); 0\le y\le 1\}$ for each $N$ such that 
$$
\sup_{0\le y \le 1}\vert \delta^N(y)-B^N(y)\vert =  \O(N^{-1/2}\log N)~~~ \mbox{a.s.}
$$   
\end{lemma}
%Next, we present a lemma from \citet[Chapter 2.5.1]{SRJ09}.
\begin{lemma}[\cite{G71}]\label{lem:Bahadur}
Let $\alpha \in (0,1)$. Suppose $F'(F^{-1}(\alpha))=f(F^{-1}(\alpha))>0$. For empirical distribution $\wF^N$ built from i.i.d. samples, we have 
$$(\wF^N)^{-1}(\alpha)=F^{-1}(\alpha)+\frac{\alpha-\wF^N(F^{-1}(\alpha))}{f(F^{-1}(\alpha))}+\smallO_\p(N^{-1/2}).$$
\end{lemma}




