\begin{proof}[Proof of Theorem \ref{thm:3}]
Assumption \ref{ass:unique} implies that $\alpha^*$ satisfies
\begin{equation}\label{eq:1}
\frac{1}{\alpha^*}\int_{1-\alpha^*}^1 G^{-1}(p) \d p=\sum_{i=1}^n \frac{1}{\alpha}\int_{1-\alpha}^1 F_i^{-1}(p)\d p.
\end{equation}
 Let $\alpha^N=\alpha\wDQES(N)$.  For the empirical version, we have
\begin{equation}\label{eq:2}
\frac{1}{\alpha^N}\int_{1-\alpha^N}^1 (\wG^N)^{-1}(p)\d p=\sum_{i=1}^n \frac{1}{\alpha}\int_{1-\alpha}^1 (\wF^N_i)^{-1}(p)\d p.
\end{equation}
Combine \eqref{eq:1} and \eqref{eq:2}, we get
\begin{align*}
%&=\frac{1}{\alpha^N}\int_{1-\alpha^N}^1 (\wG^N)^{-1}(p)\d p-\sum_{i=1}^n \frac{1}{\alpha}\int_{1-\alpha}^1 (\wF^N_i)^{-1}(p)\d p\\
0&=\underbrace{\frac{1}{\alpha^N}\int_{1-\alpha^N}^{1} (\wG^N)^{-1}(p)\d p-\frac{1}{\alpha^*}\int_{1-\alpha^*}^{1} (\wG^N)^{-1}(p)\d p}_{I_1}+\underbrace{\frac{1}{\alpha^*}\int_{1-\alpha^*}^{1} (\wG^N)^{-1}(p)\d p-\int_{1-\alpha^*}^1 G^{-1}(p) \d p}_{I_2}\\
&~~~-\underbrace{\left(\sum_{i=1}^n \frac{1}{\alpha}\int_{1-\alpha}^1  (\wF^N_i)^{-1}(p)\d p-\sum_{i=1}^n \frac{1}{\alpha}\int_{1-\alpha}^1 F_i^{-1}(p)\d p\right)}_{I_3}.
\end{align*}
For $I_1$,  the mean value theorem gives
$$
I_1=(\alpha^N-\alpha^*)\frac{ \widetilde{\alpha}^N{(\wG^N})^{-1}(1-\widetilde{\alpha}^N)-\int^{1}_{1-\widetilde{\alpha}^N}({\wG^N})^{-1}(p)\d p}{(\widetilde{\alpha}^N)^2},
$$
for some $\widetilde{\alpha}^N$  lies between $\alpha^*$ and $\alpha^N$. 
Since $S$ has a positive density function in Assumption \ref{ass:DQES}, $\beta \mapsto \ES_\beta(S)$ is a strictly decreasing function. 
By Proposition \ref{prop:consistency}, $\alpha^N$ is a strong consistent estimator of $\alpha^*$; that is $\alpha^N \to \alpha^*$ a.s. 
With the regularity and continuity conditions in Assumption \ref{ass:DQES}, we obtain
$$
\frac{ \widetilde{\alpha}^N{(\wG^N})^{-1}(1-\widetilde{\alpha}^N)-\int^{1}_{1-\widetilde{\alpha}^N}({\wG^N})^{-1}(p)\d p}{(\widetilde{\alpha}^N)^2}=\frac{ \alpha^*G^{-1}(1-\alpha^*)-\int^{1}_{1-\alpha^*}G^{-1}(p)\d p}{(\alpha^*)^2}+\smallO_\p(1).
$$

Let $S^{(k)}=\sum_{i=1}^n X^{(k)}_i$ for $k \in \N$. For $I_2$, by Lemma \ref{lem:Bahadur}, we have
\begin{equation}\label{eq:I_2_ES}\begin{aligned}
I_2&= \frac{1}{\alpha^*}\int_{1-\alpha^*}^{1} \left( (\wG^N)^{-1}(p)-G^{-1}(p)\right) \d p\\
&=\frac{1}{\alpha^*}\int_{1-\alpha^*}^{1} \frac{G(G^{-1}(p))-\wG^N(G^{-1}(p))}{g(G^{-1}(p))}\d p+\smallO_\p(1)\\
&=\frac{1}{\alpha^*}\int_{s}^{\infty} \left(G(x)-\wG^N(x)\right)\d x+\smallO_\p(1)\\
&=\frac{1}{\alpha^*}\left(\int_{s}^{\infty} \frac{1}{N}\sum_{k=1}^N\id_{\{S^{(k)}>x\}}\d x-\int_{s}^{\infty} 1-G(x)\d x\right)+\smallO_\p(1)\\
&=\frac{1}{\alpha^* N}\sum_{k=1}^N\id_{\{S^{(k)}>s\}} \int_{s}^{S^{(k)}} 1\d x -\frac{1}{\alpha^*}\int_{s}^{\infty} 1-G(x)\d x+\smallO_\p(1)\\
&=\frac{1}{\alpha^* N}\sum_{k=1}^N(S^{(k)}-s)_+-\frac{1}{\alpha^*}\E[(S-s)_+]+\smallO_\p(1).
\end{aligned}\end{equation}
Similarly, for $I_3$, we have 
\begin{align}\label{eq:I_3_ES}
I_3= \frac{1}{\alpha}\sum_{i=1}^n\int_{1-\alpha}^1 \left((\wF^N_i)^{-1}(p)-F_i^{-1}(p)\right)\d p=\frac{1}{\alpha N}\sum_{k=1}^N\sum_{i=1}^n (X_i^{(k)}-t_i)_+-\frac{1}{\alpha}\sum_{i=1}^n\E[(X_i-t_i)_+]+\smallO_\p(1).
\end{align}
Let $Z^{(k)}=(S^{(k)}-s)_+/\alpha^*-\sum_{i=1}^n(X_i^{(k)}-t_i)_+/\alpha$ for $k \in \N$. It is clear that $Z^{(1)}, Z^{(2)}, \dots$ are i.i.d. with expected value 
$$\mu=\E[Z^{(k)}]=\frac{1}{\alpha^*}\E[(S-s)_+]-\frac{1}{\alpha}\sum_{i=1}^n\E[(X_i-t_i)_+],$$ 
and variance $\sigma^2:=\var(Z^{(k)})$. 
Define $\mathbf{A}_\ES \in \R^{n+1}$  by $\mathbf{A}_\ES=(1/\alpha, \dots, 1/\alpha, -1/\alpha^*)$ and a sequence of random vectors $\mathbf Y^{(k)}=( (X^{(k)}_1-t_1)_+, \dots, (X^{(k)}_n-t_n)_+, (S^{(k)}-s)_+)$ for $k \in \N$. It is clear that $Z^{(k)}=-\mathbf A^{\top} \mathbf Y^{(k)}$. Let $\Sigma_\ES$ 
be the covariance matrix of the random vector $\mathbf Y=( (X_1-t_1)_+, \dots, (X_n-t_n)_+, (S-s)_+)$. We have $\sigma^2=\mathbf A_\ES^\top \Sigma_\ES \mathbf A_\ES< \infty$ by the regularity condition in Assumption \ref{ass:DQES}.
Let $\bar Z=\sum_{k=1}^N Z^{(k)}/N$. By
 central limit theorem, we have 
\begin{align*}
\sqrt{N}(I_2-I_3)=\sqrt{N}(\bar Z-\mu)+\smallO_\p(1)\lawto \mathrm{N}(0, \sigma^2).
\end{align*}
Let $$c:=\frac{ \alpha^*s-\int^{1}_{1-\alpha^*}G^{-1}(p)\d p}{(\alpha^*)^2/\alpha}=\frac{\VaR_{\alpha^*}(S)-\ES_{\alpha^*}(S)}{\DQES(\bX)}.$$ Positive density of $G$ in Assumption \ref{ass:DQES} further implies $c<0$. Moreover, we have $I_1=c(\alpha^N-\alpha^*)/\alpha+\smallO_\p(1)$.
Combine the fact $I_1+I_2-I_3=0$, we have 
\begin{align*}
\sqrt{N}(\wDQES(N) -\DQES(\bX))=\frac{I_1}{c}+\smallO_\p(1)=\frac{\sqrt{N}(I_3-I_2)}{c} \lawto \mathrm{N}\left(0, \frac{\sigma^2}{c^2}\right),
\end{align*}
which completes the proof. 
\end{proof}


