  We follow the proof of  Proposition \ref{prop:3} to decompose 
$\wDQVaR(N)-\mathrm{DQ}^{\VaR}_{\alpha}(\mathbf{X})$ into 
$I_1+I_2$. For  $I_1$, using Lemma \ref{lem:emp-alpha}, we still have
\begin{align*}
 \sup_{y\in \mathbb{R}}|\gamma^N(y)-B^N(G(y))|=\smallO_\p(1),
\end{align*}
where $B^N$ is a standard Brownian bridge for each $N \in \N$. Since Assumption \ref{ass:DQVaR-alpha} is stronger than Assumption \ref{ass:DQVaR},  using the same argument in the  proof of  Proposition \ref{prop:3}, we can express $I_1$ as 
\begin{equation}\label{eq:I_1}
\sqrt{N}I_1=\sqrt{N}\left(  \wG^N\left( t_{n+1}\right)-G\left( t_{n+1}\right) \right)+\smallO_\p(1).
\end{equation}

For  $I_2$,  by  Lemma \ref{lem:quan-alpha} and  the mean value theorem, we have  
\begin{equation}\label{eq:I_2}
\sqrt{N}I_2=    \mathbf H^\top\mathbf M^N+\smallO_\p(1).
\end{equation}
where 
 $$\mathbf H=\left(\frac{g(t_{n+1})}{f_1(t_1)}, \dots, \frac{g(t_{n+1})}{f_n(t_n)}\right) ~~~\mbox{and}~~~{\mathbf M}^N=\sqrt{N}\left(F_1(t_1)-{\wF}^{N}_1(t_1),\dots,F_n(t_n))-{\wF}^{N}_n(t_n)\right) .
$$



For $k \ge 1$,  let  $\mathbf Z^\k=(Z^\k_1, \dots, Z^\k_{n+1})$ where $Z^\k_i=F_i(t_i)-\mathbb{I}_{\{X^\k_i\leq t_i\}}$ for $i\in [n]$ and $Z^\k_{n+1}=G(t_{n+1})-\mathbb{I}_{\{\sum_{i=1}^n X^\k_i\leq t_{n+1}\}}$. 
Combining with \eqref{eq:I_1} and \eqref{eq:I_2}, we have
$$\sqrt{N}\left(\wDQVaR(N)-\mathrm{DQ}^{\VaR}_\alpha(\mathbf X)\right)=\sqrt{N}\frac{I_1+I_2}{\alpha}=\frac{\sum_{k=1}^N\mathbf A_\VaR^\top{\mathbf Z}^{(k)}}{\sqrt{N}}+\smallO_\p(1),$$ where $\mathbf A_\VaR=\left(\mathbf H/\alpha, -1/\alpha\right)$.
It is clear that $\{\mathbf A_{\VaR}^\top\mathbf Z^\k\}_{k \ge 1}$ is an stationary $\alpha$-mixing sequence with $\E[\mathbf A_{\VaR}^\top\mathbf Z^\k]=0$.  By Assumption \ref{ass:alpha},  $\alpha(\mathbf A_{\VaR}^\top\mathbf Z^\k,m)\le \alpha(\{\mathbf X^{(k)}\}_{k \ge 1})=\O(m^{-5-\epsilon})$. Hence, for $\delta>1/2$, we have $\sum_{m \ge 1} (\alpha(m))^{\delta/(2+\delta)}< \infty$. By Assumption \ref{ass:DQVaR-alpha}, $\{\mathbf A_{\VaR}^\top\mathbf Z^\k\}$ is bounded for all $k \ge 1$; hence, $\E[\vert \mathbf A_{\VaR}^\top\mathbf Z^\k\vert ^{2+\delta}]< \infty$. Therefore, 
$\{\mathbf A_{\VaR}^\top\mathbf Z^\k\}_{k \ge 1}$ satisfies conditions in Lemma  \ref{lem:CLT-alpha}. Hence, by Lemma \ref{lem:CLT-alpha}, we have 
$$\sqrt{N}\left(\wDQVaR(N)-\mathrm{DQ}^{\VaR}_\alpha(\mathbf X)\right)\lawto {\rm N}(0,\sigma_\VaR^2),$$
where 
\begin{align*}
\sigma^2_\VaR&=\var(\mathbf A_{\VaR}^\top\mathbf Z^{(1)})+2\sum_{k=2}^\infty \cov(\mathbf A_{\VaR}^\top\mathbf Z^{(1)}, \mathbf A_{\VaR}^\top\mathbf Z^\k)\\
&=\mathbf A_{\VaR}^\top\left(\var(\mathbf Z^{(1)})+2\sum_{k=2}^\infty\cov(\mathbf Z^{(1)},\mathbf Z^\k)\right) \mathbf A_{\VaR}\\
&=\mathbf A_{\VaR}^\top\left(\var(\mathbf I^{(1)})+2\sum_{k=2}^\infty\cov(\mathbf I^{(1)},\mathbf I^\k)\right) \mathbf A_{\VaR}\\
\end{align*}
with $\mathbf I^{(k)}=(\id_{\{X_1^{(k)}\le t_1\}}, \dots, \id_{\{X_n^{(k)}\le t_n\}})$. Hence, we have  $\sigma_\VaR=\mathbf A_{\VaR}^\top\Sigma^\alpha_\VaR\mathbf A_{\VaR}$ with $\Sigma^\alpha_{\VaR}=\var(\mathbf I^{(1)})+2\sum_{k=2}^\infty\cov(\mathbf I^{(1)},\mathbf I^\k)$.
\end{proof}

