\begin{example}
    \label{ex:cai_censor}
    Consider the setup in \cref{ex:cai} but with censoring caused by naming up to four friends.
    As illustrated in \cref{fig:sub_triangle_censor}, suppose that the sampled network link between $i_1$ and $i_2$ is not observed due to the censoring. Then, $i_2$ is misclassified as a second neighborhood friend in the observed network while one is a first neighborhood friend in the population network.
    Thus, if we consider the true exposure mapping $T_{n,i}$ as in \cref{eq:triangle}, and misspecified exposure mapping for the sampled network
    \begin{align*}
        \tilde{T}_{n,i}=&\left(R_{n,i}D^*_{n,i},
        \frac{\sum_{j\neq i}C_{n,i,j}\tilde{A}_{n,i,j}R_{n,j}D^*_{n,j}}{\sum_{j\neq i}C_{n,i,j}\tilde{A}_{n,i,j}},\right.\\
        &\left.\qquad
        \frac{\sum_{j\neq i}\sum_{k\neq i,j}C_{n,i,j}\tilde{A}_{n,i,j}C_{n,j,k}\tilde{A}_{n,j,k}(1-C_{n,i,k}\tilde{A}_{n,i,k})R_{n,k}D^*_{n,k}}{\sum_{j\neq i}\sum_{k\neq i,j}C_{n,i,j}\tilde{A}_{n,i,j}C_{n,j,k}\tilde{A}_{n,j,k}(1-C_{n,i,k}\tilde{A}_{n,i,k})}\right),
    \end{align*}
    then, there is a correlation between $T_{n,i,(2)}$ and $\tilde{T}_{n,i,(3)}$.
    An easy way to avoid contamination bias is to modify the exposure mapping $\tilde{g}$ to make $\tilde{T}_{n,i,(3)}$ equal to zero for individuals subject to censoring.
    For example, if the censoring happens by asking up to four friends, we can eliminate the individuals with four observed links from consideration
    \begin{equation*}
        \tilde{T}_{n,i,(3)}=\frac{\sum_{j\neq i}\sum_{k\neq i,j}C_{n,i,j}\tilde{A}_{n,i,j}C_{n,j,k}\tilde{A}_{n,j,k}(1-C_{n,i,k}\tilde{A}_{n,i,k})R_{n,k}D^*_{n,k}}{\sum_{j\neq i}\sum_{k\neq i,j}C_{n,i,j}\tilde{A}_{n,i,j}C_{n,j,k}\tilde{A}_{n,j,k}(1-C_{n,i,k}\tilde{A}_{n,i,k})}\mathds{1}\left\{\sum_{j\neq i}C_{n,i,j}\tilde{A}_{n,i,j}<4\right\}.
    \end{equation*}
    Note that the censoring for $i$ does not matter for the first neighborhood element $\tilde{T}_{n,i,(2)}$ by the same logic as \cref{ex:q_function}. Moreover, the censoring for $i_1$ does not matter for the second neighborhood element $\tilde{T}_{n,i,(3)}$ of $i$ because it does not introduce any misclassification.
\end{example}

\subsection{Asymptotic Theory}
We mostly follow the notation of \cite{kojevnikov2021limit}. Let $\mathcal{N}_{n}=\{1,...,n\}$ be the set of population units and $d_{n}(i,j)$ be the shortest distance between $i,j\in \mathcal{N}_{n}$ on $\bA_{n}$ (set $d_{n}(i,i)=0$; set $d_{n}(i,j)=\infty$ if there are no paths between $i$ and $j$). Define
\begin{align*}
    \mathcal{L}_{v}=\{\mathcal{L}_{v,a}:a\in\mathbb{N}\},
\end{align*}
where
\begin{align*}
    \mathcal{L}_{v,a} = \{f:\mathbb{R}^{v\times a}\to \mathbb{R}:\|f\|_{\infty}<\infty,\Lip(f)<\infty\},
\end{align*}
where $\|\cdot\|_{\infty}$ is sup-norm and $\Lip(f)$ is the Lipschitz constant of $f$. Let
\begin{align*}
    \mathcal{P}_{n}(a,b;s)=\{(A,B):A,B\subset \mathcal{N}_{n},|A|=a,|B|=b,d_{n}(A,B)\geq s\},
\end{align*}
where 
\begin{align*}
    d_{n}(A,B)=\min_{i\in A}\min_{j\in B}d_{n}(i,j).
\end{align*}
For each $A\subset \mathcal{N}_{n}$ and triangular array $(U_{n,i})$, let us write 
\begin{align*}
    U_{n,A}=(U_{n,i})_{i\in A}.
\end{align*}
\begin{definition}
    A triangular array $\{U_{n,i}\}, n\geq 1,U_{n,i}\in \mathbb{R}^{v}$, is called {\it conditionally $\psi$-dependent given $\bR_n$}, if for each $n\in\mathbb{N}$, there exists a $\sigma(\bR_n)$-measurable sequence $\xi_{n}=\{\xi_{n,s}\}_{s\geq 0},\xi_{n,0}=1$, and a collection of nonrandom functions $(\psi_{a,b})_{a,b\in\mathbb{N}},\psi_{a,b}:\mathcal{L}_{v,a}\times\mathcal{L}_{v,b}\to[0,\infty)$ such that for all $(A,B)\in\mathcal{P}_{n}(a,b;s)$ with $s>0$ and all $f\in\mathcal{L}_{v,a}$ and $g\in\mathcal{L}_{v,b}$,
    \begin{align*}
        |\Cov(f(U_{n,A}),g(U_{n,B}))|\leq \psi_{a,b}(f,g)\xi_{n,s} \quad\text{a.s.}
    \end{align*}
\end{definition}

Define
\begin{align*}
    \mathcal{N}_{n}(i;s) =\{j\in \mathcal{N}_{n}:d_{n}(i,j)\leq s\},
\end{align*}
which is the set of $i$'s neighborhood within $s$-distance.
First, we assume that the network dependence is local. 
\begin{assumption}\label{asm:local}
    There exists some $K\in\mathbb{N}$ such that for any $i\in \mathcal{N}_{n},n\in\mathbb{N}$ and $\bd_{n},\bd_{n}^{\prime}\in\{0,1\}^{n}$ such that $\bd_{\mathcal{N}_{n}(i,K)}=\bd'_{\mathcal{N}_{n}(i,K)}$,
    \begin{align*}
        g(i,\bd_{n},\bA_{n})&=g(i,\bd_{n}^{\prime},\bA_{n}),\\
        \tilde{g}(i,\bd_{n},\tilde{\bA}_{n})&=\tilde{g}(i,\bd_{n}^{\prime},\tilde{\bA}_{n})\quad\text{a.s.}
    \end{align*}
\end{assumption}

Let $\tilde{d}_{n}(i,j)$ be the shortest distance between $i,j\in \mathcal{N}_{n}$ on $\tilde{\bA}_{n}$.
\cref{asm:local,asm:sampling} imply that $T_{n,i}\indep T_{n,j}$ if $d_{n}(i,j)>2K$. They also imply that $\tilde{T}_{n,i}\indep \tilde{T}_{n,j}$ if $d_{n}(i,j)>2K$ because $\tilde{d}_{n}(i,j)\geq d_{n}(i,j)$ almost surely and bacause $i$ and $j$ do not share $R_{n,k}$ and $D^*_{n,k}$ for any $k$ in their $K$-neighborhoods.

Under the correctly specified exposure mapping, $g=\tilde{g}$, the condition $g(i,\bd_{n},\bA_{n})=g(i,\bd_{n}^{\prime},\bA_{n})$ a.s. automatically implies $\tilde{g}(i,\bd_{n},\tilde{\bA}_{n})=\tilde{g}(i,\bd_{n}^{\prime},\tilde{\bA}_{n})$ a.s. by $\tilde{d}_{n}(i,j)\geq d_{n}(i,j)$.

\begin{remark}
    For the same reason, a censored network always has a longer distance than the original sampled network.
\end{remark}

Define $\mathcal{N}_{n}^{\partial}(i;s)=\{j\in \mathcal{N}_{n}:d_{n}(i,j)=s)\}$, which is the set of $i$'s neighborhood with exact $s$-distance, and its $p$-th sample moment
\begin{align*}
    \delta_{n}^{\partial}(s;p)=\frac{1}{n}\sum_{i\in \mathcal{N}_{n}}|\mathcal{N}_{n}^{\partial}(i;s)|^{p}.
\end{align*}

\begin{assumption}
    \label{asm:sparsity}
    The sequence of networks $(\bA_{n})$ satisfies
    \begin{align*}
        \sum_{1\leq s\leq 2K}\delta_{n}^{\partial}(s;1)=O(1).%O(\rho_n).
    \end{align*}
\end{assumption}
By a simple calculation, we can show that \cref{asm:sparsity} is equivalent to $(n\rho_n)^{-1}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_n(i;2K)}1=O(1)$.
\begin{remark}
    \cref{asm:sparsity} is weaker than the bounded network degree since this assumption only requires the boundedness on average.
\end{remark}

Then, we show that our estimator is consistent for the sample-level causal estimand:
\begin{theorem}\label{thm:consistency}
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity}, $$\hat{\theta}_{n}-\theta_{n}^{\causample}\overset{p^R}{\longrightarrow}0
    \quad\text{ and }\quad \hat{\theta}_{n}-\theta_{n}^{\causample}\overset{p}{\to}0,$$
    where $\overset{p^R}{\longrightarrow}$ denotes convergence in probability conditional on $\bR_n$, that is, for any $\varepsilon>0$,
    $$
        \mathbb{P}\left(\|\hat{\theta}_{n}-\theta_{n}^{\causample}\|\leq\varepsilon\mid\bR_n\right)\overset{a.s.}{\longrightarrow}1
    $$ 
    as $n\to\infty$.
\end{theorem}
\cref{thm:consistency} establishes the internal validity of our network experiment. However, in general, $\hat{\theta}_{n}-\theta_{n}^{\causal}\not\overset{p}{\to}0$ because $\theta^{\causal}_{n}-\theta_{n}^{\causample}\not\overset{p}{\to}0$ due to misspecification of the exposure mapping. Moreover, as shown in \cref{thm:causal_element}, $\theta_{n}^{\causample}$ does not have a clear causal interpretation. Consequently, \cref{thm:consistency} does not guarantee the external validity of our network experiment.

Ideally, our network experiment would satisfy $\hat{\theta}_{n}-\theta_{n}^{\causal}\overset{p}{\to}0$ so that each element of $\hat{\theta}_{n}$ can be interpreted as a causal spillover effect. 
We show that this consistency is achieved when there is no misspecification and no mismeasurement ($\tilde{T}_{n,i}=T_{n,i}$ for each $i\in\mathcal{N}_{n}$) and the observed covariates coincide with those in the population ($\tilde{Z}_{n,i}=Z_{n,i}$ for each $i\in\mathcal{N}_{n})$. 
We are essentially assuming that each $\tilde{T}_{n,i}$ is computed by $g(i,\bD_{n},\bA_{n})=T_{n,i}$ where we replace $\tilde{g}$ with $g$ and $\tilde{\bA}_{n}$ with $\bA_{n}$. 
Under the linear propensity scores, we can show that $X_{n,i}=\tilde{X}_{n,i}$ a.s. (\cref{lem:Lambda}).

\begin{assumption}
    \label{asm:exposure}
    \
    \begin{enumerate}
        \item We have the following equalities almost surely for $R_{n,i}=1$: $\tilde{T}_{n,i}=T_{n,i}$ and $\tilde{Z}_{n,i}=Z_{n,i}$ for all $i\in\mathcal{N}_{n}$ and $n\in\mathbb{N}$.
        \item $R_{n,i}$ enters only multiplicatively in the functional form of each element of  $Z_{n,i}$.
        \item At most one element of $T_{n,i}$ depends on $i$'s own treatment $R_{n,i}D^*_{n,i}$ and the element does not depend on $R_{n,j}$ and $D_{n,j}$ for any $j\neq i$.
    \end{enumerate}
\end{assumption}

\begin{remark}
    \cref{asm:exposure} (i) is satisfied under no misspecification and no mismeasurement for sampled units, i.e., $g=\tilde{g}$ and $\tilde{\bA}_{n}=\bA_{n}$ locally.
    We can always pick covariates $Z_{n,i}$ having \cref{asm:exposure} (ii) since $R_{n,i}$ enters only multiplicatively for $T_{n,i}$ by \cref{asm:sampling} and the definition of the exposure mapping. Thus, we can choose covariates $Z_{n,i}$ satisfying \cref{asm:exposure} and \cref{asm:linear_propensity} simultaneously.
    \cref{asm:exposure} (iii) is satisfied if we do not include the cross term of the direct effect $R_{n,i}D^*_{n,i}$ and a spillover effect.
    Excluding the cross term is also need to guarantee no contamination (\cref{cor:no_contamination}).\footnote{We can allow the violation of \cref{asm:exposure} (iii) if we modify $\hat{\theta}_n$ in the same manner as $\tilde{\gamma}_n$ in \cref{app:gamma}.}
\end{remark}

\begin{theorem}
    \label{thm:causal_consistency}
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:exposure}, $$\hat{\theta}_{n}-\theta_{n}^{\causal}\overset{p}{\to}0.$$
\end{theorem}

It is worth noting that \cref{thm:causal_consistency} does not hold if $\tilde{Z}_{n,i}\neq Z_{n,i}$, since we cannot ensure $\tilde{X}_{n,i}\sim X_{n,i}$ asymptotically. Instead, under no misspecication, \cref{thm:causal_element} implies
\begin{align*}
    \theta_{n,(k)}^{\causample}=\frac{\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}^{2}|\bR_{n}]\theta_{n,i}}{\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}^{2}|\bR_{n}]}
\end{align*}
for each $k=1,...,d_{\tilde{T}}$. Thus, although the consistency for $\theta_{n}^{\causal}$ may fail in this setting, the absence of misspecification alone recovers the causal interpretability of $\theta_{n}^{\causample}$, and by extension, that of $\hat{\theta}_{n}$.

Next, we consider the asymptotic distribution of $\hat{\theta}_{n}$. 
Now, we introduce additional dependence measures of the network.
Define
\begin{align*}
    \Delta_{n}(s,m;k)=\frac{1}{n}\sum_{i\in \mathcal{N}_{n}}\max_{j\in \mathcal{N}_{n}^{\partial}(i;s)}|\mathcal{N}_{n}(i;m)\setminus \mathcal{N}_{n}(j;s-1)|^{k}
\end{align*}
and
\begin{align*}
    c_{n}(s,m;k)=\inf_{\alpha >1}[\Delta_{n}(s,m;k\alpha)]^{1/\alpha}\left[\delta^{\partial}_{n}\left(s;\frac{\alpha}{\alpha-1}\right)\right]^{1-1/\alpha}.
\end{align*}
$c_{n}(s,m;k)$ measures the density of the network and is used as a sufficient condition for the CLT.


Define
\begin{align*}
    \tilde{\varepsilon}_{n,i}&=Y_{n,i}-\tilde{X}_{n,i}'\theta_{n}^{\causample}-\tilde{Z}_{n,i}'\gamma_{n}^{\causample},\\
    \varepsilon_{n,i}&=Y_{n,i}-X_{n,i}'\theta_{n}^{\causal}-Z_{n,i}'\gamma_{n}^{\causal},
\end{align*}
and 
\begin{align*}
    \tilde{\Sigma}_{n}
    =&\Var\left(\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right)\\
    \Sigma_{n}
    =&\Var\left(\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}\right).
\end{align*}

We will make the following assumption about the dependence structure of the network.

\begin{assumption}
    \label{asm:dependence}
    There exists a positive sequence $m_{n}\to\infty$ such that for $p=1,2$,
    \begin{align*}
        n\tilde{\Sigma}_{n}^{-(1+p/2)}\sum_{s=0}^{2K}c_{n}(s,m_{n};p)&\overset{a.s.}{\longrightarrow} 0,\\
        n\Sigma_{n}^{-(1+p/2)}\sum_{s=0}^{2K}c_{n}(s,m_{n};p)&\to 0.
    \end{align*}
\end{assumption}
Then, we show that $\hat{\theta}_{n}$ is asymptotically normal relative to $\theta_{n}^{\causample}$:
\begin{theorem}
    \label{thm:normality}
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence},
    \begin{align*}
        \tilde{\Sigma}_{n}^{-1/2}\tilde{Q}_n^{XX}(\hat{\theta}_{n}-\theta_{n}^{\causample})\overset{d^R}{\longrightarrow}\mathrm{N}(0,I_{d_{\tilde{T}}})
        \quad\text{and}\quad
        \tilde{\Sigma}_{n}^{-1/2}\tilde{Q}_n^{XX}(\hat{\theta}_{n}-\theta_{n}^{\causample})\overset{d}{\to}\mathrm{N}(0,I_{d_{\tilde{T}}}),
    \end{align*}
    where $\overset{d^R}{\to}$ denotes convergence in distribution conditional on $\bR_n$, that is,
    $$
        \left|\mathbb{P}\left(\tilde{\Sigma}_{n}^{-1/2}\tilde{Q}_n^{XX}(\hat{\theta}_{n}-\theta_{n}^{\causample}) \leq t\mid\bR_n\right)-F(t)\right|\overset{a.s.}{\longrightarrow}0
    $$
    as $n\to\infty$ for any $t\in\mathbb{R}^{d_{\tilde{T}}}$ letting $F(t)$ be the distribution function of $\mathrm{N}(0,I_{d_{\tilde{T}}})$.
\end{theorem}

We also show that the absence of misspecification and access to the covariates in the population yield asymptotic normality of $\hat{\theta}_{n}$ relative to $\theta_{n}^{\causal}$:
\begin{theorem}
    \label{thm:normality_causal}
    Under \cref{asm:exposure,asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence}, we have
    \begin{align*}
        \Sigma_{n}^{-1/2}\tilde{Q}^{XX}_{n}(\hat{\theta}_{n}-\theta_{n}^{\causal})\overset{d}{\to}\mathrm{N}(0,I_{d_{T}}).
    \end{align*}
\end{theorem}

\begin{remark}
    When we have a homogeneous effect $\theta_{n,i}=\theta_{n}$, we have $$\theta_{n}^{\causample}=\theta_{n}^{\causal}\quad\text{a.s.}$$
    for large enough $n$ under $X_{n,i}=\tilde{X}_{n,i}$.
    Hence, we can use the same asymptotic distribution among them.
\end{remark}


\section{Variance Estimation}
\label{sec:variance}
In this section, we provide a conservative network heteroskedasticity and autocorrelation consistent (HAC) variance estimator for $\hat{\theta}_{n}$.
Note that even when treatments and samples are randomly assigned and drawn, dependence can persist within a $2K$-neighborhood because exposure mappings $T_{n,i}$ may share elements of $\bD_{n}$ and $\bR_{n}$. As a result, the variance estimator must account for this local dependence structure. However, for any pair $i, j$ with $d_n(i, j) > 2K$, the exposure mappings $T_{n,i}$ and $T_{n,j}$ are independent. When the exposure mapping is correctly specified ($\tilde{g}=g$), the researcher can directly choose a finite $K$ based on the functional form. If there is potential misspecification in $\tilde{g}$, $K$ should be selected conservatively, reflecting the maximum range over which the exposure mapping may induce dependence.

Define
\begin{align*}
    \tilde{\mathcal{N}}_{n}(i;s) =\{j\in \mathcal{N}_{n}:\tilde{d}_{n}(i,j)\leq s\},
\end{align*}
which is the set of $i$'s neighborhood within $s$-distance on a sampled network $\tilde{\bA}_{n}$.
Note that $\tilde{\mathcal{N}}_{n}(i;s)$ is a random set because $\tilde{d}_{n}(i,j)$ is a random variable depends on $\bR_n$.
On the other hand, $d_{n}(i,j)$ and $\mathcal{N}_{n}(i;s)$ are non-random.
Recall that we also have $\tilde{d}_{n}(i,j)\geq d_{n}(i,j)$ a.s., thus, $\tilde{\mathcal{N}}_{n}(i;s)\subseteq \mathcal{N}_{n}(i;s)$ a.s.

Let 
\begin{align*}
    \hat{\varepsilon}_{n,i}&=Y_{n,i}-\tilde{X}_{n,i}^{\prime} \hat{\theta}_n-\tilde{Z}_{n,i}^{\prime}\tilde{\gamma}_n,
\end{align*}
$\Psi_{n,i}=X_{n,i}\varepsilon_{n,i}$, $\tilde{\Psi}_{n,i}=\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}$, and $\hat{\Psi}_{n,i}=\tilde{X}_{n,i}\hat{\varepsilon}_{n,i}$, where we define $\tilde{\gamma}_n$ later in \cref{thm:var_consistency,thm:var_consistency_eig}.
By orthogonality conditions, $\sum_{i=1}^{n}\mathbb{E}\left[\Psi_{n,i}\right]=0$, $\sum_{i=1}^{n}R_{n,i}\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]=0$, and $\sum_{i=1}^{n}R_{n,i}\hat{\Psi}_{n,i}=0$.

Then, the variances of interest can be written as
\begin{align*}
    \frac{1}{n\rho_n}\tilde{\Sigma}_{n}
    =&\Var\left(\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right)\\
    =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\mathbb{E}\left[\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\right)\left(\tilde{\Psi}_{n,j}-\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]\right)^{\prime}\mid\bR_n\right],
\end{align*}
and
\begin{align*}
    \frac{1}{n\rho_n}\Sigma_{n}
    =&\Var\left(\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}\right)\\
    =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)}\mathbb{E}\left[\left(R_{n,i}\Psi_{n,i}-\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\right)\left(R_{n,j}\Psi_{n,j}-\rho_n\mathbb{E}\left[\Psi_{n,j}\right]\right)^{\prime}\mathds{1}\{\tilde{d}_n(i, j)\leq2K\}\right].
\end{align*}

\begin{remark}
    By \cref{asm:exposure} (i), $T_{n,i}$ depends on $D^*_{n,j}$ essentially if $j\in\tilde{\mathcal{N}}_{n}(i,2K)$ conditional on $\bR_n$.
    However, $T_{n,i}$ can depend on $j\in\mathcal{N}_{n}(i,2K)$ unconditionally.
    Thus, $(n\rho_n)^{-1}\Sigma_{n}$ has dependence terms over $j\in\mathcal{N}_{n}(i,2K)$ instead of $j\in\tilde{\mathcal{N}}_{n}(i,2K)$.
\end{remark}

We consider the following feasible estimator:
\begin{align*}
    \frac{1}{N}\hat{\Sigma}_n
    =&\frac{1}{N}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\hat{\Psi}_{n,i}\hat{\Psi}_{n,j}^{\prime}.
\end{align*}

To show the consistency of the variance estimator, we need to make an additional sparsity assumption. The assumption requires a few more notations. 
Let $\delta_{n}(s;p)$ be the $p$-th sample moment of the set of $i$'s neighborhood within $s$-distance:
\begin{align*}
    \delta_{n}(s;p)=\frac{1}{n}\sum_{i\in \mathcal{N}_{n}}|\mathcal{N}_{n}(i;s)|^{p}.
\end{align*}
We also define $\mathcal{J}_n(s,m)$ as the set of quadruples $(i,j,i^{\prime},j^{\prime})$ such that $i$ and $j$ are $2K$-neighbors, $i^{\prime}$ and $j^{\prime}$ are $m$-neighbors of $i$ and $j$, respectively, and the distance between $i$ and $j$ is exactly $s$:
\begin{align*}
    \mathcal{J}_n(s,m)=\left\{(i,j,i^{\prime},j^{\prime})\in\mathcal{N}_n^4:k\in\mathcal{N}_n(i,m),j^{\prime}\in\mathcal{N}_n(j,m), d_n(i,j)=s\right\}.
\end{align*}
We also denote its cardinality by $\#|\mathcal{J}_n(s,m)|$.
\begin{assumption}
    \label{asm:var_dependence}
    \
    \begin{enumerate}
        \item $\delta_{n}(2K;2)=o(n)$.
        \item $\sum_{s=0}^{2K}\#|\mathcal{J}_n(s,2K)|=o(n^2)$.
    \end{enumerate}
\end{assumption}
\cref{asm:var_dependence} is a version of Assumptions 7c and 7d of \cite{leung2022causal}. This assumption is satisfied if network links are not too dense.

\begin{theorem}
    \label{thm:var_consistency}
    %Assume that $\rho\in(0,1]$.
    Let $\tilde{\gamma}_n=\hat{\gamma}_n$.
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence,asm:var_dependence}, we have
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n
        &=\frac{1}{n\rho_n}\tilde{\Sigma}_n+\tilde{B}_{n}+o_{p^{R}}(1),
    \end{align*}
    where $U_n=o_{p^{R}}(1)$ means $U_n\overset{p^R}{\longrightarrow}0$, and
    \begin{align*}
        \tilde{B}_{n}
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]^{\prime}.
    \end{align*}

    Let $\tilde{\gamma}_n=\gamma_n^{\causal}+o_p(1)$.
    If, in addition, assume \cref{asm:exposure}. 
    Then,
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n
        &=\frac{1}{n\rho_n}\Sigma_n+\hat{B}_{n}+o_p(1),
    \end{align*}
    where 
    \begin{align*}
        \hat{B}_{n}
        =&\frac{1}{n}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)}\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\mathbb{E}\left[\Psi_{n,j}\right]^{\prime}\mathbb{P}\left(\tilde{d}_n(i, j)\leq2K\right).
    \end{align*}
\end{theorem}

\begin{remark}
    An estimator satisfying $\tilde{\gamma}_n=\gamma_n^{\causal}+o_p(1)$ is given in \cref{app:gamma}. In general, $\hat{\gamma}_n\neq\gamma_n^{\causal}+o_p(1)$, and we need a modification on $\hat{\gamma}_n$.
\end{remark}

Thus, we can only estimate the variance up to the ones with bias terms $\tilde{B}_{n}$ and $\hat{B}_{n}$ since there is no hope to estimate each heterogeneous expectation consistently.
This bias is inevitable in heterogeneous treatment effect settings (\citealp{abadie2020sampling}; \citealp{leung2020treatment}; \citealp{gao2023causal}).
Combining this convergence and the asymptotic normality, we can estimate the variance of $\hat{\theta}_{n}$ by
\begin{equation}\label{eq:se}
    {\left(\tilde{Q}^{XX}_{n}\right)}^{-1}\left(\frac{1}{N}\hat{\Sigma}_n\right){\left(\tilde{Q}^{XX}_{n}\right)}^{-1}.
\end{equation}

The above variance estimator has a problem because we cannot guarantee conservativeness.
Indeed, bias matrices $\hat{B}_{n}$ and $\tilde{B}_{n}$ are not necessarily positive semi-definite.\footnote{Alternatively, we can implement the randomized inference as \cite{borusyak2023nonrandom}. For multidimensional $\hat{\theta}_n$, the randomized inference do not guarantee conservativeness, too.}
Conservative guarantee modification is possible.
We can write
$(1/N)\hat{\Sigma}_n=(1/N)\hat{R\Psi}^{\prime}_n\tilde{K}_n\hat{R\Psi}_n$,
where 
\begin{align*}
    \hat{R\Psi}_n&=\left(R_{n,1}\tilde{X}_{n,1}\hat{\varepsilon}_{n,1},\cdots,R_{n,n}\tilde{X}_{n,n}\hat{\varepsilon}_{n,n}\right)^{\prime},\\
    \tilde{K}_{n}&=[\mathds{1}\{\tilde{d}_n(i, j)\leq2K\}]_{i,j}.
\end{align*}
Eigendecomposition gives $\tilde{K}_n=\mathcal{Q}_n\Xi_n\mathcal{Q}_n^{\prime}$.
By replacing $\tilde{K}_n$ by $\tilde{K}_n^+=\mathcal{Q}_n\max\{0,\Xi_n\}\mathcal{Q}_n^{\prime}$ ($\max$ is taken element-wise), the variance matrix estimator 
\begin{align*}
    \frac{1}{N}\hat{\Sigma}_n^+
    =\frac{1}{N}\hat{R\Psi}^{\prime}_n\tilde{K}_n^{+}\hat{R\Psi}_n=\frac{1}{N}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\hat{\Psi}_{n,i}\hat{\Psi}_{n,j}^{\prime}\tilde{K}_{n,i,j}^{+}.
\end{align*}
becomes positive semi-definite.
We also have $\tilde{K}_n^{-}=\mathcal{Q}_n|\min\{0,\Xi_n\}|\mathcal{Q}_n^{\prime}=\tilde{K}_n^{+}-\tilde{K}_n$.
This modification is provided by \cite{gao2023causal}. The modified variance estimator is given by
\begin{equation}\label{eq:se_mod}
    {\left(\tilde{Q}^{XX}_{n}\right)}^{-1}\left(\frac{1}{N}\hat{\Sigma}^{+}_n\right){\left(\tilde{Q}^{XX}_{n}\right)}^{-1}.
\end{equation}

Define $K_n=[\mathds{1}\{d_n(i, j)\leq2K\}]_{i,j}$, and define $K_n^{+}$ and $K_n^{-}$ in a similar manner to $\tilde{K}_n^{+}$ and $\tilde{K}_n^{-}$.
Define
\begin{align*}
    \delta_{n}^{-}(2K;p)=\frac{1}{n}\sum_{i=1}^{n}\left(\sum_{j=1}^{n}|\tilde{K}_{n,i,j}^{-}|\right)^{p},
\end{align*}
and
\begin{align*}
    \#|\mathcal{J}_n^{-}(s,2K)|=\sum_{i=1}^{n}\sum_{j=1}^{n}\mathds{1}\{d_n(i, j)=s\}\left(\sum_{i^{\prime}=1}^{n}|\tilde{K}_{n,i,i^{\prime}}^{-}|\right)\left(\sum_{j^{\prime}=1}^{n}|\tilde{K}_{n,j,j^{\prime}}^{-}|\right).
\end{align*}

\begin{assumption}
    \label{asm:var_dependence_eig}
    We assume that
    \begin{enumerate}
        \item $\delta_{n}^{-}(2K;1)=O_{\text{a.s.}}(1)$.
        \item $\delta_{n}^{-}(2K;2)=O_{\text{a.s.}}(n)$.
        \item $\sum_{s=0}^{2K}\#|\mathcal{J}_n^{-}(s,2K)|=O_{\text{a.s.}}(n^2)$.
    \end{enumerate}
\end{assumption}
\cref{asm:var_dependence_eig} is a version of Assumptions 7b-7d of \cite{gao2023causal}. The assumption is a modified version of \cref{asm:var_dependence} for the eigenvalue modification.

\begin{theorem}
    \label{thm:var_consistency_eig}
    %Assume that $\rho\in(0,1]$.
    Let $\tilde{\gamma}_n=\hat{\gamma}_n$.
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence,asm:var_dependence_eig}, we have
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n^{+}
        &=\frac{1}{n\rho_n}\tilde{\Sigma}_n+\tilde{B}_{n}^{+}+o_p^R(1),
    \end{align*}
    where 
    \begin{align*}
        \tilde{B}_{n}^{+}
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]^{\prime}\tilde{K}_{n,i,j}^{+}\\
        &+\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\mathbb{E}\left[\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\right)\left(\tilde{\Psi}_{n,j}-\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]\right)^{\prime}\mid\bR_n\right]\tilde{K}_{n,i,j}^{-}
    \end{align*}

    Let $\tilde{\gamma}_n=\gamma_n^{\causal}+o_p(1)$.
    If, in addition, assume \cref{asm:exposure}. 
    Then,
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n^{+}
        &=\frac{1}{n\rho_n}\Sigma_n+\hat{B}_{n}^{+}+o_p(1),
    \end{align*}
    where 
    \begin{align*}
        \hat{B}_{n}^{+}
        =&\frac{1}{n}\sum_{i=1}^{n}\sum_{j=1}^{n}\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\mathbb{E}\left[\Psi_{n,j}\right]^{\prime}\mathbb{E}\left[\tilde{K}_{n,i,j}^{+}\right]\\
        &+\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}\mathbb{E}\left[\left(R_{n,i}\Psi_{n,i}-\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\right)\left(R_{n,j}\Psi_{n,j}-\rho_n\mathbb{E}\left[\Psi_{n,j}\right]\right)^{\prime}\tilde{K}_{n,i,j}^{-}\right].
    \end{align*}
\end{theorem}


\section{Simulation}\label{sec:simulation}
In this section, we conduct two simulation exercises to illustrate the performance of our proposed inferential procedure as well as to underscore the potential severity of contamination bias. In the first exercise, we focus on a case where $T_{n,i}=\tilde{T}_{n,i}$ holds to test whether the asymptotic approximation above works in finite samples. In the second exercise, we switch to a case where $T_{n,i}\neq \tilde{T}_{n,i}$ and contamination bias arises. 

In the following exercises, to discipline the structure of the population network, we utilize network data from \cite{banerjee2013diffusion}. They conducted a network survey among randomly selected respondents across 75 villages in rural southern India. Respondents were asked to name 5 to 8 contacts across 12 interaction dimensions (e.g., house visits, borrowing goods). We use a network of borrowing relationships, specifically whether a person borrows rice or kerosene from others. To illustrate the applicability of our framework to a single large network without relying on numerous clusters, we focus on the largest village and use the network as the population $\bA_{n}$. Basic network statistics for this village are presented in \cref{tab:network_info}:

\begin{table}[H]
    \caption{Network Information}
    \label{tab:network_info}
    \centering
    \begin{tabular}{cccc}
      \hline
      \hline
      \textbf{Nodes} & \textbf{Edges} & \textbf{Mean Degree} & \textbf{Mean 2nd Order Degree} \\\hline
        1770 &  5556 & 6.28 & 11.44 \\\hline
    \end{tabular}
    \caption*{\footnotesize \textit{Notes}: \textbf{Mean Degree} reports mean degree; \textbf{Mean 2nd Order Degree reports} reports the mean count of friends-of-friends not directly connected to node $i$.}
