\subsection{Preliminary Lemmas}
We will use the following results from \cite{kojevnikov2021limit}. We will only state the conditional version of the results, but also use the unconditional version of the results, which can be understood analogously.
\begin{condition}
    \label{cond:clt}
    A triangular array $\{U_{n,i}\}$ is conditionally $\psi$-dependent given $\bR_n$ with $\zeta_{n}$ satisfying
    \begin{itemize}
        \item For some constant $C>0$,
        \begin{align*}
            \psi_{a,b}\leq C\times ab(\|f\|_{\infty}+\Lip(f))(\|g\|_{\infty}+\Lip(g)).
        \end{align*}
        \item $\sup_{n}\max_{s\geq1}\xi_{n,s}<\infty$ a.s.
        \item For some $p>4$, $\sup_{n\geq 1}\max_{i\in \mathcal{N}_{n}}\mathbb{E}[|U_{n,i}|^{p}\mid\bR_n]<\infty$ a.s.
        \item There exists a positive sequence $m_{n}\to\infty$ such that for $k=1,2$,
        \begin{align*}
            &\frac{n}{\sigma_{n}^{2+k}}\sum_{s\geq 0}c_{n}(s,m_{n};k)\zeta_{n,s}^{1-\frac{2+k}{p}}\overset{a.s.}{\longrightarrow} 0,\\
            &\frac{n^{2}\zeta_{n,m_{n}}^{1-1/p}}{\sigma_{n}}\overset{a.s.}{\longrightarrow} 0.
        \end{align*}
        \item $\mathbb{E}[U_{n,i}\mid\bR_n]=0$.
    \end{itemize}
\end{condition}

Define
\begin{align*}
    \sigma^{2}_{n}=\Var(S_{n}\mid\bR_n),
\end{align*}
where $S_{n}=\sum_{i\in \mathcal{N}_{n}}U_{i,n}$.


\begin{lemma}[CLT, Theorem 3.2 in \citealp{kojevnikov2021limit}] Under \cref{cond:clt}, 
\begin{align*}
    \sup_{t\in\mathbb{R}}\left|\mathbb{P}\left\{\frac{S_{n}}{\sigma_{n}}\leq t\mid\bR_n\right\}-\Phi(t)\right|\overset{a.s.}{\longrightarrow}0\text{ as }n\to\infty,
\end{align*}
    where $\Phi$ denotes the distribution function of $\mathcal{N}(0,1)$.
\end{lemma}

\begin{lemma}[Linear Transformation, Lemma 2.1 in \citealp{kojevnikov2021limit}]
    \label{lem:linear}
    For each $n \geq 1$, let $\left\{c_{n, i}\right\}_{i \in \mathcal{N}_n}$ be a sequence of $\sigma(\bR_n)$-measurable vectors such that $\max _{i \in \mathcal{N}_n}\left\|c_{n, i}\right\| \leq 1$ a.s. 
    Under the first condition of \cref{cond:clt}, 
    the array $c_{n, i}^{\prime} U_{n, i}$ is conditionally $\psi$-dependent given $\bR_n$ with the dependence coefficients $\left\{\zeta_n\right\}$.
\end{lemma}

\begin{condition}
    \label{cond:var_consistency}
    Let $\omega(x)=\mathds{1}\{|x|\leq1\}$.
    There exists $p>4$ such that
    \begin{itemize}
        \item $\sup _{n \geq 1} \max _{i \in \mathcal{N}_n}\mathbb{E}[|U_{n,i}|^{p}\mid\bR_n]<\infty$ a.s.
        \item $\lim _{n \rightarrow \infty} \sum_{s \geq 1}\left|\omega(s/2K)-1\right| \delta_n^{\partial}(s,1) \xi_{n,s}^{1-(2 / p)}=0$ a.s.
        \item $\lim _{n \rightarrow \infty} n^{-1} \sum_{s \geq 0} c_n\left(s, 2K ; 2\right) \xi_{n,s}^{1-(4 / p)}=0$ a.s.
    \end{itemize}
\end{condition}

\begin{lemma}[Variance Consistency, $2K$ Local Case of Proposition 4.1. in \citealp{kojevnikov2021limit}]
    \label{lem:var_consistency}
    Suppose that \cref{cond:clt,cond:var_consistency} hold. Then as $n \rightarrow \infty$,
    $$
        \mathbf{E}\left[\left\|\frac{1}{n}\sum_{i=1}^n \sum_{j \in \mathcal{N}_n(i;2K)} U_{n,i}U_{n,j}^{\prime}-\Var\left(S_n / \sqrt{n}\right)\right\|_F
        \mid\bR_n\right] \overset{a.s.}{\longrightarrow} 0,
    $$
    where $\|\cdot\|_F$ is the Frobenius norm.
    By Markov's inequality, we also have
    $$
        \frac{1}{n}\sum_{i=1}^n \sum_{j \in \mathcal{N}_n(i;2K)} U_{n,i}U_{n,j}^{\prime}-\Var\left(S_n / \sqrt{n}\right)\overset{p^R}{\longrightarrow}0.
    $$
\end{lemma}

\subsection{Main Lemmas}
\begin{lemma}
\label{lem:N_pos}
    %Under $\rho_n n\to\infty$,
    \begin{align*}
        N>0 \text{ a.s. for large enough $n$}
    \end{align*}
\end{lemma}
\begin{proof}
    Since the result is trivial for $\rho_n=1$, we focus on the case $\rho_{n}\in(0,1)$.
    By the inequality $1-x \leq e^{-x}$ for $x \in(0,1)$, we have $\left(1-\rho_n\right)^n \leq e^{-n \rho_n}$.
    Thus,
    $$
        \sum_{n=1}^{\infty} \mathbb{P}(N=0) 
        =\sum_{n=1}^{\infty}\left(1-\rho_n\right)^n
        \leq \sum_{n=1}^{\infty} e^{-n \rho_n}.
    $$
    $\rho_n n\to\infty$ implies the right-hand side is bounded.
    By the Borel-Cantelli lemma, we can conclude.
\end{proof}

\begin{lemma}
\label{lem:nNconv}
    %Under $\rho_n^2 n\to\infty$,
    \begin{align*}
        \frac{N}{n\rho_n}\overset{a.s.}{\longrightarrow}1
    \end{align*}
\end{lemma}
as $n\to\infty$.
\begin{proof}
    Pick any $\varepsilon>0$.
    By Hoeffding's inequality with $R_i\in[0,1]$,
    \begin{align*}
        \mathbb{P}\left(\left|\frac{N}{n \rho_n}-1\right|>\varepsilon\right)
        &=\mathbb{P}\left(\left|N-n \rho_n\right|>\varepsilon n \rho_n\right)
        =\mathbb{P}\left(\left|\sum_{i=1}^n R_i-n \rho_n\right|>\varepsilon n \rho_n\right)\\
        &\leq 2 \exp \left(-\frac{2 (\varepsilon n \rho_n)^2}{n}\right)=2 \exp \left(-2\varepsilon^2 n \rho_n^2\right).
    \end{align*}
    $\rho_n^2 n\to\infty$ implies $\sum_{n=1}^{\infty}\mathbb{P}\left(\left|\frac{N}{n \rho_n}-1\right|>\varepsilon\right)$ is bounded.
    From the Borel-Cantelli lemma, we can conclude.
    \end{proof}

\begin{lemma}
    \label{lem:as_rep}
    Assume that \cref{asm:moment,asm:linear_propensity} hold. Then, for large enough $n$,
    $$
        \Lambda_{n}=L_n,\quad X_{n,i}=T_{n,i}-\mathbb{E}[T_{n,i}|\bR_n]\quad\text{a.s.},
    $$
    and
    $$              
        \tilde{\Lambda}_{n}=\tilde{L}_{n},\quad\tilde{X}_{n,i}=\tilde{T}_{n,i}-\mathbb{E}[\tilde{T}_{n,i}|\bR_{n}]\quad\text{a.s.}
    $$
\end{lemma}
\begin{proof}
    Observe that $\Lambda_{n}=L_{n}$ a.s. for large enough $n$ as
    \begin{align*}
        \Lambda_{n}&=\sum_{i=1}^{n}\mathbb{E}[\mathbb{E}[T_{n,i}|\bR_n]Z_{n,i}']\left(\sum_{i=1}^{n}\mathbb{E}[Z_{n,i}Z_{n,i}']\right)^{-1}\\
        &=L_{n}\sum_{i=1}^{n}\mathbb{E}[Z_{n,i}Z_{n,i}']\left(\sum_{i=1}^{n}\mathbb{E}[Z_{n,i}Z_{n,i}']\right)^{-1}\\
        &=L_{n},
    \end{align*}
    where $\Lambda_{n}$ is well-defined by \cref{asm:moment} and the second equality holds
    by \cref{asm:linear_propensity}. Similarly, $\tilde{\Lambda}_{n}=\tilde{L}_{n}$ a.s. for large enough $n$ as
    \begin{align*}
        \tilde{\Lambda}_{n}&=\sum_{i=1}^{n}R_{n,i}\mathbb{E}[\tilde{T}_{n,i}|\bR_{n}]\tilde{Z}_{n,i}'\left(\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{Z}_{n,i}'\right)^{-1}\\
        &=\tilde{L}_{n}\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{Z}_{n,i}\left(\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{Z}_{n,i}'\right)^{-1}\\
        &=\tilde{L}_{n},
    \end{align*}
    where $\tilde{\Lambda}_{n}$ is well-defined by \cref{asm:moment} and the second equality holds by \cref{asm:linear_propensity}.

    Since we define $X_{n,i}=T_{n,i}-\Lambda_n Z_{n,i}$ and $\tilde{X}_{n,i}=\tilde{T}_{n,i}-\tilde{\Lambda}_{n}\tilde{Z}_{n,i}$, \cref{asm:linear_propensity} and the above two displayed qualities imply for large enough $n$, $X_{n,i}=T_{n,i}-\mathbb{E}[T_{n,i}|\bR_n]$ a.s. and $\tilde{X}_{n,i}=\tilde{T}_{n,i}-\mathbb{E}[\tilde{T}_{n,i}|\bR_{n}]$ a.s.
\end{proof}

\begin{lemma}
    \label{lem:Lambda}
    Suppose that $\tilde{T}_{n,i}=T_{n,i}$ and $\tilde{Z}_{n,i}=Z_{n,i}$ for all $i\in\mathcal{N}_{n}$ and $n\in\mathbb{N}$. Under \cref{asm:moment,asm:linear_propensity}, (i) $\tilde{\Lambda}_{n}=\Lambda_{n}$ a.s. and (ii) $\tilde{X}_{n,i}=X_{n,i}$ a.s.
\end{lemma}
\begin{proof}
    The results follow directly from \cref{lem:as_rep}.
\end{proof}

\begin{lemma}
    \label{lem:psi_dependency}
    Assume that \cref{asm:sampling,asm:linear,asm:moment,asm:linear_propensity,asm:local} hold.
    The following sequences of triangular arrays are $\psi$-dependent with $\xi_{n,s}=\mathds{1}\{s\leq 2K\}$:
    \begin{align*}
        X_{n,i}Z_{n,i}^{\prime}, \ 
        X_{n,i}X_{n,i}^{\prime}, \ 
        X_{n,i}Y_{n,i}, \ 
        Z_{n,i}Z_{n,i}^{\prime}, \ 
        Z_{n,i}Y_{n,i}.
    \end{align*}
    The following sequences of triangular arrays are conditionally $\psi$-dependent given $\bR_n$ with $\xi_{n,s}=\mathds{1}\{s\leq 2K\}$:
    \begin{align*}
        R_{n,i}\tilde{X}_{n,i}\tilde{Z}_{n,i}^{\prime}, \
        R_{n,i}\tilde{X}_{n,i}\tilde{T}_{n,i}^{\prime}, \
        R_{n,i}\tilde{X}_{n,i}Y_{n,i}, \ 
        R_{n,i}\tilde{Z}_{n,i}\tilde{Z}_{n,i}^{\prime}, \
        R_{n,i}\tilde{Z}_{n,i}Y_{n,i}.
    \end{align*}
\end{lemma}
\begin{proof}
    By \cref{asm:local}, we can set $\xi_{n,s}=\mathds{1}\{s\leq 2K\}$ for $s\geq 1$ since if $d_{n}(A,B)>2K$, $f(U_{n,A})\indep g(U_{n,B})$ for any $f\in\mathcal{L}_{v,a}$ and $g\in\mathcal{L}_{v,b}$ as long as $U_{n,i}$ are based on $\tilde{T}_{n,i},T_{n,i},\tilde{Z}_{n,i},Z_{n,i},\tilde{Y}_{n,i},Y_{n,i}$. 
    for large enough $n$, \cref{lem:as_rep} implies $X_{n,i}=T_{n,i}-\mathbb{E}[T_{n,i}|\bR_n]$ and $\tilde{X}_{n,i}=\tilde{T}_{n,i}-\mathbb{E}[\tilde{T}_{n,i}|\bR_{n}]$ almost surely.
    Thus, for large enough $n$, $X_{n,i}$ and  $\tilde{X}_{n,i}$ also have the local dependence with $2K$.
    By \cref{asm:moment}, each element is uniformly bounded. Thus, we can set $\psi_{a,b}=2\|f\|_{\infty}\|g\|_{\infty}$ for any  $f\in\mathcal{L}_{v,a}$ and $g\in\mathcal{L}_{v,b}$. This completes the proof.
\end{proof}

\begin{lemma}
    \label{lem:eps_bound}
    Under \cref{asm:moment},
    $$\max_{i}|\tilde{
        \varepsilon
        }_{n,i}|<\infty\text{ a.s. }\qquad\text{and}\qquad\max_{i}|
        \varepsilon_{n,i}|<\infty\text{ a.s. }$$
\end{lemma}
\begin{proof}
    Under the uniform boundedness and the invertibility condition (\cref{asm:moment}), $\|\theta_{n}^{\causample}\|<\infty$ a.s. and $\|\gamma_{n}^{\causample}\|<\infty$ a.s.
    Thus, by the Schwarz Inequality,
    \begin{align*}
        |\tilde{\varepsilon}_{n,i}|&\leq\max_{i}|Y_{n,i}|+\max_{i}\|\tilde{X}_{n,i}\|\times\|\theta_{n}^{\causample}\|+\max_{i}\|\tilde{Z}_{n,i}\|\times\|\gamma_{n}^{\causample}\|\\
        &<\infty\quad\text{a.s.}
    \end{align*}
    for all $i$.
    The bound for $|\varepsilon_{n,i}|$ can be derived similarly.
\end{proof}

\begin{lemma}
    \label{lem:LLN}
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity}, 
    \begin{align*}
        \tilde{Q}_{n}-\tilde{\Omega}_{n}\overset{p^R}{\longrightarrow}0
        \quad\text{and}\quad
        \tilde{Q}_{n}-\tilde{\Omega}_{n}\overset{p}{\to}0.
    \end{align*}
\end{lemma}
\begin{proof}
    Let $W_{n,i}\equiv (Y_{n,i},\tilde{X}_{n,i},\tilde{Z}_{n,i})'$. Then,
    \begin{align*}
        \tilde{Q}_{n}-\tilde{\Omega}_{n}&=\frac{1}{N}\sum_{i=1}^{n}R_{n,i}(W_{n,i}W_{n,i}'-\mathbb{E}[W_{n,i}W_{n,i}'|\bR_{n}])\\
        &=\frac{n\rho_{n}}{N}\times \frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i}W_{n,i}'-\mathbb{E}[W_{n,i}W_{n,i}'|\bR_{n}]\right).
    \end{align*}
    Since $(n\rho_{n})/N\overset{a.s.}{\longrightarrow}1$ (\cref{lem:nNconv}) implies $(n\rho_{n})/N\overset{p^R}{\longrightarrow}1$, it suffices to show that
    \begin{align*}
         \frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i}W_{n,i}'-\mathbb{E}[W_{n,i}W_{n,i}'|\bR_{n}]\right)\overset{p^R}{\longrightarrow}0.
    \end{align*}
    We will show it by verifying
    \begin{align*}
        \mathbb{E}\left[\left(\frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}\mid\bR_{n}]\right)\right)^{2}\mid\bR_{n}\right]\overset{a.s.}{\longrightarrow}0
    \end{align*}
    for all $k,\ell=1,\dots,d_{\tilde{T}}$.
    Observe that 
    \begin{align}
        &\mathbb{E}\left[\left(\frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}\mid\bR_{n}]\right)\right)^{2}\mid\bR_{n}\right]\nonumber\\
        =& \frac{1}{n^{2}\rho_{n}^{2}}\sum_{i=1}^{n}R_{n,i}\mathbb{E}\left[(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}|\bR_{n}])^{2}\mid\bR_{n}\right]\label{eq:WW_var}\\
        &+\frac{1}{n^{2}\rho_{n}^{2}}\sum_{i\neq j}R_{n,i}R_{n,j}\mathbb{E}[(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}|\bR_{n}])\nonumber\\
        &\hspace{80pt}
        \times(W_{n,j,(k)}W_{n,j,(\ell)}-\mathbb{E}[W_{n,j,(k)}W_{n,j,(\ell)}|\bR_{n}])\mid\bR_{n}]\label{eq:WW_cov}
    \end{align}

    For \cref{eq:WW_var}, since there is some absolute constant $C$ such that $|W_{n,j,(k)}W_{n,j,(\ell)}|<C$ by \cref{asm:moment},
    \begin{align*}
        \cref{eq:WW_var}
        &\leq \frac{1}{n^{2}\rho_{n}^{2}}\sum_{i=1}^n(2C)^2
        = 4C^{2}\times \frac{1}{n\rho_{n}^2}\to0
    \end{align*} 
    where the inequality and the convergence do not depend on $\bR_n$.

    For $\cref{eq:WW_cov}$, note that if $d_{n}(i,j)>2K$, then
    \begin{align*}
        \mathbb{E}[(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}|\bR_{n}])
        (W_{n,j,(k)}W_{n,j,(\ell)}-\mathbb{E}[W_{n,j,(k)}W_{n,j,(\ell)}|\bR_{n}])\mid\bR_{n}]=0
    \end{align*}
    as $R_{n,i}$ is i.i.d and $(T_{n,i},\tilde{T}_{n,i})\indep (T_{n,j},\tilde{T}_{n,j})$ with no overlap in $\bD_{n}$ and $\bR_{n}$. Thus,
    \begin{align*}
        \cref{eq:WW_cov} &= \frac{1}{n^{2}\rho^{2}_{n}}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}(i,2K)\setminus\{i\}}R_{n,i}R_{n,j}\mathbb{E}[(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}|\bR_{n}])\nonumber\\
        &\hspace{120pt}
        \times(W_{n,j,(k)}W_{n,j,(\ell)}-\mathbb{E}[W_{n,j,(k)}W_{n,j,(\ell)}|\bR_{n}])\mid\bR_{n}]\\
        &\leq 4C^{2}\times\frac{1}{n\rho_{n}^2}\sum_{1\leq s\leq 2K}\delta_{n}^{\partial}(s;1)\to0,
    \end{align*}
    where the last line holds by \cref{asm:sparsity}, and the inequality and the convergence do not depend on $\bR_n$.

    Thus, by Markov's inequality for $\left(\frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}\mid\bR_{n}]\right)\right)^{2}$, 
    $$
    \frac{1}{n\rho_{n}}\sum_{i=1}^{n}R_{n,i}\left(W_{n,i,(k)}W_{n,i,(\ell)}-\mathbb{E}[W_{n,i,(k)}W_{n,i,(\ell)}\mid\bR_{n}]\right)\overset{p^R}{\longrightarrow}0,
    $$
    and
    \begin{align*}
        \tilde{Q}_{n}-\tilde{\Omega}_{n}\overset{p^R}{\longrightarrow} 0.
    \end{align*}

    Unconditional consistency can be shown easily from this result.
    Since a conditional probability is bounded, the dominated convergence theorem and the law of iterated expectations imply $\tilde{Q}_{n}-\tilde{\Omega}_{n}\overset{p}{\to} 0.$
\end{proof}



\begin{lemma}
    \label{lem:LLN_W}
    Let $W_{n,i}$ be a scalar random variable satisfying $|W_{n,i}|\leq\bar{W}<\infty$ a.s.
    We allow $W_{n,i}$ to depend on $\bR_n$ and $\bD_n$, but assume that $W_{n,i}\indep R_{n,i}$ and $W_{n,i}\indep W_{n,j}$ if $d_n(i,j)>2K$. Then, under \cref{asm:sampling,asm:sparsity},
    \begin{align*}
        \frac{1}{N}\sum_{i=1}^nR_{n,i}\mathbb{E}[W_{n,i}|\bR_{n}]-\frac{1}{n}\sum_{i=1}^n\mathbb{E}[W_{n,i}]\overset{p}{\to} 0.
    \end{align*}
\end{lemma}
\begin{proof}
    By \cref{lem:nNconv}, 
    \begin{align*}
        \frac{1}{N}\sum_{i=1}^nR_{n,i}\mathbb{E}[W_{n,i}|\bR_{n}]=\frac{1}{n}\sum_{i=1}^n\frac{R_{n,i}}{\rho_n}\mathbb{E}[W_{n,i}|\bR_{n}]+o_p(1).
    \end{align*}
    Thus, it suffices to show that
    \begin{align}
       \mathbb{E}\left[\left(\frac{1}{n}\sum_{i=1}^n\frac{R_{n,i}}{\rho_n}\mathbb{E}[W_{n,i}|\bR_{n}]-\frac{1}{n}\sum_{i=1}^n\mathbb{E}[W_{n,i}]\right)^{2}\right]\to0
       \label{eq:consistency_causal}
    \end{align}
    The left-hand side of \cref{eq:consistency_causal} is given by
    \begin{align}
        &\frac{1}{n^{2}}\sum_{i=1}^n\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\mathbb{E}[W_{i,n}|\bR_{n}]-\mathbb{E}[W_{n,i}]\right)^{2}\right]\label{eq:cc_var}\\
        &+\frac{1}{n^{2}}\sum_{i\neq j}\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\mathbb{E}[W_{n,i}|\bR_{n }]-\mathbb{E}[W_{n,i}]\right)\left(\frac{R_{n,j}}{\rho_n}\mathbb{E}[W_{n,j}|\bR_{n}]-\mathbb{E}[W_{n,j}]\right)\right]\label{eq:cc_cov}
    \end{align}
    For \cref{eq:cc_var}, we have
        \begin{align*}
            \cref{eq:cc_var}&\leq \frac{2}{n^{2}}\sum_{i=1}^n\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\right)^{2}(\mathbb{E}[W_{i,n}|\bR_{n}])^{2}+(\mathbb{E}[W_{n,i}])^{2}\right]\\
            &\leq \frac{2\bar{W}}{n}\left[\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\right)^{2}\right]+1\right],
        \end{align*}
        where the first inequality holds from the inequality $(a-b)^{2}\leq 2(a^{2}+b^{2})$ for any $a,b\in\mathbb{R}$ and the second inequality holds by the uniform boundedness. Note that
        \begin{align*}
            \frac{1}{n}\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\right)^{2}\right]&=\frac{1}{n\rho_n}=o(1).
        \end{align*}

    For \cref{eq:cc_cov},
    \begin{align*}
        \cref{eq:cc_cov}
        &=\frac{1}{n^{2}}\sum_{i=1}^n\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}\mathbb{E}[W_{n,i}|\bR_{n}]-\mathbb{E}[W_{n,i}]\right)\left(\frac{R_{n,j}}{\rho_n}\mathbb{E}[W_{n,j}|\bR_{n}]-\mathbb{E}[W_{n,j}]\right)\right]\\
        &\leq\frac{\bar{W}^2}{n^{2}}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}\mathbb{E}\left[\left|\frac{R_{n,i}}{\rho_n}-1\right|\cdot\left|\frac{R_{n,j}}{\rho_n}-1\right|\right]\\
        &\leq\frac{\bar{W}^2}{n^{2}}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}\mathbb{E}\left[\left(\frac{R_{n,i}}{\rho_n}-1\right)^2\right]\\
        &=\left(\frac{1}{\rho_n}-1\right)\frac{\bar{W}^2}{n^{2}}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}1=O\left(\frac{1}{n\rho_n}\right)\sum_{1\leq s\leq2K}\delta_n^{\partial}(s;1)=o(1),
    \end{align*}
    where the first equality holds by $W_{n,i}\indep R_{n,j}$, $W_{n,i}\indep W_{n,j}$ if $d_{n}(i,j)>2K$, and \cref{asm:sampling}, the first inequality holds by the uniform boundedness, the next inequality holds by the Cauchy-Schwarz inequality, and the last step follows from \cref{asm:sparsity}.

    Combining the arguments for $\cref{eq:cc_var}$ and \cref{eq:cc_cov}, we have shown the convergence \cref{eq:consistency_causal} as $n\to\infty$.
\end{proof}

\begin{lemma}
    \label{lem:LLN_RW}
    Let $W_{n,i}$ be a scalar random variable satisfying $|W_{n,i}|\leq\bar{W}<\infty$ a.s.
    We allow $W_{n,i}$ to depend on $\bR_n$ and $\bD_n$, but assume that $W_{n,i}\indep R_{n,i}$ and $W_{n,i}\indep W_{n,j}$ if $d_n(i,j)>2K$. Then, under \cref{asm:sampling,asm:sparsity},
    \begin{align*}
        \frac{1}{N}\sum_{i=1}^nR_{n,i}\mathbb{E}[R_{n,i}W_{n,i}|\bR_{n}]-\frac{1}{n\rho_n}\sum_{i=1}^n\mathbb{E}[R_{n,i}W_{n,i}]
        &=\frac{1}{N}\sum_{i=1}^nR_{n,i}\mathbb{E}[W_{n,i}|\bR_{n}]-\frac{1}{n}\sum_{i=1}^n\mathbb{E}[W_{n,i}]\\
        &\overset{p}{\to}0.
    \end{align*}
\end{lemma}
\begin{proof}
    The result follows by the same logic as \cref{lem:LLN_RW}.
\end{proof}


\begin{lemma}\label{lem:CLT} 
    Under \cref{asm:sampling,asm:linear,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence},
    \begin{align*}
        \tilde{\Sigma}_{n}^{-1/2}
        \sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i} \overset{d^R}{\longrightarrow} \mathrm{N}(0,I_{d_{\tilde{T}}}).
    \end{align*}
\end{lemma}

\begin{proof}
    We use the Cramer-Wold device and verify \cref{cond:clt} for any given $a\in\mathbb{R}^{|\mathcal{T}|}$.

    First, we will transform the statistics and verify the zero expectation condition.
    The orthogonality condition for $\theta_{n}^{\causample}$ \cref{eq:moment_causalsample} implies
    \begin{align}
        \sum_{i=1}^n R_{n,i}\mathbb{E}\left[\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i} \mid \bR_n\right] &=0.
    \end{align}

    Define $U_{n,i}\equiv R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}-\mathbb{E}\left[R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right]$.
    Then, $\tilde{\Sigma}_{n}^{-1/2}\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}
    =\tilde{\Sigma}_{n}^{-1/2}\sum_{i=1}^{n}U_{n,i}$
    and we have $\mathbb{E}[U_{n,i}\mid\bR_n]=0$ for all $i$.

    By the Cramer-Wold device, it suffices to show that 
    $$
    \frac{\sum_{i=1}^n a^{\prime}U_{n, i}}{\sqrt{a^{\prime}\tilde{\Sigma}_{n}a}} \overset{d^R}{\longrightarrow} \mathrm{N}(0,1)
    $$
    for any $a\in\mathbb{R}^{d_{\tilde{T}}}$ with $a^{\prime}a=1$.

    By \cref{lem:psi_dependency,lem:linear}, $a^{\prime}U_{n, i}$ is conditionally $\psi$-dependent with $\zeta_{n,s}=\mathds{1}\{s\leq 2K\}$ given $\bR_n$.
    The other conditions are assumed in \cref{asm:dependence}.
\end{proof}

\begin{lemma}\label{lem:CLT_causal} 
    Under \cref{asm:exposure,asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity,asm:dependence},
    \begin{align*}
        \Sigma_{n}^{-1/2}
        \sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i} \overset{d}{\to} \mathrm{N}(0,I_{d_{T}}).
    \end{align*}
\end{lemma}
\begin{proof}
    An orthogonality condition for $\theta_{n}^{\causal}$ \cref{eq:moment_causal} implies
    \begin{align}
        \sum_{i=1}^n \mathbb{E}\left[X_{n,i}\varepsilon_{n,i}\right]  &=0.
    \end{align}
    By \cref{asm:linear,asm:exposure} (i),
    \begin{align*}
        X_{n,i}\varepsilon_{n,i}&=X_{n,i}(Y_{n,i}-X_{n,i}'\theta_{n}^{\causal}-Z_{n,i}'\gamma_{n}^{\causal})\\
        &=X_{n,i}T_{n,i}'\theta_{n,i}+X_{n,i}\nu_{n,i}-X_{n,i}X_{n,i}'\theta_{n}^{\causal}
        -X_{n,i}Z_{n,i}'\gamma_{n}^{\causal}.
    \end{align*}
    By \cref{asm:sampling} and the definition of the exposure mapping, $R_{n,i}$ enters only multiplicatively for $T_{n,i}$ and $X_{n,i}=T_{n,i}-\mathbb{E}[T_{n,i}|\bR_n]$.
    By \cref{lem:as_rep,asm:exposure} (ii), each element of $Z_{n,i}$ is multiplicatively in $R_{n,i}$.
    Thus, each element of $X_{n,i}\varepsilon_{n,i}$ is multiplicatively in $R_{n,i}$ by $R_{n,i}^2=R_{n,i}$.
    Combining it with the orthogonality, 
    \begin{align*}
        \sum_{i=1}^{n}\mathbb{E}[R_{n,i}X_{n,i}\varepsilon_{n,i}]=0.
    \end{align*}

    Define $U_{n,i}=R_{n,i}X_{n,i}\varepsilon_{n,i}-\mathbb{E}[R_{n,i}X_{n,i}\varepsilon_{n,i}]$. Then, we have 
    \begin{align*}
        \Sigma_{n}^{-1/2}\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}
        &=\Sigma_{n}^{-1/2}\sum_{i=1}^{n}U_{n,i}+\Sigma^{-1/2}_{n}\sum_{i=1}^{n}\mathbb{E}[R_{n,i}X_{n,i}\varepsilon_{n,i}]\\
        &=\Sigma_{n}^{-1/2}\sum_{i=1}^{n}U_{n,i},
    \end{align*}
    and $\mathbb{E}[U_{n,i}]=0$.

    The other parts of the proof are similar to \cref{lem:CLT}.
\end{proof}

\begin{lemma}
    \label{lem:gamma_consistency}
    Under \cref{asm:linear,asm:sampling,asm:moment,asm:linear_propensity,asm:local,asm:sparsity}, $$\hat{\gamma}_{n}-\gamma_{n}^{\causample}\overset{p^R}{\longrightarrow}0.$$
    If we assume \cref{asm:exposure} additionally, 
    $$\tilde{\gamma}_{n}-\gamma_{n}^{\causal}\overset{p}{\to}0,$$
    where $\tilde{\gamma}_{n}$ is defined in \cref{eq:gamma}.
\end{lemma}

\begin{proof}
    We can show $\hat{\gamma}_{n}-\gamma_{n}^{\causample}\overset{p^R}{\longrightarrow}0$ by \cref{lem:LLN} as the proof for \cref{thm:consistency}.

    Next, we show $\tilde{\gamma}_{n}-\gamma_{n}^{\causal}\overset{p}{\to}0$. 
    By \cref{lem:LLN}, $\tilde{P}_n^{ZZ}\overset{p^R}{\longrightarrow}\mathbb{E}[\tilde{P}_n^{ZZ}|\bR_n]$ and $\tilde{P}_n^{ZY}\overset{p^R}{\longrightarrow}\mathbb{E}[\tilde{P}_n^{ZY}|\bR_n]$.
    By \cref{lem:LLN_W} and \cref{lem:LLN_RW},
    $\mathbb{E}[\tilde{P}_n^{ZZ}|\bR_n]\overset{p}{\to}\Omega_n^{ZZ}$ and $\mathbb{E}[\tilde{P}_n^{ZY}|\bR_n]\overset{p}{\to}\Omega_n^{ZY}$. Thus, we can conclude by the continuous mapping theorem.
\end{proof}

\section{Proofs}
\label{app:proof}
\subsection{Proof of \cref{thm:weakly_causal}}
\begin{proof}
    \cref{lem:as_rep} implies that
    \begin{align*}
        \Omega_{n}^{XZ}=0=\mathbb{E}[(T_{n,i}-\mathbb{E}[T_{n,i}|\bR_n])Z_{n,i}']=0
    \end{align*}
     for large enough $n$.
    Similarly, 
    \begin{align*}
        \tilde{\Omega}_{n}^{XZ}=\mathbb{E}[\tilde{X}_{n,i}\tilde{Z}_{n,i}'|\bR_{n}] 
        = \mathbb{E}[(\tilde{T}_{n,i}-\mathbb{E}[\tilde{T}_{n,i}|\bR_{n}])\tilde{Z}_{n,i}'|\bR_{n}] = 0\quad\text{a.s.}
    \end{align*}
    for large enough $n$ since $\tilde{Z}_{n,i}$ is measurable with respect to $\sigma(\bR_{n})$.

    Therefore, for large enough $n$,
    \begin{align*}
        \theta_{n}^{\causal}&=\left(\Omega_{n}^{XX}\right)^{-1}\Omega_{n}^{XY},
    \end{align*}
    and
    \begin{align*}
        \theta_{n}^{\causample}&=\left(\tilde{\Omega}_{n}^{XX}\right)^{-1}\tilde{\Omega}_{n}^{XY}\quad\text{a.s.}
    \end{align*}
    They are well-defined under \cref{asm:moment}.
    Then, it suffices to show that for large enough $n$,
    \begin{align*}
        \mathbb{E}[X_{n,i}Y_{n,i}]&=\mathbb{E}[X_{n,i}X_{n,i}']\theta_{n,i},
       \end{align*}
    and
    \begin{align*}
        \mathbb{E}[\tilde{X}_{n,i}Y_{n,i}|\bR_{n}]&=\mathbb{E}[\tilde{X}_{n,i}X_{n,i}'|\bR_{n}]\theta_{n,i}\quad\text{a.s.}
    \end{align*}

    The following transformations hold for large enough $n$:
    \begin{align*}
        \mathbb{E}[X_{n,i}Y_{n,i}]&=\mathbb{E}[X_{n,i}T_{n,i}']\theta_{n,i}+ \mathbb{E}[X_{n,i}]\nu_{n,i}\\
        &=\mathbb{E}[X_{n,i}X_{n,i}']\theta_{n,i}+\mathbb{E}[X_{n,i}(T_{n,i}-X_{n,i})']\theta_{n,i}\\
        &=\mathbb{E}[X_{n,i}X_{n,i}']\theta_{n,i}+\mathbb{E}[X_{n,i}]Z_{n,i}'\Lambda_{n}'\theta_{n,i}\\
        &=\mathbb{E}[X_{n,i}X_{n,i}']\theta_{n,i},
    \end{align*}
    where the first equality holds by \cref{asm:linear}, the third equality follows by the definition of $X_{n,i}$, and the last equality follows by $\mathbb{E}[X_{n,i}]=0$, which is implied by \cref{lem:as_rep}. Similarly, the following transformations hold almost surely for large enough $n$:
    \begin{align*}
        \mathbb{E}[\tilde{X}_{n,i}Y_{n,i}]&=\mathbb{E}[\tilde{X}_{n,i}T_{n,i}'|\bR_{n}]\theta_{n,i}+\mathbb{E}[\tilde{X}_{n,i}|\bR_{n}]\nu_{n,i}\\
        &=\mathbb{E}[\tilde{X}_{n,i}X_{n,i}|\bR_{n}]\theta_{n,i}+\mathbb{E}[\tilde{X}_{n,i}(T_{n,i}-X_{n,i})'|\bR_{n}]\theta_{n,i}\\
        &=\mathbb{E}[\tilde{X}_{n,i}X_{n,i}'|\bR_{n}]\theta_{n,i}+\mathbb{E}[\tilde{X}_{n,i}|\bR_{n}]Z_{n,i}'\Lambda_{n}'\theta_{n,i}\\
        &=\mathbb{E}[\tilde{X}_{n,i}X_{n,i}'|\bR_{n}]\theta_{n,i},
    \end{align*}
    where we used $\mathbb{E}[\tilde{X}_{n,i}|\bR_{n}]=0$. This completes the proof.
\end{proof}

\subsection{Proof of \cref{thm:causal_element}}
\begin{proof}
    By the population version of the Frisch-Waugh-Lovell theorem,
    \begin{align*}
        \theta_{n,(k)}^{\causal}=\frac{\sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}Y_{n,i}]}{\sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}^{2}]}
    \end{align*}
    By the linearity of the model (\cref{asm:linear}), the numerator can be transformed as
    \begin{align*}
        \sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}Y_{n,i}]&=\sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}T_{n,i}']\theta_{n,i}+\sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}]\nu_{n,i}\\
        &=\sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}X_{n,i,(k)}]\theta_{n,i,(k)} + \sum_{i=1}^n\mathbb{E}[U_{n,i,(k)}X_{n,i,(-k)}']\theta_{n,i,(-k)},
    \end{align*}
    where the second equality holds as $\mathbb{E}[U_{n,i,(k)}]=0$, which is implied by $\mathbb{E}[X_{n,i}]=0$, a consequence of \cref{lem:as_rep}.

    Similarly,
    \begin{align*}
        \theta_{n,(k)}^{\causample}=\frac{\sum_{i=1}^n\mathbb{E}[\tilde{U}_{n,i,(k)}Y_{n,i}|\bR_{n}]}{\sum_{i=1}^n\mathbb{E}[\tilde{U}_{n,i,(k)}^{2}|\bR_{n}]}.
    \end{align*}
    The numerator is given by
    \begin{align*}
        \sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}Y_{n,i}|\bR_{n}]
        &=\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}T_{n,i}'|\bR_{n}]\theta_{n,i}\\
        &=\sum_{i=1}^nR_{n,i}\sum_{l=1}^{d_{T}}\mathbb{E}[\tilde{U}_{n,i,(k)}X_{n,i,(l)}|\bR_{n}]\theta_{n,i,(l)}.
    \end{align*}
    Under $d_T=d_{\tilde{T}}$, the last equation can be simplified further to
    \begin{align*}
        &\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}X_{n,i,(k)}|\bR_{n}]\theta_{n,i,(k)}+\sum_{i=1}^n\sum_{l\neq k}R_{n,i}\mathbb{E}[\tilde{U}_{n,i,(k)}X_{n,i,(l)}|\bR_{n}]\theta_{n,i,(l)}
    \end{align*}
    as above. This completes the proof.
\end{proof}


\subsection{Proof of \cref{cor:no_contamination}}
\begin{proof}
    By \cref{lem:as_rep},
    \begin{align*}
        &\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(l)}|\bR_{n}]\\
        =&\mathbb{E}[(\tilde{T}_{n,i,(k)}-\mathbb{E}[\tilde{T}_{n,i,(k)}|\bR_{n}])(T_{n,i,(l)}-\mathbb{E}[T_{n,i,(l)}])|\bR_{n}]\\
        =&\mathbb{E}[(\tilde{T}_{n,i,(k)}-\mathbb{E}[\tilde{T}_{n,i,(k)}|\bR_{n}])(T_{n,i,(l)}-\mathbb{E}[T_{n,i,(l)}|\bR_{n}]+\mathbb{E}[T_{n,i,(l)}|\bR_{n}]-\mathbb{E}[T_{n,i,(l)}])|\bR_{n}]\\
        =&\mathbb{E}[(\tilde{T}_{n,i,(k)}-\mathbb{E}[\tilde{T}_{n,i,(k)}|\bR_{n}])(T_{n,i,(l)}-\mathbb{E}[T_{n,i,(l)}|\bR_{n}])|\bR_{n}]\\
        =&\Cov(\tilde{T}_{n,i,(k)},T_{n,i,(l)}|\bR_{n}).
    \end{align*}
    Also,
    \begin{equation*}
        \mathbb{E}[X_{n,i,(k)}X_{n,i,(l)}]
        =\mathbb{E}[(T_{n,i,(k)}-\mathbb{E}[T_{n,i,(k)}|\bR_{n}]))(T_{n,i,(l)}-\mathbb{E}[T_{n,i,(l)}|\bR_{n}]))].
    \end{equation*}

    By the condition stated in \cref{cor:no_contamination}, $\mathbb{E}[X_{n,i,(k)}X_{n,i,(k)}]=0$ and $\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(l)}|\bR_{n}]=0$ for any $k\neq l$.
    By the definition of $U_{n,i,(k)}$ and $\tilde{U}_{n,i,(k)}$, we have $U_{n,i,(k)}=X_{n,i,(k)}$ and $\tilde{U}_{n,i,(k)}=\tilde{X}_{n,i,(k)}$.

    Moreover, the numerator of $\theta_{n,(k)}^{\causample}$ is 
    \begin{align*}
        &\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(k)}|\bR_{n}]\theta_{n,i,(k)}+\sum_{i=1}^n\sum_{l\in\{1,\cdots,d_T\}\setminus \{k\}}R_{n,i}\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(l)}|\bR_{n}]\theta_{n,i,(l)}\\
        =&\sum_{i=1}^nR_{n,i}\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(k)}|\bR_{n}]\theta_{n,i,(k)},
    \end{align*}
    and $R_{n,i}\mathbb{E}[\tilde{X}_{n,i,(k)}X_{n,i,(k)}|\bR_{n}]\geq0$ if we assume that $\Cov(\tilde{T}_{n,i,(k)},T_{n,i,(k)}|\bR_{n})\geq0$.
\end{proof}


\subsection{Proof of \cref{thm:consistency}}
\begin{proof}
    By \cref{lem:as_rep}, we have $\mathbb{E}[\tilde{X}_{n,i}\tilde{Z}_{n,i}|\bR_{n}]=0$ a.s. for large enough $n$. Thus, $\tilde{Q}^{ZX}_{n},\tilde{Q}_{n}^{XZ}\overset{a.s.}{\longrightarrow}0$. Since
    $$
    \left(
    \begin{array}{c}
    \hat{\theta}_{n}\\
    \hat{\gamma}_{n}
    \end{array}
    \right)
    =
    \left(
    \begin{array}{cc}
    \tilde{Q}_{n}^{XX}&\tilde{Q}_{n}^{XZ}\\
    \tilde{Q}_{n}^{ZX}&\tilde{Q}_{n}^{ZZ}
    \end{array}\right)^{-1}
    \left(
    \begin{array}{c}
    \tilde{Q}_{n}^{XY}\\
    \tilde{Q}_{n}^{ZY}
    \end{array}
    \right),
    $$
    \cref{lem:LLN} implies that
    $$
    \hat{\theta}_{n}-\theta_{n}^{\causample}=\hat{\theta}_{n}-(\tilde{\Omega}_{n}^{XX})^{-1}\tilde{\Omega}_{n}^{XY}+o_{p^R}(1)\overset{p^R}{\longrightarrow}0,
    $$
    which further implies
    $$
    \hat{\theta}_{n}-\theta_{n}^{\causample}\overset{p}{\to}0.
    $$
\end{proof}

\subsection{Proof of \cref{thm:causal_consistency}}
\begin{proof}
    By \cref{lem:as_rep}, we have $\mathbb{E}[X_{n,i}Z_{n,i}|\bR_{n}]=0$ a.s. and $\mathbb{E}[X_{n,i}Z_{n,i}]=0$ for large enough $n$.
    Thus, for large enough $n$,
    $\theta_{n}^{\causample}=(\tilde{\Omega}_{n}^{XX})^{-1}\tilde{\Omega}_{n}^{XY}$ a.s. and
    $\theta_{n}^{\causal}=(\Omega_{n}^{XX})^{-1}\Omega_{n}^{XY}$.
    Without loss of generality, assume that the first element of $T_{n,i}$ depends on $R_{n,i}D^*_{n,i}$.
    By \cref{asm:exposure} (i) and (iii), we can treat the first element of $\theta_{n,(1)}^{\causample}$ and  $\theta_{n,(1)}^{\causample}$ the other elements separately as $\theta_{n,(1)}^{\causal}=(\Omega_{n,(1,1)}^{XX})^{-1}\Omega_{n,(1,1)}^{XY}$, 
    $\theta_{n,(-1)}^{\causal}=(\Omega_{n,(-1,-1)}^{XX})^{-1}\Omega_{n,(-1,-1)}^{XY}$, 
    $\theta_{n,(1)}^{\causample}=(\tilde{\Omega}_{n,(1,1)}^{XX})^{-1}\tilde{\Omega}_{n,(1,1)}^{XY}$, and 
    $\theta_{n,(-1)}^{\causample}=(\tilde{\Omega}_{n,(-1,-1)}^{XX})^{-1}\tilde{\Omega}_{n,(-1,-1)}^{XY}$, 
    where $\Omega_{n,(1,1)}$ is the $(1,1)$ element of $\Omega_{n}$ and $\Omega_{n,(-1,-1)}$ is the submatrix of $\Omega_{n}$ except for its first row and first column and $\tilde{\Omega}_{n,(1,1)}$ is defined analogously.
    By  \cref{lem:LLN_W}, 
    \begin{align*}
        \theta_{n,(-1)}^{\causample}=(\tilde{\Omega}_{n,(-1,-1)}^{XX})^{-1}\tilde{\Omega}_{n,(-1,-1)}^{XY}\overset{p}{\to}(\Omega_{n,(-1,-1)}^{XX})^{-1}\Omega_{n,(-1,-1)}^{XY}=\theta_{n,(-1)}^{\causal}
    \end{align*}
    By \cref{lem:LLN_RW}, 
    \begin{align*}
        \theta_{n,(1)}^{\causample}=(\tilde{\Omega}_{n,(1,1)}^{XX})^{-1}\tilde{\Omega}_{n,(1,1)}^{XY}\overset{p}{\to}((1/\rho_n)\Omega_{n,(1,1)}^{XX})^{-1}(1/\rho_n)\Omega_{n,(1,1)}^{XY}=\theta_{n,(1)}^{\causal}
    \end{align*}
    We can conclude by stacking them.
\end{proof}

\subsection{Proof of \cref{thm:normality}}
\begin{proof}
    We have $\tilde{\Omega}_n^{XZ}\overset{a.s.}{\longrightarrow}0$ and $(n\rho_n)/N\overset{a.s.}{\longrightarrow}1$ under the invertibility and the moment conditions.
    Thus,
    \begin{align*}
        &\sqrt{n\rho_n}\left(
        \begin{array}{c}
            \hat{\theta}_{n}-\theta_n^{\causample}\\
            \hat{\gamma}_{n}-\gamma_n^{\causample}
        \end{array}
        \right)\\
        =&
        \left(
        \begin{array}{cc}
            \tilde{Q}_{n}^{XX}&\tilde{Q}_{n}^{XZ}\\
            \tilde{Q}_{n}^{ZX}&\tilde{Q}_{n}^{ZZ}
        \end{array}\right)^{-1}
        \left(
        \begin{array}{c}
            \frac{\sqrt{n\rho_n}}{N}\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\\
            \frac{\sqrt{n\rho_n}}{N}\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{\varepsilon}_{n,i}
        \end{array}
        \right)\\
        =&\left[\left(
    \begin{array}{cc}
        \tilde{Q}_n^{XX} & O \\
        O & \tilde{Q}_n^{ZZ}
    \end{array}\right)^{-1}+o_{p^R}(1)\right]\left(
    \begin{array}{c}
            (1+o_{p^R}(1))\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\\
            (1+o_{p^R}(1))\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{\varepsilon}_{n,i}
        \end{array}
        \right),
    \end{align*}
    and it suffices to show\footnote{
            A random variable $X_n$ is $O_{p^R}(1)$ if for any $\varepsilon>0$, there exist some constant $M_\varepsilon<\infty$ such that
            \begin{align*}
                \mathbb{P}\left(\|X_n\|>M_\varepsilon\mid\bR_n\right)<\varepsilon\quad\text{a.s.}
            \end{align*}
            for large enough $n$.
        }
    \begin{align}
        \frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^n R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}&=O_{p^R}(1),\label{eq:tilde_X_eps}\\
        \frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}\tilde{Z}_{n,i}\tilde{\varepsilon}_{n,i}&=O_{p^R}(1),\label{eq:tilde_Z_eps}\\
        \frac{1}{\sqrt{n\rho_n}}\tilde{\Sigma}_{n}^{-1/2}&=O_{\text{a.s.}}(1)\label{eq:tilde_Sigma_bound}
    \end{align}
    since these conditions imply that 
    \begin{align*}
        &\tilde{\Sigma}_{n}^{-1/2}\tilde{Q}_n^{XX}\left(
            \hat{\theta}_{n}-\theta_n^{\causample}
        \right)\\
        =&\frac{1}{\sqrt{n\rho_n}}\tilde{\Sigma}_{n}^{-1/2}\tilde{Q}_n^{XX}\left(\tilde{Q}_n^{XX}\right)^{-1}\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}+o_{p^R}(1),
    \end{align*}
    and we can conclude the convergence in conditional distribution with \cref{lem:CLT}. The dominated convergence theorem and the law of iterated expectations imply the unconditional result.

    We show \cref{eq:tilde_X_eps}-\cref{eq:tilde_Sigma_bound}.
    By Chebyshev's inequality, it suffices to show that its conditional variance is almost surely bounded.
    \begin{align}
        &\Var\left(\frac{1}{\sqrt{n}}\sum_{i=1}^{n}\frac{R_{n,i}}{\sqrt{\rho_n}}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right)
        \nonumber\\
        =&\frac{1}{n}\sum_{i=1}^{n}\Var\left(\frac{R_{n,i}}{\sqrt{\rho_n}}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right)
        +\frac{1}{n}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}\Cov\left(\frac{R_{n,i}}{\sqrt{\rho_n}}\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i},\frac{R_{n,j}}{\sqrt{\rho_n}}\tilde{X}_{n,j}\tilde{\varepsilon}_{n,j}\mid\bR_n\right)
        \nonumber\\
        \leq&\frac{1}{n}\sum_{i=1}^{n}\frac{R_{n,i}}{\rho_n}\mathbb{E}\left[\tilde{X}_{n,i}\tilde{X}_{n,i}^{\prime}\tilde{\varepsilon}_{n,i}^2\mid\bR_n\right]
        \label{eq:clt_var}\\
        &+\frac{1}{n}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)\setminus\{i\}}\frac{R_{n,i}R_{n,j}}{\rho_n}\left(\mathbb{E}\left[\tilde{X}_{n,i}\tilde{X}_{n,j}^{\prime}\tilde{\varepsilon}_{n,i}\tilde{\varepsilon}_{n,j}\mid\bR_n\right]-\mathbb{E}\left[\tilde{X}_{n,i}\tilde{\varepsilon}_{n,i}\mid\bR_n\right]\mathbb{E}\left[\tilde{X}_{n,j}\tilde{\varepsilon}_{n,j}\mid\bR_n\right]'\right).
        \label{eq:clt_cov}
    \end{align}
    Each element of the first term \cref{eq:clt_var} is almost surely bounded by
    \begin{align*}
        \left(\frac{N}{n\rho_n}\right)\cdot\max_{i}\|\tilde{X}_{n,i}\|^2\cdot\max_{i}|\tilde{
        \varepsilon
        }_{n,i}|^2.
    \end{align*}
    Thus, the first term \cref{eq:clt_var} is $O_{\text{a.s.}}(1)$ by \cref{asm:moment,lem:eps_bound,lem:nNconv}.
    The second term \cref{eq:clt_cov} is also $O_{\text{a.s.}}(1)$ by a similar argument as the first term and \cref{asm:sparsity}.
    Similarly, we can show that \cref{eq:tilde_Z_eps} is $O_{p^R}(1)$. \cref{eq:tilde_Sigma_bound} is also $O_{\text{a.s.}}(1)$ by the invertibility assumption (\cref{asm:moment}). 
\end{proof}

\subsection{Proof of \cref{thm:normality_causal}}
\begin{proof}
    Since $\tilde{X}_{n,i}=X_{n,i}$ and $\tilde{Z}_{n,i}=Z_{n,i}$,
    \begin{align*}
        &\sqrt{n\rho_n}\left(
        \begin{array}{c}
            \hat{\theta}_{n}-\theta_n^{\causal}\\
            \hat{\gamma}_{n}-\gamma_n^{\causal}
        \end{array}
        \right)\\
        =&
        \left(
        \begin{array}{cc}
            \tilde{Q}_{n}^{XX}&\tilde{Q}_{n}^{XZ}\\
            \tilde{Q}_{n}^{ZX}&\tilde{Q}_{n}^{ZZ}
        \end{array}\right)^{-1}
        \left(
        \begin{array}{c}
            \frac{\sqrt{n\rho_n}}{N}\sum_{i=1}^{n}R_{n,i}X_{n,i}(Y_{n,i}-X_{n,i}'\theta_{n}^{\causal}-Z_{n,i}'\gamma_{n}^{\causal})\\
            \frac{\sqrt{n\rho_n}}{N}\sum_{i=1}^{n}R_{n,i}Z_{n,i}(Y_{n,i}-X_{n,i}'\theta_{n}^{\causal}-Z_{n,i}'\gamma_{n}^{\causal})\\
        \end{array}
        \right)\\
        =&\left[\left(
    \begin{array}{cc}
        \tilde{Q}_n^{XX} & O \\
        O & \tilde{Q}_n^{ZZ}
    \end{array}\right)^{-1}+o_{p}(1)\right]\\
    &\qquad\times\left(
    \begin{array}{c}
            (1+o_p(1))\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}\\
            (1+o_p(1))\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}Z_{n,i}\varepsilon_{n,i}
        \end{array}
        \right).
    \end{align*}
    By a similar way to the proof of \cref{thm:normality}, we can show that 
    \begin{align}
        \frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}&=O_p(1),
        \label{eq:X_eps}\\
        \frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}Z_{n,i}\varepsilon_{n,i}&=O_p(1),
        \label{eq:Z_eps}\\
        \frac{1}{\sqrt{n\rho_n}}\Sigma_{n}^{-1/2}&=O_p(1).
        \label{eq:Sigma_bound}
    \end{align}
    Thus, \cref{eq:X_eps,eq:Z_eps,eq:Sigma_bound} imply that 
    \begin{align*}
        \Sigma_{n}^{-1/2}\tilde{Q}_n^{XX}\left(
            \hat{\theta}_{n}-\theta_n^{\causal}
        \right)
        =\frac{1}{\sqrt{n\rho_n}}\Sigma_{n}^{-1/2}\tilde{Q}_n^{XX}\left(\tilde{Q}_n^{XX}\right)^{-1}\frac{1}{\sqrt{n\rho_n}}\sum_{i=1}^{n}R_{n,i}X_{n,i}\varepsilon_{n,i}+o_p(1),
    \end{align*}
    and we can conclude with \cref{lem:CLT_causal}.
\end{proof}

\subsection{Proof of \cref{thm:var_consistency}}
\begin{proof}
    \textbf{[Proof for $\frac{1}{n\rho_n}\tilde{\Sigma}_{n}$]}

    Let 
    \begin{align*}
        \frac{1}{n\rho_n}\tilde{\Sigma}_{n}^{\dagger}
        =\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\right)\left(\tilde{\Psi}_{n,j}-\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]\right)^{\prime}.
    \end{align*}
    Then, \cref{lem:var_consistency} implies that 
    \begin{equation*}
        \frac{1}{n\rho_n}\tilde{\Sigma}_{n}^{\dagger}=\frac{1}{n\rho_n}\tilde{\Sigma}_{n}+o_{p^R}(1).
    \end{equation*}
    Hence, it suffices to show that 
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n
        =&\frac{1}{n\rho_n}\tilde{\Sigma}_{n}^{\dagger}+\tilde{B}_{n}+o_{p^R}(1).
    \end{align*}

    Here, $\max_{i}|\hat{\varepsilon}_{n,i}-\tilde{\varepsilon}_{n,i}|=o_p^{R}(1)$ by \cref{asm:moment,thm:consistency,lem:gamma_consistency}. Also,
    $$\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\tilde{X}_{n,i}\tilde{X}_{n,j}^{\prime}\hat{\varepsilon}_{n,i}\hat{\varepsilon}_{n,j}=O_{\text{a.s.}}(1)$$
    by \cref{asm:moment,asm:sparsity}, $\rho\in(0,1]$, and \cref{lem:eps_bound}.
    Thus, we can show that
    \begin{align}
        \frac{1}{N}\hat{\Sigma}_n
        =&\frac{1}{N}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\hat{\Psi}_{n,i}\hat{\Psi}_{n,j}^{\prime}\nonumber\\
        =&\frac{1}{N}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\tilde{X}_{n,i}\tilde{X}_{n,j}^{\prime}\hat{\varepsilon}_{n,i}\hat{\varepsilon}_{n,j}\nonumber\\
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\tilde{X}_{n,i}\tilde{X}_{n,j}^{\prime}\tilde{\varepsilon}_{n,i}\tilde{\varepsilon}_{n,j}+o_{p^R}(1),\label{eq:hateps_to_tildeeps}
    \end{align}
    where the last equality holds by \cref{lem:nNconv}.

    Then,
    \begin{align}
        \cref{eq:hateps_to_tildeeps}
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}R_{n,j}\tilde{\Psi}_{n,i}\tilde{\Psi}_{n,j}^{\prime}+o_{p^R}(1)\nonumber\\
        =&\frac{1}{n\rho_n}\tilde{\Sigma}_{n}^{\dagger}+\tilde{B}_{n}+o_{p^R}(1)\\
        &+\frac{2}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}
        \left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\right)\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]^{\prime}\mathds{1}\{\tilde{d}_n(i,j)\leq2K\},\label{eq:tilde_psi_rem}
    \end{align}
    thus, it suffices to show that the remainder term $\cref{eq:tilde_psi_rem}=o_{p^R}(1)$.

    We will show it element-wise. Take the $(k,k^{\prime})$-element of \cref{eq:tilde_psi_rem}. Let 
    \begin{align*}
        \tilde{\varphi}_i=\sum_{j=1}^{n}R_{n,j}\mathbb{E}\left[\tilde{\Psi}_{n,j,(k^{\prime})}\mid\bR_n\right]\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}.
    \end{align*}
    Then,
    \begin{align*}
        &\mathbb{E}\left[\left|(k,k^{\prime})\text{-element of }\cref{eq:tilde_psi_rem}\right|\mid\bR_n\right]\\
        =&
        \mathbb{E}\left[\left|\frac{2}{n\rho_n}\sum_{i=1}^{n}R_{n,i}\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i,(k)}\mid\bR_n\right]\right)\tilde{\varphi}_i\right|\mid\bR_n\right]\\
        \leq&\mathbb{E}\left[\left(\frac{2}{n\rho_n}\sum_{i=1}^{n}R_{n,i}\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i,(k)}\mid\bR_n\right]\right)\tilde{\varphi}_i\right)^2\mid\bR_n\right]^{1/2}\\
        \leq&\frac{2}{\rho_n}\left(\frac{1}{n^2}\sum_{i=1}^{n}\Var\left(\tilde{\Psi}_{n,i,(k)}\mid\bR_n\right)\tilde{\varphi}_i^2+\frac{1}{n^2}\sum_{i=1}^{n}\sum_{j\neq i}\left|\Cov\left(\tilde{\Psi}_{n,i,(k)},\tilde{\Psi}_{n,j,(k)}\mid\bR_n\right)\right|\times|\tilde{\varphi}_i\tilde{\varphi}_j|\right)^{1/2},
    \end{align*}
    where the first inequality follows from Jensen's inequality.

    By \cref{asm:moment} and \cref{lem:eps_bound}, $\tilde{\Psi}_{n,i,(k)}$ is uniformly bounded, thus $\max_{i}\Var\left(\tilde{\Psi}_{n,i,(k)}\mid\bR_n\right)=O_{\text{a.s.}}(1)$ and $\tilde{\varphi}_i^2\leq C\times(\sum_{j=1}^{n}\mathds{1}\{\tilde{d}_n(i,j)\leq2K\})^2\leq C\times|\mathcal{N}_{n}(i;2K)|^2$ for some constant $C>0$. Hence,
    $\frac{1}{n^2}\sum_{i=1}^{n}\Var\left(\tilde{\Psi}_{n,i,(k)}\mid\bR_n\right)\tilde{\varphi}_i^2\leq C'\delta_n(2K,2)/n$ for some constant $C'>0$.
    By \cref{asm:var_dependence} (i), $\delta_n(2K,2)/n\to0$ as $n\to\infty$.

    By \cref{lem:psi_dependency}, $\tilde{\Psi}_{n,i,(k)}$ is conditionally $\psi$-dependent with $\xi_{n,s}=\mathds{1}\{s\leq 2K\}$ given $\bR_n$, thus $\left|\Cov\left(\tilde{\Psi}_{n,i,(k)},\tilde{\Psi}_{n,j,(k)}\mid\bR_n\right)\right|\leq C''\times\mathds{1}\{s\leq 2K\}\times\mathds{1}\{d_n(i,j)=s\}$ for some constant $C''>0$. Thus,
    \begin{align*}
        &\frac{1}{n^2}\sum_{i=1}^{n}\sum_{j\neq i}\left|\Cov\left(\tilde{\Psi}_{n,i,(k)},\tilde{\Psi}_{n,j,(k)}\mid\bR_n\right)\right|\times|\tilde{\varphi}_i\tilde{\varphi}_j|\\
        \leq&\frac{C''}{n^2}\sum_{s=1}^{2K}\sum_{i=1}^{n}\sum_{j\neq i}\mathds{1}\{d_n(i,j)=s\}|\tilde{\varphi}_i\tilde{\varphi}_j|\\
        \leq&\frac{C'''}{n^2}\sum_{s=1}^{2K}\mathcal{J}_n(s,2K)
    \end{align*}
    for some constant $C'''>0$.
    By \cref{asm:var_dependence} (ii), $\sum_{s=1}^{2K}\mathcal{J}_n(s,2K)/n^2\to0$ as $n\to\infty$.

    Therefore, we have shown that $\mathbb{E}\left[\left|(k,k^{\prime})\text{-element of }\cref{eq:tilde_psi_rem}\right|\mid\bR_n\right]=o_{p^R}(1)$.
    By Markov's inequality, we can conclude that the remainder term $\cref{eq:tilde_psi_rem}=o_{p^R}(1)$.

    \vspace{20pt}
    \textbf{[Proof for $\frac{1}{n\rho_n}\Sigma_{n}$]}
    Let 
    \begin{align*}
        \frac{1}{n\rho_n}\Sigma_{n}^{\dagger}=\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}\left(R_{n,i}\Psi_{n,i}-\rho_n\mathbb{E}[\Psi_{n,i}]\right)\left(R_{n,j}\Psi_{n,j}-\rho_n\mathbb{E}[\Psi_{n,j}]\right)^{\prime}\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}.
    \end{align*}
    We can show that
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j\in\tilde{\mathcal{N}}_{n}(i,2K)}R_{n,i}\Psi_{n,i}R_{n,j}\Psi_{n,j}^{\prime}+o_p(1)\\
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}\Psi_{n,i}R_{n,j}\Psi_{n,j}^{\prime}\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}+o_p(1)\\
        =&\frac{1}{n\rho_n}\Sigma_{n}^{\dagger}+\hat{B}_n+o_p(1)\\
        &+\frac{2}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}\left(R_{n,i}\Psi_{n,i}-\rho_n\mathbb{E}[\Psi_{n,i}]\right)R_{n,j}\Psi_{n,j}^{\prime}\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}\\
        &+\frac{1}{n}\sum_{i=1}^{n}\sum_{j\in\mathcal{N}_{n}(i,2K)}\rho_n\mathbb{E}[\Psi_{n,i}]\mathbb{E}[\Psi_{n,j}]^{\prime}\left(\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}-\mathbb{P}(\tilde{d}_n(i,j)\leq2K)\right)\\
        =&\frac{1}{n\rho_n}\Sigma_{n}^{\dagger}+\hat{B}_n+o_p(1),
    \end{align*}
    where the first equality follows by the similar arguments as we derive \cref{eq:hateps_to_tildeeps} and by \cref{lem:Lambda}, the second and third equalities are just transformations, and the last equality holds by the similar arguments for the remainder term $\cref{eq:tilde_psi_rem}$.

    Thus, it suffices to show that 
    \begin{align}
        \frac{1}{n\rho_n}\Sigma_{n}^{\dagger}
        =\frac{1}{n\rho_n}\Sigma_n+o_p(1).\label{eq:Sigma_conv}
    \end{align}
    We will show it element-wise. Take the $(k,k^{\prime})$-element of $\frac{1}{n\rho_n}\Sigma_{n}^{\dagger}-\frac{1}{n\rho_n}\Sigma_{n}$. Let 
    \begin{align*}
        \varphi_i=\sum_{j=1}^{n}\left(R_{n,j}\Psi_{n,j,(k^{\prime})}-\rho_n\mathbb{E}[\Psi_{n,j,(k^{\prime})}]\right)\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}.
    \end{align*}
    Then, by the similar arguments for the remainder term $\cref{eq:tilde_psi_rem}$,
    \begin{align*}
        \mathbb{E}\left[\left|(k,k^{\prime})\text{-element of }\frac{1}{n\rho_n}\Sigma_{n}^{\dagger}-\frac{1}{n\rho_n}\Sigma_{n}\right|\right]
        =\frac{1}{n\rho_n}\sum_{i=1}^{n}\left(R_{n,i}\Psi_{n,i,(k)}-\rho_n\mathbb{E}[\Psi_{n,i,(k)}]\right)\varphi_i=o(1).
    \end{align*}
\end{proof}

\subsection{Proof of \cref{thm:var_consistency_eig}}
\begin{proof}
    Let $\frac{1}{N}\hat{\Sigma}_n^{-}=\frac{1}{N}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\hat{\Psi}_{n,i}\hat{\Psi}_{n,j}^{\prime}\tilde{K}_{n,i,j}^{-}$.
    Since $\tilde{K}_n^{+}=\tilde{K}_n+\tilde{K}_n^{-}$,
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n^{+}
        &=\frac{1}{N}\hat{\Sigma}_n+\frac{1}{N}\hat{\Sigma}_n^{-}.
    \end{align*}

    \textbf{[Proof for $\frac{1}{n\rho_n}\tilde{\Sigma}_{n}$]}

    \cref{thm:var_consistency} implies 
    \begin{align*}
        &\frac{1}{N}\hat{\Sigma}_n\\
        =&\frac{1}{n\rho_n}\tilde{\Sigma}_n+\tilde{B}_{n}+o_{p^{R}}(1)\\
        =&\frac{1}{n\rho_n}\tilde{\Sigma}_n+\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]^{\prime}\left(\tilde{K}_{n,i,j}^{+}-\tilde{K}_{n,i,j}^{-}\right)+o_{p^{R}}(1).
    \end{align*}
    By the same logic for the proof of \cref{thm:var_consistency} after replacing $\mathds{1}\{\tilde{d}_n(i,j)\leq2K\}$ by $\tilde{K}_{n,i,j}^{-}$ and \cref{asm:var_dependence} by \cref{asm:var_dependence_eig}, we can show that
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n^{-}
        =&\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]^{\prime}\tilde{K}_{n,i,j}^{-}\\
        &+\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}R_{n,i}R_{n,j}\mathbb{E}\left[\left(\tilde{\Psi}_{n,i}-\mathbb{E}\left[\tilde{\Psi}_{n,i}\mid\bR_n\right]\right)\left(\tilde{\Psi}_{n,j}-\mathbb{E}\left[\tilde{\Psi}_{n,j}\mid\bR_n\right]\right)^{\prime}\mid\bR_n\right]\tilde{K}_{n,i,j}^{-}.
    \end{align*}
    We get the conclusion by combining these results.

    \textbf{[Proof for $\frac{1}{n\rho_n}\Sigma_{n}$]}

    The proof is similar.
    By the same logic for the proof of \cref{thm:var_consistency},
    \begin{align*}
        \frac{1}{N}\hat{\Sigma}_n^{-}
        =&\frac{1}{n}\sum_{i=1}^{n}\sum_{j=1}^{n}\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\mathbb{E}\left[\Psi_{n,j}\right]^{\prime}\mathbb{E}\left[\tilde{K}_{n,i,j}^{-}\right]\\
        &+\frac{1}{n\rho_n}\sum_{i=1}^{n}\sum_{j=1}^{n}\mathbb{E}\left[\left(R_{n,i}\Psi_{n,i}-\rho_n\mathbb{E}\left[\Psi_{n,i}\right]\right)\left(R_{n,j}\Psi_{n,j}-\rho_n\mathbb{E}\left[\Psi_{n,j}\right]\right)^{\prime}\tilde{K}_{n,i,j}^{-}\right].
    \end{align*}
    We get the conclusion by combining it with the result of \cref{thm:var_consistency}.
\end{proof}


    \section{Survey of OLS usage in network experiment applications}\label{app:survey}
    In this section, we summarize our survey of the usage of OLS in network experiment applications in economics. 

    We considered papers published between April 2010 and April 2025 in the following journals: American Economic Review, Econometrica, Quarterly Journal of Economics, Journal of Political Economy, Review of Economic Studies, American Economic Journal: Applied Economics, and Journal of Development Economics. We searched for articles that included both ``networks'' and either ``field experiments'' or ``randomized trial'' as keywords on the Web of Science platform. This search yielded 52 papers, as listed in \cref{tab:survey_summary}. We then reviewed each paper to determine whether it conducted a network experiment and estimated spillover effects using regression. Among these, 29 papers ran regressions to estimate spillover effects; all 29 used the OLS estimator, while only two papers (\citealp{Coutts2022} and \citealp{Fafchamps2013}) mentioned propensity scores or used related estimators.
