\subsection{Exact path simulation for the continuous dynamics}
\label{subsection3.1}

The continuous dynamics of the PDifMP between jumps evolve according to the SDE in \eqref{eq:flow_map}. To simulate these paths exactly, we adopt the method introduced in \cite{beskos2005exact}, which consists of two main steps: first, applying a Lamperti transform to standardise the diffusion coefficient to unity; second, performing a Girsanov measure change to express the transformed process as a Brownian motion under a new probability measure. This approach enables rejection sampling of exact trajectories and is particularly advantageous as it eliminates the discretisation error while preserving the distribution of the original diffusion.\\
\noindent To establish the theoretical foundation for our method, we extend the regularity condition in Assumption~\ref{regularity_assump} by further assuming the following.
\begin{assumption}
    For all $t\in[T_{i},T_{i+1})$ and $y\in \mathbb{R}$ the diffusion coefficient $\sigma(t,y)$ is non-negative.
    \label{assuption_for_Lamperti}
\end{assumption}
\noindent Together with assumption (1) in \ref{Reg_assumption}, they guarantee the existence and invertibility of the Lamperti transform.

\begin{proposition}[Lamperti transformation]
Suppose Assumption~\ref{assuption_for_Lamperti} holds. Define the time-dependent bijective map
\begin{equation*}
  F(t,Y_{t}) := \int^{y} \frac{1}{\sigma(t, y)} dy \bigg|_{y=Y_t},
  \end{equation*}
which transforms $Y_t$ to the process $X_t := F(t,Y_t)$ satisfying
\begin{equation}
dX_t = \alpha(t,X_t)dt + dB_t, \quad   X_0 = F(0, Y_0).
\label{eq:cont_SDE_after_Lamperti}
\end{equation}
Here, the transformed drift $\alpha$ is given by
\begin{equation*}
    \alpha(t,x) = \left.\left(\frac{\partial F}{\partial t}(t, y)+ \frac{\mu(t, y)}{\sigma(t, y)} - \frac{1}{2}\frac{\partial \sigma}{\partial y}(t, y) \right)\right|_{y=F^{-1}(t,x)}.
\end{equation*}
\label{Lampt}
\end{proposition}
\noindent The transformed process $X_t := F(t,Y_t)$ in Proposition ~\ref{Lampt} inherits the same probability space $(\Omega, \mathcal{F}, (\mathcal{F}_t)_{t \geq 0}, \mathbb{P})$ as the original process $Y_t$. To simulate paths of this process exactly, we rely on a change of measure via Girsanov’s theorem. We denote by $C^{1,1}([T_i, T_{i+1}) \times \mathbb{R})$ the set of functions that are continuously differentiable in time and in space. To proceed, we fix a time interval $[T_i, T_{i+1})$ and assume he following regularity conditions on the transformed drift.

\begin{assumption}
\label{assumption_for_girsanov}
The drift function $\alpha : [T_i, T_{i+1}) \times \mathbb{R} \to \mathbb{R}$ satisfies:
\begin{enumerate}[label=(\roman*)]
    \item the Novikov’s condition
    \begin{equation}
        \mathbb{E}_{\mathbb{P}}\left[\exp\left(\frac{1}{2} \int_{T_i}^{T_{i+1}} \alpha^2(t, X_t)\, dt\right)\right] < \infty;
        \label{novik}
    \end{equation}
    \item the drift ${\alpha(t,x) \in C^{1,1}([T_i, T_{i+1}) \times \mathbb{R}) }$ and satisfies the following integrability condition
\begin{equation}
    \mathbb{E}_{\mathbb{P}}\left[\int_{T_i}^{T_{i+1}} \alpha^2(t, X_t)\, dt\right] < \infty.
    \label{integr}
\end{equation}


\end{enumerate}
\end{assumption}
\noindent These conditions ensure that the change of measure is well-defined and that It\^o’s formula can be applied to the exponential weight used in the Exact simulation algorithm.

\begin{theorem}[Girsanov transformation]
\label{thm:girsanov_change_of_measure}
Let $(X_t^{\mathbb{P}})_{t \in [T_i, T_{i+1})}$ be the solution to the SDE \eqref{eq:cont_SDE_after_Lamperti} on the filtered probability space $(\Omega, \mathcal{F}, (\mathcal{F}_t)_{t \geq 0}, \mathbb{P})$, and assume that the drift coefficient $\alpha$ satisfies the conditions in Assumption~\ref{assumption_for_girsanov}. Define a new probability measure $\mathbb{Q}$ via the Radon–Nikodym derivative
\begin{equation}
 \left.\frac{d\mathbb{Q}}{d\mathbb{P}}\right|_{\mathcal{F}_{T_{i+1}}} := M_{T_{i+1}}= \exp\left( \int_{T_i}^{T_{i+1}} \alpha(s, X_s^{\mathbb{P}})\, dB_s - \frac{1}{2} \int_{T_i}^{T_{i+1}} \alpha^2(s, X_s^{\mathbb{P}})\, ds \right).
 \label{exp_mart}
\end{equation}
\noindent Then the following statements hold:
\begin{enumerate}[label=(\roman*)]
    \item Under $\mathbb{Q}$, the process $(X_t^{\mathbb{Q}} := X_t^{\mathbb{P}})$ is an $(\mathcal{F}_t, \mathbb{Q})$-Brownian motion on the interval $[T_i, T_{i+1})$.
      \item For any bounded $\mathcal{F}_{T_{i+1}}$-measurable function $\Psi: \mathbb{R} \to \mathbb{R}$, it holds
    \begin{equation*}
        \mathbb{E}_{\mathbb{P}}[\Psi(X_t^{\mathbb{P}})] = \mathbb{E}_{\mathbb{Q}}\left[\Psi(X_t^{\mathbb{Q}})\, M_{T_{i+1}}\right], \quad \forall\, t \in [T_i, T_{i+1}].
    \end{equation*}  
    \item Define
    \begin{equation*}
        A(t,x) := \int_{X_{T_i}^{\mathbb{Q}}}^{x} \alpha(t, z)\, dz,
    \end{equation*}
    and the correction term $\gamma_2(t,x): [T_i, T_{i+1})\times \mathbb{R} \to \mathbb{R}$ by
    \begin{equation}
           \gamma_2(t,x) := \frac{\partial A}{\partial t}(t,x) + \frac{1}{2} \left( \frac{\partial \alpha}{\partial x}(t,x) + \alpha^2(t,x) \right).
           \label{gamma_2}
    \end{equation}
    Then, for all $t\in [T_{i}, T_{i+1})$ 
    \begin{equation}
      \mathbb{E}_{\mathbb{P}}[\Psi(X_t^{\mathbb{P}})] = 
    \mathbb{E}_{\mathbb{Q}}\left[ \Psi(X_t^{\mathbb{Q}})\, \exp\left( A(T_{i+1}, X_{T_{i+1}}^{\mathbb{Q}}) - \int_{T_i}^{T_{i+1}} \gamma_2(t, X_t^{\mathbb{Q}})\, dt \right) \right].  
    \label{eq:Girsanov1}
    \end{equation}

\end{enumerate}
\end{theorem}
\noindent Equation~\eqref{eq:Girsanov1} shows that expectations under the original measure $\mathbb{P}$ can be computed by reweighting expectations under the auxiliary measure $\mathbb{Q}$,
provided the following regularity conditions hold.
\begin{assumption}
\label{ass:reweighting}
The functional $A $ and the term $\gamma_2$ satisfy the following conditions
\begin{enumerate}[label=(\roman*)]
    \item there exists a constant $A^{+} > 0$ such that
    \begin{equation*}
     \sup_{x \in \mathbb{R}} A(T_{i+1},\, x) \leq A^{+},
    \end{equation*}

    \item the function $\gamma_2(t,x)$ is non-negative for all $ (t,x) \in [T_i, T_{i+1}) \times \mathbb{R}$.

    \item there exists a constant $C> 0$ such that
    \begin{equation*}
         \sup_{(t,x) \in [T_i, T_{i+1}) \times \mathbb{R}} \gamma_2(t,x) \leq C.
    \end{equation*}

\end{enumerate}
\end{assumption}

\noindent Under conditions $(i)-(ii)$ in Assumption~\ref{ass:reweighting}, the weight
\begin{equation}
    \eta^{[1]}(t) := 
    \mathbb{E}_{\mathbb{Q}}\left[\exp\left(A(T_{i+1}, X_{T_{i+1}}^{\mathbb{Q}})\right)\right] 
    \cdot 
    \mathbb{E}_{\mathbb{Q}}\left[\exp\left(-\int_{T_i}^{T_{i+1}} \gamma_2(t, X_t^{\mathbb{Q}})\, dt\right)\right]
    \label{eq:Girsanov1_prob}
\end{equation}
is well-defined.\\
Moreover, the direct evaluation of $\eta^{[1]}(t)$ is not straightforward due to its dependence on the full continuous path of $X^{\mathbb{Q}}$. To overcome this, we apply a Poisson thinning technique that requires only finitely many path evaluations.

