\begin{theorem}[Poisson thinning representation]
Let $\Phi$ be a homogeneous Poisson point process of unit intensity on the rectangle
\begin{equation*}
    B := [T_i, T_{i+1}) \times [0, C] \subset \mathbb{R}^2,
\end{equation*}

where $C > 0$ is the uniform upper bound on $\gamma_2$ from Assumption~\ref{ass:reweighting}. For a given trajectory $(X_t^{\mathbb{Q}})_{t \in [T_i, T_{i+1})}$, define the subgraph of $\gamma_2$ as
\begin{equation*}
    \mathcal{G} := \left\{ (t, s) \in B \,\middle|\, 0 \leq s \leq \gamma_2(t, X_t^{\mathbb{Q}}) \right\}.
\end{equation*}
Further, let $N := \Phi(\mathcal{G})$ be the number of Poisson points lying under the graph of $\gamma_2$. Then, conditional on the trajectory of $X^{\mathbb{Q}}$, we have
\begin{equation*}
    \mathbb{P}\left(N = 0 \,\middle|\, \{X_t^{\mathbb{Q}}\}_{t \in [T_i, T_{i+1})} \right)
= \exp\left( -\int_{T_i}^{T_{i+1}} \gamma_2(t, X_t^{\mathbb{Q}})\, dt \right).
\end{equation*}
\label{thm:poisson_thinning}
\end{theorem}
\noindent Theorem~\ref{thm:poisson_thinning} yields the following computational procedure for simulating sample paths of $X^{\mathbb{P}}$ via reweighted proposals from $X^{\mathbb{Q}}$. The method sequentially generates Brownian proposals and accepts the full path if no Poisson points fall below the rejection curve defined by $\gamma_2$, with an additional acceptance criterion based on the terminal weight $\exp(A(T_{i+1}, X^{\mathbb{Q}}_{T_{i+1}})) $. We refer to \cite{herrmann2023exact,beskos2006retrospective,beskos2005exact} for further details and to Algorithm~\ref{alg:path_sim} for a complete description.

\begin{algorithm}[H]
\caption{Exact simulation of the continuous dynamics of the PDifMP}
\begin{algorithmic}[1]
\State Initialise $t_1 = T_i$, $X_1 = X_{T_i}$, and set $k = 1$.
\While{$t_k < T_{i+1}$}
\vspace{0.1cm}
    \State Sample $E_k \sim \text{Exp}(C)$, $g_k \sim \mathcal{N}(0,1)$, $\mathcal{U}_k \sim U(0,1)$  \Comment{$E_k, g_k$ and $\mathcal{U}_k$ are independent.}
    \vspace{0.1cm}
    \State Set $t_{k+1} \gets \min(t_k + E_k, T_{i+1})$
    \vspace{0.1cm}
    \State Update $X_{k+1} \gets X_k + g_k \cdot \sqrt{t_{k+1} - t_k}$
    \vspace{0.1cm}
    \If{$t_{k+1} < T_{i+1}$ and $\mathcal{U}_k\cdot C < \gamma_2(t_{k+1},X_{k+1})$}
    \vspace{0.1cm}
        \State \textbf{Reject} and restart from Step 1.
        \vspace{0.1cm}
    \EndIf
    \vspace{0.1cm}
    \State $k \gets k + 1$
\EndWhile
\vspace{0.1cm}
\If{$\mathcal{U} \cdot e^{A^+} > \exp(A(T_{i+1},X_k))$}
    \State \textbf{Reject} the final state.
\EndIf
\vspace{0.1cm}
\State \textbf{Return} $\{(t_j,X_j)\}_{j=1,\ldots,k}$ as valid $X^{\mathbb{P}}$ trajectory.
\end{algorithmic}
\label{alg:path_sim}
\end{algorithm}
\noindent We now adapt the Exact simulation framework from this section to compute the FPT for the continuous component of the PDifMP. While the method was originally developed for time-homogeneous SDEs with constant thresholds~\cite{herrmann2019exact}, and later extended to time-dependent thresholds~\cite{khurana2024exact}, our setting involves a more general time and space dependent SDE given in Equation~\eqref{eq:cont_SDE_after_Lamperti}, with a time-varying threshold function $\beta(t)$.
