    \begin{subfigure}[t]{0.46\textwidth}
        \centering
        \includegraphics[width=\linewidth]{Figures/plot_3_alg._Ax_process.png}
        \caption{The distance between the constructed linear threshold and the original threshold $\beta$ is very small at $t_3$ before $T_{i+1}$. We generate a new $t_1$.}
        \label{fig:sub1_alg_cond_BM}
    \end{subfigure}
    \hfill
    \begin{subfigure}[t]{0.46\textwidth}
        \centering
        \includegraphics[width=\linewidth]{Figures/plot_2_alg._Ax_process.png}
        \caption{If $t_1 \geq T_{i+1}$, we reduce the slope and resample $t_1$ for the linear threshold with the new slope.}
        \label{fig:sub2_alg_cond_BM}
    \end{subfigure}
