\begin{algorithm}[h]
\caption{Simulation of a point from a Brownian path conditioned on $\tau^{*}\geq T_{i+1}$}
\label{alg:point_conditional_Brownian}
\begin{algorithmic}[1]
\State \textbf{Input:} initial slope $s < \inf_{t \geq T_i} \beta'(t)$, minimum slope $s_{\text{min}}$, decrement $s_1$, tolerance $\epsilon$, initial value $X^{i}_{T_i}$
\vspace{0.2em}
\Repeat
  \State simulate $t_1$ FPT of Brownian motion to $b_1(t) = s(t - T_i) + \beta(T_i)$ starting at $T_i$
  \If{$t_1 \geq T_{i+1}$}
    \If{$s > s_{\text{min}}$}
      \State decrease slope: $s \gets s - s_1$
    \Else
      \State set $t_c \gets t_1$, $x \gets b_1(t_1)$
      \State \textbf{break} \Comment{accept path and exit}
    \EndIf
  \Else
    \State compute the distance: $d \gets \beta(t_1) - b_1(t_1)$
    \If{$d > \epsilon$}
      \State $j \gets 2$
      \While{$d > \epsilon$}
        \State simulate $t_j$ FPT of Brownian motion to $b_j(t) = s(t - t_{j-1}) + \beta(t_{j-1})$ starting from $t_{j-1}$
        \State $d \gets \beta(t_j) - b_j(t_j)$
        \If{$t_j \geq T_{i+1}$}
          \State \textbf{break} \Comment{exit while-loop}
        \Else
          \State $j \gets j + 1$
        \EndIf
      \EndWhile
      \If{$t_j \geq T_{i+1}$}
        \State set $t_c \gets t_j$, $x \gets b_j(t_j)$
        \State \textbf{break} \Comment{accept path and exit}
      \EndIf
    \EndIf
  \EndIf
\Until{false}
\State \textbf{Output:} $(t_c, x)$, where $x = \beta_c(t_c)$
\end{algorithmic}
\end{algorithm}
\noindent To ensure the well-posedness of the Algorithm~\ref{alg:point_conditional_Brownian}, it is essential to verify that the constructed point $(t_c, \beta_c(t_c))$ indeed belongs to a Brownian path conditioned to stay below the threshold $\beta$ until time $T_{i+1}$. The following theorem establishes the validity of the Algorithm.
\begin{theorem}
\label{thm:valid_alg_2}
Assume that the slope parameter satisfies $s_{\text{min}} = -\infty$. Then, as the tolerance $\epsilon \to 0$, the output $(t_c, \beta_c(t_c))$ of Algorithm~\ref{alg:point_conditional_Brownian} corresponds to a point sampled from a path of Brownian motion conditioned to stay below the threshold up to time $T_{i+1}$, as presented in Equation \eqref{eq:aux_process}.
\end{theorem}

\begin{proof}
The Algorithm~\ref{alg:point_conditional_Brownian} is designed to generate a point $(t_c, \beta_c(t_c))$ from a Brownian path that remains below the threshold $\beta(t)$ up to time $T_{i+1}$. More precisely, it constructs a sequence of linear thresholds $b_j(t)$ with slope $s < \inf_t \beta'(t)$ and simulates the FPTs $t_j$ to these lines, starting from $(t_{j-1}, \beta(t_{j-1}))$, with $t_0 = T_i$. This procedure continues until a time $t_j \geq T_{i+1}$ is reached, and the corresponding linear barrier $b_j$ is denoted by $\beta_c$. The final output is the point $(t_c, \beta_c(t_c)) := (t_j, b_j(t_j))$. Therefore, we aim to show here that in the limit as $\epsilon \to 0$ and $s_{\text{min}} = -\infty$, the law of the process 
\begin{equation*}
 \{W_t \mid t \in [T_i, t_c],\ W_{t_c} = \beta_c(t_c),\ t_c \geq T_{i+1} \}   
\end{equation*}
coincides with that of the Brownian motion conditioned to stay below $\beta$ until $T_{i+1}$, i.e., the process defined in Equation \eqref{eq:aux_process}.
By the definition of the accepted point $t_c$, we have that $t_c \geq T_{i+1}$ and $W_t < \beta(t)$ for all $t \in [T_i, t_c)$. Therefore, the simulated paths satisfy $\tau^{*} > T_{i+1}$ and hence we have that
\begin{equation*}
  \text{sample paths of } \{W_t \mid t_c \geq T_{i+1},\ W_{t_c} = \beta_c(t_c)\}
\subseteq
\text{sample paths of } \{W_t \mid \tau^* \geq T_{i+1}\}.  
\end{equation*}
Now, consider the probability,
\begin{equation*}
 \mathbb{P}\{W_t \mid t_c \geq T_{i+1} ,\beta_c(t_c) = W_{t_c}\}.    
\end{equation*}
The pair $(t_j,b_j)$ for $j\geq 2$ is constructed by tracking the Brownian path such that each $t_j$ satisfies $b_{j}(t_j)=W_{t_j}$. Thus, $\beta_c(t_c)=W_{t_c}$ is a sure event except if we choose $t_c=t_1$, in which case $b_1$ is fixed. Since we start with the fixed slope $s$ and a fixed initial point $\beta(T_i)$ for $b_1$, assuming that FPT to $b_1$ is finite would introduce bias. To avoid this, the algorithm reduces the slope if $t_1\geq T_{i+1}$, repeating this step as needed.\\
Therefore if we do not impose any restriction on the minimum slope, i.e. if $s_\text{min}=-\infty$, this ensures that $t_1<T_{i+1}$ and hence
\[
\beta_c(t_c)=W_{t_c}
\]
is a sure event. Consequently we can write:
\[
\mathbb{P}\{W_t \mid t_c \geq T_{i+1} ,\beta_c(t_c) = W_{t_c}\}=\mathbb{P}\{W_t \mid t_c \geq T_{i+1}\}.
\]
The probability on the right describes the path of Brownian motion which stays below the threshold $\beta$ at least until time $t_c$. On the other hand, the process defined in \eqref{eq:aux_process} corresponds to Brownian motion conditioned to stay below $\beta$ until $\tau^*$. If the crossing from $\beta$ is detected exactly, then both probabilities are equivalent on the interval $[T_i,t_c]$, i.e.
\[
  \mathbb{P}\{W_t \mid t_c \geq T_{i+1}\} = \mathbb{P}\left\{ W_t \,\middle|\, \tau^{*} \geq T_{i+1} \right\} \qquad t\in[T_i,t_c].
\]
Accurate detection of threshold crossing is essential. For instance, if a large $\epsilon$ is chosen, the algorithm may falsely reject paths that actually remain below $\beta$ until $T_{i+1}$. These paths would be valid under the law of the auxiliary process $\{W_t \mid \tau^*\geq T_{i+1}\}$ but would be wrongly excluded by the algorithm. Hence, precise detection of crossings is crucial to ensure convergence to the correct conditional law.
%Further, as $\epsilon \to 0$, the algorithm detects any threshold crossing, meaning that the event $W_t < \beta(t)$ on $[T_i, t_c]$ is ensured. Also, if we allow $s_{\text{min}} \to -\infty$, the algorithm can always reduce the slope sufficiently to ensure a finite FPT $t_c \geq T_{i+1}$ is eventually reached. This avoids any forced acceptance that might occur if the algorithm were constrained by a minimal admissible slope, ensuring that only paths satisfying the conditioning criterion are accepted.\\
%As a result, in the joint limit $\epsilon \to 0$ and $s_{\text{min}} \to -\infty$, the algorithm samples from the correct support of the conditional law:
%\begin{equation*}
% \lim_{\substack{\epsilon \to 0 \\ s_{\text{min}} \to -\infty}} \mathbb{P}(W_t \mid t_c \geq T_{i+1},\ W_{t_c} = \beta_c(t_c)) = 
%\mathbb{P}(W_t \mid \tau^* \geq T_{i+1}).   
%\end{equation*}
%\noindent Finally, we emphasise that conditioning on the endpoint value $W_{t_c} = \beta_c(t_c)$ does not affect the distribution of the Brownian path on the interval $[T_i, t_c)$, since:
%\begin{enumerate}
   % \item If $j = 1$ and $b_1(t)$ is fixed, then forcing $W_{t_1} = b_1(t_1)$ would introduce a bias unless we ensure that $t_c \geq t_2$ by further reducing the slope. Allowing $s_{\text{min}} \to -\infty$ ensures this.
   % \item If $j \geq 2$, then $b_j(t)$ is constructed based on the realised path, so conditioning on $W_{t_c} = b_j(t_c)$ simply reflects the stopping criterion.
%\end{enumerate}
%Therefore, in either case, the path remains valid under the conditional law.
\end{proof}

