\noindent Now that a valid point $(t_c, \beta_c(t_c))$ has been sampled, the next step is to simulate the entire Brownian trajectory on the time interval $[T_i, t_c]$ that stays below the threshold $\beta$ and passes exactly through this point $(t_c, \beta_c(t_c))$.\\
\noindent To construct such a path, we use the fact that the following process
\begin{equation*}
  R_h = \beta(t_c - h) - W_{t_c - h}, \qquad 0 \leq h \leq t_c - T_i,  
\end{equation*}
is a Bessel bridge. We start by simulating a Bessel bridge $R_h$ on $[0, t_c - T_i]$ starting at
\begin{equation*}
R_0 = \beta(t_c) - \beta_c(t_c),    
\end{equation*}
and ending at
\begin{equation*}
 R_{t_c - T_i} = \beta(T_i) - X^{i,\infty}_{T_i}.   
\end{equation*}
After generating the Bessel bridge $R_h$, we invert the transformation to recover the Brownian path $W_t$ over $[T_i, t_c]$. This path will be our \emph{auxiliary process} for the rejection sampling algorithm.
\begin{remark}
One might consider directly using the FPT $\tau_{\beta}^{\text{cont}, i}$ and generating a Bessel bridge on $[T_i, \tau_{\beta}^{\text{cont}, i}]$ starting at $0$ and ending at $\beta(T_i) - W_{T_i}$. However, this would lead to biased sampling because it excludes Brownian paths that remain strictly below the threshold and never hit it.
\end{remark}
\noindent We now turn to the key ingredient of the Exact simulation method: the \emph{rejection probability}. While we are ultimately interested only in the value of the process at time $T_{i+1}$, the acceptance-rejection step must be performed on the entire path over $[T_i, t_c]$, since the law of the auxiliary process depends on its endpoint at $t_c$.\\
\noindent Following again the Girsanov-based framework introduced in \cite{beskos2005exact,beskos2006retrospective,herrmann2019exact}, the acceptance probability is derived from a change of measure between the diffusion process and the auxiliary Brownian motion. In this setting, for any bounded measurable functional $\Psi$, we have
\begin{equation*}
\mathbb{E}_{\mathbb{P}}\left[\Psi\left(X^{i,\infty}_t\right)_{T_i \leq t \leq t_c} \right] = 
\mathbb{E}_{\mathbb{Q}}\left[\Psi\left(\tilde{X}^i_t\right)_{T_i \leq t \leq t_c} \cdot \eta^{[2]}(t)\right],    
\end{equation*}
where
\begin{equation}
\eta^{[2]}(t) = \exp\left(
A\left(t_c,\,( \tilde{X}^i_{t_c}, z_i)\right)
- \int_{T_i}^{t_c} \gamma_2\left(t,\, (\tilde{X}^i_t, z_i)\right) \, dt
\right)
\end{equation}
is the rejection probability.\\
\noindent
As discussed in Subsection~\ref{subsection3.2}, directly evaluating the acceptance probability $\eta^{[2]}(t)$ is not feasible in closed form. Therefore, we employ a Poisson thinning representation that allows the acceptance or rejection of a path based on finitely many sampled time points over the interval $[T_i, t_c]$. However, with this approach it is not guaranteed that one of the sampled points coincides exactly with the jump time $T_{i+1}$, which is essential in our context.\\
\noindent To address this, we decompose the Girsanov weight in the interval $[T_i, t_c]$ as follows. First, we have
\begin{align*}
\mathbb{E}_{\mathbb{P}}\left[\Psi\left(X_t^{i,\infty}\right)_{T_i \leq t \leq t_c}\right]
= \mathbb{E}_{\mathbb{Q}}\Bigg[
\Psi\left(\tilde{X}^i_t\right) \exp\Bigg(
\int_{T_i}^{t_c} \alpha\big(t,\,(\tilde{X}^i_t, z_i)\big) \, dB_t 
- \frac{1}{2} \int_{T_i}^{t_c} \alpha^2\big(t,\, ( \tilde{X}^i_t, z_i)\big) \, dt
\Bigg)
\Bigg].
\end{align*}
\noindent We then split the integrals at $T_{i+1}$ as follows
\begin{align*}
\mathbb{E}_{\mathbb{P}}\left[\Psi\left(X_t^{i,\infty}\right)_{T_i \leq t \leq t_c}\right]
= \mathbb{E}_{\mathbb{Q}}\Bigg[
\Psi\left(\tilde{X}^i_t\right) \exp\Bigg(
&\int_{T_i}^{T_{i+1}} \alpha\big(t,\, (\tilde{X}^i_t, z_i)\big) \, dB_t 
- \frac{1}{2} \int_{T_i}^{T_{i+1}} \alpha^2\big(t,\, (\tilde{X}^i_t, z_i)\big) \, dt \\[0.22cm]
+ &\int_{T_{i+1}}^{t_c} \alpha\big(t,\, ( \tilde{X}^i_t, z_i)\big) \, dB_t 
- \frac{1}{2} \int_{T_{i+1}}^{t_c} \alpha^2\big(t,\, ( \tilde{X}^i_t, z_i)\big) \, dt
\Bigg)
\Bigg].
\end{align*}
\noindent Applying Itô's formula to the function $A(t,\,(x, z_i))$ yields the following decomposition:
\begin{align}
\mathbb{E}_{\mathbb{P}}\left[\Psi\left(X_t^{i,\infty}\right)\right]
= & \; \mathbb{E}_{\mathbb{Q}}\left[\Psi\left(\tilde{X}^i_t\right)\right]
\cdot \exp\Big({-A\big(T_i,\,( \tilde{X}^i_{T_i}, z_i)\big)}\Big) \cdot
\mathbb{E}_{\mathbb{Q}}\left[\exp\left(-\int_{T_i}^{T_{i+1}} \gamma_2\big(t,\, (\tilde{X}^i_t, z_i)\big) \, dt \right)\right] \notag \\[0.31cm]
& \cdot \mathbb{E}_{\mathbb{Q}}\left[\exp\Big({A\big(T_{i+1},\, (\tilde{X}^i_{T_{i+1}}, z_i)\big)}\Big)\right] 
\cdot \exp\Big({-A\big(T_{i+1}, \, (\tilde{X}^i_{T_{i+1}}, z_i)\big)}\Big) \notag \\[0.3cm]
& \cdot \mathbb{E}_{\mathbb{Q}}\left[\exp\left(-\int_{T_{i+1}}^{t_c} \gamma_2\big(t,\, (\tilde{X}^i_t, z_i)\big) \, dt \right)\right] \cdot \mathbb{E}_{\mathbb{Q}}\left[\exp\Big({A\big(t_c,\,( \tilde{X}^i_{t_c}, z_i)\big)}\Big)\right].
\end{align}
\noindent This decomposition shows that the overall rejection probability can be broken down into four distinct components, each of which must be evaluated separately.
\begin{itemize}
    \item[1.] Rejection probability on $[T_i, T_{i+1}]$:
    \begin{equation*}
        \mathbb{E}_{\mathbb{Q}}\left[\exp\left(-\int_{T_i}^{T_{i+1}} \gamma_2\big(t,\, (\tilde{X}^i_{t}, z_i)\big) \, dt\right)\right].
    \end{equation*}
    This term can be computed using Poisson thinning, as in \cite{beskos2006retrospective}, applying Theorem~\ref{thm:poisson_thinning} with substitutions $\gamma_1 + \gamma_2 \mapsto \gamma_2$, $\kappa \mapsto \kappa_2$, and $\mathcal{T}_\beta \mapsto T_{i+1}$, where $\kappa_2 \geq \sup \gamma_2$.

    \item[2.] Acceptance weight at time $T_{i+1}$:
    \begin{equation*}
\mathbb{E}_{\mathbb{Q}}\left[\exp\Big({A\big(T_{i+1},\, (\tilde{X}^i_{T_{i+1}}, z_i)\big)}\Big)\right].
    \end{equation*}


    \item[3.] Rejection probability on $[T_{i+1}, t_c]$:
    \begin{equation*}
        \mathbb{E}_{\mathbb{Q}}\left[\exp\left(-\int_{T_{i+1}}^{t_c}  \gamma_2\big(t,\, (\tilde{X}^i_{t}, z_i)\big) \, dt\right)\right],
    \end{equation*}
    which is again evaluated via thinning on the interval $[T_{i+1}, t_c]$.

    \item[4.] Acceptance weight at final time $t_c$:
    \begin{equation*}
     \mathbb{E}_{\mathbb{Q}}\left[\exp\Big({A\big(t_{c},\, (\tilde{X}^i_{t_{c}}, z_i)\big)}\Big)\right].   
    \end{equation*}
\end{itemize}

\noindent All four components must yield sufficiently high values to accept the auxiliary process \eqref{eq:aux_process}. If any one of them results in a rejection, a new candidate point $(t_c, \beta_c(t_c))$ is generated via Algorithm~\ref{alg:point_conditional_Brownian}, and the process is restarted with a new Brownian trajectory.\\
\noindent To ensure the well-posedness of the rejection probability and the validity of the thinning method, we impose the following conditions.

\begin{assumption}
\label{ass:kappa2andA+}
\begin{enumerate}[label=(\roman*)]
    \item The function $\gamma_2$ is uniformly bounded:
    \begin{equation*}
        0 \leq \gamma_2\left(t, (x, z_i)\right) \leq \kappa_2.
    \end{equation*}

    \item The function $A(t,\,(x,z_i))$ is bounded above by a constant $A^+ > 0$.
\end{enumerate}
\end{assumption}
\begin{algorithm}[H]
\caption{Exact simulation of the diffusion $X^{i,\infty}$ at $T_{i+1}$ conditioned on $\tau^{*}\geq T_{i+1}$}
\label{alg:trajectory of continuous part until jump}
\begin{algorithmic}[1]
\State \textbf{Input:} $(t_c,\beta_c(t_c)) \sim$ Algorithm~\ref{alg:point_conditional_Brownian}, \quad $\kappa_2 \geq \sup_{(t,x)} \gamma_2(t,\,(x,z))$ and $X^{i,\infty}_{T_i}$
\vspace{0.5em}
\Function{Rejection-Sampling}{$t_{\text{start}}, t_{\text{end}}, x_{\text{start}}$}
    \State initialise: $l \gets c\big((\beta(t_c) - \beta_c(t_c)),\, 0, 0\big)$, \quad $\mathcal{E}_0 \gets 0$, \quad $\mathcal{E}_1 \gets \text{Exp}(\kappa_2)$, \quad $\mathcal{W} \gets 0$
    \While{$\mathcal{E}_1 < \big(t_{\text{end}} - t_{\text{start}}\big)$ and $\mathcal{W} = 0$}
        \State Sample $G \sim \mathcal{N}(0, I_3)$, \quad $e \sim \text{Exp}(\kappa_2)$, \quad $\mathcal{U} \sim \mathcal{U}(0,1)$
        \State update:
        \begin{equation*}
        l \gets \frac{(t_c - t_{\text{start}}) - \mathcal{E}_1}{(t_c - t_{\text{start}}) - \mathcal{E}_0} \cdot l + \sqrt{\frac{((t_c - t_{\text{start}}) - \mathcal{E}_1)(\mathcal{E}_1 - \mathcal{E}_0)}{(t_c - t_{\text{start}}) - \mathcal{E}_0}} \cdot G   \end{equation*}
        \begin{equation*}
            \xi \gets \beta(\mathcal{E}_1 + t_{\text{start}}) - \left\| \dfrac{\mathcal{E}_1(\beta(t_{\text{start}}) - x_{\text{start}})}{t_c - t_{\text{start}}} \right\|
        \end{equation*}

        \If{$\kappa_2 \cdot \mathcal{U} \leq \gamma_2\big((\mathcal{E}_1 + t_{\text{start}}),\,(\xi,z_i)\big)$}
            \State $\mathcal{W} \gets 1$
        \Else
            \State $\mathcal{E}_0 \gets \mathcal{E}_1$, \quad $\mathcal{E}_1 \gets \mathcal{E}_1 + e$
        \EndIf
    \EndWhile
    \State \Return $(\mathcal{W}, \mathcal{E}_1, l)$
\EndFunction

\vspace{0.7em}
\State $(\mathcal{W}, \mathcal{E}_1, l) \gets$ \Call{Rejection-Sampling}{$T_i$, $T_{i+1}$, $X^{i,\infty}_{T_i}$} \Comment{sampling over $[T_i, T_{i+1}]$}
\If{$\mathcal{W} = 0$ and $\mathcal{E}_1 \geq (T_{i+1} - T_i)$}
\vspace{0.4em}
    \State $x_j \gets \beta(T_{i+1}) - \left\| \dfrac{(T_{i+1} - T_i)(\beta(T_i) - X^{i,\infty}_{T_i})}{t_c - T_i} \right\|$
\vspace{0.3em}    
    \State Sample $\mathcal{U} \sim \mathcal{U}(0,1)$
    \If{$\mathcal{U} \cdot e^{A^+} > e^{A\big(T_{i+1}, (x_j, z_i)\big)}$} \Comment{evaluation at $T_{i+1}$}
        \State $\mathcal{W} \gets 1$
        \State restart with a new $(t_c, \beta_c(t_c))$
    \EndIf
\Else
    \State restart with a new $(t_c, \beta_c(t_c))$
\EndIf

\If{$\mathcal{W} = 0$}
    \State $(\mathcal{W}, \mathcal{E}_1, l) \gets$ \Call{Rejection-Sampling}{$T_{i+1}$, $t_c$, $x_j$} \Comment{sampling over $[T_{i+1}, t_c]$}
    \If{$\mathcal{W} = 0$ and $\mathcal{E}_1 \geq t_c - T_{i+1}$}
        \State sample $\mathcal{U} \sim \mathcal{U}(0,1)$
        \If{$\mathcal{U} \cdot e^{A^+} > e^{A\big(t_c,\,( \beta_c(t_c), z_i)\big)}$} \Comment{evaluation at $t_c$}
            \State $\mathcal{W} \gets 1$
            \State restart with a new $(t_c, \beta_c(t_c))$
        \EndIf
    \EndIf
\EndIf
\State \textbf{Output:} $x_j$
\end{algorithmic}
\end{algorithm}


\subsection{Exact algorithm for the FPT of PDifMPs}
We now combine the components developed in the previous sections into a unified scheme for the exact simulation of the FPT of a PDifMP to a time-dependent threshold. This algorithm extends the diffusion-based methods of \cite{khurana2024exact,herrmann2019exact} and the jump-diffusion framework of \cite{herrmann2023exact} to the more general setting of PDifMPs.
\noindent The procedure is built on a piecewise recursive strategy that alternates between continuous diffusion phases and discrete jump updates. The core simulation tasks are:
\begin{itemize}
    \item[(i)] sampling the FPT $\tau_{\beta}^{\text{cont}, i}$ of the auxiliary diffusion $X^{i,\infty}$, using a Girsanov-based Exact method adapted to time- and space-dependent SDEs, see Subsection~\ref{subsection3.2}.

    \item[(ii)] simulating the diffusion value at the next jump time, conditioned on no threshold crossing before the jump. This requires constructing an auxiliary process and a tailored rejection step to account for the conditional structure and time-dependent threshold, see Subsection~\ref{subsection3.3}.
\end{itemize}
\noindent Bringing all of these steps together yields an Exact algorithm for simulating the FPT of the PDifMP $(U_t)_{t\geq 0}$. To ensure termination even when the process does not reach the threshold in finite time, in the following Algorithm~\ref{alg:final algorithm} we introduce a fixed terminal time $T_f$. The output is then the FPT if it occurs before $T_f$, and $T_f$ otherwise.
\begin{algorithm}[H]
\caption{Exact simulation of the FPT with terminal time $T_f$}
\label{alg:final algorithm}
\begin{algorithmic}[1]
\State Initialise: terminal time $T_f$, jump index $i \gets 0$, $T_0 \gets 0$, $X^{i,\infty}_{T_{i}}=x_i$, \texttt{crossing} $\gets$ \texttt{FALSE}
\Repeat
    \State sample exponential waiting time $\omega \sim \text{Exp}(\lambda)$ and set $T_{i+1} \gets T_i + \omega$
    \If{$T_i \geq T_f$} 
        \State \texttt{crossing} $\gets$ \texttt{TRUE}, \quad $\tau \gets T_f$
    \Else
        \State simulate $\tau_1 \sim$ Algorithm \ref{alg:fpt_simulation}
        \If{$T_f \leq T_{i+1}$ \textbf{and} $\tau_1 > T_f$}
            \State \texttt{crossing} $\gets$ \texttt{TRUE}, \quad $\tau \gets T_f$
        \EndIf
        \If{$\tau_1 < \min(T_{i+1}, T_f)$}
            \State \texttt{crossing} $\gets$ \texttt{TRUE}, \quad $\tau \gets \tau_1$
        \EndIf  
        \If{$T_f > T_{i+1} \text{ and } \tau_1 \geq T_{i+1}$}
        \Comment{ FPT did not occur before the next jump. Simulate the process at $T_{i+1}$}
            \If{$\tau_1 = T_{i+1}$}
                \State $x_j \gets \beta(T_{i+1})$
            \Else    
                \State $x_j \sim$ Algorithm \ref{alg:trajectory of continuous part until jump}
            \EndIf 
            \State sample $z_i\sim \mathcal{Q}$
             \State compute tracking state: $Y^{i,\infty}_{T_{i+1}} \gets {F^i}^{-1}\big(T_{i+1},\, (x_j, z_i)\big)$
             \vspace{0.2em}
            \State add jump: $Y^{i+1}_{T_{i+1}} \gets Y^{i,\infty}_{T_{i+1}} + j\big(T_{i+1},\, Y^{i,\infty}_{T_{i+1}}, z_i\big)$
            \vspace{0.25em}
            \State transform: $X^{{i+1},\infty}_{T_{i+1}} \gets F^{i+1}\big(T_{i+1},\, (Y^{i+1}_{T_{i+1}}, z_i)\big)$
            \vspace{0.2em}
            \If{$X^{i+1,\infty}_{T_{i+1}} \geq \beta(T_{i+1})$}
                \State \texttt{crossing} $\gets$ \texttt{TRUE}, \quad $\tau \gets T_{i+1}$
            \Else  \qquad $i\gets i+1$    
            \EndIf    
        \EndIf    
    \EndIf
\Until{\texttt{crossing} = \texttt{TRUE}}
\State \textbf{Output:} $\tau$
\end{algorithmic}
\end{algorithm}
\begin{remark}
At each jump time $T_{i+1}$, the continuous component of the PDifMP undergoes a discrete jump. Since the auxiliary process $X^{i,\infty}$ evolves without jumps, we first recover the pre-jump value of the underlying diffusion $Y^{i,\infty}_{T_{i+1}}$ via the inverse Lamperti transform. The jump size is then added to obtain the post-jump value $Y^{i+1}_{T_{i+1}}$, which serves as the initial condition for the next inter-jump interval. Finally, we reapply the Lamperti transform to define $X^{i+1,\infty}$. This ensures the correct initialisation of the next interval in the piecewise simulation.
\end{remark}
\begin{theorem}
Assume that Assumptions \ref{ass: on drift}–\ref{ass:kappa2andA+} hold, and let $s_{\text{min}} = -\infty$. Then, as $\epsilon \to 0$, the distribution of the output of Algorithm~\ref{alg:final algorithm}, i.e. $\tau$, converges in law to the distribution of $\min( \tau_{\tilde{\beta}}, T_f)$, where $\tau_{\tilde{\beta}}$ denotes the FPT of the PDifMP to the threshold $\tilde{\beta}$.
\label{final_thm}
\end{theorem}
\begin{proof}
Since Algorithm~\ref{alg:final algorithm} is a coupling of several steps, the proof of Theorem~\ref{final_thm} follows by combining already well established results. We outline the main arguments here.

\begin{enumerate}[label=(\roman*)]
    \item \emph{Exact FPT sampling.} The simulation of the FPT $\tau_{\beta}^{\text{cont}, i}$ of the tracking diffusion $X^{i,\infty}$ is exact, based on the method introduced in \cite{khurana2024exact, herrmann2019exact}, adapted here to account for time- and space-dependent coefficients via a modified rejection probability.

    \item \emph{Conditional value at jump time.} The simulation of $X^{i,\infty}_{T_{i+1}}$ conditioned on $\tau_{\beta}^{\text{cont}, i} \geq T_{i+1}$ is treated using an auxiliary process and a tailored acceptance-rejection strategy. As shown in Theorem~\ref{thm:valid_alg_2}, the distribution of this approximation converges to the exact conditional law as $\epsilon \to 0$ and $s_{\text{min}} \to -\infty$.

    \item \emph{Recursive structure.} The combination of components (i) and (ii) within the hybrid recursive framework follows the structure presented in \cite{herrmann2023exact}, ensuring that the overall algorithm remains consistent with the target distribution of the FPT.
\end{enumerate}
\noindent Therefore, it is straightforward to show that Algorithm~\ref{alg:final algorithm} produces samples whose distribution converges to that of $\tau_\beta \wedge T_f$ in the limit $\epsilon \to 0$. \qedhere
\end{proof}

\section{Numerical examples}
\label{Numa_exp}


In this section, we apply Algorithm~\ref{alg:final algorithm} to simulate the FPT of a PDifMP in two illustrative examples. To evaluate the accuracy of our method, we compare the results with those obtained using the classical Euler-Maruyama scheme with a fine time discretisation. We present the estimated FPT densities for both approaches and perform statistical tests to  quantify how close the two methods are.

\begin{remark}
Throughout the examples, we assume a constant jump rate $\lambda$. This guarantees the integrability condition~\eqref{eq:lambda_integrability} and the finite-jump condition~\eqref{jump_count}. The results can be extended to time dependent $\lambda$.
\end{remark}

\noindent Algorithm~\ref{alg:final algorithm} depends on two parameters, $\epsilon$ and $s_{\text{min}}$, which influence the accuracy of the simulated FPT. In the examples below, we examine the effect of $s_{\text{min}}$ by varying its value and observing its impact on the resulting density estimates and test outcomes. This complements the theoretical analysis established in Theorem~\ref{thm:valid_alg_2}.

\begin{remark}
We do not explicitly study the impact of the parameter $\epsilon$, as previous works, see for instance \cite{herrmann2016first, khurana2024exact}, already demonstrates that the algorithm accurately detects threshold crossings in the limit $\epsilon \to 0$. Consequently, taking $\epsilon$ sufficiently small guarantees precision in the hitting time estimates.
\end{remark}

\subsection*{Example 1: time-homogeneous PDifMP}
As a first example, we consider a time-homogeneous PDifMP $U_t = (Y_t, Z_t)$ defined by the following dynamics. Let $T_f$ be a deterministic final time, for all $t$ in the inter-jump time intervals $\in [T_{i}, T_{i+1})$, the continuous dynamics of the process $U_t$ are given by

\begin{equation}
   \left\{
\begin{array}{ll}
  dY^{i}_{t} = \big(1.6 + \sin(Y^{i}_{t})\big)\,dt + dB_t, & \quad t \in [T_{i}, T_{i+1}), \\[0.65em]
  dZ^{i}_{t} = 0, & 
\end{array}
\right.
\label{first_exp}
\end{equation}
with initial condition $Y^0_0 = -1$. At jump times $T_{i+1}$ the process is updated as follows:

\begin{equation*}
   \left\{
\begin{array}{ll}
  Y^{i+1}_{T_{i+1}} = Y^{i}_{T_{i+1}} - z_i \sin(Y^{i}_{T_{i+1}}), & \\[0.65em]
  Z^{i+1}_{T_{i+1}} = z_i, & \quad \text{with } z_i \sim \text{Exp}(1)
\end{array}
\right.
\end{equation*}
The characteristic triple $(\phi, \lambda, \mathcal{Q})$ of the PDifMP $U_t$ is given by
\begin{equation}
	\label{charc}
	\left\{
	\begin{array}{ll}
		\phi &= \text{consecutive solutions of the system \eqref{first_exp} on } [T_i, T_{i+1}), \\[0.2cm]
		\lambda(u) &= \lambda, \quad \text{constant jump rate}, \\[0.2cm]
		\mathcal{Q}((y, z), \mathcal{A}) &= \mathbb{P}\left(\left(y - \zeta \sin(y),\, \zeta\right) \in \mathcal{A} \right), \quad \zeta \sim \text{Exp}(1).

	\end{array}
	\right.
\end{equation}

\noindent The time-dependent threshold is defined by the linear function:
\begin{equation*}
  \beta(t) = -t + 1.  
\end{equation*}

\noindent We start by verifying that the PDifMP $U_t$ satisfies the structural assumptions required for the simulation algorithm:
\begin{itemize}
    \item The drift and diffusion coefficients in Equation\eqref{first_exp} are differentiable and bounded, hence satisfy both the Lipschitz continuity and linear growth conditions.
    \item The jump function $j(y,z) = -z\sin(y)$ is bounded considering $z$ is a constant and thus satisfies Assumption~\ref{ass:jump-size}.
\end{itemize}
\noindent We define the tracking process $Y^{i,\infty}$, used in the simulation of the FPT by
\begin{equation*}
 dY^{i,\infty}_t = \left(1.6 + \sin(Y^{i,\infty}_t)\right)\,dt + dB_t, \qquad t \in [T_i, \infty).   
\end{equation*}
To apply Girsanov’s theorem for the exact simulation of the tracking process, we verify that the drift term is regular and satisfies Novikov's condition. The drift is continuously differentiable and bounded, and satisfies the Novikov condition:
\begin{align*}
\mathbb{E}\left[\exp\left(\frac{1}{2} \int_0^{\tau^{*}} \left(1.6 + \sin(Y_s)\right)^2 ds\right)\right]
&= \mathbb{E}\left[\exp\left(\frac{1}{2} \int_0^{\tau^{*}} \left((1.6)^2 + \sin^2(Y_s) + 2 \cdot (1.6) \sin(Y_s)\right) ds\right)\right] \\[0.8em]
&\leq \mathbb{E}\left[\exp\left(36 \cdot \tau^{*}\right)\right].
\end{align*}
\noindent It is straightforward to see that the threshold function is differentiable. Additionally, it is necessary to ensure that the tracking process $Y^{i,\infty}$ does not explode before reaching the threshold. This follows from the fact that the drift is bounded, the diffusion coefficient is Lipschitz continuous, and its square is bounded away from zero. By Proposition 5.17 in \cite{karatzas1991brownian}, these conditions guarantee non-explosion of the solution to the SDE.\\
\noindent We now specify the functions $\gamma_1$, $\gamma_2$, and $A$ associated with this example, and verify that they satisfy the assumptions required for the application of the exact simulation method:
\begin{align*}
\gamma_1(t) &= 1.6 + \sin(-t + 1), \\[0.65em]
\gamma_2(t, (y, z_i)) &= \frac{(1.6 + \sin(y))^2 + \cos(y)}{2}, \\[0.65em]
A(t, (y, z_i)) &= 1.6x - \cos(y).
\end{align*}

\noindent The function $\gamma_1$ is bounded and strictly positive, taking values in the interval $[0.6, 2.6]$. Numerical evaluation confirms that $\gamma_2$ is also strictly positive and bounded above by approximately 3.88. Consequently, the sum $\gamma_1 + \gamma_2$ is non-negative and uniformly bounded.\\
\noindent Since the simulation terminates at the FPT $\tau_\beta$, it is sufficient that these assumptions hold up to that time. Because the process remains below the threshold $\beta(t) = -t + 1$, which is bounded above by 1, we have $Y^{i,\infty}_t < 1$ for all $t < \tau_\beta$. Therefore, on this interval, the function $A(t, (y, z_i))$ is also bounded above by $2.6$.

\noindent Finally, we apply Algorithm~\ref{alg:final algorithm} to simulate samples of $\min(\tau_\beta, T_f)$. To assess the accuracy of our method, we compare it against a high-resolution Euler–Maruyama method (i.e. using a very fine time discretisation). The corresponding densities results for different $s_{\text{min}}$ values are displayed in Figure~\ref{fig:example1_1}.

\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\linewidth]{Figures/Example_1.png}
    \caption{Density plots of FPT of the PDifMP in example 1, based on 3,000 simulations using two methods: (i) the Exact method for different values of the parameter $s_{\text{min}}$ and (ii) a high-resolution Euler–Maruyama scheme. The jump rate is fixed at $\lambda = 1$, and the terminal time is $T_f = 3$.}
    \label{fig:example1_1}
\end{figure}

\noindent The density curves produced by the Exact method show strong alignment with those from the Euler–Maruyama scheme, confirming the validity of the proposed algorithm. The choice of $s_{\text{min}}$ does not influence the accuracy much. In particular, the results for $s_{\text{min}} = -5$ and $s_{\text{min}} = -10$ are nearly indistinguishable from the benchmark.\\
To quantify the similarity between the simulated distributions, we perform a Kolmogorov–Smirnov (KS) test comparing the Exact and Euler–Maruyama outputs for various values of $s_{\text{min}}$:

\begin{table}[H]
\centering
\begin{tabular}{|c|c|c|c|}
\hline
$s_\text{min}$ & $-2$ & $-5$ & $-10$ \\
\hline
p-value  & $0.0004$  & $0.2242$  & $0.3369$  \\
\hline
\end{tabular}
\caption{KS test p-values comparing the Exact method with the Euler–Maruyama}
\label{tab:s_pvalue}
\end{table}

\noindent The results in Table~\ref{tab:s_pvalue} show that the p-values are comfortably above common significance levels. This provides empirical support for the theoretical convergence result established in Theorem~\ref{thm:valid_alg_2}, and confirms that moderately small values of $s_{\text{min}}$ already yield reliable approximations in practice.
\subsection*{Example 2: time-inhomogeneous PDifMP}

We consider now the following PDifMP $U_t = (Y_t, Z_t)$, with dynamics defined as follows. Between jumps, the system evolves according to the SDE:
\begin{equation}
\left\{
\begin{array}{ll}
dY_t^{i} = \left(Z_t^i + \frac{1}{2} \sin(t + Y_t^i)\right) dt + dB_t, & \quad t \in [T_i, T_{i+1}), \\[0.65em]
dZ_t^i = 0. &
\end{array}
\right.
\label{Exmpl_2}
\end{equation}
\noindent The process is initialised at $Y_0^0 = -1$. At each jump time $T_{i+1}$, the process is updated as:
\begin{equation*}
\left\{
\begin{array}{ll}
Y^{i+1}_{T_{i+1}} = Y^{i}_{T_{i+1}} + j(Y^{i}_{T_{i+1}}, z_i), \\[0.4em]
Z^{i+1}_{T_{i+1}} = z_i,
\end{array}
\right.
\end{equation*}
where $z_i \sim \mathcal{U}(1.8, 3)$ i.i.d., and the jump function is given by $j(y, z) = \frac{1 - y}{z}$.
\noindent We consider the same linear threshold as in Example 1. The PDifMP $U_t = (Y_t, Z_t)$ is defined by the following local characteristics:
\begin{equation*}
\label{eq:example2_char}
\left\{
\begin{array}{ll}
\phi &= \text{solution of system \eqref{Exmpl_2}} \\[0.4em]
\lambda(u) &= \lambda, \\[0.4em]
\mathcal{Q}((y, z), \mathcal{A}) &= \mathbb{P}\left( \left(y + \frac{1 - y}{z'},\, \zeta\right) \in \mathcal{A} \right), \quad \zeta \sim \mathcal{U}(1.8, 3).
\end{array}
\right.
\end{equation*}
\noindent We verify that the PDifMP satisfies the assumptions required for our simulation framework:
\begin{itemize}
    \item The drift and diffusion coefficients satisfy Lipschitz continuity and linear growth conditions.
    \item The jump size function $j(y,z)$ satisfies a linear growth condition in $y$. The drift and diffusion coefficients meet the conditions ensuring non-explosion of the process \cite{karatzas1991brownian}, and since $z$ is constant, the jump size is bounded.
\end{itemize}
\noindent Furthermore, the tracking diffusion $Y^{i,\infty}$ on the interval $[T_i, \infty)$ satisfies:
\begin{equation*}
dY^{i,\infty}_t = \left(z_i + \frac{1}{2} \sin(t + Y^{i,\infty}_t)\right) dt + dB_t.    
\end{equation*}
The drift term is continuously differentiable and satisfies Novikov’s condition. In particular, we have:
\begin{align*}
\mathbb{E}\left[\exp\left( \frac{1}{2} \int_0^{\tau^{*}} \left(z_i + \frac{1}{2} \sin(h + Y_h)\right)^2 dh \right)\right]
&\leq \mathbb{E}\left[\exp\left( \frac{1}{2} \cdot (3.5)^2 \cdot \tau^{*} \right)\right],
\end{align*}
which is finite under integrability assumptions on $\tau^{*}$. Hence, Novikov’s condition is satisfied.\\
\noindent We now specify the functions $\gamma_1$, $\gamma_2$, and $A$ used in the rejection probability of the Exact method:
\begin{equation*}
\begin{aligned}
\gamma_1(t) &= z \\[0.4em]
\gamma_2(t, (y, z)) &= \frac{1}{2}\sin(t+y) + \frac{1}{2}\left(\frac{1}{2}\cos(t+y)+(\zeta_i + \frac{1}{2}\sin(t+y))^{2}\right), \\[0.4em]
A(t, (y, z)) &= z y -\frac{1}{2}\cos(t+y).
\end{aligned}    
\end{equation*}
\noindent It is straightforward to verify that all three functions are smooth and bounded from above on intervals preceding the threshold crossing time, ensuring the applicability of the Exact algorithm.\\
\noindent We apply Algorithm~\ref{alg:final algorithm} to simulate samples of $\min(\tau_{\beta}, T_f)$ for the PDifMP described above. To validate the accuracy of our method, we also simulate the same quantity using the high-resolution Euler–Maruyama method. The resulting densities are approximated and displayed in Figure~\ref{fig:example2}.

\begin{figure}[H]
    \centering
    \includegraphics[width=0.6\linewidth]{Figures/Example2.png}
    \caption{FPT densities for the PDifMP model including jump effects in both drift and diffusion, based on $3 \cdot 10^3$ simulations. Results are compared for (i) the Exact method with varying values of $s_\text{min}$, and (ii) the high-resolution Euler–Maruyama method. The jump rate is set to $\lambda = 1$.}
    \label{fig:example2}
\end{figure}

\noindent Figure~\ref{fig:example2} demonstrates a close similarity between the density curves produced by the Exact and Euler–Maruyama methods, particularly as the parameter $s_\text{min}$ becomes more negative. To assess this similarity quantitatively, we perform the KS test again to compare the empirical distributions obtained by both methods.


