\section{}
\subsection{Proof of Theorem \ref{thm:girsanov_stopping} }
\label{Appendix_A}
\begin{proof}
We divide the proof into three steps: (i) showing that $(M_t)_{t \geq 0}$ is a true $\mathbb{P}$-martingale up to time $\mathcal{T}$; 
(ii) verifying that under $\mathbb{Q}$, the process $\tilde{B}_t := B_t + \int_0^t \alpha\big(s,\, (X^{i,\infty}_h, z_i)\big)\, dh$ is a Brownian motion; and  (iii) establishing the expectation transformation identity.

\paragraph{\textit{Step 1.}} For $z_i$ fixed in $E_2$, recall the exponential process $M_t$
\begin{equation*}
 M_t := \exp\left( - \int_0^t \alpha\big(h,\,(X^{i,\infty}_h, z_i)\big)\, dB_h - \frac{1}{2} \int_0^t \alpha^2(h,\, (X^{i,\infty}_h, z_i)\big)\, dh \right), \quad t \geq 0.   
\end{equation*}
\noindent Using Itô’s formula, we have:
\begin{equation*}
dM_t = -M_t \alpha\big(t,\, (X^{i,\infty}_t, z_i)\big)\, dB_t.    
\end{equation*}
\noindent Since $\mathcal{T}$ is a stopping time, the stopped process $(M_{t \wedge \mathcal{T}})_{t \geq 0}$ is a local martingale. 
By the Novikov condition \eqref{novik}, it is uniformly integrable, hence a true martingale, see \cite{oksendal2013stochastic} for more details. 
Therefore, the measure $\mathbb{Q}$ defined via
\begin{equation*}
\left. \frac{d\mathbb{Q}}{d\mathbb{P}} \right|_{\mathcal{F}_{\mathcal{T}}} = M_{\mathcal{T}}    
\end{equation*}
is well-defined and satisfies $\mathbb{Q} \sim \mathbb{P}$ on $\mathcal{F}_{\mathcal{T}}$.
\paragraph{\textit{Step 2.}} Under $\mathbb{Q}$, define the process
\begin{equation*}
 \tilde{B}_t := B_t + \int_0^t \alpha\big(h,\, (X^{i,\infty}_h, z_i)\big)\, dh, \quad 0 \leq t \leq \mathcal{T}.   
\end{equation*}
By Girsanov’s theorem (see e.g. \cite{oksendal2013stochastic}), for fixed $z_i$ values, $(\tilde{B}_t)_{0 \leq t \leq \mathcal{T}}$ is a standard Brownian motion under $\mathbb{Q}$. Hence, the original SDE under $\mathbb{P}$:
\begin{equation*}
 dX^{i,\infty}_t = \alpha\big(t,\, ( X^{i,\infty}_t, z_i)\big)\, dt + dB_t   
\end{equation*}
\noindent becomes, under $\mathbb{Q}$,
\begin{equation*}
dX^{i,\infty}_t = d\tilde{B}_t, \quad 0 \leq t \leq \mathcal{T}. \end{equation*}
This shows that $(X^{i,\infty}_t)_{0 \leq t \leq \mathcal{T}}$ behaves as a Brownian motion under $\mathbb{Q}$.

\paragraph{\textit{Step 3.}} Let $\Psi: C([0, \mathcal{T}]; \mathbb{R}) \to \mathbb{R}$ be a bounded, measurable functional. 
Using the definition of the Radon–Nikodym derivative \eqref{measure_transf}, we obtain:
\begin{equation*}
\mathbb{E}_{\mathbb{P}}\left[\Psi(X^{i,\infty}_h; 0 \leq h \leq \mathcal{T})\right]
= \mathbb{E}_{\mathbb{Q}}\left[\Psi(X^{i,\infty}_h; 0 \leq h \leq \mathcal{T}) M_{\mathcal{T}} \right].    
\end{equation*}
\noindent Since $M_{\mathcal{T}} > 0$ $\mathbb{P}$-almost surely and $\mathbb{E}_{\mathbb{P}}[M_{\mathcal{T}}] = 1$, 
the measures $\mathbb{Q}$ and $\mathbb{P}$ are equivalent on $\mathcal{F}_{\mathcal{T}}$. Note that absolute continuity may not hold beyond $\mathcal{T}$.
\end{proof}



\subsection{Proof of Theorem \ref{thm:Girsanovprob_FPT} }
\label{Appendix_B}

\begin{proof}
This proof follows the methodology of \cite{khurana2024exact}, with appropriate modifications tailored to our setting. We use Girsanov's transformation described in Theorem \ref{thm:girsanov_stopping}, resulting in the following equality:
\footnotesize{
\begin{equation}
    \mathbb{E}_{\mathbb{P}}\left[\Psi(\tau_{\beta}^{\text{cont},i})\mathbf{1}_{\{\tau_{\beta}^{\text{cont},i}<\infty\}}\right] 
    = \mathbb{E}_{\mathbb{Q}}\left[\Psi(\tau_{\beta}^{\text{cont},i}) \exp \left( \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \alpha\big(t,\,( {\tilde{X}^{i}_t},z_i)\big) dB_t - \frac{1}{2} \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \alpha^2\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) dt \right) \right].
    \label{eq:proof1}
\end{equation}}
\normalsize
\noindent To simplify the stochastic integral, we apply It\^o’s lemma to the function $A(t, (x,z))$ defined in Subsection \ref{subsection3.2}. Since $\frac{\partial}{\partial x}A(t, (x,z)) = \alpha(t, (x,z))$, we have
\begin{multline}
        \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \alpha\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) dB_t = A(\tau_{\beta}^{\text{cont},i}, \,({\tilde{X}_{\tau_{\beta}^{\text{cont},i}}^{i}},z_i)) - A(T_{i},\,( {\tilde{X}^{i}_{T_{i}}},z_i)) -\\ \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \left( \frac{\partial}{\partial t}A\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) + \frac{1}{2} \frac{\partial}{\partial x}\alpha\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) \right) dt.
\label{eq:proof2}
\end{multline}


\noindent Substituting \eqref{eq:proof2} into \eqref{eq:proof1}, we obtain
\small{
\begin{align}
\mathbb{E}_{\mathbb{P}}\left[\Psi(\tau_{\beta}^{\text{cont},i})\mathbf{1}_{\{\tau_{\beta}^{\text{cont},i}<\infty\}}\right] 
    &= \mathbb{E}_{\mathbb{Q}} \Bigg[ \Psi(\tau_{\beta}^{\text{cont},i}) 
    \exp \Bigg( A(\tau_{\beta}^{\text{cont},i},\,( \tilde{X}^i_{\tau_{\beta}^{\text{cont},i}},z_i)) - A(T_{i},\,( {\tilde{X}^{i}_{T_{i}}},z_i)) \notag \\
    &\quad - \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \left( \frac{\partial}{\partial t}A\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) + \frac{1}{2} \frac{\partial}{\partial x}\alpha\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) + \frac{1}{2} \alpha^2\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) \right) dt \Bigg) \Bigg].
\label{eq:proof3}
\end{align}}
\normalsize
\noindent Under the measure $\mathbb{Q}$, $\tau_{\beta}^{\text{cont},i}$ is the FPT of the process ${\tilde{X}^{i}}$, thus we have
\begin{equation*}
      \tilde{X}^i_{\tau_{\beta}^{\text{cont},i}} = \beta(\tau_{\beta}^{\text{cont},i}).
  \end{equation*}
\noindent Substituting this into \eqref{eq:proof3} gives
\footnotesize{
\begin{align*}
\mathbb{E}_{\mathbb{P}}\left[\Psi(\tau_{\beta}^{\text{cont},i})\mathbf{1}_{\{\tau_{\beta}^{\text{cont},i}<\infty\}}\right] 
    &= \mathbb{E}_{\mathbb{Q}} \Bigg[ \Psi(\tau_{\beta}^{\text{cont},i}) e^{ - A(T_{i},\,( {\tilde{X}^{i}_{T_{i}}},z_i))}
    \exp \Bigg( A(\tau_{\beta}^{\text{cont},i}, \, (\beta(\tau_{\beta}^{\text{cont},i}),z_i)) \notag \\
    &\quad - \int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \left( \frac{\partial}{\partial t}A\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) + \frac{1}{2} \left( \frac{\partial}{\partial x}\alpha(t,\, ( {\tilde{X}_t^{i,\infty}}, z_i)) + \alpha^2\big(t,\,( {\tilde{X}_t^{i}}, z_i)\big) \right) \right) dt \Bigg) \Bigg].
\end{align*}}
\normalsize
\noindent Assumption~\ref{ass: on drift} allows us to write the following:
\begin{equation}
A(\tau_{\beta}^{\text{cont},i}, \,(\beta(\tau_{\beta}^{\text{cont},i}),z_i))=\int_{T_{i}}^{\tau_{\beta}^{\text{cont},i}} \left(\frac{\partial}{\partial t}A(t,\,( \beta(t),z_i)) + \alpha(t,\,( \beta(t), z_i))\beta'(t)\right) dt.
\label{eq: proof4}
\end{equation}
\noindent Rewriting the integral terms, using  equation \eqref{eq: proof4} and the pre-defined functions $\gamma_1$ and $\gamma_2$, we obtain
\begin{equation}
    \mathbb{E}_{\mathbb{P}}\left[\Psi(\tau_{\beta}^{\text{cont},i})\mathbf{1}_{\{\tau_{\beta}^{\text{cont},i}<\infty\}}\right] 
    = e^{-A(T_{i},\,(  {\tilde{X}^{i}_{T_{i}}},z_i)) + A(T_{i},\,( \beta(T_{i}),z_i))} \mathbb{E}_{\mathbb{Q}} \left[\Psi(\tau_{\beta}^{\text{cont},i}) \eta^{[2]}(\tau_{\beta}^{\text{cont},i}) \right],
\label{eq:proof_final}
\end{equation}
where $\eta^{[2]}(t)$ is defined in \eqref{eq:eta_def}.
\end{proof}
